def normalizar_flujo_recepcion_sbh(valor, predeterminado='INGRESO_MERCADERIA'):
    """Obtiene el flujo de navegación válido de Recepción SBH."""
    flujo = str(valor or '').strip().upper()
    return flujo if flujo in FLUJOS_NAVEGACION_RECEPCION_SBH else predeterminado


def queryset_secuencias_recepcion_sbh_por_flujo(empresa_id, flujo):
    """Secuencias activas permitidas para cada flujo de Recepción SBH.

    La separación se basa en SE_CCODIGO, que es la identidad persistente de la
    secuencia, y no en el nombre que se muestra en el selector.
    """
    secuencias = SECUENCIA.objects.filter(
        EP_NID_id=empresa_id,
        SE_CTIPO=CIT_RECEPCION,
        SE_BHABILITADO=True,
    )
    if normalizar_flujo_recepcion_sbh(flujo) == 'TRANSFERENCIA':
        return secuencias.filter(SE_CCODIGO=SECUENCIA_RECEPCION_TRANSFERENCIA_SBH)
    secuencias = secuencias.exclude(
        SE_CCODIGO__in={
            SECUENCIA_RECEPCION_TRANSFERENCIA_SBH,
            SECUENCIA_RECEPCION_NEW_JERSEY_P2,
            SECUENCIA_RECEPCION_NEW_JERSEY_P3,
            *SECUENCIAS_RECEPCION_LEGACY_NO_ETAPA_0,
        }
    )
    if empresa_id == ID_ACEITES_SBH:
        secuencias = secuencias.exclude(SE_CCODIGO__in=SECUENCIAS_PATIO_LF_HISTORICAS_SBH)
    return secuencias


def resolver_formulario_etapa0(planificacion):
    """Resuelve el formulario vigente desde la empresa, tipo y secuencias guardadas."""
    if not planificacion or planificacion.PL_BARCHIVADO or not planificacion.PL_FFECHAINICIO:
        return ''
    empresa_id = planificacion.EP_NID_id
    tipo = str(planificacion.PL_CTIPOCUPO or '').upper()
    citaciones = list(CITACION.objects.filter(
        PL_NID=planificacion, CI_BHABILITADO=True,
    ).values('EP_NID_id', 'CI_CTIPO', 'SC_NID_id'))
    if not citaciones or any(
        item['EP_NID_id'] != empresa_id
        or str(item['CI_CTIPO'] or '').upper() != tipo
        or not item['SC_NID_id']
        for item in citaciones
    ):
        return ''
    secuencias_actuales = {item['SC_NID_id'] for item in citaciones}
    if empresa_id == ID_ACEITES_SBH and tipo == CIT_RECEPCION:
        transferencia = set(queryset_secuencias_recepcion_sbh_por_flujo(
            empresa_id, 'TRANSFERENCIA',
        ).values_list('id', flat=True))
        if secuencias_actuales.issubset(transferencia):
            return 'transferencia_sbh'
        ingreso = set(queryset_secuencias_recepcion_sbh_por_flujo(
            empresa_id, 'INGRESO_MERCADERIA',
        ).values_list('id', flat=True))
        return 'recepcion_sbh' if secuencias_actuales.issubset(ingreso) else ''
    if empresa_id == ID_ACEITES_SBH and tipo == CIT_DESPACHO:
        codigos = {flujo[0] for flujo in FLUJOS_DESPACHO_ETAPA_0}
        permitidas = set(SECUENCIA.objects.filter(
            EP_NID_id=empresa_id, SE_CTIPO=tipo, SE_BHABILITADO=True,
            SE_CCODIGO__in=codigos,
        ).values_list('id', flat=True))
        return 'despacho_sbh' if secuencias_actuales.issubset(permitidas) else ''
    if empresa_es_terramar_chile(empresa_id) and tipo == CIT_RECEPCION:
        permitidas = set(queryset_secuencias_recepcion_terramar(
            empresa_id,
        ).values_list('id', flat=True))
        return 'recepcion_terramar' if secuencias_actuales.issubset(permitidas) else ''
    if empresa_es_terramar_chile(empresa_id) and tipo == CIT_DESPACHO:
        codigos = {flujo[0] for flujo in FLUJOS_DESPACHO_TERRAMAR_ETAPA_0}
        permitidas = set(SECUENCIA.objects.filter(
            EP_NID_id=empresa_id, SE_CTIPO=tipo, SE_BHABILITADO=True,
            SE_CCODIGO__in=codigos,
        ).values_list('id', flat=True))
        return 'despacho_terramar' if secuencias_actuales.issubset(permitidas) else ''
    return ''


def es_flujo_recepcion_transferencia_sbh(citacion):
    """Identificación persistente, independiente de los parámetros GET."""
    tipo = str(
        getattr(citacion, 'CI_CTIPO', '')
        or (getattr(getattr(citacion, 'PL_NID', None), 'PL_CTIPOCUPO', '') if citacion else '')
        or ''
    ).upper()
    secuencia = str(getattr(getattr(citacion, 'SC_NID', None), 'SE_CCODIGO', '') or '').upper()
    return bool(
        citacion
        and getattr(citacion, 'EP_NID_id', None) == ID_ACEITES_SBH
        and tipo == CIT_RECEPCION
        and secuencia == SECUENCIA_RECEPCION_TRANSFERENCIA_SBH
    )


def es_flujo_recepcion_estanque_sbh(citacion):
    tipo = str(
        getattr(citacion, 'CI_CTIPO', '')
        or (getattr(getattr(citacion, 'PL_NID', None), 'PL_CTIPOCUPO', '') if citacion else '')
        or ''
    ).upper()
    secuencia = getattr(getattr(citacion, 'SC_NID', None), 'SE_CCODIGO', '')
    return bool(
        citacion
        and getattr(citacion, 'EP_NID_id', None) == ID_ACEITES_SBH
        and tipo == CIT_RECEPCION
        and secuencia == SECUENCIA_RECEPCION_ESTANQUE_SBH
    )


def requiere_borrador_sap_recepcion_para_avanzar(citacion):
    """Conserva la exigencia histórica salvo en Recepción Estanque SBH."""
    return not es_flujo_recepcion_estanque_sbh(citacion)


def codigo_secuencia_citacion(citacion):
    return str(
        getattr(getattr(citacion, 'SC_NID', None), 'SE_CCODIGO', '') or ''
    ).strip().upper()


def es_recepcion_new_jersey(citacion):
    return bool(
        citacion
        and getattr(citacion, 'EP_NID_id', None) == ID_ACEITES_SBH
        and str(getattr(citacion, 'CI_CTIPO', '') or '').strip().upper() == CIT_RECEPCION
        and codigo_secuencia_citacion(citacion) in SECUENCIAS_RECEPCION_NEW_JERSEY
    )


def es_recepcion_new_jersey_p1(citacion):
    return es_recepcion_new_jersey(citacion) and (
        codigo_secuencia_citacion(citacion) in SECUENCIAS_RECEPCION_NEW_JERSEY_P1
    )


def es_recepcion_new_jersey_p1_con_calidad(citacion):
    return es_recepcion_new_jersey(citacion) and (
        codigo_secuencia_citacion(citacion) == SECUENCIA_RECEPCION_NEW_JERSEY_P1_CON_CALIDAD
    )


def es_recepcion_new_jersey_p1_sin_calidad(citacion):
    return es_recepcion_new_jersey(citacion) and (
        codigo_secuencia_citacion(citacion) == SECUENCIA_RECEPCION_NEW_JERSEY_P1_SIN_CALIDAD
    )


def es_recepcion_new_jersey_p2(citacion):
    return es_recepcion_new_jersey(citacion) and (
        codigo_secuencia_citacion(citacion) == SECUENCIA_RECEPCION_NEW_JERSEY_P2
    )


def es_recepcion_new_jersey_p3(citacion):
    return es_recepcion_new_jersey(citacion) and (
        codigo_secuencia_citacion(citacion) == SECUENCIA_RECEPCION_NEW_JERSEY_P3
    )


def obtener_citacion_item_legacy(citacion):
    """P2 es una citación interna; las demás conservan la integridad legacy."""
    try:
        return CITACION_ITEM.objects.select_related('IT_NID').get(CI_NID=citacion)
    except CITACION_ITEM.DoesNotExist:
        if es_recepcion_new_jersey_p2(citacion):
            return None
        raise

def crear_operacion_new_jersey_proceso_1(citacion, item, usuario):
    if not es_recepcion_new_jersey_p1(citacion):
        return None

    # La operación física puede planificarse aunque el destino SAP aún no esté configurado.
    bodega_virtual = get_new_jersey_virtual_warehouse()

    modalidad = (
        OPERACION_NEW_JERSEY.Modalidad.CON_CALIDAD
        if es_recepcion_new_jersey_p1_con_calidad(citacion)
        else OPERACION_NEW_JERSEY.Modalidad.SIN_CALIDAD
    )
    operacion = OPERACION_NEW_JERSEY.objects.create(
        EP_NID=citacion.EP_NID,
        PRO_NID=citacion.PRO_NID,
        US_NID=usuario,
        ONJ_CMODALIDAD=modalidad,
        ONJ_CESTADO=OPERACION_NEW_JERSEY.Estado.PENDIENTE_PROCESO_1,
        ONJ_CITEM_CODE=str(item.get('codigo') or item.get('codigo_sap') or '').strip(),
        ONJ_CPRODUCTO=str(item.get('insumo') or '').strip(),
        ONJ_CPURCHASE_ORDER=str(item.get('pedido') or '').strip(),
        ONJ_CBASE_ENTRY=str(item.get('docentry') or item.get('sap_opor_id') or '').strip(),
        ONJ_CBASE_LINE=str(next((
            valor for valor in (
                item.get('base_line'),
                item.get('baseline'),
                item.get('linea_pedido'),
            ) if valor is not None and str(valor).strip() != ''
        ), '')).strip(),
        ONJ_CBODEGA_VIRTUAL=bodega_virtual,
        ONJ_CTK_DESTINO=str(item.get('estanque_destino') or '').strip(),
        ONJ_FFECHA_OPERACION=citacion.CI_FFECHACITACION,
        ONJ_BHABILITADO=True,
    )
    OPERACION_NEW_JERSEY_PROCESO.objects.create(
        ONJ_NID=operacion,
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        US_NID=usuario,
        ONJP_CTIPO=OPERACION_NEW_JERSEY_PROCESO.TipoProceso.PROCESO_1,
        ONJP_CESTADO=OPERACION_NEW_JERSEY_PROCESO.Estado.PENDIENTE,
    )
    return operacion


def es_recepcion_prosesa_piso_1(citacion):
    """Alias historico; la identificacion canonica vive en SAP Recepcion."""
    return es_recepcion_prosesa_contenedor_piso_1(citacion)


def estado_sap_recepcion_para_citacion(citacion):
    if es_recepcion_new_jersey_p1(citacion):
        return get_purchase_delivery_note_new_jersey_p1_status(citacion)
    if es_recepcion_prosesa_contenedor_piso_1(citacion):
        return get_purchase_delivery_note_prosesa_piso_1_status(citacion)
    return get_goods_receipt_draft_guide_status(citacion)


def es_recepcion_prosesa_piso_2(citacion):
    return bool(
        citacion
        and getattr(citacion, 'EP_NID_id', None) == ID_ACEITES_SBH
        and str(getattr(citacion, 'CI_CTIPO', '') or '').strip().upper() == CIT_RECEPCION
        and codigo_secuencia_citacion(citacion) == SECUENCIA_RECEPCION_PROSESA_PISO_2
    )


def unidad_peso_guia_revision_recepcion(citacion):
    """Unidad del peso de guía capturado por Asistente Recepción."""
    if (
        getattr(citacion, 'EP_NID_id', None) != ID_ACEITES_SBH
        or str(getattr(citacion, 'CI_CTIPO', '') or '').strip().upper() != CIT_RECEPCION
    ):
        return ''
    codigo = codigo_secuencia_citacion(citacion)
    if codigo not in {
        'RECEPCION_BODEGA_EXTERNA',
        SECUENCIA_RECEPCION_PROSESA_PISO_1,
        SECUENCIA_RECEPCION_PROSESA_PISO_2,
        SECUENCIA_RECEPCION_ESTANQUE_SBH,
        'RECEPCION_TRASVASIJE',
        *SECUENCIAS_RECEPCION_NEW_JERSEY_P1,
        *SECUENCIAS_RECEPCION_LEGACY_NO_ETAPA_0,
    }:
        return ''
    return 'MT' if es_recepcion_prosesa_descarga_camion(citacion) else 'kg'

def _ultimo_camion_patio_prosesa(citacion):
    return CAMION_PATIO.objects.filter(CI_NID=citacion).order_by(
        '-CPA_FFECHAACTUALIZACION', '-id'
    ).first()


def resolver_guia_prosesa_piso_1(citacion, guia_buscada=None):
    detalle = getattr(citacion, 'detalle_operacional', None)
    candidatos = [
        (
            getattr(citacion, 'CI_CNUMERODOCUMENTO', ''),
            'CITACION.CI_CNUMERODOCUMENTO',
        ),
        (
            getattr(detalle, 'CDO_CGUIA', ''),
            'CITACION_DETALLE_OPERACIONAL.CDO_CGUIA',
        ),
    ]
    candidatos.extend(
        (camion.CPA_CNUMERO_GUIA, 'CAMION_PATIO.CPA_CNUMERO_GUIA')
        for camion in CAMION_PATIO.objects.filter(CI_NID=citacion).order_by(
            '-CPA_FFECHAACTUALIZACION', '-id'
        )
    )
    guia_buscada = str(guia_buscada or '').strip().casefold()
    for valor, fuente in candidatos:
        valor = str(valor or '').strip()
        if valor and (not guia_buscada or valor.casefold() == guia_buscada):
            return valor, fuente
    return '', ''


def resolver_guia_prosesa_piso_2(citacion):
    guia, fuente = resolver_guia_prosesa_piso_1(citacion)
    if guia:
        return guia, fuente

    try:
        relacion = citacion.relacion_prosesa_retiro
    except CITACION_PROSESA_RELACION.DoesNotExist:
        relacion = None
    if not relacion:
        return '', ''

    guia, fuente = resolver_guia_prosesa_piso_1(relacion.CI_NID_ORIGEN)
    if guia:
        return guia, f'CITACION_PROSESA_RELACION.CI_NID_ORIGEN -> {fuente}'
    return '', ''


def resolver_numero_guia_operacion(citacion, datos_operacion=None):
    if es_recepcion_prosesa_piso_2(citacion):
        return resolver_guia_prosesa_piso_2(citacion)[0]
    return obtener_numero_guia(citacion, datos_operacion)

def _dato_operacion_prosesa(citacion, codigo):
    return DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO=codigo,
    ).select_related('CAMP_NID').order_by('-id').first()


def _contenedor_desde_ticket_entrada_prosesa(citacion):
    dato = _dato_operacion_prosesa(citacion, 'OP_TICKET_PESAJE_ENT')
    if not dato:
        return '', ''
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return '', ''
    if not isinstance(metadata, dict):
        return '', ''

    for clave in ('contenedor', 'container', 'lote_contenedor'):
        valor = str(metadata.get(clave) or '').strip()
        if valor:
            return valor, f'DATO_OPERACION.OP_TICKET_PESAJE_ENT.{clave}'

    observacion = str(metadata.get('observacion') or '').strip()
    normalizado = re.sub(r'[^A-Z0-9]', '', observacion.upper())
    if re.fullmatch(r'[A-Z]{4}[0-9]{7}', normalizado):
        return normalizado, 'DATO_OPERACION.OP_TICKET_PESAJE_ENT.observacion'
    return '', ''


def resolver_contenedor_prosesa_piso_1(citacion):
    detalle = getattr(citacion, 'detalle_operacional', None)
    camion_patio = _ultimo_camion_patio_prosesa(citacion)
    dato_lote = _dato_operacion_prosesa(citacion, 'AR_LOTE_CONTENEDOR')
    candidatos = (
        (
            getattr(detalle, 'CDO_CBL_CONTENEDOR', ''),
            'CITACION_DETALLE_OPERACIONAL.CDO_CBL_CONTENEDOR',
        ),
        (
            getattr(dato_lote, 'DO_CVALOR', ''),
            'DATO_OPERACION.AR_LOTE_CONTENEDOR',
        ),
        (
            getattr(camion_patio, 'CPA_CLOTE_CONTENEDOR', ''),
            'CAMION_PATIO.CPA_CLOTE_CONTENEDOR',
        ),
    )
    for valor, fuente in candidatos:
        valor = str(valor or '').strip()
        if valor:
            return valor, fuente
    return _contenedor_desde_ticket_entrada_prosesa(citacion)


def resolver_base_line_prosesa_piso_1(citacion):
    dato = _dato_operacion_prosesa(citacion, CAMPO_PROSESA_BASE_LINE_SAP)
    valor = str(getattr(dato, 'DO_CVALOR', '') or '').strip()
    if valor:
        return valor, f'DATO_OPERACION.{CAMPO_PROSESA_BASE_LINE_SAP}'

    dato_lote = _dato_operacion_prosesa(
        citacion,
        'SAP_LOTE_INGRESO_PROSESA_PISO1',
    )
    if dato_lote:
        try:
            metadata = json.loads(dato_lote.DO_CVALOR or '{}')
        except (TypeError, ValueError):
            metadata = {}
        if isinstance(metadata, dict):
            valor = metadata.get('base_line')
            if valor not in (None, ''):
                return str(valor), 'DATO_OPERACION.SAP_LOTE_INGRESO_PROSESA_PISO1.base_line'
    return '', ''



def preparar_item_prosesa_piso_2_desde_origen(item, citacion_origen):
    detalle = getattr(citacion_origen, 'detalle_operacional', None)
    if not detalle:
        raise ValueError('La citación Prosesa Piso 1 no tiene detalle operacional para heredar.')

    guia, fuente_guia = resolver_guia_prosesa_piso_1(
        citacion_origen, item.get('guia_origen_prosesa')
    )
    contenedor, fuente_contenedor = resolver_contenedor_prosesa_piso_1(
        citacion_origen
    )
    if not contenedor:
        raise ValueError(
            'La Citación Prosesa Piso 1 no tiene un identificador de contenedor '
            'en sus fuentes operacionales.'
        )
    base_line, fuente_base_line = resolver_base_line_prosesa_piso_1(
        citacion_origen
    )

    item.update({
        'origen': 'prosesa_piso_2',
        'cliente': str(citacion_origen.SN_NID_id or ''),
        'cliente_codigo': (
            getattr(citacion_origen.SN_NID, 'SN_CCODIGO_SAP', '') or ''
        ),
        'cliente_nombre': (
            getattr(citacion_origen.SN_NID, 'SN_CRAZONSOCIAL', '') or ''
        ),
        'proveedor': str(citacion_origen.PRO_NID_id or ''),
        'tipo_carga': citacion_origen.CI_CTIPO_FLETE or '',
        'inf_24hrs': detalle.CDO_CINF_24HRS or '',
        'codigo': detalle.CDO_CCODIGO_SAP or '',
        'codigo_sap': detalle.CDO_CCODIGO_SAP or '',
        'insumo': detalle.CDO_CINSUMO or '',
        'pedido': detalle.CDO_CPEDIDO_SAP or '',
        'sap_opor_id': detalle.CDO_CSAP_OPOR_ID or '',
        'codigo_proveedor_sap': detalle.CDO_CPROVEEDOR_CODIGO or '',
        'proveedor_codigo': detalle.CDO_CPROVEEDOR_CODIGO or '',
        'proveedor_nombre': detalle.CDO_CPRODUCTOR or '',
        'proveedor_sap': detalle.CDO_CPRODUCTOR or '',
        'contenedor': contenedor,
        'bl': detalle.CDO_CBL or '',
        'guia': guia,
        'fecha_produccion': detalle.CDO_CFECHA_PRODUCCION or '',
        'fecha_vencimiento': detalle.CDO_CFECHA_VENCIMIENTO or '',
        'cda': detalle.CDO_CCDA or '',
        'di': detalle.CDO_CDI or '',
        'sui': detalle.CDO_CSUI or '',
        'nave_naviera': detalle.CDO_CNAVE_NAVIERA or '',
        'booking': detalle.CDO_CBOOKING or '',
        'cantidad_disponible': detalle.CDO_NCANTIDAD_DISPONIBLE,
        'docentry': detalle.CDO_CDOCENTRY or '',
        'tipo_origen_recepcion': detalle.CDO_CTIPO_RECEPCION or '',
        'almacen_destino': normalizar_almacen_planificacion(detalle.CDO_CALMACEN_DESTINO),
        'estanque_destino': detalle.CDO_CESTANQUE_DESTINO or '',
        'base_line': base_line,
        '_prosesa_fuente_guia': fuente_guia,
        '_prosesa_fuente_contenedor': fuente_contenedor,
        '_prosesa_fuente_base_line': fuente_base_line,
        'observacion': (
            f'Retiro Prosesa vinculado a citación Piso 1 #{citacion_origen.id}. '
            'Integración SAP y cálculo de peso pendientes de definición.'
        ),
        '_prosesa_origen_id': citacion_origen.id,
    })
    return item


class ProsesaPiso2SnapshotError(ValueError):
    def __init__(self, message, status_code=409):
        super().__init__(message)
        self.status_code = status_code


def cargar_snapshot_prosesa_piso_2(guia, bloquear=False):
    guia = str(guia or '').strip()
    if not guia:
        raise ProsesaPiso2SnapshotError(
            'Contenedor a Piso 2 requiere el n\u00famero de gu\u00eda de la Citaci\u00f3n 1.',
            status_code=400,
        )

    ids_coincidentes = list(
        CITACION.objects.filter(
            EP_NID_id=ID_ACEITES_SBH,
            CI_CTIPO=CIT_RECEPCION,
            CI_CESTADO=ESTADO_PROSESA_ESPERANDO_RETIRO,
            CI_BHABILITADO=True,
            SC_NID__SE_CCODIGO=SECUENCIA_RECEPCION_PROSESA_PISO_1,
        ).filter(
            Q(CI_CNUMERODOCUMENTO__iexact=guia)
            | Q(detalle_operacional__CDO_CGUIA__iexact=guia)
            | Q(camiones_patio__CPA_CNUMERO_GUIA__iexact=guia)
        ).order_by('pk').values_list('pk', flat=True).distinct()[:2]
    )
    coincidencias = CITACION.objects.select_related(
        'SC_NID', 'SN_NID', 'PRO_NID', 'detalle_operacional'
    ).filter(pk__in=ids_coincidentes).order_by('pk')
    if bloquear:
        coincidencias = coincidencias.select_for_update(of=('self',))
    coincidencias = list(coincidencias)
    if not coincidencias:
        raise ProsesaPiso2SnapshotError(
            'No existe una Citaci\u00f3n Prosesa Piso 1 pendiente con esa gu\u00eda.',
            status_code=404,
        )
    if len(coincidencias) > 1:
        raise ProsesaPiso2SnapshotError(
            'La gu\u00eda coincide con m\u00e1s de una Citaci\u00f3n Prosesa Piso 1; debe corregirse la inconsistencia.'
        )

    origen = coincidencias[0]
    if CITACION_PROSESA_RELACION.objects.filter(CI_NID_ORIGEN=origen).exists():
        raise ProsesaPiso2SnapshotError(
            'La Citaci\u00f3n Prosesa Piso 1 ya tiene una Citaci\u00f3n 2 vinculada.'
        )

    try:
        datos = preparar_item_prosesa_piso_2_desde_origen(
            {'guia_origen_prosesa': guia}, origen
        )
    except ValueError as exc:
        raise ProsesaPiso2SnapshotError(str(exc)) from exc

    if not CITACION_ITEM.objects.filter(CI_NID=origen).exists():
        raise ProsesaPiso2SnapshotError(
            'La Citaci\u00f3n Prosesa Piso 1 no tiene un insumo asociado.'
        )
    faltantes = [
        nombre for clave, nombre in (
            ('codigo_sap', 'codigo SAP'),
            ('insumo', 'insumo'),
            ('pedido', 'pedido SAP'),
        )
        if not str(datos.get(clave) or '').strip()
    ]
    if faltantes:
        raise ProsesaPiso2SnapshotError(
            'Faltan datos en la Citaci\u00f3n Piso 1: ' + ', '.join(faltantes) + '.'
        )
    _, mensaje_tipo = validar_tipo_recepcion_sbh(
        datos.get('tipo_origen_recepcion'), 'INGRESO_MERCADERIA'
    )
    if mensaje_tipo:
        raise ProsesaPiso2SnapshotError(mensaje_tipo)
    destino_valido, mensaje_destino = validar_destino_recepcion_sbh(
        datos.get('almacen_destino'), datos.get('estanque_destino')
    )
    if not destino_valido:
        raise ProsesaPiso2SnapshotError(mensaje_destino)
    _, mensaje_proveedor = normalizar_proveedor_ingreso_mercaderia_sbh(datos)
    if mensaje_proveedor:
        raise ProsesaPiso2SnapshotError(mensaje_proveedor)
    return origen, datos


@require_GET
def PROSESA_PISO_2_CARGAR_ORIGEN(request):
    if Verificar_empresa(request) != ID_ACEITES_SBH:
        return JsonResponse({
            'success': False,
            'message': 'Esta consulta requiere Empresa 2.',
        }, status=403)
    try:
        origen, datos = cargar_snapshot_prosesa_piso_2(request.GET.get('guia'))
    except ProsesaPiso2SnapshotError as exc:
        return JsonResponse({
            'success': False,
            'message': str(exc),
        }, status=exc.status_code)
    return JsonResponse({
        'success': True,
        'message': f'Datos cargados desde Citaci\u00f3n Piso 1 #{origen.pk}',
        'citacion_piso_1': origen.pk,
        'datos': {
            clave: valor for clave, valor in datos.items()
            if not clave.startswith('_')
        },
        'base_line_disponible': bool(datos.get('base_line')),
    })


def validar_camion_retiro_planificado_prosesa_piso_2(item, requeridos=False):
    patente = _normalizar_patente(item.get('patente_retiro_prosesa'))
    if requeridos and not patente:
        raise ValueError('Debe ingresar la patente del camion de retiro de Piso 2.')
    if len(patente) > 32:
        raise ValueError('La patente del camion de retiro es demasiado larga.')

    transportista_id = str(
        item.get('empresa_transporte_retiro_prosesa_id') or ''
    ).strip()
    empresa_transporte = re.sub(
        r'\s+', ' ',
        str(item.get('empresa_transporte_retiro_prosesa') or ''),
    ).strip()
    transportistas = queryset_transportistas_validos_ingreso_camion(
        ID_ACEITES_SBH, estrictamente_empresa=True
    )
    if transportista_id:
        if not transportista_id.isdigit():
            raise ValueError('La empresa de transporte seleccionada no es valida.')
        transportista = transportistas.filter(pk=int(transportista_id)).first()
        if not transportista:
            raise ValueError('La empresa de transporte seleccionada no pertenece a Empresa 2 o no esta habilitada.')
        empresa_transporte = transportista.SN_CRAZONSOCIAL
    elif empresa_transporte:
        transportista = transportistas.filter(
            SN_CRAZONSOCIAL__iexact=empresa_transporte
        ).first()
        if transportista:
            empresa_transporte = transportista.SN_CRAZONSOCIAL
            transportista_id = str(transportista.pk)

    if requeridos and not empresa_transporte:
        raise ValueError('Debe ingresar la empresa de transporte del camion de retiro de Piso 2.')
    if len(empresa_transporte) > 256:
        raise ValueError('La empresa de transporte no puede superar 256 caracteres.')
    return {
        'patente_retiro_prosesa': patente,
        'empresa_transporte_retiro_prosesa': empresa_transporte,
        'empresa_transporte_retiro_prosesa_id': transportista_id,
    }


def citaciones_prosesa_piso_2_pendientes_por_patente(patente):
    patente = _normalizar_patente(patente)
    queryset = CITACION.objects.filter(
        EP_NID_id=ID_ACEITES_SBH,
        CI_CTIPO=CIT_RECEPCION,
        CI_CESTADO='Insumo Programado',
        CI_BHABILITADO=True,
        SC_NID__SE_CCODIGO=SECUENCIA_RECEPCION_PROSESA_PISO_2,
    )
    if not patente:
        return queryset.none()
    return queryset.filter(
        dato_operacion__CAMP_NID__CA_CCODIGO=CAMPO_PROSESA_PISO2_PATENTE_RETIRO,
        dato_operacion__DO_CVALOR=patente,
    ).distinct()

def es_flujo_recepcion_new_jersey_sin_calidad(citacion):
    return es_recepcion_new_jersey_p1_sin_calidad(citacion)


def es_citacion_despacho_terramar(citacion):
    return bool(
        citacion
        and citacion.EP_NID_id == 1
        and str(citacion.CI_CTIPO or '').upper() == CIT_DESPACHO
        and citacion.SC_NID
        and citacion.SC_NID.SE_CCODIGO in {'DESPACHO_TERRAMAR', 'DESPACHO_TERRAMAR_BODEGA_EXTERNA'}
    )

def es_citacion_despacho_terramar_principal(citacion):
    return bool(
        es_citacion_despacho_terramar(citacion)
        and citacion.SC_NID
        and str(citacion.SC_NID.SE_CCODIGO or '').strip().upper() == 'DESPACHO_TERRAMAR'
    )


def es_flujo_preoperacional_terramar(citacion):
    """Flujo común de ingreso físico Terramar, aislado de los datos de Recepción."""
    return es_citacion_recepcion_terramar(citacion) or es_citacion_despacho_terramar(citacion)


def _empresa_timbre_recepcion(citacion):
    """Identifica la empresa legal a partir de la relación real de la citación."""
    empresa = getattr(citacion, 'EP_NID', None)
    nombre = normalizar_nombre_flujo_operacion(getattr(empresa, 'EP_CRAZONSOCIAL', ''))
    if empresa and empresa.id == ID_TERRAMAR and 'TERRAMAR' in nombre:
        return 'TERRAMAR'
    if empresa and empresa.id == ID_ACEITES_SBH and {'ACEITES', 'SBH'} <= set(nombre.split()):
        return 'SBH'
    return ''


def aplica_timbraje_recepcion(citacion):
    """El timbraje documental sólo existe para recepciones reales de Terramar y SBH."""
    return bool(
        citacion
        and str(getattr(citacion, 'CI_CTIPO', '') or '').strip().upper() == CIT_RECEPCION
        and _empresa_timbre_recepcion(citacion) in {'TERRAMAR', 'SBH'}
        and not rs.es_recepcion_servicio(citacion)
    )


def _datos_empresa_timbre(citacion):
    datos = {
        'TERRAMAR': ('Terramar Chile SpA', '77.620.020-4'),
        'SBH': ('Aceites SBH SpA', '76.957.638-K'),
    }
    empresa = _empresa_timbre_recepcion(citacion)
    if empresa not in datos:
        raise ValueError('La empresa de la citación no está habilitada para timbraje de recepción.')
    return datos[empresa]

def _pk_corresponde_recepcion_terramar(pk):
    return CITACION.objects.filter(
        pk=pk,
        EP_NID_id=1,
        CI_CTIPO='RECEPCION',
        SC_NID__SE_CCODIGO__in={'RECEPCION_TERRAMAR', 'RECEPCION_TERRAMAR_BODEGA_EXTERNA'},
    ).exists()


def operacion_envio_guardia_para_citacion(citacion):
    if es_flujo_preoperacional_terramar(citacion):
        return SYSLOGGER_OP_ENVIA_BODEGA_GUARDIA
    if es_recepcion_new_jersey_p3(citacion):
        return 'APRUEBA_AR'
    return 'ENVIA_CD_NEXT'


def citacion_fue_enviada_a_guardia(citacion):
    return SYSLOGGER.objects.filter(
        LOG_COPERACION=operacion_envio_guardia_para_citacion(citacion),
        LOG_CADD1=str(citacion.id),
    ).exists()


def contenido_notificacion_ingreso_planta(citacion, patente, autorizar_ingreso=False):
    mensaje = f'El camión patente {patente} debe ingresar a planta.'
    if autorizar_ingreso:
        mensaje += ' Autorizar ingreso físico.'
    return f'{mensaje} Citación: {citacion.id}.'


def obtener_etapa_recepcion_terramar(citacion):
    avance = ETAPA_LOG.objects.filter(CI_NID=citacion, EL_FFECHAFIN__isnull=True).select_related('ET_NID').order_by('-EL_FFECHAINICIO').first()
    if avance and avance.ET_NID:
        return avance.ET_NID.ET_CNOMBRE
    primera = DETALLE_SECUENCIA.objects.filter(SC_NID=citacion.SC_NID, SE_BHABILITADO=True).select_related('ET_NID').order_by('SE_NPASO').first()
    return primera.ET_NID.ET_CNOMBRE if primera and primera.ET_NID else ''

def queryset_secuencias_recepcion_terramar(empresa_id):
    """Flujos reales de recepción de Harinas habilitados para Terramar."""
    codigos = ['RECEPCION_TERRAMAR', 'RECEPCION_TERRAMAR_BODEGA_EXTERNA']
    return SECUENCIA.objects.filter(
        EP_NID_id=empresa_id,
        SE_CTIPO='RECEPCION',
        SE_BHABILITADO=True,
        SE_CCODIGO__in=codigos,
    ).order_by(
        models.Case(
            models.When(SE_CCODIGO='RECEPCION_TERRAMAR', then=models.Value(0)),
            models.When(SE_CCODIGO='RECEPCION_TERRAMAR_BODEGA_EXTERNA', then=models.Value(1)),
            default=models.Value(2),
            output_field=models.IntegerField(),
        ),
        'id',
    )


TIPOS_RECEPCION_SBH_HISTORICOS = {'NACIONAL', 'EXTRANJERO'}
TIPOS_RECEPCION_SBH_INGRESO_MERCADERIA = {'NACIONAL', 'IMPORTACION'}

ESTANQUES_RECEPCION_TRANSFERENCIA_SBH = ('PROCESA', 'PROSEG10', 'PROSE_G2', 'PROSE_G4', 'PROSE_G9', 'PROSE_T3', 'PROSE_T4', 'PROSE_T5', 'PROSE_T8')


def obtener_snapshot_recepcion_transferencia_sap(estanque, codigo_sap):
    """Reconsulta SAP para no confiar en los campos readonly del navegador."""
    estanque = str(estanque or '').strip()
    codigo_sap = str(codigo_sap or '').strip()
    if estanque not in ESTANQUES_RECEPCION_TRANSFERENCIA_SBH:
        raise ValueError('El estanque origen no es válido para Recepción de Transferencia SBH.')
    if not codigo_sap:
        raise ValueError('Debe seleccionar un producto SAP para la transferencia.')

    resultado = consultar_productos_recepcion_transferencia_sap(estanque)
    for producto in resultado['productos']:
        if str(producto.get('codigo_sap') or '').strip() == codigo_sap:
            return producto
    raise ValueError('El producto seleccionado no está disponible en el estanque origen indicado.')


def validar_movimientos_recepcion_transferencia_sbh(movimientos):
    if not isinstance(movimientos, list) or not movimientos:
        raise ValueError('Debe agregar al menos un producto / origen para la transferencia.')

    movimientos_validados = []
    combinaciones = set()
    for orden, movimiento in enumerate(movimientos, start=1):
        if not isinstance(movimiento, dict):
            raise ValueError(f'El movimiento {orden} no tiene un formato válido.')
        estanque = str(movimiento.get('estanque_origen') or '').strip()
        codigo_sap = str(movimiento.get('codigo_sap') or movimiento.get('codigo') or '').strip()
        combinacion = (estanque, codigo_sap)
        if combinacion in combinaciones:
            raise ValueError('Este producto ya fue agregado para este estanque.')
        combinaciones.add(combinacion)

        cantidad = decimal_or_none(movimiento.get('cantidad_a_mover'))
        if cantidad is None or cantidad <= 0:
            raise ValueError(f'La cantidad a mover del movimiento {orden} debe ser mayor que cero.')

        snapshot = obtener_snapshot_recepcion_transferencia_sap(estanque, codigo_sap)
        stock = decimal_or_none(snapshot.get('stock_disponible'))
        unidad = str(snapshot.get('unidad') or '').strip()
        if stock is None:
            raise ValueError(f'SAP no informó stock disponible para el movimiento {orden}.')
        if unidad and cantidad > stock:
            raise ValueError(f'La cantidad a mover del movimiento {orden} supera el stock disponible.')

        movimientos_validados.append({
            'estanque_origen': estanque,
            'codigo_sap': str(snapshot.get('codigo_sap') or codigo_sap).strip(),
            'codigo': str(snapshot.get('codigo_sap') or codigo_sap).strip(),
            'insumo': str(snapshot.get('insumo') or '').strip(),
            'codigo_propietario': str(snapshot.get('codigo_propietario') or '').strip(),
            'propiedad_producto': str(snapshot.get('propiedad_producto') or '').strip(),
            'stock_disponible_snapshot': stock,
            'cantidad_disponible': stock,
            'unidad_inventario_snapshot': unidad,
            'cantidad_a_mover': cantidad,
            'orden': orden,
        })
    return movimientos_validados


def validar_cantidad_camiones_transferencia(valor):
    texto = str(valor or '').strip()
    try:
        cantidad = int(texto)
    except (TypeError, ValueError):
        return None, 'La cantidad de camiones debe ser un número entero positivo.'
    if cantidad < 1:
        return None, 'La cantidad de camiones debe ser mayor o igual a 1.'
    return cantidad, ''


def validar_tipo_recepcion_sbh(valor, flujo=''):
    texto = str(valor or '').strip()
    if not texto:
        if str(flujo or '').strip().upper() == 'INGRESO_MERCADERIA':
            return '', 'Debe seleccionar si la recepción es Nacional o Importación.'
        return '', 'Debe seleccionar si la recepción es Nacional o Extranjera.'

    codigo = texto.upper()
    tipos_permitidos = (
        TIPOS_RECEPCION_SBH_INGRESO_MERCADERIA
        if str(flujo or '').strip().upper() == 'INGRESO_MERCADERIA'
        else TIPOS_RECEPCION_SBH_HISTORICOS
    )
    if codigo not in tipos_permitidos:
        return '', 'Tipo de recepción inválido.'
    return codigo, ''


def etiqueta_tipo_recepcion_sbh(valor):
    texto = str(valor or '').strip()
    return {
        'NACIONAL': 'Nacional',
        'EXTRANJERO': 'Extranjero',
        'IMPORTACION': 'Importación',
    }.get(texto.upper(), texto)


def normalizar_proveedor_ingreso_mercaderia_sbh(item):
    proveedor = str(
        item.get('proveedor_nombre')
        or item.get('proveedor_sap')
        or ''
    ).strip()
    if not proveedor:
        return '', 'Debe ingresar o seleccionar un proveedor.'
    if len(proveedor) > 256:
        return '', 'El proveedor no puede superar los 256 caracteres.'
    return proveedor, ''


def validar_programacion_despacho_sbh_item(
    item, requerir_fecha_llegada_destino=True
):
    campos = {
        'fecha despacho': item.get('fecha_despacho'),
        'hora llegada a planta': item.get('hora_llegada_planta'),
        'hora llegada a destino': item.get('hora_llegada_destino'),
        'orden de carga': item.get('orden_carga'),
        'formato': item.get('tipo_carga'),
        'destino': item.get('destino') or item.get('estanque_destino_texto'),
    }
    if requerir_fecha_llegada_destino:
        campos['fecha llegada a destino'] = item.get('fecha_llegada_destino')
    faltantes = [
        nombre for nombre, valor in campos.items()
        if not str(valor or '').strip()
    ]
    if faltantes:
        raise ValueError('Debe completar: ' + ', '.join(faltantes) + '.')

    try:
        fecha_despacho = datetime.strptime(
            str(item.get('fecha_despacho')).strip(), '%Y-%m-%d'
        ).date()
    except ValueError as exc:
        raise ValueError('La fecha de despacho debe tener formato YYYY-MM-DD.') from exc

    fecha_llegada_destino = None
    if requerir_fecha_llegada_destino or str(
        item.get('fecha_llegada_destino') or ''
    ).strip():
        try:
            fecha_llegada_destino = datetime.strptime(
                str(item.get('fecha_llegada_destino')).strip(), '%Y-%m-%d'
            ).date()
        except ValueError as exc:
            raise ValueError(
                'La fecha de llegada a destino debe tener formato YYYY-MM-DD.'
            ) from exc
        if fecha_llegada_destino < fecha_despacho:
            raise ValueError(
                'La fecha de llegada a destino no puede ser anterior a la fecha de despacho.'
            )

    horas = {}
    for clave, etiqueta in (
        ('hora_llegada_planta', 'Hora llegada a planta'),
        ('hora_llegada_destino', 'Hora llegada a destino'),
    ):
        try:
            horas[clave] = datetime.strptime(
                str(item.get(clave)).strip(), '%H:%M'
            ).strftime('%H:%M')
        except ValueError as exc:
            raise ValueError(f'{etiqueta} debe tener formato HH:MM.') from exc

    item.update({
        'fecha_despacho': fecha_despacho.isoformat(),
        'hora_llegada_planta': horas['hora_llegada_planta'],
        'hora_llegada_destino': horas['hora_llegada_destino'],
        # Se conserva el campo textual legacy como respaldo de lectura.
        'ventana_horaria_despacho': horas['hora_llegada_planta'],
        'destino': str(campos['destino']).strip(),
        'orden_carga': str(item.get('orden_carga')).strip(),
    })
    if fecha_llegada_destino:
        item['fecha_llegada_destino'] = fecha_llegada_destino.isoformat()
    return item


def validar_transportes_borradores_despacho_sbh(citaciones, empresa_id, resolver_direcciones=None):
    """Valida y normaliza el transporte independiente de cada borrador SBH."""
    resolver_direcciones = resolver_direcciones or consultar_direcciones_despacho_sap
    direcciones_cache = {}
    for indice, item in enumerate(citaciones, start=1):
        condicion = str(
            item.get('condicion_entrega')
            or item.get('transportado_por')
            or item.get('inf_24hrs')
            or ''
        ).strip()
        if condicion not in {'Terramar', 'Cliente'}:
            raise ValueError(
                f'Borrador {indice}: debe seleccionar Condici\u00f3n de entrega.'
            )

        cliente_codigo = str(item.get('cliente_codigo') or item.get('cliente') or '').strip()
        direccion_codigo = str(item.get('direccion_despacho_sap_codigo') or '').strip()
        if not cliente_codigo:
            raise ValueError(f'Borrador {indice}: falta el cliente SAP de la dirección de despacho.')
        if not direccion_codigo:
            raise ValueError(f'Borrador {indice}: debe seleccionar una dirección de despacho SAP.')

        if cliente_codigo not in direcciones_cache:
            direcciones_cache[cliente_codigo] = resolver_direcciones(
                cliente_codigo, empresa_id=empresa_id
            )
        direcciones = direcciones_cache[cliente_codigo] or []
        direccion_sap = next((
            direccion for direccion in direcciones
            if str(direccion.get('direccion_codigo') or '').strip() == direccion_codigo
            and str(direccion.get('tipo_direccion') or '').strip().upper() == 'S'
            and str(direccion.get('cliente_codigo') or '').strip() == cliente_codigo
        ), None)
        if not direccion_sap:
            raise ValueError(
                f'Borrador {indice}: la dirección SAP no pertenece al cliente o no es de despacho.'
            )
        destino_resuelto = resolver_destino_despacho_sap(direccion_sap)
        direccion_texto = ' - '.join(filter(None, (
            direccion_codigo,
            str(direccion_sap.get('calle') or '').strip(),
            str(direccion_sap.get('ciudad') or '').strip(),
        )))

        limpiar = lambda valor: re.sub(r'\s+', ' ', str(valor or '')).strip()
        empresa_transporte = limpiar(
            item.get('empresa_transporte_manual') or item.get('empresa_transporte')
        )
        conductor_nombre = limpiar(
            item.get('conductor_manual') or item.get('conductor')
        )
        patente = limpiar(item.get('patente')).upper()

        item.update({
            'condicion_entrega': condicion,
            'transportado_por': condicion,
            'inf_24hrs': condicion,
            'patente': patente,
            'direccion_despacho_sap_codigo': direccion_codigo,
            'direccion_despacho_sap_texto': direccion_texto,
            'destino': direccion_codigo,
            '_destino_despacho_sbh': destino_resuelto,
        })

        if condicion == 'Cliente':
            item.update({
                'empresa_transporte': empresa_transporte,
                'empresa_transporte_id': '',
                'proveedor': '',
                'proveedor_codigo': '',
                'codigo_proveedor_sap': '',
                'proveedor_nombre': empresa_transporte,
                'proveedor_sap': '',
                'conductor': conductor_nombre,
                'conductor_id': '',
                'ingreso_manual_transporte': True,
                'ruta_id': '',
                'tarifa_id': '',
                'valor_tarifa': '',
                '_tarifa_planificacion': None,
            })
        else:
            transportista_id = str(item.get('empresa_transporte_id') or '').strip()
            if not transportista_id.isdigit():
                raise ValueError(
                    f'Borrador {indice}: debe seleccionar una Empresa Transporte v\u00e1lida.'
                )
            transportista = SOCIONEGOCIO.objects.filter(
                pk=transportista_id,
                EP_NID_id=empresa_id,
                SN_CTIPO='S',
                SN_BHABILITADO=True,
            ).exclude(SN_CRUT='55555555-5').first()
            if not transportista:
                raise ValueError(
                    f'Borrador {indice}: la Empresa Transporte no pertenece a SBH o no est\u00e1 habilitada.'
                )

            tarifa_planificacion, error_alternativa = validar_alternativa_transporte_sbh(
                destino_resuelto=destino_resuelto,
                transportista_id=transportista.id,
                ruta_id=item.get('ruta_id'),
                tarifa_id=item.get('tarifa_id'),
            )
            if error_alternativa:
                raise ValueError(f'Borrador {indice}: {error_alternativa}')
            transportista = tarifa_planificacion.SN_NID

            conductor_id = str(item.get('conductor_id') or '').strip()
            conductor = None
            if conductor_id:
                if not conductor_id.isdigit():
                    raise ValueError(
                        f'Borrador {indice}: el conductor seleccionado no es v\u00e1lido.'
                    )
                conductor = CONDUCTOR.objects.filter(
                    pk=conductor_id,
                    CON_BHABILITADO=True,
                ).first()
                if not conductor:
                    raise ValueError(
                        f'Borrador {indice}: el conductor seleccionado no est\u00e1 habilitado.'
                    )
                conductor_nombre = f'{conductor.CON_CNOMBRE or ""} {conductor.CON_CAPELLIDO or ""}'.strip()
            elif conductor_nombre:
                raise ValueError(
                    f'Borrador {indice}: seleccione el conductor desde el maestro o d\u00e9jelo vac\u00edo.'
                )

            item.update({
                'empresa_transporte': transportista.SN_CRAZONSOCIAL,
                'empresa_transporte_manual': '',
                'empresa_transporte_id': str(transportista.id),
                'proveedor': '',
                'proveedor_codigo': '',
                'codigo_proveedor_sap': '',
                'proveedor_nombre': transportista.SN_CRAZONSOCIAL,
                'proveedor_sap': transportista.SN_CRAZONSOCIAL,
                'conductor': conductor_nombre,
                'conductor_manual': '',
                'conductor_id': str(conductor.id) if conductor else '',
                'ingreso_manual_transporte': False,
                'ruta_id': str(tarifa_planificacion.RUT_NID_id),
                'tarifa_id': str(tarifa_planificacion.id),
                'valor_tarifa': str(tarifa_planificacion.TAR_NVALOR),
                '_tarifa_planificacion': tarifa_planificacion,
            })

        if not normalizar_salida_documento_despacho(item.get('salida_documento')):
            raise ValueError(
                f'Borrador {indice}: debe seleccionar Salida de documento.'
            )

    return citaciones


def normalizar_carga_despacho_terramar_etapa0(item):
    """Valida y normaliza la carga exclusiva de Despacho Terramar Etapa 0."""
    if str(item.get('tipo_camion') or '').strip() not in {'Plano', 'Cortina'}:
        raise ValueError('Tipo de camión inválido para Despacho Terramar.')
    for campo in ('pallet', 'relleno'):
        if str(item.get(campo) or '').strip().upper() not in {'SI', 'NO'}:
            raise ValueError(f'El valor de {campo} debe ser Sí o No.')

    requeridos = {
        'contenedor 1 / CRT': item.get('contenedor_crt'),
        'peso 1': item.get('peso_1'),
        'N° Maxis 1': item.get('maxis_1'),
    }
    faltantes = [
        nombre for nombre, valor in requeridos.items()
        if str(valor or '').strip() == ''
    ]
    if faltantes:
        raise ValueError('Debe completar: ' + ', '.join(faltantes) + '.')

    relleno_activo = str(item.get('relleno') or '').strip().upper() == 'SI'
    if relleno_activo:
        requeridos_relleno = {
            'contenedor 2 / CRT': item.get('contenedor_2_crt'),
            'peso 2': item.get('peso_2'),
            'N° Maxis 2': item.get('maxis_2'),
        }
        faltantes_relleno = [
            nombre for nombre, valor in requeridos_relleno.items()
            if str(valor or '').strip() == ''
        ]
        if faltantes_relleno:
            raise ValueError(
                'Para carga con relleno debe completar: '
                + ', '.join(faltantes_relleno) + '.'
            )
    else:
        item.update({'contenedor_2_crt': '', 'peso_2': '', 'maxis_2': ''})

    for clave, etiqueta in (('peso_1', 'Peso 1'), ('peso_2', 'Peso 2')):
        if clave == 'peso_2' and not relleno_activo:
            continue
        try:
            peso = Decimal(str(item.get(clave) or '').strip().replace(',', '.'))
        except (InvalidOperation, ValueError):
            raise ValueError(f'{etiqueta} debe ser un número válido.')
        if not peso.is_finite() or peso <= 0:
            raise ValueError(f'{etiqueta} debe ser mayor que cero.')
        item[clave] = str(peso)

    for clave, etiqueta in (('maxis_1', 'N° Maxis 1'), ('maxis_2', 'N° Maxis 2')):
        if clave == 'maxis_2' and not relleno_activo:
            continue
        valor = str(item.get(clave) or '').strip()
        if not valor.isdigit() or int(valor) <= 0:
            raise ValueError(f'{etiqueta} debe ser un entero mayor que cero.')
        item[clave] = str(int(valor))

    item['patente_rampla'] = re.sub(
        r'\s+', ' ', str(item.get('patente_rampla') or '')
    ).strip().upper()
    item['contenedor_crt'] = str(item.get('contenedor_crt') or '').strip()
    item['contenedor_2_crt'] = str(item.get('contenedor_2_crt') or '').strip()
    return item


@transaction.atomic
def CREAR_PLANIFICACION_CITACION(request):
    try:
        if request.method != 'POST':
            return JsonResponse({'success': False, 'message': 'Método no permitido.'})

        Empresa = Verificar_empresa(request)

        if Empresa is None:
            return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'})

        usuario = request.user
        planificacion_existente_id = str(request.POST.get('planificacion_existente_id') or '').strip()
        planificacion_existente = None
        formulario_etapa0_existente = ''
        if planificacion_existente_id:
            if not (usuario.is_superuser or usuario_es_planificador(usuario) or validar_perfiles_activos(usuario.id, 'pla_addone')):
                return JsonResponse({'success': False, 'message': 'No tiene permisos para agregar citaciones.'}, status=403)
            if not planificacion_existente_id.isdigit():
                return JsonResponse({'success': False, 'message': 'Planificación no válida para este modo.'}, status=400)
            planificacion_existente = PLANIFICACION.objects.select_for_update().filter(
                pk=planificacion_existente_id,
                EP_NID_id=Empresa,
                PL_CTIPOCUPO__in=(CIT_RECEPCION, CIT_DESPACHO),
                PL_BARCHIVADO=False,
                PL_FFECHAINICIO__isnull=False,
            ).first()
            if not planificacion_existente:
                return JsonResponse({'success': False, 'message': 'Planificación activa no encontrada en la empresa seleccionada.'}, status=404)
            formulario_etapa0_existente = resolver_formulario_etapa0(planificacion_existente)
            if not formulario_etapa0_existente:
                return JsonResponse({'success': False, 'message': 'La planificación no tiene un formulario Etapa 0 vigente y homogéneo.'}, status=404)
        solicitud_patio = None
        solicitud_patio_id = str(request.POST.get('solicitud_no_planificado_id') or '').strip()
        if planificacion_existente and solicitud_patio_id:
            return JsonResponse({'success': False, 'message': 'Agregar citaciones no admite solicitudes de camión no planificado.'}, status=400)
        if solicitud_patio_id:
            if not usuario_puede_revisar_no_planificado_patio(usuario):
                return JsonResponse({'success': False, 'message': 'No tiene permisos para completar esta solicitud.'}, status=403)
            solicitud_patio = CAMION_PATIO_NO_PLANIFICADO.objects.select_for_update().select_related(
                'CPA_NID', 'EP_NID'
            ).filter(pk=solicitud_patio_id, EP_NID_id=Empresa).first()
            if not solicitud_patio:
                return JsonResponse({'success': False, 'message': 'Solicitud de camion no planificado no encontrada.'}, status=404)
            if solicitud_patio.CPNP_CESTADO != CAMION_PATIO_NO_PLANIFICADO.ESTADO_APROBADO_PENDIENTE_PLANIFICACION:
                return JsonResponse({'success': False, 'message': 'La solicitud ya no esta pendiente de crear planificacion.'}, status=409)
            if solicitud_patio.PL_NID_id:
                return JsonResponse({'success': False, 'message': 'La solicitud ya tiene una planificacion vinculada.'}, status=409)

        citaciones_json = request.POST.get('citaciones_json', '[]')
        es_sobrecupo = (
            request.POST.get('es_sobrecupo')
            or request.POST.get('es_sobrecupo_planificacion')
            or 'No'
        ).strip()
        cantidad_sobrecupo_raw = (
            request.POST.get('cantidad_sobrecupo')
            or request.POST.get('cantidad_sobrecupo_planificacion')
            or '0'
        )

        try:
            citaciones_data = json.loads(citaciones_json)
        except Exception:
            return JsonResponse({'success': False, 'message': 'No se pudieron leer las citaciones enviadas.'})

        if not citaciones_data:
            return JsonResponse({'success': False, 'message': 'Debe agregar al menos una citación antes de guardar.'})

        primera_citacion = citaciones_data[0]

        fecha_llegada = primera_citacion.get('fecha_llegada', '').strip()
        tipo_operacion = primera_citacion.get('tipo_operacion', '').strip()

        if not fecha_llegada:
            return JsonResponse({'success': False, 'message': 'Debe ingresar fecha de llegada.'})

        if not tipo_operacion:
            return JsonResponse({'success': False, 'message': 'Debe seleccionar tipo de operación.'})

        cantidad_repetir = len(citaciones_data)
        try:
            cantidad_sobrecupo = int(cantidad_sobrecupo_raw)
        except (TypeError, ValueError):
            cantidad_sobrecupo = 0

        if cantidad_sobrecupo < 0:
            cantidad_sobrecupo = 0

        pl_sobrecupo = es_sobrecupo.lower() in ['si', 'sí', 'true', '1', 'on'] or cantidad_sobrecupo > 0

        fecha_llegada_obj = datetime.strptime(fecha_llegada, '%Y-%m-%d')
        if planificacion_existente:
            fecha_planificacion = planificacion_existente.PL_FFECHAINICIO
            if timezone.is_aware(fecha_planificacion):
                fecha_planificacion = timezone.localtime(fecha_planificacion)
            if (
                tipo_operacion.upper() != planificacion_existente.PL_CTIPOCUPO
                or fecha_llegada_obj.date() != fecha_planificacion.date()
                or any(
                    str(item.get('tipo_operacion') or '').upper() != planificacion_existente.PL_CTIPOCUPO
                    or str(item.get('fecha_llegada') or '') != fecha_llegada
                    for item in citaciones_data
                )
            ):
                return JsonResponse({'success': False, 'message': 'Las citaciones deben usar el tipo y la fecha de la planificación.'}, status=400)
            espera_recepcion_terramar = formulario_etapa0_existente == 'recepcion_terramar'
            espera_despacho_terramar = formulario_etapa0_existente == 'despacho_terramar'
            if any(
                bool(item.get('recepcion_terramar')) != espera_recepcion_terramar
                or bool(item.get('despacho_terramar')) != espera_despacho_terramar
                for item in citaciones_data
            ):
                return JsonResponse({'success': False, 'message': 'El formulario enviado no corresponde al flujo de esta planificación.'}, status=400)
            if formulario_etapa0_existente in {'recepcion_sbh', 'transferencia_sbh'}:
                flujo_esperado = ('TRANSFERENCIA' if formulario_etapa0_existente == 'transferencia_sbh'
                                  else 'INGRESO_MERCADERIA')
                if str(request.POST.get('flujo') or '').strip().upper() != flujo_esperado:
                    return JsonResponse({'success': False, 'message': 'El flujo enviado no corresponde a esta planificación.'}, status=400)
            else:
                secuencias_permitidas_existente = {
                    'despacho_sbh': {flujo[0] for flujo in FLUJOS_DESPACHO_ETAPA_0},
                    'recepcion_terramar': {'RECEPCION_TERRAMAR', 'RECEPCION_TERRAMAR_BODEGA_EXTERNA'},
                    'despacho_terramar': {flujo[0] for flujo in FLUJOS_DESPACHO_TERRAMAR_ETAPA_0},
                }[formulario_etapa0_existente]
                for item in citaciones_data:
                    secuencia_item_id = str(item.get('secuencia_id') or '').strip()
                    if not secuencia_item_id.isdigit() or not SECUENCIA.objects.filter(
                        pk=secuencia_item_id, EP_NID_id=Empresa,
                        SE_CTIPO=planificacion_existente.PL_CTIPOCUPO,
                        SE_CCODIGO__in=secuencias_permitidas_existente,
                        SE_BHABILITADO=True,
                    ).exists():
                        return JsonResponse({'success': False, 'message': 'La secuencia no corresponde al formulario de esta planificación.'}, status=400)
        es_recepcion_terramar = (
            empresa_es_terramar_chile(Empresa)
            and str(primera_citacion.get('tipo_operacion') or '').upper() == 'RECEPCION'
            and bool(primera_citacion.get('recepcion_terramar'))
        )
        es_despacho_terramar = (
            empresa_es_terramar_chile(Empresa)
            and str(primera_citacion.get('tipo_operacion') or '').upper() == CIT_DESPACHO
            and bool(primera_citacion.get('despacho_terramar'))
        )
        es_despacho_sbh_etapa0 = (
            Empresa == ID_ACEITES_SBH
            and str(primera_citacion.get('tipo_operacion') or '').strip().upper() == CIT_DESPACHO
        )

        es_recepcion_sbh = (
            Empresa == ID_ACEITES_SBH
            and str(primera_citacion.get('tipo_operacion') or '').strip().upper() == CIT_RECEPCION
        )
        flujo_recepcion_sbh = ''
        if es_recepcion_sbh:
            flujo_recibido = str(request.POST.get('flujo') or '').strip().upper()
            if flujo_recibido and flujo_recibido not in FLUJOS_NAVEGACION_RECEPCION_SBH:
                return JsonResponse({
                    'success': False,
                    'message': 'El flujo de Recepción SBH no es válido.',
                }, status=400)
            # Las integraciones previas que no enviaban el parámetro continúan
            # siendo ingreso de mercadería; el formulario actual siempre lo envía.
            flujo_recepcion_sbh = normalizar_flujo_recepcion_sbh(flujo_recibido)
            secuencias_permitidas = queryset_secuencias_recepcion_sbh_por_flujo(
                Empresa,
                flujo_recepcion_sbh,
            )
            if planificacion_existente:
                secuencias_actuales = set(CITACION.objects.filter(
                    PL_NID=planificacion_existente, CI_BHABILITADO=True,
                ).values_list('SC_NID_id', flat=True))
                secuencias_del_flujo = set(secuencias_permitidas.values_list('id', flat=True))
                if not secuencias_actuales or not secuencias_actuales.issubset(secuencias_del_flujo):
                    return JsonResponse({'success': False, 'message': 'El flujo no coincide con las secuencias de esta planificación.'}, status=400)
            secuencia_transferencia = None
            if flujo_recepcion_sbh == 'TRANSFERENCIA':
                secuencia_transferencia = secuencias_permitidas.filter(
                    SE_CCODIGO=SECUENCIA_RECEPCION_TRANSFERENCIA_SBH,
                ).first()
                if not secuencia_transferencia:
                    return JsonResponse({
                        'success': False,
                        'message': 'No existe una secuencia activa para Recepción de Transferencia SBH.',
                    }, status=400)
            for item in citaciones_data:
                flujo_item = str(item.get('flujo') or '').strip().upper()
                if flujo_item and flujo_item != flujo_recepcion_sbh:
                    return JsonResponse({
                        'success': False,
                        'message': 'El flujo informado en la citación no coincide con el flujo de guardado.',
                    }, status=400)
                item['flujo'] = flujo_recepcion_sbh
                if secuencia_transferencia:
                    secuencia_enviada = str(item.get('secuencia_id') or '').strip()
                    if secuencia_enviada and secuencia_enviada != str(secuencia_transferencia.pk):
                        return JsonResponse({
                            'success': False,
                            'message': 'La secuencia enviada no corresponde a Transferencia.',
                        }, status=400)
                    item['secuencia_id'] = secuencia_transferencia.pk
                    continue
                secuencia_item_id = str(item.get('secuencia_id') or '').strip()
                if not secuencia_item_id.isdigit() or not secuencias_permitidas.filter(
                    pk=secuencia_item_id
                ).exists():
                    etiqueta_flujo = (
                        'Transferencia' if flujo_recepcion_sbh == 'TRANSFERENCIA'
                        else 'Ingreso de mercadería'
                    )
                    return JsonResponse({
                        'success': False,
                        'message': f'La secuencia seleccionada no es válida para {etiqueta_flujo}.',
                    }, status=400)


            if flujo_recepcion_sbh == 'INGRESO_MERCADERIA':
                ids_secuencia = [
                    int(str(item.get('secuencia_id')).strip())
                    for item in citaciones_data
                    if str(item.get('secuencia_id') or '').strip().isdigit()
                ]
                codigos_secuencia = dict(
                    secuencias_permitidas.filter(pk__in=ids_secuencia).values_list('id', 'SE_CCODIGO')
                )
                items_prosesa_piso_2 = [
                    item for item in citaciones_data
                    if codigos_secuencia.get(
                        int(str(item.get('secuencia_id')).strip())
                    ) == SECUENCIA_RECEPCION_PROSESA_PISO_2
                ]
                if items_prosesa_piso_2 and len(citaciones_data) != 1:
                    return JsonResponse({
                        'success': False,
                        'message': 'Contenedor a Piso 2 debe crear exactamente una citación.',
                    }, status=400)

                for item in citaciones_data:
                    secuencia_codigo = codigos_secuencia.get(
                        int(str(item.get('secuencia_id')).strip())
                    )
                    item['_secuencia_codigo'] = secuencia_codigo or ''
                    if secuencia_codigo == SECUENCIA_RECEPCION_PROSESA_PISO_2:
                        guia = str(item.get('guia_origen_prosesa') or '').strip()
                        if not guia:
                            return JsonResponse({
                                'success': False,
                                'message': 'Contenedor a Piso 2 requiere el número de guía de la Citación 1.',
                            }, status=400)
                        try:
                            citacion_origen, datos_origen = cargar_snapshot_prosesa_piso_2(
                                guia, bloquear=True
                            )
                        except ProsesaPiso2SnapshotError as exc:
                            return JsonResponse({
                                'success': False,
                                'message': str(exc),
                            }, status=exc.status_code)
                        item.update(datos_origen)
                        try:
                            item.update(
                                validar_camion_retiro_planificado_prosesa_piso_2(item)
                            )
                        except ValueError as exc:
                            return JsonResponse({
                                'success': False,
                                'message': str(exc),
                            }, status=400)
        if planificacion_existente:
            secuencias_de_la_carpeta = {str(secuencia_id) for secuencia_id in CITACION.objects.filter(
                PL_NID=planificacion_existente, CI_BHABILITADO=True,
            ).values_list('SC_NID_id', flat=True)}
            if any(
                str(item.get('secuencia_id') or '').strip() not in secuencias_de_la_carpeta
                for item in citaciones_data
            ):
                return JsonResponse({
                    'success': False,
                    'message': 'La secuencia debe corresponder a esta planificación.',
                }, status=400)

        es_recepcion_transferencia_sbh = (
            es_recepcion_sbh and flujo_recepcion_sbh == 'TRANSFERENCIA'
        )
        if es_recepcion_terramar or es_despacho_terramar:
            hora_citacion = str(primera_citacion.get('hora_citacion') or '').strip()
            try:
                hora_citacion_obj = datetime.strptime(hora_citacion, '%H:%M').time()
            except ValueError:
                return JsonResponse({'success': False, 'message': 'Debe ingresar una hora de citación válida.'}, status=400)
            fecha_llegada_obj = datetime.combine(fecha_llegada_obj.date(), hora_citacion_obj)
            if timezone.is_naive(fecha_llegada_obj) and timezone.is_aware(timezone.now()):
                fecha_llegada_obj = timezone.make_aware(fecha_llegada_obj, timezone.get_current_timezone())
        fecha_termino_obj = fecha_llegada_obj.replace(hour=23, minute=59, second=0)

        if es_recepcion_terramar or es_despacho_terramar:
            for item in citaciones_data:
                item_id = str(item.get('item_id') or '').strip()
                if not item_id.isdigit() or not (queryset_insumos_despacho_terramar(Empresa) if es_despacho_terramar else queryset_insumos_recepcion_terramar(Empresa)).filter(pk=int(item_id)).exists():
                    return JsonResponse({
                        'success': False,
                        'message': 'Debe seleccionar un insumo válido del catálogo Terramar.'
                    }, status=400)
        if es_despacho_terramar:
            try:
                clientes_sap_despacho_terramar = {
                    str(cliente.get('cardcode') or '').strip(): cliente
                    for cliente in consultar_clientes_sap().get('clientes', [])
                    if str(cliente.get('cardcode') or '').strip()
                }
            except SapDiApiError as exc:
                return JsonResponse({'success': False, 'message': str(exc)}, status=503)

            for item in citaciones_data:
                cliente_codigo_sap = str(item.get('cliente_codigo') or item.get('cliente') or '').strip()
                cliente_nombre_sap = str(item.get('cliente_nombre') or '').strip()
                cliente_sap = clientes_sap_despacho_terramar.get(cliente_codigo_sap)
                if not cliente_codigo_sap or not cliente_nombre_sap or not cliente_sap:
                    return JsonResponse({
                        'success': False,
                        'message': 'Debe seleccionar un cliente válido del catálogo SAP.'
                    }, status=400)
                item.update({
                    'cliente': cliente_sap['cardcode'],
                    'cliente_codigo': cliente_sap['cardcode'],
                    'cliente_nombre': cliente_sap['cardname'],
                })
                conductor_pendiente = (
                    str(item.get('transporte_a_cargo') or '').strip() == 'Terramar'
                    and str(item.get('conductor_pendiente') or '').strip().lower() in {'1', 'true', 'on', 'yes', 'si', 'sí'}
                )
                if conductor_pendiente:
                    transportista_id = str(item.get('empresa_transporte_id') or '').strip()
                    if not transportista_id.isdigit() or not SOCIONEGOCIO.objects.filter(
                        pk=transportista_id,
                        EP_NID_id=Empresa,
                        SN_CTIPO='S',
                        SN_BHABILITADO=True,
                    ).exists():
                        return JsonResponse({
                            'success': False,
                            'message': 'Debe seleccionar un transportista válido.'
                        }, status=400)

        if es_recepcion_transferencia_sbh:
            for item in citaciones_data:
                if str(item.get('tipo_operacion', tipo_operacion) or '').strip().upper() != CIT_RECEPCION or str(item.get('flujo') or '').strip().upper() != 'TRANSFERENCIA':
                    return JsonResponse({'success': False, 'message': 'La planificación de transferencia sólo permite Recepción de Transferencia.'}, status=400)
                faltantes = [nombre for nombre, valor in {
                    'fecha': item.get('fecha_llegada'),
                    'cantidad de camiones': item.get('cantidad_camion'),
                    'almacén destino': item.get('almacen_destino'),
                    'estanque destino': item.get('estanque_destino'),
                }.items() if str(valor or '').strip() == '']
                if faltantes:
                    return JsonResponse({'success': False, 'message': 'Debe completar: ' + ', '.join(faltantes) + '.'}, status=400)
                cantidad_camiones, mensaje_cantidad_camiones = validar_cantidad_camiones_transferencia(
                    item.get('cantidad_camion')
                )
                if mensaje_cantidad_camiones:
                    return JsonResponse({'success': False, 'message': mensaje_cantidad_camiones}, status=400)
                if cantidad_camiones != 1:
                    return JsonResponse({'success': False, 'message': 'Cada borrador de transferencia debe representar exactamente un camión.'}, status=400)
                destino_valido, mensaje_destino = validar_destino_recepcion_sbh(
                    str(item.get('almacen_destino') or '').strip(),
                    str(item.get('estanque_destino') or '').strip(),
                )
                if not destino_valido:
                    return JsonResponse({'success': False, 'message': mensaje_destino}, status=400)
                movimientos_recibidos = item.get('movimientos')
                if not isinstance(movimientos_recibidos, list):
                    movimientos_recibidos = [{
                        'estanque_origen': item.get('estanque_origen'),
                        'codigo_sap': item.get('codigo_sap') or item.get('codigo'),
                        'cantidad_a_mover': item.get('cantidad_a_mover'),
                    }]
                try:
                    movimientos_validados = validar_movimientos_recepcion_transferencia_sbh(
                        movimientos_recibidos
                    )
                except ValueError as exc:
                    return JsonResponse({'success': False, 'message': str(exc)}, status=400)
                except SapDiApiError as exc:
                    return JsonResponse({'success': False, 'message': str(exc)}, status=503)

                snapshot_sap = movimientos_validados[0]
                item.update({
                    'codigo': snapshot_sap['codigo_sap'],
                    'codigo_sap': snapshot_sap['codigo_sap'],
                    'insumo': snapshot_sap['insumo'],
                    'codigo_propietario': snapshot_sap['codigo_propietario'],
                    'propiedad_producto': snapshot_sap['propiedad_producto'],
                    'cantidad_disponible': snapshot_sap['stock_disponible_snapshot'],
                    'stock_disponible_snapshot': snapshot_sap['stock_disponible_snapshot'],
                    'unidad_inventario_snapshot': snapshot_sap['unidad_inventario_snapshot'],
                    'cantidad_camion': 1,
                    'cantidad_a_mover': snapshot_sap['cantidad_a_mover'],
                    'movimientos': movimientos_validados,
                })
        elif Empresa == ID_ACEITES_SBH:
            for item in citaciones_data:
                if str(item.get('tipo_operacion', tipo_operacion) or '').strip().upper() != CIT_RECEPCION:
                    continue
                tipo_recepcion_sbh, mensaje_tipo_recepcion = validar_tipo_recepcion_sbh(
                    item.get('tipo_origen_recepcion'),
                    flujo_recepcion_sbh,
                )
                if mensaje_tipo_recepcion:
                    return JsonResponse({
                        'success': False,
                        'message': mensaje_tipo_recepcion,
                    }, status=400)
                item['tipo_origen_recepcion'] = tipo_recepcion_sbh
                almacen_destino = str(item.get('almacen_destino') or '').strip()
                estanque_destino = str(item.get('estanque_destino') or '').strip()
                if not almacen_destino or not estanque_destino:
                    return JsonResponse({
                        'success': False,
                        'message': 'Debe seleccionar almacén y estanque de destino.'
                    }, status=400)
                destino_valido, mensaje_destino = validar_destino_recepcion_sbh(
                    almacen_destino,
                    estanque_destino,
                )
                if not destino_valido:
                    return JsonResponse({
                        'success': False,
                        'message': mensaje_destino,
                    }, status=400)
                try:
                    item['_proveedor_manual_sbh'] = normalizar_proveedor_recepcion_sbh_etapa_0(
                        item, Empresa
                    )
                except ValueError as exc:
                    return JsonResponse({'success': False, 'message': str(exc)}, status=400)
                if flujo_recepcion_sbh == 'INGRESO_MERCADERIA':
                    proveedor_final, mensaje_proveedor = normalizar_proveedor_ingreso_mercaderia_sbh(item)
                    if mensaje_proveedor:
                        return JsonResponse({
                            'success': False,
                            'message': mensaje_proveedor,
                        }, status=400)
                    item['proveedor_nombre'] = proveedor_final
                    item['proveedor_sap'] = proveedor_final

        if es_despacho_sbh_etapa0:
            acuerdos_sap_cache = {}

            def resolver_acuerdo_sap(asignacion):
                numero = str(asignacion.get('contrato_sap') or '').strip()
                if numero not in acuerdos_sap_cache:
                    acuerdos_sap_cache[numero] = consultar_acuerdos_despacho(numero, Empresa).get('resultados', [])
                identidad = (
                    str(asignacion.get('sap_abs_id') or '').strip(),
                    numero,
                    str(asignacion.get('linea_acuerdo_sap') or '').strip(),
                    str(asignacion.get('codigo_producto_sap') or '').strip(),
                    str(asignacion.get('cliente_codigo') or '').strip(),
                )
                return next((fila for fila in acuerdos_sap_cache[numero] if (
                    str(fila.get('sap_abs_id') or '').strip(),
                    str(fila.get('sap_acuerdo_numero') or '').strip(),
                    str(fila.get('linea_acuerdo') or '').strip(),
                    str(fila.get('codigo_insumo') or '').strip(),
                    str(fila.get('cliente_codigo') or '').strip(),
                ) == identidad), None)

            try:
                validar_lote_borradores_sbh(citaciones_data, resolver_acuerdo=resolver_acuerdo_sap)
                validar_transportes_borradores_despacho_sbh(citaciones_data, Empresa)
            except ValueError as exc:
                return JsonResponse({'success': False, 'message': str(exc)}, status=400)
            except SapDiApiError as exc:
                return JsonResponse({'success': False, 'message': str(exc)}, status=503)

        for item in citaciones_data:
            if str(item.get('tipo_operacion', tipo_operacion) or '').strip().upper() != CIT_DESPACHO:
                continue
            try:
                validar_asignaciones_sap_planificadas(item)
            except ValueError as exc:
                return JsonResponse({'success': False, 'message': str(exc)}, status=400)

        if Empresa == ID_ACEITES_SBH:
            for item in citaciones_data:
                if str(item.get('tipo_operacion', tipo_operacion) or '').strip().upper() != CIT_DESPACHO:
                    continue
                try:
                    validar_programacion_despacho_sbh_item(item)
                except ValueError as exc:
                    return JsonResponse({'success': False, 'message': str(exc)}, status=400)


        secuencia_id = primera_citacion.get('secuencia_id')
        secuencia = None

        if secuencia_id:
            secuencia = SECUENCIA.objects.filter(
                pk=secuencia_id,
                EP_NID_id=Empresa,
                SE_CTIPO=tipo_operacion.upper(),
                SE_BHABILITADO=True
            ).first()

        if not secuencia:
            secuencia = SECUENCIA.objects.filter(
                EP_NID_id=Empresa,
                SE_CTIPO=tipo_operacion.upper(),
                SE_BHABILITADO=True
            ).first()

        if not secuencia:
            return JsonResponse({
                'success': False,
                'message': f'No existe una secuencia activa para el tipo {tipo_operacion}.'
            })

        if es_recepcion_transferencia_sbh:
            secuencia = SECUENCIA.objects.filter(
                EP_NID_id=Empresa, SE_CTIPO=CIT_RECEPCION,
                SE_CCODIGO=SECUENCIA_RECEPCION_TRANSFERENCIA_SBH,
                SE_BHABILITADO=True,
            ).first()
            if not secuencia:
                return JsonResponse({'success': False, 'message': 'No existe una secuencia activa para Recepción de Transferencia SBH.'}, status=400)

        if es_recepcion_terramar and not queryset_secuencias_recepcion_terramar(Empresa).filter(pk=secuencia.pk).exists():
            return JsonResponse({
                'success': False,
                'message': 'Debe seleccionar una secuencia de Recepción de Harinas habilitada para Terramar.'
            }, status=400)
        if es_despacho_terramar and secuencia.SE_CCODIGO not in {'DESPACHO_TERRAMAR', 'DESPACHO_TERRAMAR_BODEGA_EXTERNA'}:
            return JsonResponse({
                'success': False,
                'message': 'La secuencia seleccionada no es válida para Despacho Terramar.'
            }, status=400)
        # Etapa 0 RECEPCION con Purchase Order: el saldo proviene de POR1.OpenQty,
        # no del valor editable en el JSON enviado por el navegador.
        for item in citaciones_data:
            if str(item.get('tipo_operacion', tipo_operacion) or '').strip().upper() != CIT_RECEPCION:
                continue
            if es_recepcion_terramar or es_recepcion_transferencia_sbh:
                continue
            if item.get('_secuencia_codigo') == SECUENCIA_RECEPCION_PROSESA_PISO_2:
                continue
            docentry_sap = str(item.get('sap_opor_id') or item.get('docentry') or '').strip()
            if not docentry_sap:
                if str(item.get('pedido') or '').strip():
                    return JsonResponse({
                        'success': False,
                        'message': 'No se pudo identificar la línea SAP seleccionada para planificar.',
                    }, status=400)
                continue  # Flujos de recepción sin Purchase Order.
            try:
                linea_sap = consultar_saldo_linea_pedido_sap(
                    docentry_sap, item.get('codigo') or item.get('codigo_sap'), item.get('line_num'),
                )
                saldo_sap = Decimal(str(linea_sap['OpenQty']))
            except ValueError as exc:
                return JsonResponse({'success': False, 'message': str(exc)}, status=400)
            except (SapDiApiError, KeyError, TypeError, InvalidOperation) as exc:
                return JsonResponse({
                    'success': False,
                    'message': f'No fue posible validar el saldo disponible SAP: {exc}',
                }, status=503)
            if (str(linea_sap.get('DocStatus') or '').upper() != 'O'
                    or not saldo_sap.is_finite() or saldo_sap <= Decimal('0')):
                return JsonResponse({
                    'success': False,
                    'message': 'No se puede planificar: la línea SAP seleccionada no tiene cantidad disponible.',
                }, status=400)
            item['cantidad_disponible'] = str(saldo_sap)
            item['sap_opor_id'] = str(linea_sap.get('DocEntry') or docentry_sap)
            item['docentry'] = item['sap_opor_id']
            item['pedido'] = str(linea_sap.get('DocNum') or item.get('pedido') or '')
            item['line_num'] = linea_sap['LineNum']
        if empresa_es_terramar_chile(Empresa):
            for item in citaciones_data:
                if (
                    str(item.get('tipo_operacion', tipo_operacion) or '').strip().upper() == CIT_DESPACHO
                    and bool(item.get('despacho_terramar'))
                ):
                    try:
                        normalizar_carga_despacho_terramar_etapa0(item)
                    except ValueError as exc:
                        return JsonResponse({'success': False, 'message': str(exc)}, status=400)

        calendario = CALENDARIO.objects.filter(
            EP_NID_id=Empresa,
            CA_NDIA=fecha_llegada_obj.day,
            CA_NMES=fecha_llegada_obj.month,
            CA_NANO=fecha_llegada_obj.year,
            CA_BHABILITADO=True
        ).first()

        if not calendario and not planificacion_existente:
            calendario = CALENDARIO.objects.create(
                CA_CNOMBRE=f'ACEITES SBH: {fecha_llegada_obj.day}/{fecha_llegada_obj.month}/{fecha_llegada_obj.year}',
                CA_FHORA_APERTURA=time(0, 0),
                CA_FHORA_CIERRE=time(23, 59),
                CA_NDIA=fecha_llegada_obj.day,
                CA_NMES=fecha_llegada_obj.month,
                CA_NANO=fecha_llegada_obj.year,
                CA_NCANTIDADCUPOS=50,
                CA_BIS_FERIADO=False,
                CA_BHABILITADO=True,
                US_NID=usuario,
                EP_NID_id=Empresa
            )

        if planificacion_existente:
            planificacion = planificacion_existente
            siguiente_numero_cupo = (CITACION.objects.filter(PL_NID=planificacion)
                                     .order_by('-CI_NCUPO').values_list('CI_NCUPO', flat=True).first() or 0) + 1
        else:
            planificacion = PLANIFICACION()
            planificacion.US_NID = usuario
            planificacion.EP_NID_id = Empresa
            planificacion.CAL_NID = calendario
            planificacion.PL_FFECHAREGISTRO = timezone.now()
            planificacion.PL_FFECHAINICIO = fecha_llegada_obj
            planificacion.PL_FFECHAFIN = fecha_termino_obj
            planificacion.PL_CTIPOCUPO = tipo_operacion.upper()
            planificacion.PL_NCANTIDADCUPOS = cantidad_repetir
            planificacion.PL_NSOBRECUPO = pl_sobrecupo
            planificacion.PL_NCANTIDADSOBRECUPO = cantidad_sobrecupo
            planificacion.PL_BARCHIVADO = False
            planificacion.save()
            siguiente_numero_cupo = 1

        citaciones_creadas = []
        operaciones_new_jersey_creadas = []

        for i, item in enumerate(citaciones_data):
            tipo_item_citacion = str(item.get('tipo_operacion', tipo_operacion)).strip().upper()
            es_item_recepcion_terramar = empresa_es_terramar_chile(Empresa) and tipo_item_citacion == CIT_RECEPCION and bool(item.get('recepcion_terramar'))
            es_item_despacho_terramar = empresa_es_terramar_chile(Empresa) and tipo_item_citacion == CIT_DESPACHO and bool(item.get('despacho_terramar'))
            tarifa_planificacion = item.get('_tarifa_planificacion')
            conductor_planificacion = None
            if es_despacho_sbh_etapa0 and item.get('conductor_id'):
                conductor_planificacion = CONDUCTOR.objects.filter(
                    pk=item['conductor_id'], CON_BHABILITADO=True
                ).first()
            if es_item_despacho_terramar:
                requeridos = {
                    'cliente': item.get('cliente') or item.get('cliente_codigo'),
                    'código cliente SAP': item.get('cliente_codigo'),
                    'nombre cliente SAP': item.get('cliente_nombre'),
                    'destino': item.get('destino'),
                    'contenedor 1 / CRT': item.get('contenedor_crt'),
                    'peso 1': item.get('peso_1'),
                    'N° Maxis 1': item.get('maxis_1'),
                    'insumo': item.get('insumo'),
                    'bodega': item.get('bodega'),
                    'tipo camion': item.get('tipo_camion'),
                    'pallet': item.get('pallet'),
                    'relleno': item.get('relleno'),
                    'transporte a cargo de': item.get('transporte_a_cargo'),
                    'hora citacion': item.get('hora_citacion'),
                    'flujo operacional': item.get('secuencia_id'),
                }
                faltantes = [nombre for nombre, valor in requeridos.items() if str(valor or '').strip() == '']
                if faltantes:
                    return JsonResponse({'success': False, 'message': 'Debe completar: ' + ', '.join(faltantes) + '.'}, status=400)
                if str(item.get('tipo_camion') or '').strip() not in {'Plano', 'Cortina'}:
                    return JsonResponse({'success': False, 'message': 'Tipo de camión inválido para Despacho Terramar.'}, status=400)
                for campo in ('pallet', 'relleno'):
                    if str(item.get(campo) or '').strip().upper() not in {'SI', 'NO'}:
                        return JsonResponse({'success': False, 'message': f'El valor de {campo} debe ser Sí o No.'}, status=400)
                try:
                    datetime.strptime(str(item.get('hora_citacion') or '').strip(), '%H:%M')
                except ValueError:
                    return JsonResponse({'success': False, 'message': 'Debe ingresar una hora de citación válida.'}, status=400)
                item['patente'] = re.sub(r'\s+', ' ', str(item.get('patente') or '')).strip().upper()
                item['conductor'] = re.sub(r'\s+', ' ', str(item.get('conductor') or '')).strip()
                item['empresa_transporte'] = re.sub(r'\s+', ' ', str(item.get('empresa_transporte') or '')).strip()
                transporte_a_cargo = str(item.get('transporte_a_cargo') or '').strip()
                if transporte_a_cargo not in {'Terramar', 'Cliente'}:
                    return JsonResponse({'success': False, 'message': 'Transporte a cargo de inválido.'}, status=400)
                conductor_pendiente = (
                    transporte_a_cargo == 'Terramar'
                    and str(item.get('conductor_pendiente') or '').strip().lower() in {'1', 'true', 'on', 'yes', 'si', 'sí'}
                )
                item['conductor_pendiente'] = conductor_pendiente
                if transporte_a_cargo == 'Terramar':
                    transportista_id = str(item.get('empresa_transporte_id') or '').strip()
                    conductor_id = str(item.get('conductor_id') or '').strip()
                    if not transportista_id.isdigit() or (not conductor_pendiente and not conductor_id.isdigit()):
                        mensaje = 'Debe seleccionar un transportista válido.' if conductor_pendiente else 'Debe seleccionar un transportista y conductor válidos.'
                        return JsonResponse({'success': False, 'message': mensaje}, status=400)
                    transportista = SOCIONEGOCIO.objects.filter(pk=transportista_id, EP_NID_id=Empresa, SN_CTIPO='S', SN_BHABILITADO=True).first()
                    conductor = None
                    if transportista and not conductor_pendiente:
                        conductor = CONDUCTOR.objects.filter(pk=conductor_id, CON_BHABILITADO=True).first()
                    if not transportista or (not conductor_pendiente and not conductor):
                        return JsonResponse({'success': False, 'message': 'El transportista no pertenece a la empresa activa o el conductor no está habilitado.'}, status=400)
                    conductor_planificacion = conductor
                    tarifa_planificacion, error_ruta = validar_tarifa_transportista(Empresa, transportista.id, item.get('tarifa_id'), item.get('ruta_id'))
                    if error_ruta:
                        return JsonResponse({'success': False, 'message': error_ruta}, status=400)
                    item.update({
                        'empresa_transporte': transportista.SN_CRAZONSOCIAL,
                        'empresa_transporte_id': str(transportista.id),
                        'ruta_id': str(tarifa_planificacion.RUT_NID_id),
                        'tarifa_id': str(tarifa_planificacion.id),
                    })
                    if conductor_pendiente:
                        item.update({
                            'conductor': '',
                            'conductor_id': '',
                            'telefono_codigo_pais': '',
                            'telefono_conductor': '',
                            'patente': '',
                        })
                    else:
                        if not item['patente']:
                            return JsonResponse({'success': False, 'message': 'Debe ingresar la patente del camión.'}, status=400)
                        try:
                            telefono = normalize_international_phone(item.get('telefono_codigo_pais'), item.get('telefono_conductor'))
                        except ValueError as exc:
                            return JsonResponse({'success': False, 'message': str(exc)}, status=400)
                        item.update({
                            'conductor': f'{conductor.CON_CNOMBRE or ""} {conductor.CON_CAPELLIDO or ""}'.strip(),
                            'telefono_codigo_pais': telefono['country_code'],
                            'telefono_conductor': telefono['local_number'],
                            'conductor_id': str(conductor.id),
                        })
                else:
                    item['conductor_pendiente'] = False
                    manuales = {
                        'empresa transporte': item.get('empresa_transporte'),
                        'conductor': item.get('conductor'),
                        'código país': item.get('telefono_codigo_pais'),
                        'celular conductor': item.get('telefono_conductor'),
                        'patente camión': item.get('patente'),
                    }
                    faltantes_manuales = [nombre for nombre, valor in manuales.items() if not str(valor or '').strip()]
                    if faltantes_manuales:
                        return JsonResponse({'success': False, 'message': 'Debe completar: ' + ', '.join(faltantes_manuales) + '.'}, status=400)
                    try:
                        telefono = normalize_international_phone(item.get('telefono_codigo_pais'), item.get('telefono_conductor'))
                    except ValueError as exc:
                        return JsonResponse({'success': False, 'message': str(exc)}, status=400)
                    item.update({
                        'telefono_codigo_pais': telefono['country_code'],
                        'telefono_conductor': telefono['local_number'],
                        'empresa_transporte_id': '',
                        'conductor_id': '',
                    })
            if es_item_recepcion_terramar:
                requeridos = {
                    'insumo': item.get('insumo'),
                    'bodega': item.get('bodega'),
                    'N° guía despacho': item.get('numero_guia'),
                    'hora citación': item.get('hora_citacion'),
                    'flujo operacional': item.get('secuencia_id'),
                    'transporte a cargo de': item.get('transporte_a_cargo'),
                }
                faltantes = [nombre for nombre, valor in requeridos.items() if not str(valor or '').strip()]
                if faltantes:
                    return JsonResponse({'success': False, 'message': 'Debe completar: ' + ', '.join(faltantes) + '.'}, status=400)
                transporte_a_cargo = str(item.get('transporte_a_cargo') or '').strip()
                if transporte_a_cargo not in {'Terramar', 'Cliente'}:
                    return JsonResponse({'success': False, 'message': 'Transporte a cargo de inválido.'}, status=400)
                item['patente'] = re.sub(r'\s+', ' ', str(item.get('patente') or '')).strip().upper()
                item['conductor'] = re.sub(r'\s+', ' ', str(item.get('conductor') or '')).strip()
                item['empresa_transporte'] = re.sub(r'\s+', ' ', str(item.get('empresa_transporte') or '')).strip()
                item['telefono_conductor'] = str(item.get('telefono_conductor') or '').strip()
                item['telefono_codigo_pais'] = str(item.get('telefono_codigo_pais') or '').strip()
                if transporte_a_cargo == 'Terramar':
                    transportista_id = str(item.get('empresa_transporte_id') or '').strip()
                    conductor_id = str(item.get('conductor_id') or '').strip()
                    if not transportista_id.isdigit() or not conductor_id.isdigit():
                        return JsonResponse({'success': False, 'message': 'Debe seleccionar un transportista y conductor válidos.'}, status=400)
                    transportista = SOCIONEGOCIO.objects.filter(pk=transportista_id, EP_NID_id=Empresa, SN_CTIPO='S', SN_BHABILITADO=True).first()
                    if not transportista:
                        return JsonResponse({'success': False, 'message': 'El transportista no pertenece a la empresa activa.'}, status=400)
                    conductor = CONDUCTOR.objects.filter(pk=conductor_id, CON_BHABILITADO=True).first()
                    if not conductor:
                        return JsonResponse({'success': False, 'message': 'El conductor no está habilitado en el maestro.'}, status=400)
                    if not item['patente']:
                        return JsonResponse({'success': False, 'message': 'Debe ingresar la patente del camión.'}, status=400)
                    tarifa_planificacion, error_ruta = validar_tarifa_transportista(
                        Empresa, transportista.id, item.get('tarifa_id'), item.get('ruta_id')
                    )
                    if error_ruta:
                        return JsonResponse({'success': False, 'message': error_ruta}, status=400)
                    item['ruta_id'] = str(tarifa_planificacion.RUT_NID_id)
                    item['tarifa_id'] = str(tarifa_planificacion.id)
                    try:
                        telefono = normalize_international_phone(item['telefono_codigo_pais'], item['telefono_conductor'])
                    except ValueError as exc:
                        return JsonResponse({'success': False, 'message': str(exc)}, status=400)
                    item.update({'empresa_transporte': transportista.SN_CRAZONSOCIAL, 'conductor': f'{conductor.CON_CNOMBRE or ""} {conductor.CON_CAPELLIDO or ""}'.strip(), 'empresa_transporte_id': str(transportista.id), 'conductor_id': str(conductor.id), 'telefono_codigo_pais': telefono['country_code'], 'telefono_conductor': telefono['local_number']})
                else:
                    item.update({'empresa_transporte': '', 'empresa_transporte_id': '', 'conductor_id': '', 'telefono_codigo_pais': '', 'telefono_conductor': '' if not item['telefono_conductor'] else item['telefono_conductor']})
            if tipo_item_citacion == 'DESPACHO':
                condicion_entrega = str(
                    item.get('condicion_entrega')
                    or item.get('transportado_por')
                    or item.get('inf_24hrs')
                    or ''
                ).strip()
                if condicion_entrega not in ['Terramar', 'Cliente']:
                    return JsonResponse({
                        'success': False,
                        'message': 'Debe seleccionar Condicion de entrega para crear el despacho.'
                    }, status=400)

                def limpiar_texto_despacho(valor):
                    return re.sub(r'\s+', ' ', str(valor or '')).strip()

                empresa_transporte_manual = limpiar_texto_despacho(
                    item.get('empresa_transporte_manual') or item.get('empresa_transporte')
                )
                conductor_manual = limpiar_texto_despacho(
                    item.get('conductor_manual') or item.get('conductor')
                )
                patente_despacho = limpiar_texto_despacho(item.get('patente')).upper()
                item['condicion_entrega'] = condicion_entrega
                item['transportado_por'] = condicion_entrega
                item['inf_24hrs'] = condicion_entrega
                item['patente'] = patente_despacho

                if condicion_entrega == 'Cliente':
                    item['empresa_transporte'] = empresa_transporte_manual
                    item['proveedor_nombre'] = empresa_transporte_manual
                    item['proveedor_sap'] = ''
                    item['proveedor'] = ''
                    item['proveedor_codigo'] = ''
                    item['codigo_proveedor_sap'] = ''
                    item['empresa_transporte_id'] = ''
                    item['conductor'] = conductor_manual
                    item['conductor_id'] = ''
                    item['ingreso_manual_transporte'] = True
                else:
                    item['empresa_transporte'] = limpiar_texto_despacho(item.get('empresa_transporte'))
                    item['empresa_transporte_manual'] = ''
                    item['ingreso_manual_transporte'] = False
                    if es_item_despacho_terramar and item.get('conductor_pendiente'):
                        item.update({
                            'conductor': '',
                            'conductor_manual': '',
                            'conductor_id': '',
                            'telefono_codigo_pais': '',
                            'telefono_conductor': '',
                            'patente': '',
                        })
                        campos_transporte_terramar = {
                            'empresa transporte': item.get('empresa_transporte'),
                        }
                    else:
                        item['conductor'] = limpiar_texto_despacho(item.get('conductor'))
                        item['conductor_manual'] = ''
                        campos_transporte_terramar = {
                            'empresa transporte': item.get('empresa_transporte'),
                        } if es_despacho_sbh_etapa0 else {
                            'empresa transporte': item.get('empresa_transporte'),
                            'conductor': item.get('conductor'),
                            'patente': item.get('patente'),
                        }
                    faltantes_transporte = [
                        etiqueta for etiqueta, valor in campos_transporte_terramar.items()
                        if not str(valor or '').strip()
                    ]
                    if faltantes_transporte:
                        return JsonResponse({
                            'success': False,
                            'message': 'Debe completar los campos de transporte Terramar: ' + ', '.join(faltantes_transporte) + '.'
                        }, status=400)
            cliente_codigo = item.get('cliente_codigo', '').strip()
            proveedor_codigo = item.get('proveedor', '').strip()
            proveedor_codigo_hidden = item.get('proveedor_codigo', '').strip()
            codigo_proveedor_sap = item.get('codigo_proveedor_sap', '').strip()
            proveedor_codigo_final = codigo_proveedor_sap or proveedor_codigo_hidden or proveedor_codigo
            proveedor_sap = item.get('proveedor_sap') or item.get('proveedor_nombre') or ''
            if tipo_item_citacion == 'DESPACHO' and item.get('condicion_entrega') == 'Cliente':
                proveedor_sap = ''
            secuencia_item_id = item.get('secuencia_id') or secuencia_id
            secuencia_item = secuencia

            if secuencia_item_id and not es_recepcion_transferencia_sbh:
                secuencia_item = SECUENCIA.objects.filter(
                    pk=secuencia_item_id,
                    EP_NID_id=Empresa,
                    SE_CTIPO=item.get('tipo_operacion', tipo_operacion).upper(),
                    SE_BHABILITADO=True
                ).first() or secuencia

            if es_item_despacho_terramar and (not secuencia_item or secuencia_item.SE_CCODIGO not in {'DESPACHO_TERRAMAR', 'DESPACHO_TERRAMAR_BODEGA_EXTERNA'}):
                return JsonResponse({
                    'success': False,
                    'message': 'La secuencia seleccionada no es válida para Despacho Terramar.'
                }, status=400)
            if es_item_recepcion_terramar and not queryset_secuencias_recepcion_terramar(Empresa).filter(pk=secuencia_item_id).exists():
                return JsonResponse({
                    'success': False,
                    'message': 'La secuencia seleccionada no es válida para Recepción Terramar.'
                }, status=400)
            cliente_sn = resolver_socio_negocio_planificacion(
                Empresa,
                'C',
                valor=item.get('cliente'),
                codigo=cliente_codigo,
                nombre=item.get('cliente_nombre')
            )


            proveedor_sn = None if (
                (tipo_item_citacion == 'DESPACHO' and item.get('condicion_entrega') == 'Cliente')
                or item.get('_proveedor_manual_sbh')
            ) else resolver_socio_negocio_planificacion(
                Empresa,
                'S',
                valor=proveedor_codigo,
                codigo=proveedor_codigo_final,
                nombre=proveedor_sap or item.get('proveedor_nombre')
            )

            prosesa_origen = None
            prosesa_origen_id = item.get('_prosesa_origen_id')
            if prosesa_origen_id:
                prosesa_origen = CITACION.objects.select_for_update(of=('self',)).select_related(
                    'SN_NID', 'PRO_NID'
                ).get(pk=prosesa_origen_id, EP_NID_id=Empresa)
                cliente_sn = prosesa_origen.SN_NID
                proveedor_sn = prosesa_origen.PRO_NID


            if tipo_item_citacion == 'DESPACHO':
                salida_documento = normalizar_salida_documento_despacho(item.get('salida_documento'))
                if not salida_documento:
                    return JsonResponse({
                        'success': False,
                        'message': 'Debe seleccionar Salida de documento para crear el despacho.'
                    })
                item['salida_documento'] = salida_documento

            citacion = CITACION.objects.create(
                US_NID=usuario,
                EP_NID_id=Empresa,
                PL_NID=planificacion,
                SN_NID=cliente_sn,
                PRO_NID=proveedor_sn,
                CON_NID=conductor_planificacion,
                SC_NID=secuencia_item,
                CI_FFECHAREGISTRO=timezone.now(),
                CI_FFECHACITACION=fecha_llegada_obj,
                CI_NCUPO=siguiente_numero_cupo + i,
                CI_CTIPO=item.get('tipo_operacion', tipo_operacion),
                CI_CTIPO_FLETE=item.get('tipo_carga', ''),
                CI_CESTADO='Despacho Programado' if tipo_item_citacion == 'DESPACHO' else 'Insumo Programado',
                CI_CCOMENTARIO='' if tipo_item_citacion == 'DESPACHO' else item.get('observacion', ''),
                CI_BHABILITADO=True,
                CI_BARCHIVADO=False,
                CI_BSOBRECUPO=False,
                CI_BAVISADO=False,
                CI_BCONFIRMADO=False,
                CI_BARRIBADO=False,
                CI_BCONFORME=False,
                RUT_NID=tarifa_planificacion.RUT_NID if tarifa_planificacion else None,
                TAR_NID=tarifa_planificacion,
                CI_NVALORTARIFA=tarifa_planificacion.TAR_NVALOR if tarifa_planificacion else None
            )

            item_maestro_id = 26
            if es_item_recepcion_terramar:
                item_maestro = queryset_insumos_recepcion_terramar(Empresa).filter(pk=int(item.get('item_id'))).first()
                if not item_maestro:
                    return JsonResponse({'success': False, 'message': 'El insumo seleccionado no es válido.'}, status=400)
                item_maestro_id = item_maestro.id
                item['codigo'] = item_maestro.IT_CCODIGO
                item['insumo'] = item_maestro.IT_CNOMBRE
            if prosesa_origen:
                item_origen = CITACION_ITEM.objects.filter(CI_NID=prosesa_origen).first()
                if not item_origen:
                    return JsonResponse({
                        'success': False,
                        'message': 'La Citación Prosesa Piso 1 no tiene un insumo asociado.',
                    }, status=409)
                item_maestro_id = item_origen.IT_NID_id


            CITACION_ITEM.objects.create(
                CI_NID=citacion,
                EP_NID_id=Empresa,
                IT_NID_id=item_maestro_id
            )

            guardar_detalle_operacional_citacion(
                citacion,
                {**item, 'proveedor_sap': proveedor_sap},
                usuario=usuario,
                origen_default='planificacion'
            )
            operacion_new_jersey = crear_operacion_new_jersey_proceso_1(
                citacion,
                item,
                usuario,
            )
            if operacion_new_jersey:
                operaciones_new_jersey_creadas.append(operacion_new_jersey.id)
            if es_recepcion_transferencia_sbh:
                guardar_detalles_transferencia_citacion(
                    citacion,
                    item.get('movimientos') or [],
                    usuario,
                )
            guardar_detalle_despacho_citacion(
                citacion,
                {**item, 'proveedor_sap': proveedor_sap},
                usuario=usuario
            )
            if prosesa_origen:
                CITACION_PROSESA_RELACION.objects.create(
                    EP_NID_id=Empresa,
                    CI_NID_ORIGEN=prosesa_origen,
                    CI_NID_RETIRO=citacion,
                    US_NID=usuario,
                )
                guardar_dato_operacion_codigo(
                    citacion,
                    CAMPO_PROSESA_PISO2_PATENTE_RETIRO,
                    item['patente_retiro_prosesa'],
                    usuario,
                    etiqueta='Patente camion retiro Prosesa Piso 2',
                )
                guardar_dato_operacion_codigo(
                    citacion,
                    CAMPO_PROSESA_PISO2_EMPRESA_TRANSPORTE,
                    item['empresa_transporte_retiro_prosesa'],
                    usuario,
                    etiqueta='Empresa transporte retiro Prosesa Piso 2',
                )
                if item['empresa_transporte_retiro_prosesa_id']:
                    guardar_dato_operacion_codigo(
                        citacion,
                        CAMPO_PROSESA_PISO2_TRANSPORTISTA_ID,
                        item['empresa_transporte_retiro_prosesa_id'],
                        usuario,
                        etiqueta='Transportista retiro Prosesa Piso 2',
                    )
                if item.get('base_line') not in (None, ''):
                    guardar_dato_operacion_codigo(
                        citacion,
                        CAMPO_PROSESA_BASE_LINE_SAP,
                        item.get('base_line'),
                        usuario,
                        etiqueta='BaseLine SAP Prosesa',
                    )

            if es_item_despacho_terramar:
                guardar_detalle_despacho_terramar_citacion(citacion, item, usuario)
                guardar_cliente_planificacion_despacho_terramar(citacion, item, usuario)
            guardar_datos_planificacion_operacional(citacion, {**item, 'proveedor_sap': proveedor_sap}, usuario, proveedor_sn=proveedor_sn)
            if Empresa == 2 and tipo_item_citacion == CIT_RECEPCION:
                guardar_cliente_planificacion_recepcion_sbh(citacion, item, usuario)

            if es_item_recepcion_terramar:
                citacion.CI_CNUMERODOCUMENTO = str(item.get('numero_guia') or '').strip()
                citacion.save(update_fields=['CI_CNUMERODOCUMENTO'])
                guardar_detalle_recepcion_terramar_citacion(citacion, item, usuario)
                guardar_ruta_transportista_revision(citacion, tarifa_planificacion, usuario)
                registrar_log_camion_no_planificado(
                    usuario, citacion.EP_NID, SYSLOGGER_OP_ASIGNA_RUTA_PLANIF,
                    f'Ruta asignada desde planificación para citación #{citacion.id}: {tarifa_planificacion.RUT_NID.RUT_CNOMBRE} / tarifa #{tarifa_planificacion.id}.',
                    citacion.id, planificacion.id
                )

            citaciones_creadas.append(citacion.id)

        if solicitud_patio:
            solicitud_patio.PL_NID = planificacion
            solicitud_patio.CPNP_CESTADO = CAMION_PATIO_NO_PLANIFICADO.ESTADO_APROBADO
            solicitud_patio.save(update_fields=['PL_NID', 'CPNP_CESTADO'])
            registrar_log_camion_no_planificado(
                request.user,
                solicitud_patio.EP_NID,
                'PAT_NP_PLAN',
                (
                    f'Planificacion #{planificacion.id} creada para solicitud de camion patio no planificado '
                    f'#{solicitud_patio.id}, camion #{solicitud_patio.CPA_NID_id}, patente '
                    f'{solicitud_patio.CPA_NID.CPA_CPATENTE}.'
                ),
                solicitud_patio.id,
                planificacion.id
            )

        return JsonResponse({
            'success': True,
            'message': (
                f'Se agregaron {len(citaciones_creadas)} citaciones a la planificación #{planificacion.id}.'
                if planificacion_existente else
                f'Planificación y {len(citaciones_creadas)} citación(es) creadas correctamente.'
            ),
            'planificacion_id': planificacion.id,
            'citaciones': citaciones_creadas,
            'operaciones_new_jersey': operaciones_new_jersey_creadas,
        })

    except Exception as e:
        transaction.set_rollback(True)
        print('ERROR CREAR_PLANIFICACION_CITACION:', e)

        return JsonResponse({
            'success': False,
            'message': str(e)
        })

@transaction.atomic
def CREAR_CITACION_NO_PLANIFICADA(request, pk):
    try:
        if request.method != 'POST':
            return JsonResponse({'success': False, 'message': 'Método no permitido.'})

        Empresa = Verificar_empresa(request)

        if Empresa is None:
            return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'})

        planificacion = PLANIFICACION.objects.select_for_update().get(pk=pk, EP_NID_id=Empresa)
        tipo_operacion = planificacion.PL_CTIPOCUPO
        fecha_llegada = request.POST.get('fecha_llegada', '').strip()
        secuencia_id = request.POST.get('secuencia_id')
        solicitud_id = request.POST.get('solicitud_id')
        solicitud_patio_id_despacho = request.POST.get('solicitud_no_planificado_id')
        solicitud_patio_id = solicitud_patio_id_despacho or request.POST.get('solicitud_patio_no_planificado_id')
        solicitud_camion = None
        solicitud_camion_patio = None

        if solicitud_id and solicitud_patio_id:
            return JsonResponse({
                'success': False,
                'message': 'La solicitud de camion no planificado es ambigua.'
            }, status=400)

        if solicitud_patio_id:
            if solicitud_patio_id_despacho and str(tipo_operacion or '').strip().upper() != 'DESPACHO':
                return JsonResponse({
                    'success': False,
                    'message': 'La solicitud indicada corresponde al flujo de Despacho y la planificacion seleccionada no es de ese tipo.'
                }, status=400)
            if not usuario_puede_revisar_no_planificado_patio(request.user):
                return JsonResponse({
                    'success': False,
                    'message': 'No tiene permisos para completar esta solicitud.'
                }, status=403)
            solicitud_camion_patio = CAMION_PATIO_NO_PLANIFICADO.objects.select_for_update().select_related(
                'CPA_NID', 'CPA_NID__US_GUARDIA_ID', 'EP_NID', 'US_SOLICITA_ID'
            ).filter(
                pk=solicitud_patio_id,
                EP_NID_id=Empresa,
                CPA_NID__EP_NID_id=Empresa,
                CPNP_CESTADO=CAMION_PATIO_NO_PLANIFICADO.ESTADO_APROBADO_PENDIENTE_PLANIFICACION,
                PL_NID__isnull=True,
                CI_NID__isnull=True,
            ).first()
            if not solicitud_camion_patio:
                return JsonResponse({
                    'success': False,
                    'message': 'La solicitud de camion en patio ya no esta disponible para planificar.'
                }, status=409)

            camion_patio_id_post = str(request.POST.get('camion_patio_id') or '').strip()
            if camion_patio_id_post and camion_patio_id_post != str(solicitud_camion_patio.CPA_NID_id):
                return JsonResponse({
                    'success': False,
                    'message': 'El camion informado no corresponde a la solicitud no planificada.'
                }, status=400)

            if str(tipo_operacion or '').strip().upper() == 'DESPACHO':
                if solicitud_camion_patio.CPA_NID.CI_NID_id:
                    return JsonResponse({
                        'success': False,
                        'message': 'El camion ya tiene una citacion asociada.'
                    }, status=409)
                if str(request.POST.get('origen') or '').strip() != 'camion_no_planificado':
                    return JsonResponse({
                        'success': False,
                        'message': 'El origen de la solicitud de despacho no es valido.'
                    }, status=400)

        if not fecha_llegada:
            fecha_llegada = planificacion.PL_FFECHAINICIO.strftime('%Y-%m-%d')

        if solicitud_id:
            solicitud_camion = CAMION_NO_PLANIFICADO.objects.filter(
                pk=solicitud_id,
                EP_NID_id=Empresa,
                PL_NID=planificacion,
                CNP_CESTADO=CAMION_NO_PLANIFICADO.ESTADO_PENDIENTE
            ).first()

            if not solicitud_camion:
                return JsonResponse({
                    'success': False,
                    'message': 'No existe una solicitud pendiente asociada a este camion.'
                })
        else:
            patente_post = str(request.POST.get('patente') or '').strip().upper()
            if patente_post:
                solicitud_camion = CAMION_NO_PLANIFICADO.objects.filter(
                    EP_NID_id=Empresa,
                    PL_NID=planificacion,
                    CNP_CPATENTE__iexact=patente_post,
                    CNP_CESTADO=CAMION_NO_PLANIFICADO.ESTADO_PENDIENTE
                ).order_by('-CNP_FFECHACREACION').first()

        secuencia = SECUENCIA.objects.filter(
            pk=secuencia_id,
            EP_NID_id=Empresa,
            SE_CTIPO=tipo_operacion,
            SE_BHABILITADO=True
        ).first()

        if not secuencia:
            return JsonResponse({
                'success': False,
                'message': f'Debe seleccionar una secuencia activa de tipo {tipo_operacion}.'
            })

        sobrecupos_disponibles = planificacion.PL_NCANTIDADSOBRECUPO or 0

        if sobrecupos_disponibles <= 0:
            registrar_log_camion_no_planificado(
                request.user,
                planificacion.EP_NID,
                'SIN_SOBRECUPO',
                f'Intento de agregar camion no planificado en planificacion #{planificacion.id} sin sobrecupos disponibles',
                planificacion.id,
                '0'
            )
            return JsonResponse({
                'success': False,
                'message': 'No quedan sobrecupos disponibles para esta planificación.'
            })

        cliente_codigo = request.POST.get('cliente_codigo', '').strip()
        proveedor_codigo = request.POST.get('proveedor', '').strip()
        proveedor_codigo_hidden = request.POST.get('proveedor_codigo', '').strip()
        codigo_proveedor_sap = request.POST.get('codigo_proveedor_sap', '').strip()
        proveedor_codigo_final = codigo_proveedor_sap or proveedor_codigo_hidden or proveedor_codigo

        cliente_sn = resolver_socio_negocio_planificacion(
            Empresa,
            'C',
            valor=request.POST.get('cliente'),
            codigo=cliente_codigo,
            nombre=request.POST.get('cliente_nombre')
        )

        proveedor_sn = resolver_socio_negocio_planificacion(
            Empresa,
            'S',
            valor=proveedor_codigo,
            codigo=proveedor_codigo_final,
            nombre=request.POST.get('proveedor_sap') or request.POST.get('proveedor_nombre')
        )

        fecha_citacion = datetime.strptime(fecha_llegada, '%Y-%m-%d')
        numero_cupo = CITACION.objects.filter(PL_NID=planificacion).count() + 1

        tipo_operacion_normalizado = str(tipo_operacion or '').strip().upper()
        if tipo_operacion_normalizado == 'DESPACHO':
            almacen_destino = str(request.POST.get('bodega') or '').strip()
            estanque_destino = str(request.POST.get('destino') or '').strip()
            salida_documento = normalizar_salida_documento_despacho(request.POST.get('salida_documento'))
            campos_despacho_requeridos = {
                'cliente': request.POST.get('cliente'),
                'producto SAP / insumo': request.POST.get('insumo'),
                'OC cliente': request.POST.get('pedido') or request.POST.get('oc_cliente'),
                'cantidad intentada': request.POST.get('cantidad_intentada_despachar'),
                'destino': estanque_destino,
                'formato': request.POST.get('tipo_carga'),
                'orden de carga': request.POST.get('orden_carga'),
                'ventana horaria': request.POST.get('ventana_horaria_despacho'),
                'bodega': almacen_destino,
                'empresa transporte': request.POST.get('empresa_transporte'),
                'conductor': request.POST.get('conductor'),
            }
            faltantes_despacho = [
                etiqueta for etiqueta, valor in campos_despacho_requeridos.items()
                if not str(valor or '').strip()
            ]
            if faltantes_despacho:
                return JsonResponse({
                    'success': False,
                    'message': 'Debe completar los campos de despacho: ' + ', '.join(faltantes_despacho) + '.'
                }, status=400)
            if not salida_documento:
                return JsonResponse({
                    'success': False,
                    'message': 'Debe seleccionar Salida de documento para crear el despacho.'
                }, status=400)
        else:
            almacen_destino = request.POST.get('almacen_destino', '').strip()
            estanque_destino = request.POST.get('estanque_destino', '').strip()
            opciones_estanque = obtener_estanques_por_almacen(almacen_destino)

            if not normalizar_almacen_planificacion(almacen_destino):
                return JsonResponse({
                    'success': False,
                    'message': 'Debe seleccionar una planta destino valida.'
                })

            if not estanque_destino:
                return JsonResponse({
                    'success': False,
                    'message': 'Debe seleccionar un estanque destino.'
                })

            if estanque_destino not in opciones_estanque:
                return JsonResponse({
                    'success': False,
                    'message': 'El estanque seleccionado no corresponde a la planta destino.'
                })

        if solicitud_camion_patio:
            camion_patio_solicitado = solicitud_camion_patio.CPA_NID
            patente_solicitud = str(camion_patio_solicitado.CPA_CPATENTE or '').strip().upper()
            numero_guia_solicitud = camion_patio_solicitado.CPA_CNUMERO_GUIA or ''
            transporte_solicitud = camion_patio_solicitado.CPA_CTRANSPORTISTA_DECLARADO or ''
        else:
            patente_solicitud = (
                solicitud_camion.CNP_CPATENTE
                if solicitud_camion
                else str(request.POST.get('patente') or '').strip().upper()
            )
            numero_guia_solicitud = solicitud_camion.CNP_CNUMEROGUIA if solicitud_camion else ''
            transporte_solicitud = solicitud_camion.CNP_CEMPRESATRANSPORTE if solicitud_camion else ''

        detalle_operacional_data = {
            'origen': 'camion_no_planificado',
            'inf_24hrs': request.POST.get('inf_24hrs', ''),
            'codigo': request.POST.get('codigo', ''),
            'insumo': request.POST.get('insumo', ''),
            'pedido': request.POST.get('pedido', ''),
            'sap_opor_id': request.POST.get('sap_opor_id', ''),
            'proveedor_codigo': proveedor_codigo_final,
            'proveedor_sap': request.POST.get('proveedor_sap') or request.POST.get('proveedor_nombre', ''),
            'codigo_proveedor_sap': codigo_proveedor_sap,
            'contrato_sap': request.POST.get('contrato_sap', ''),
            'bl': '' if str(tipo_operacion or '').upper() == 'DESPACHO' else request.POST.get('bl', ''),
            'cantidad_disponible': request.POST.get('cantidad_disponible', ''),
            'docentry': request.POST.get('docentry', ''),
            'almacen_destino': almacen_destino,
            'estanque_destino': estanque_destino,
            'observacion': request.POST.get('observacion', ''),
            'patente': patente_solicitud,
            'numero_guia': numero_guia_solicitud,
            'empresa_transporte': request.POST.get('empresa_transporte', '') if tipo_operacion_normalizado == 'DESPACHO' else transporte_solicitud,
            'conductor': request.POST.get('conductor', ''),
            'destino': request.POST.get('destino', ''),
            'oc_cliente': request.POST.get('oc_cliente') or request.POST.get('pedido', ''),
            'cantidad_intentada_despachar': request.POST.get('cantidad_intentada_despachar', ''),
            'condicion_entrega': request.POST.get('condicion_entrega', ''),
            'salida_documento': salida_documento if tipo_operacion_normalizado == 'DESPACHO' else '',
            'orden_carga': request.POST.get('orden_carga', ''),
            'ventana_horaria_despacho': request.POST.get('ventana_horaria_despacho', ''),
            'bodega': request.POST.get('bodega', ''),
            'sap_abs_id': request.POST.get('sap_abs_id', ''),
            'sap_numero_acuerdo': request.POST.get('sap_numero_acuerdo', ''),
            'sap_linea_acuerdo': request.POST.get('sap_linea_acuerdo', ''),
            'sap_cliente_codigo': cliente_codigo,
            'sap_cliente_nombre': request.POST.get('cliente_nombre', ''),
            'sap_oc_cliente': request.POST.get('oc_cliente') or request.POST.get('pedido', ''),
            'sap_codigo_producto': request.POST.get('sap_codigo_producto') or request.POST.get('codigo', ''),
            'sap_nombre_producto': request.POST.get('sap_nombre_producto') or request.POST.get('insumo', ''),
            'sap_cantidad_planificada': request.POST.get('sap_cantidad_planificada', ''),
            'sap_cantidad_consumida': request.POST.get('sap_cantidad_consumida', ''),
            'sap_saldo_contrato': request.POST.get('sap_saldo_contrato', ''),
        }

        citacion = CITACION.objects.create(
            US_NID=request.user,
            EP_NID_id=Empresa,
            PL_NID=planificacion,
            SN_NID=cliente_sn,
            PRO_NID=proveedor_sn,
            SC_NID=secuencia,
            CI_FFECHAREGISTRO=timezone.now(),
            CI_FFECHACITACION=fecha_citacion,
            CI_NCUPO=numero_cupo,
            CI_CTIPO=tipo_operacion,
            CI_CNUMERODOCUMENTO=numero_guia_solicitud,
            CI_CTIPO_FLETE=request.POST.get('tipo_carga', ''),
            CI_CESTADO='Despacho Programado' if tipo_operacion_normalizado == 'DESPACHO' else 'Insumo Programado',
            CI_CCOMENTARIO='' if tipo_operacion_normalizado == 'DESPACHO' else detalle_operacional_data.get('observacion', ''),
            CI_BHABILITADO=True,
            CI_BARCHIVADO=False,
            CI_BSOBRECUPO=True,
            CI_BAVISADO=False,
            CI_BCONFIRMADO=False,
            CI_BARRIBADO=False,
            CI_BCONFORME=False
        )

        CITACION_ITEM.objects.create(
            CI_NID=citacion,
            EP_NID_id=Empresa,
            IT_NID_id=26
        )

        guardar_detalle_operacional_citacion(
            citacion,
            detalle_operacional_data,
            usuario=request.user,
            origen_default='camion_no_planificado'
        )
        guardar_detalle_despacho_citacion(
            citacion,
            detalle_operacional_data,
            usuario=request.user
        )
        guardar_datos_planificacion_operacional(citacion, detalle_operacional_data, request.user, proveedor_sn=proveedor_sn)

        if patente_solicitud:
            guardar_dato_operacion_codigo(citacion, 'ING_PATENTE', patente_solicitud, request.user, etiqueta='Patente')
        if numero_guia_solicitud:
            guardar_dato_operacion_codigo(citacion, 'CI_CNUMERODOCUMENTO', numero_guia_solicitud, request.user, etiqueta='Numero guia')
        if transporte_solicitud:
            guardar_dato_operacion_codigo(citacion, 'ING_EMPRESA_TRANSPORTE', transporte_solicitud, request.user, etiqueta='Empresa transporte')

        if solicitud_camion:
            solicitud_camion.CNP_CESTADO = CAMION_NO_PLANIFICADO.ESTADO_PLANIFICADO
            solicitud_camion.US_PLANIFICADOR_ID = request.user
            solicitud_camion.CNP_FFECHARESPUESTA = timezone.now()
            solicitud_camion.save(update_fields=[
                'CNP_CESTADO',
                'US_PLANIFICADOR_ID',
                'CNP_FFECHARESPUESTA',
            ])

            registrar_log_camion_no_planificado(
                request.user,
                planificacion.EP_NID,
                'APR_NO_PLAN',
                f'Solicitud camion no planificado #{solicitud_camion.id} planificada como citacion #{citacion.id}',
                planificacion.id,
                patente_solicitud
            )

        if solicitud_camion_patio:
            solicitud_camion_patio.PL_NID = planificacion
            solicitud_camion_patio.CI_NID = citacion
            solicitud_camion_patio.CPNP_CESTADO = CAMION_PATIO_NO_PLANIFICADO.ESTADO_APROBADO
            solicitud_camion_patio.US_PLANIFICADOR_ID = request.user
            solicitud_camion_patio.CPNP_FFECHARESOLUCION = timezone.now()
            solicitud_camion_patio.save(update_fields=[
                'PL_NID',
                'CI_NID',
                'CPNP_CESTADO',
                'US_PLANIFICADOR_ID',
                'CPNP_FFECHARESOLUCION',
            ])

            _crear_notificacion_citacion_no_planificada(
                solicitud_camion_patio,
                usuario_planificador=request.user,
            )
            registrar_log_camion_no_planificado(
                request.user,
                solicitud_camion_patio.EP_NID,
                'PAT_NP_PLAN',
                (
                    f'Solicitud patio no planificado #{solicitud_camion_patio.id} vinculada a '
                    f'planificacion #{planificacion.id} y citacion #{citacion.id}.'
                ),
                solicitud_camion_patio.id,
                citacion.id
            )

        planificacion.PL_NSOBRECUPO = True
        planificacion.PL_NCANTIDADSOBRECUPO = max(sobrecupos_disponibles - 1, 0)
        planificacion.save(update_fields=['PL_NSOBRECUPO', 'PL_NCANTIDADSOBRECUPO'])

        return JsonResponse({
            'success': True,
            'message': 'Camión no planificado agregado correctamente.',
            'citacion_id': citacion.id,
            'solicitud_patio_no_planificado_id': solicitud_camion_patio.id if solicitud_camion_patio else None,
        })

    except PLANIFICACION.DoesNotExist:
        return JsonResponse({'success': False, 'message': 'No se encontró la planificación.'})
    except Exception as e:
        transaction.set_rollback(True)
        print('ERROR CREAR_CITACION_NO_PLANIFICADA:', e)
        return JsonResponse({'success': False, 'message': str(e)})


def NOTIFICAR_CAMION_NO_PLANIFICADO_LEGACY(request):
    print("ENTRO A NOTIFICAR_CAMION_NO_PLANIFICADO")
    print(request.POST)

    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)

    if not usuario_puede_operar_ingreso_camion(request.user):
        return JsonResponse({
            'success': False,
            'message': 'No tiene permisos para notificar camiones no planificados.'
        }, status=403)

    Empresa = Verificar_empresa(request)

    if Empresa is None:
        return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'}, status=400)

    empresa = EMPRESA.objects.filter(pk=Empresa).first()
    planificacion_id = request.POST.get('planificacion_id')
    log_estado = 'ERROR'
    log_detalle = ''

    try:
        planificacion = PLANIFICACION.objects.get(pk=planificacion_id, EP_NID_id=Empresa)
        planificador = User.objects.filter(username__iexact='MAESC', is_active=True).first()

        if not planificador:
            log_detalle = 'No se encontro el usuario MAESC.'
            return JsonResponse({'success': False, 'message': log_detalle}, status=404)

        if not planificador.email:
            log_detalle = 'El usuario MAESC no tiene email configurado.'
            return JsonResponse({'success': False, 'message': log_detalle}, status=400)

        fecha_hora = timezone.localtime(timezone.now()).strftime('%d/%m/%Y %H:%M:%S')
        empresa_nombre = empresa.EP_CRAZONSOCIAL if empresa else str(Empresa)
        mensaje = (
            'ALERTA CAMIÓN NO PLANIFICADO\n\n'
            f'Guardia: {request.user.username}\n'
            f'Planificación: {planificacion.id}\n'
            f'Empresa: {empresa_nombre}\n'
            f'Fecha/hora: {fecha_hora}\n\n'
            'Acción requerida por Planificación.'
        )

        notificacion = crear_notificacion_interna(
            USER_SENDER_ID=request.user,
            USER_RECEIVER_ID=planificador,
            EP_NID=empresa,
            NOT_CCONTENIDO=mensaje,
            NOT_CURL=f'/pla_listone/{planificacion.id}'
        )

        resultado_teams = enviar_alerta_camion_no_planificado_teams(planificador.email, mensaje)
        log_estado = resultado_teams.status
        log_detalle = resultado_teams.detail

        return JsonResponse({
            'success': True,
            'message': 'Se notifico al planificador',
            'teams_status': resultado_teams.status,
            'teams_sent': resultado_teams.success,
            'notificacion_id': getattr(notificacion, 'id', None)
        })

    except PLANIFICACION.DoesNotExist:
        log_detalle = 'No se encontro la planificacion para la empresa activa.'
        return JsonResponse({'success': False, 'message': log_detalle}, status=404)
    except Exception as e:
        log_detalle = str(e)
        return JsonResponse({'success': False, 'message': log_detalle}, status=500)
    finally:
        try:
            SYSLOGGER.objects.create(
                US_NID=request.user,
                EP_NID=empresa,
                LOG_FFECHAREGISTRO=timezone.now(),
                LOG_CMODULO='PLANIFICACION',
                LOG_COPERACION='NOTIF_NO_PLAN',
                LOG_CDESCRIPCION=f'Intento notificacion camion no planificado: {log_estado} - {log_detalle}'[:1024],
                LOG_CADD1=str(planificacion_id or '')[:128],
                LOG_CADD2='MAESC'
            )
        except Exception as log_error:
            print('ERROR LOG NOTIFICAR_CAMION_NO_PLANIFICADO:', log_error)


def obtener_planificador_camion_no_planificado():
    return User.objects.filter(username__iexact='MAESC', is_active=True).first()


def registrar_log_camion_no_planificado(usuario, empresa, operacion, descripcion, add1='', add2='', raise_on_error=False):
    """Registra auditoría; un DatabaseError revierte la operación atómica completa."""
    operacion = str(operacion or '').strip()
    if len(operacion) > SYSLOGGER_LOG_COPERACION_MAX_LENGTH:
        raise ValueError(
            f'LOG_COPERACION supera {SYSLOGGER_LOG_COPERACION_MAX_LENGTH} caracteres: {operacion}'
        )
    try:
        SYSLOGGER.objects.create(
            US_NID=usuario,
            EP_NID=empresa,
            LOG_FFECHAREGISTRO=timezone.now(),
            LOG_CMODULO='PLANIFICACION',
            LOG_COPERACION=operacion,
            LOG_CDESCRIPCION=str(descripcion or '')[:1024],
            LOG_CADD1=str(add1 or '')[:128],
            LOG_CADD2=str(add2 or '')[:128]
        )
    except DatabaseError:
        logger.exception(
            'Error de base de datos registrando trazabilidad de camion; se revierte la operación.',
            extra={'operacion': operacion, 'citacion_id': str(add1 or ''), 'camion_patio_id': str(add2 or '')},
        )
        raise
    except Exception:
        logger.exception(
            'Error registrando trazabilidad de camion',
            extra={'operacion': operacion, 'citacion_id': str(add1 or ''), 'camion_patio_id': str(add2 or '')},
        )
        if raise_on_error:
            raise

def armar_mensaje_solicitud_camion_no_planificado(request, solicitud, empresa, planificacion):
    fecha_hora = timezone.localtime(solicitud.CNP_FFECHACREACION).strftime('%d/%m/%Y %H:%M:%S')
    empresa_nombre = empresa.EP_CRAZONSOCIAL if empresa else ''
    link_planificacion = request.build_absolute_uri(f'/pla_listone/{planificacion.id}')
    link_guia = request.build_absolute_uri(solicitud.CNP_FARCHIVOGUIA.url) if solicitud.CNP_FARCHIVOGUIA else ''

    return (
        f'Guardia: {solicitud.US_GUARDIA_ID.username}\n'
        f'Cliente: {solicitud.CLI_CNOMBRE}\n'
        f'Insumo: {solicitud.CNP_CINSUMO}\n'
        f'Guia: {solicitud.CNP_CNUMEROGUIA}\n'
        f'Patente: {solicitud.CNP_CPATENTE}\n'
        f'Empresa transporte: {solicitud.CNP_CEMPRESATRANSPORTE}\n'
        f'Observacion: {solicitud.CNP_COBSERVACION or "Sin observacion"}\n'
        f'Empresa: {empresa_nombre}\n'
        f'Planificacion: {planificacion.id}\n'
        f'Fecha/hora: {fecha_hora}\n'
        f'Link interno: {link_planificacion}\n'
        f'Guia escaneada: {link_guia}'
    )


def SOLICITAR_CAMION_NO_PLANIFICADO(request):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)

    if not usuario_puede_operar_ingreso_camion(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para solicitar camiones no planificados.'}, status=403)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'}, status=400)

    empresa = EMPRESA.objects.filter(pk=Empresa).first()
    planificacion_id = request.POST.get('planificacion_id')

    try:
        planificacion = PLANIFICACION.objects.get(pk=planificacion_id, EP_NID_id=Empresa)
        planificador = obtener_planificador_camion_no_planificado()

        if not planificador:
            mensaje_error = 'No se encontro el usuario MAESC.'
            registrar_log_camion_no_planificado(request.user, empresa, 'SOL_NO_PLAN', mensaje_error, planificacion_id)
            return JsonResponse({'success': False, 'message': mensaje_error}, status=404)

        if not planificador.email:
            mensaje_error = 'El usuario MAESC no tiene email configurado.'
            registrar_log_camion_no_planificado(request.user, empresa, 'SOL_NO_PLAN', mensaje_error, planificacion_id)
            return JsonResponse({'success': False, 'message': mensaje_error}, status=400)

        archivo_guia = request.FILES.get('archivo_guia')
        if not archivo_guia:
            return JsonResponse({'success': False, 'message': 'Debe adjuntar la guia escaneada.'}, status=400)

        patente = str(request.POST.get('patente') or '').strip().upper()
        if Empresa == ID_ACEITES_SBH and es_despacho:
            patente = _normalizar_patente_busqueda(patente)
        if not patente:
            return JsonResponse({'success': False, 'message': 'Debe ingresar la patente.'}, status=400)

        campos_requeridos = {
            'cliente': str(request.POST.get('cliente') or '').strip(),
            'insumo': str(request.POST.get('insumo') or '').strip(),
            'numero_guia': str(request.POST.get('numero_guia') or '').strip(),
            'empresa_transporte': str(request.POST.get('empresa_transporte') or '').strip(),
        }
        if any(not valor for valor in campos_requeridos.values()):
            return JsonResponse({'success': False, 'message': 'Debe completar cliente, insumo, numero guia y empresa transporte.'}, status=400)

        solicitud_existente = CAMION_NO_PLANIFICADO.objects.filter(
            EP_NID=empresa,
            PL_NID=planificacion,
            CNP_CPATENTE__iexact=patente,
            CNP_CESTADO=CAMION_NO_PLANIFICADO.ESTADO_PENDIENTE
        ).first()

        if solicitud_existente:
            return JsonResponse({
                'success': False,
                'message': f'Ya existe una solicitud pendiente para la patente {patente}.'
            }, status=409)

        cliente_codigo = str(request.POST.get('cliente') or '').strip()
        cliente_nombre = str(request.POST.get('cliente_nombre') or cliente_codigo).strip()

        solicitud = CAMION_NO_PLANIFICADO.objects.create(
            EP_NID=empresa,
            PL_NID=planificacion,
            US_GUARDIA_ID=request.user,
            CLI_CCODIGO=cliente_codigo,
            CLI_CNOMBRE=cliente_nombre,
            CNP_CINSUMO=campos_requeridos['insumo'],
            CNP_CNUMEROGUIA=campos_requeridos['numero_guia'],
            CNP_CPATENTE=patente,
            CNP_CEMPRESATRANSPORTE=campos_requeridos['empresa_transporte'],
            CNP_COBSERVACION=str(request.POST.get('observacion') or '').strip(),
            CNP_FARCHIVOGUIA=archivo_guia,
        )

        mensaje = armar_mensaje_solicitud_camion_no_planificado(request, solicitud, empresa, planificacion)
        notificacion = crear_notificacion_interna(
            USER_SENDER_ID=request.user,
            USER_RECEIVER_ID=planificador,
            EP_NID=empresa,
            NOT_CCONTENIDO=f'Camion no planificado pendiente: patente {solicitud.CNP_CPATENTE}',
            NOT_CURL=f'/pla_listone/{planificacion.id}'
        )

        resultado_teams = enviar_solicitud_camion_no_planificado_teams(planificador.email, mensaje)
        registrar_log_camion_no_planificado(
            request.user,
            empresa,
            'SOL_NO_PLAN',
            f'Solicitud camion no planificado #{solicitud.id}: {resultado_teams.status} - {resultado_teams.detail}',
            planificacion_id,
            solicitud.CNP_CPATENTE
        )

        return JsonResponse({
            'success': True,
            'message': 'Solicitud enviada al planificador',
            'teams_status': resultado_teams.status,
            'teams_sent': resultado_teams.success,
            'solicitud_id': solicitud.id,
            'notificacion_id': getattr(notificacion, 'id', None)
        })

    except PLANIFICACION.DoesNotExist:
        mensaje_error = 'No se encontro la planificacion para la empresa activa.'
        registrar_log_camion_no_planificado(request.user, empresa, 'SOL_NO_PLAN', mensaje_error, planificacion_id)
        return JsonResponse({'success': False, 'message': mensaje_error}, status=404)
    except Exception as e:
        mensaje_error = str(e)
        registrar_log_camion_no_planificado(request.user, empresa, 'SOL_NO_PLAN', mensaje_error, planificacion_id)
        return JsonResponse({'success': False, 'message': mensaje_error}, status=500)


def NOTIFICAR_CAMION_NO_PLANIFICADO(request):
    return SOLICITAR_CAMION_NO_PLANIFICADO(request)


def RECHAZAR_CAMION_NO_PLANIFICADO(request):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)

    if not usuario_es_planificador(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para rechazar solicitudes.'}, status=403)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'}, status=400)

    empresa = EMPRESA.objects.filter(pk=Empresa).first()
    planificacion_id = request.POST.get('planificacion_id')
    solicitud_id = request.POST.get('solicitud_id')
    patente = str(request.POST.get('patente') or '').strip().upper()
    observacion = str(request.POST.get('observacion_rechazo') or '').strip()

    if not solicitud_id and not patente:
        return JsonResponse({'success': False, 'message': 'No se encontro la solicitud pendiente a rechazar.'}, status=400)

    if not observacion:
        return JsonResponse({'success': False, 'message': 'Debe ingresar el motivo u observacion de rechazo.'}, status=400)

    try:
        planificacion = PLANIFICACION.objects.get(pk=planificacion_id, EP_NID_id=Empresa)
        solicitudes = CAMION_NO_PLANIFICADO.objects.select_related('US_GUARDIA_ID').filter(
            EP_NID=empresa,
            PL_NID=planificacion,
            CNP_CESTADO=CAMION_NO_PLANIFICADO.ESTADO_PENDIENTE
        )

        if solicitud_id:
            solicitudes = solicitudes.filter(pk=solicitud_id)
        else:
            solicitudes = solicitudes.filter(CNP_CPATENTE__iexact=patente)

        solicitud = solicitudes.order_by('-CNP_FFECHACREACION').first()

        if not solicitud:
            return JsonResponse({'success': False, 'message': 'No existe solicitud pendiente para rechazar.'}, status=404)

        patente = solicitud.CNP_CPATENTE

        solicitud.CNP_CESTADO = CAMION_NO_PLANIFICADO.ESTADO_RECHAZADO
        solicitud.US_PLANIFICADOR_ID = request.user
        solicitud.CNP_COBSERVACION_RECHAZO = observacion
        solicitud.CNP_FFECHARESPUESTA = timezone.now()
        solicitud.save(update_fields=[
            'CNP_CESTADO',
            'US_PLANIFICADOR_ID',
            'CNP_COBSERVACION_RECHAZO',
            'CNP_FFECHARESPUESTA',
        ])

        mensaje = (
            f'Planificador: {request.user.username}\n'
            f'Patente: {solicitud.CNP_CPATENTE}\n'
            f'Cliente: {solicitud.CLI_CNOMBRE}\n'
            f'Insumo: {solicitud.CNP_CINSUMO}\n'
            f'Guia: {solicitud.CNP_CNUMEROGUIA}\n'
            f'Motivo/observacion: {observacion}\n'
            f'Guardia notificado: {solicitud.US_GUARDIA_ID.username}\n'
            f'Link interno: {request.build_absolute_uri(f"/pla_listone/{planificacion.id}")}'
        )

        crear_notificacion_interna(
            USER_SENDER_ID=request.user,
            USER_RECEIVER_ID=solicitud.US_GUARDIA_ID,
            EP_NID=empresa,
            NOT_CCONTENIDO=f'Camion no planificado rechazado: patente {solicitud.CNP_CPATENTE}. Motivo: {observacion}',
            NOT_CURL=f'/pla_listone/{planificacion.id}'
        )

        resultado_teams = enviar_rechazo_camion_no_planificado_teams(solicitud.US_GUARDIA_ID.email, mensaje)
        registrar_log_camion_no_planificado(
            request.user,
            empresa,
            'RECH_NO_PLAN',
            f'Rechazo camion no planificado #{solicitud.id}: {resultado_teams.status} - {resultado_teams.detail}',
            planificacion_id,
            solicitud.CNP_CPATENTE
        )

        return JsonResponse({
            'success': True,
            'message': 'Solicitud rechazada y guardia notificado.',
            'solicitud_id': solicitud.id,
            'teams_status': resultado_teams.status,
            'teams_sent': resultado_teams.success
        })

    except PLANIFICACION.DoesNotExist:
        mensaje_error = 'No se encontro la planificacion para la empresa activa.'
        registrar_log_camion_no_planificado(request.user, empresa, 'RECH_NO_PLAN', mensaje_error, planificacion_id, patente)
        return JsonResponse({'success': False, 'message': mensaje_error}, status=404)
    except Exception as e:
        mensaje_error = str(e)
        registrar_log_camion_no_planificado(request.user, empresa, 'RECH_NO_PLAN', mensaje_error, planificacion_id, patente)
        return JsonResponse({'success': False, 'message': mensaje_error}, status=500)


def usuario_puede_registrar_camion_patio(user):
    return getattr(user, 'is_superuser', False) or usuario_es_asistente_recepcion(user)


def usuario_puede_revisar_camion_patio(user):
    return getattr(user, 'is_superuser', False) or usuario_es_asistente_recepcion(user)


PERFIL_CODIGO_ASISTENTE_DESPACHO = 'ASISTENTE_DESPACHO'


def usuario_es_asistente_despacho_global(user):
    if not user or not getattr(user, 'is_authenticated', False) or not getattr(user, 'is_active', False):
        return False
    return PERFIL_USUARIO.objects.filter(
        US_NID=user,
        PE_BHABILITADO=True,
        PR_NID__PR_CCODIGO__iexact=PERFIL_CODIGO_ASISTENTE_DESPACHO,
        PR_NID__PR_BHABILITADO=True,
    ).exists()


def usuario_es_asistente_despacho_empresa(user, empresa_id):
    return bool(
        usuario_es_asistente_despacho_global(user)
        and _usuario_tiene_acceso_empresa(user, empresa_id)
    )


def usuario_puede_registrar_camion_patio_empresa(user, empresa_id):
    return bool(
        usuario_puede_registrar_camion_patio(user)
        or usuario_es_asistente_despacho_empresa(user, empresa_id)
    )


def usuario_puede_ver_control_camion_patio_empresa(user, empresa_id):
    return bool(
        usuario_puede_ver_control_camion_patio(user)
        or usuario_es_asistente_despacho_empresa(user, empresa_id)
    )


def usuario_puede_ingreso_camion_despacho(user, empresa_id):
    return bool(
        getattr(user, 'is_superuser', False)
        or usuario_es_ingreso_camion(user)
        or usuario_es_asistente_despacho_empresa(user, empresa_id)
    )


def usuario_puede_revisar_camion_patio_empresa(user, empresa_id):
    return bool(
        getattr(user, 'is_superuser', False)
        or usuario_puede_revisar_camion_patio(user)
        or usuario_es_asistente_despacho_empresa(user, empresa_id)
    )


def _usuarios_asistente_despacho_empresa(empresa_id, usuario_excluir=None):
    usuarios = User.objects.filter(
        is_active=True,
        empresas_asignadas__EP_NID_id=empresa_id,
        id__in=PERFIL_USUARIO.objects.filter(
            PE_BHABILITADO=True,
            PR_NID__PR_CCODIGO__iexact=PERFIL_CODIGO_ASISTENTE_DESPACHO,
            PR_NID__PR_BHABILITADO=True,
        ).values_list('US_NID_id', flat=True),
    ).distinct()
    if usuario_excluir:
        usuarios = usuarios.exclude(pk=usuario_excluir.pk)
    return list(usuarios)


def usuario_puede_revisar_no_planificado_patio(user):
    return (
        getattr(user, 'is_superuser', False)
        or normalizar_nombre_perfil(getattr(user, 'username', '')) == 'MAESC'
        or usuario_es_planificador(user)
    )


def _usuario_tiene_acceso_empresa(user, empresa_id):
    return USERS_EMPRESA.objects.filter(US_NID=user, EP_NID_id=empresa_id).exists()


def _usuarios_guardia_empresa(empresa_id):
    usuarios_ids = USERS_EMPRESA.objects.filter(
        EP_NID_id=empresa_id
    ).values_list('US_NID_id', flat=True)
    return [
        usuario
        for usuario in User.objects.filter(id__in=usuarios_ids, is_active=True).select_related('userv')
        if usuario_es_guardia(usuario)
    ]


def usuario_tiene_perfil_guardia_derivacion(user):
    if not user or not getattr(user, 'is_authenticated', False) or not getattr(user, 'is_active', False):
        return False
    perfiles = PERFIL_USUARIO.objects.select_related('PR_NID').filter(
        US_NID=user,
        PE_BHABILITADO=True,
        PR_NID__PR_BHABILITADO=True,
    )
    if any(
        normalizar_nombre_perfil(valor) in PERFILES_GUARDIA
        for perfil_usuario in perfiles
        for valor in (
            perfil_usuario.PR_NID.PR_CNOMBRE,
            perfil_usuario.PR_NID.PR_CCODIGO,
        )
    ):
        return True
    # Compatibilidad con usuarios Guardia operativos anteriores al RBAC canonico.
    return usuario_es_guardia(user)


def _url_publica_aplicacion(request, ruta):
    base_url = str(getattr(settings, 'APP_PUBLIC_BASE_URL', '') or '').strip().rstrip('/')
    if base_url:
        return f'{base_url}/{str(ruta).lstrip("/")}'
    url = request.build_absolute_uri(ruta)
    if url.lower().startswith(('http://127.0.0.1', 'https://127.0.0.1', 'http://localhost', 'https://localhost')):
        logger.warning('CAMION_PATIO_NO_PLANIFICADO enlace local generado para Teams: %s', url)
    return url


def _solicitud_no_planificado_visible(camion):
    return camion.solicitudes_no_planificado.select_related(
        'CI_NID', 'CI_NID__PL_NID', 'PL_NID'
    ).order_by('-CPNP_FFECHASOLICITUD', '-id').first()


def _crear_notificacion_citacion_no_planificada(solicitud, usuario_planificador):
    camion = solicitud.CPA_NID
    citacion = solicitud.CI_NID
    planificacion = solicitud.PL_NID
    destinatario = camion.US_GUARDIA_ID
    datos_log = (
        f'Solicitud #{solicitud.id}; camion patio #{camion.id}; patente {camion.CPA_CPATENTE}; '
        f'citacion #{citacion.id if citacion else "-"}; planificacion #{planificacion.id if planificacion else "-"}; '
        f'planificador {getattr(usuario_planificador, "username", "-")}; '
        f'destinatario {getattr(destinatario, "username", "-")}.'
    )

    if not citacion or solicitud.CPNP_CESTADO != CAMION_PATIO_NO_PLANIFICADO.ESTADO_APROBADO:
        registrar_log_camion_no_planificado(
            usuario_planificador,
            solicitud.EP_NID,
            'PAT_NP_NOT_ERR',
            f'Notificacion final no creada: solicitud sin citacion aprobada. {datos_log}',
            solicitud.id,
            camion.id,
        )
        return None, False

    if (
        not destinatario
        or not destinatario.is_active
        or not usuario_es_asistente_recepcion(destinatario)
        or not _usuario_tiene_acceso_empresa(destinatario, solicitud.EP_NID_id)
    ):
        registrar_log_camion_no_planificado(
            usuario_planificador,
            solicitud.EP_NID,
            'PAT_NP_NOT_ERR',
            f'Notificacion final no creada: destinatario de registro invalido o sin acceso. {datos_log}',
            solicitud.id,
            camion.id,
        )
        return None, False

    url = reverse('camiones_patio_list') + '?' + urlencode({
        '_empresa_id': solicitud.EP_NID_id,
        'camion_patio_id': camion.id,
    })
    tipo_operacion_codigo = str(
        citacion.CI_CTIPO or (planificacion.PL_CTIPOCUPO if planificacion else '') or 'RECEPCION'
    ).strip().upper()
    tipo_operacion = 'Recepción' if tipo_operacion_codigo == 'RECEPCION' else 'Despacho'
    contenido = (
        'citación creada para camión no planificado\n'
        f'La citación #{citacion.id} fue creada para la patente {camion.CPA_CPATENTE}.\n'
        f'El camión ya puede continuar con el proceso de {tipo_operacion}.\n'
        f'Planificación: #{planificacion.id if planificacion else "-"}'
    )

    existente = NOTIFICACION.objects.filter(
        USER_RECEIVER_ID=destinatario,
        EP_NID=solicitud.EP_NID,
        NOT_CURL=url,
        NOT_CCONTENIDO__icontains=f'#{citacion.id}',
        NOT_BHABILITADO=True,
    ).order_by('id').first()
    if existente:
        registrar_log_camion_no_planificado(
            usuario_planificador,
            solicitud.EP_NID,
            'PAT_NP_NOT_DUP',
            f'Notificacion final ya existente #{existente.id}. {datos_log}',
            solicitud.id,
            existente.id,
        )
        return existente, False

    try:
        with transaction.atomic():
            notificacion = crear_notificacion_interna(
                USER_SENDER_ID=usuario_planificador,
                USER_RECEIVER_ID=destinatario,
                EP_NID=solicitud.EP_NID,
                NOT_CCONTENIDO=contenido,
                NOT_CURL=url,
                NOT_BHABILITADO=True,
                NOT_BREAD=False,
                NOT_FFECHALEIDO=None,
            )
    except Exception as exc:
        registrar_log_camion_no_planificado(
            usuario_planificador,
            solicitud.EP_NID,
            'PAT_NP_NOT_ERR',
            f'Error controlado al crear notificacion final: {type(exc).__name__}: {str(exc)[:250]}. {datos_log}',
            solicitud.id,
            camion.id,
        )
        return None, False

    if notificacion is None:
        registrar_log_camion_no_planificado(
            usuario_planificador,
            solicitud.EP_NID,
            'PAT_NP_NOT_ERR',
            f'Notificacion final no creada: destinatario sin acceso vigente. {datos_log}',
            solicitud.id,
            camion.id,
        )
        return None, False

    registrar_log_camion_no_planificado(
        usuario_planificador,
        solicitud.EP_NID,
        'PAT_NP_NOT_OK',
        f'Notificacion final #{notificacion.id} creada correctamente. {datos_log}',
        solicitud.id,
        notificacion.id,
    )
    return notificacion, True


def _datos_teams_camion_patio_no_planificado(solicitud, request):
    camion = solicitud.CPA_NID
    empresa = solicitud.EP_NID
    valor = lambda dato: str(dato).strip() if dato not in (None, '') else '-'
    llegada = timezone.localtime(camion.CPA_FFECHALLEGADA).strftime('%d/%m/%Y %H:%M:%S') if camion.CPA_FFECHALLEGADA else '-'
    hechos = [
        ('Patente', valor(camion.CPA_CPATENTE)),
        ('Transporte a cargo de', valor(camion.get_transporte_a_cargo_display())),
        ('Transportista', valor(camion.CPA_CTRANSPORTISTA_DECLARADO)),
        ('Conductor', valor(camion.CPA_CNOMBRE_CONDUCTOR)),
        ('RUT conductor', valor(camion.CPA_CRUT_CONDUCTOR)),
        ('Telefono', valor(camion.CPA_CTELEFONO_CONDUCTOR)),
        ('Proveedor declarado', valor(camion.CPA_CPROVEEDOR_DECLARADO)),
        ('Cliente declarado', valor(camion.CPA_CCLIENTE_DECLARADO)),
        ('Insumo declarado en guia', valor(camion.CPA_CINSUMO_DECLARADO_GUIA)),
        ('Numero guia/documento', valor(camion.CPA_CNUMERO_GUIA)),
        ('BL', valor(camion.CPA_CBL)),
        ('Lote/contenedor', valor(camion.CPA_CLOTE_CONTENEDOR)),
        ('Observacion', valor(camion.CPA_COBSERVACION)),
        ('Fecha y hora de llegada', llegada),
        ('Asistente Recepcion', valor(camion.US_GUARDIA_ID.username if camion.US_GUARDIA_ID else '')),
        ('Empresa activa', valor(empresa.EP_CRAZONSOCIAL)),
    ]
    documentos = []
    for adjunto in camion.adjuntos.all().order_by('CPA_FFECHACARGA', 'id'):
        documentos.append((
            os.path.basename(adjunto.CPA_FARCHIVO.name) or f'Documento #{adjunto.id}',
            _url_publica_aplicacion(
                request,
                reverse('camion_patio_adjunto_ver', args=[adjunto.id]) + f'?_empresa_id={empresa.id}'
            )
        ))
    revisar_url = _url_publica_aplicacion(
        request,
        reverse('camion_patio_no_planificado_revisar', args=[solicitud.id]) + f'?_empresa_id={empresa.id}'
    )
    camion_url = _url_publica_aplicacion(
        request,
        reverse('camiones_patio_list') + f'?_empresa_id={empresa.id}&camion_patio={camion.id}'
    )
    mensaje = (
        f'Solicitud #{solicitud.id} para el camion patio #{camion.id}.\n'
        'Revise los antecedentes y documentos en TRANSIX.'
    )
    mensaje += '\n\n' + '\n'.join(f'{titulo}: {dato}' for titulo, dato in hechos)
    if documentos:
        mensaje += '\n\nDocumentos:\n' + '\n'.join(f'- {nombre}: {url}' for nombre, url in documentos)
    else:
        mensaje += '\n\nSin documentos adjuntos'
    mensaje += f'\n\nRevisar solicitud: {revisar_url}\nVer camion en patio: {camion_url}'
    return mensaje, hechos, documentos, revisar_url, camion_url


def _enviar_teams_camion_patio_no_planificado(solicitud_id, request, operacion_log):
    with transaction.atomic():
        solicitud = CAMION_PATIO_NO_PLANIFICADO.objects.select_for_update().select_related(
            'CPA_NID', 'CPA_NID__US_GUARDIA_ID', 'EP_NID'
        ).prefetch_related('CPA_NID__adjuntos').get(pk=solicitud_id)
        if solicitud.CPNP_BTEAMS_ENVIADO:
            return solicitud, False
        if solicitud.CPNP_CTEAMS_ESTADO == 'ENVIANDO':
            return solicitud, False
        solicitud.CPNP_CTEAMS_ESTADO = 'ENVIANDO'
        solicitud.CPNP_CTEAMS_DETALLE = ''
        solicitud.save(update_fields=['CPNP_CTEAMS_ESTADO', 'CPNP_CTEAMS_DETALLE'])

    mensaje, hechos, documentos, revisar_url, camion_url = _datos_teams_camion_patio_no_planificado(solicitud, request)
    planificador = obtener_planificador_camion_no_planificado()
    try:
        resultado = enviar_solicitud_camion_patio_no_planificado_teams(
            planificador.email if planificador else '',
            mensaje,
            hechos,
            documentos,
            revisar_url,
            camion_url
        )
    except Exception as exc:
        resultado = TeamsNotificationResult(False, 'TEAMS_ERROR', str(exc))
    with transaction.atomic():
        solicitud = CAMION_PATIO_NO_PLANIFICADO.objects.select_for_update().select_related(
            'CPA_NID', 'EP_NID'
        ).get(pk=solicitud_id)
        solicitud.CPNP_BTEAMS_ENVIADO = bool(resultado.success)
        solicitud.CPNP_CTEAMS_ESTADO = str(resultado.status or '')[:50]
        solicitud.CPNP_CTEAMS_DETALLE = str(resultado.detail or '')[:4000]
        solicitud.save(update_fields=['CPNP_BTEAMS_ENVIADO', 'CPNP_CTEAMS_ESTADO', 'CPNP_CTEAMS_DETALLE'])
    registrar_log_camion_no_planificado(
        request.user,
        solicitud.EP_NID,
        operacion_log if resultado.success else 'PAT_NP_TERR',
        (
            f'Teams {"enviado" if resultado.success else "con error"} para solicitud patio no planificado '
            f'#{solicitud.id}. Estado: {resultado.status}. Detalle: {resultado.detail}'
        ),
        solicitud.id,
        solicitud.CPA_NID.CPA_CPATENTE
    )
    return solicitud, True


def usuario_puede_ver_control_camion_patio(user):
    return (
        getattr(user, 'is_superuser', False)
        or normalizar_nombre_perfil(getattr(user, 'username', '')) == 'MAESC'
        or usuario_es_guardia(user)
        or usuario_es_asistente_recepcion(user)
        or usuario_es_asistente_cd(user)
        or usuario_es_planificador(user)
    )


def _usuarios_asistente_recepcion_empresa(empresa_id, usuario_excluir=None):
    usuarios_empresa_ids = USERS_EMPRESA.objects.filter(
        EP_NID_id=empresa_id
    ).values_list('US_NID_id', flat=True)
    usuarios = User.objects.filter(
        id__in=usuarios_empresa_ids,
        is_active=True
    ).select_related('userv')
    if usuario_excluir:
        usuarios = usuarios.exclude(pk=usuario_excluir.pk)
    return [
        usuario for usuario in usuarios
        if usuario_es_asistente_recepcion(usuario)
    ]


def notificar_camion_patio_nuevo(camion, usuario_registra):
    if not camion or camion.CPA_CESTADO != CAMION_PATIO.ESTADO_PENDIENTE_ASOCIACION:
        return 0

    empresa = camion.EP_NID
    if not empresa:
        return 0

    url = f'/camiones-patio/?_empresa_id={empresa.id}&camion_patio={camion.id}'
    fecha_llegada = timezone.localtime(camion.CPA_FFECHALLEGADA).strftime('%d/%m/%Y %H:%M:%S') if camion.CPA_FFECHALLEGADA else timezone.localtime(timezone.now()).strftime('%d/%m/%Y %H:%M:%S')
    mensaje = (
        'Camion ingresado a patio\n'
        f'Ha ingresado camion patente {camion.CPA_CPATENTE} al patio de espera. Se debe asignar a citacion.\n'
        f'Transportista: {camion.CPA_CTRANSPORTISTA_DECLARADO or "Sin informacion"}\n'
        f'Conductor: {camion.CPA_CNOMBRE_CONDUCTOR or "Sin informacion"}\n'
        f'Insumo declarado en guia: {camion.CPA_CINSUMO_DECLARADO_GUIA or "Sin informacion"}\n'
        f'Hora de llegada: {fecha_llegada}\n'
        f'Asistente Recepcion: {usuario_registra.username if usuario_registra else "Sin informacion"}\n'
        f'Camion patio: #{camion.id}'
    )

    creadas = 0
    for usuario in _usuarios_asistente_recepcion_empresa(empresa.id, usuario_excluir=usuario_registra):
        if NOTIFICACION.objects.filter(
            USER_RECEIVER_ID=usuario,
            EP_NID=empresa,
            NOT_CURL=url,
            NOT_CCONTENIDO__icontains=f'Camion patio: #{camion.id}',
            NOT_BHABILITADO=True,
        ).exists():
            continue
        crear_notificacion_interna(
            USER_SENDER_ID=usuario_registra,
            USER_RECEIVER_ID=usuario,
            EP_NID=empresa,
            NOT_CCONTENIDO=mensaje,
            NOT_CURL=url
        )
        creadas += 1
    return creadas


def notificar_camion_patio_asistente_despacho(camion, usuario_envia, *, origen):
    if not camion:
        return 0
    url = f'/camiones-patio/?_empresa_id={camion.EP_NID_id}&camion_patio={camion.id}'
    try:
        traza = camion.trazabilidad_planificacion
    except CAMION_PATIO_TRAZABILIDAD_PLANIFICACION.DoesNotExist:
        traza = None
    llegada = timezone.localtime(camion.CPA_FFECHALLEGADA).strftime('%d/%m/%Y %H:%M:%S')
    sin_dato = '-'
    citacion_sugerida = f'#{traza.CI_NID_id}' if traza and traza.CI_NID_id else sin_dato
    planificacion_sugerida = f'#{traza.PL_NID_id}' if traza and traza.PL_NID_id else sin_dato
    mensaje = (
        'Camión de despacho requiere atención\n\n'
        f'El camión patente {camion.CPA_CPATENTE or sin_dato} se presentó en Patio de Camiones y requiere su atención.\n\n'
        f'Conductor: {camion.CPA_CNOMBRE_CONDUCTOR or sin_dato}\n'
        f'Transportista: {camion.CPA_CTRANSPORTISTA_DECLARADO or sin_dato}\n'
        f'Origen: {origen}\nIngreso: {llegada}\n\n'
        f'Citacion sugerida: {citacion_sugerida}\n'
        f'Planificacion: {planificacion_sugerida}\n\n'
        'Revise y asocie el camión a la citación de despacho correspondiente.\n\n'
        f'Camion patio: #{camion.id}'
    )
    creadas = 0
    for usuario in _usuarios_asistente_despacho_empresa(camion.EP_NID_id, usuario_excluir=usuario_envia):
        if NOTIFICACION.objects.filter(USER_RECEIVER_ID=usuario, EP_NID=camion.EP_NID, NOT_CURL=url, NOT_CCONTENIDO__icontains=f'Camion patio: #{camion.id}', NOT_BHABILITADO=True).exists():
            continue
        crear_notificacion_interna(USER_SENDER_ID=usuario_envia, USER_RECEIVER_ID=usuario, EP_NID=camion.EP_NID, NOT_CCONTENIDO=mensaje, NOT_CURL=url)
        creadas += 1
    return creadas


def resolver_notificaciones_camion_patio_asistente_despacho(camion):
    url = f'/camiones-patio/?_empresa_id={camion.EP_NID_id}&camion_patio={camion.id}'
    return NOTIFICACION.objects.filter(
        EP_NID_id=camion.EP_NID_id,
        NOT_CURL=url,
        NOT_CCONTENIDO__icontains=f'Camion patio: #{camion.id}',
        NOT_BHABILITADO=True,
        NOT_BREAD=False,
    ).update(NOT_BREAD=True, NOT_FFECHALEIDO=timezone.now())


def _normalizar_match_texto(valor):
    texto = unicodedata.normalize('NFKD', str(valor or '').upper())
    texto = ''.join(caracter for caracter in texto if not unicodedata.combining(caracter))
    return ' '.join(re.sub(r'[^A-Z0-9]+', ' ', texto).split())


def _resolver_conductor_snapshot_camion_patio(camion):
    rut = str(getattr(camion, 'CPA_CRUT_CONDUCTOR', '') or '').strip()
    nombre = str(getattr(camion, 'CPA_CNOMBRE_CONDUCTOR', '') or '').strip()
    if not rut:
        return None
    conductor_id = getattr(camion, 'CON_NID_id', None)
    if conductor_id:
        conductor_fk = CONDUCTOR.objects.select_related('SN_NID').filter(
            pk=conductor_id,
            CON_BHABILITADO=True,
        ).first()
        if conductor_fk and _conductor_coincide_nombre(conductor_fk, nombre):
            return conductor_fk
    try:
        conductor_planificado = camion.trazabilidad_planificacion.CI_NID.CON_NID
    except (
        CAMION_PATIO_TRAZABILIDAD_PLANIFICACION.DoesNotExist,
        AttributeError,
        CITACION.DoesNotExist,
    ):
        conductor_planificado = None
    if (
        conductor_planificado
        and conductor_planificado.CON_BHABILITADO
        and _conductor_coincide_nombre(conductor_planificado, nombre)
    ):
        return conductor_planificado
    candidatos = list(
        CONDUCTOR.objects.select_related('SN_NID').filter(
            CON_CRUT__iexact=rut,
            CON_BHABILITADO=True,
        ).order_by('id')[:3]
    )
    if len(candidatos) == 1:
        return candidatos[0]
    nombre_normalizado = _normalizar_match_texto(nombre)
    coincidencias = [
        candidato for candidato in candidatos
        if nombre_normalizado in {
            _normalizar_match_texto(candidato.CON_CNOMBRE),
            _normalizar_match_texto(
                ' '.join(filter(None, [
                    candidato.CON_CNOMBRE,
                    candidato.CON_CAPELLIDO,
                ]))
            ),
        }
    ]
    return coincidencias[0] if len(coincidencias) == 1 else None


def _conductor_coincide_nombre(conductor, nombre):
    nombre_normalizado = _normalizar_match_texto(nombre)
    nombres_maestro = {
        _normalizar_match_texto(conductor.CON_CNOMBRE),
        _normalizar_match_texto(' '.join(filter(None, [
            conductor.CON_CNOMBRE,
            conductor.CON_CAPELLIDO,
        ]))),
    }
    return bool(nombre_normalizado and nombre_normalizado in nombres_maestro)


def _conductor_coincide_identidad(conductor, nombre, rut):
    try:
        rut_snapshot = normalizar_rut_chileno(rut)
        rut_maestro = normalizar_rut_chileno(conductor.CON_CRUT)
    except RutChilenoInvalido:
        return False
    return bool(
        _conductor_coincide_nombre(conductor, nombre)
        and rut_snapshot == rut_maestro
    )


def _resolver_conductor_maestro_por_identidad(nombre, rut, conductor_id=None):
    candidatos = CONDUCTOR.objects.select_related('SN_NID').filter(CON_BHABILITADO=True)
    if conductor_id and str(conductor_id).isdigit():
        candidato = candidatos.filter(pk=int(conductor_id)).first()
        if candidato and _conductor_coincide_identidad(candidato, nombre, rut):
            return candidato
    cuerpo, dv = rut.split('-', 1)
    rut_con_puntos = f'{int(cuerpo):,}'.replace(',', '.') + '-' + dv
    coincidencias = [
        candidato for candidato in candidatos.filter(
            Q(CON_CRUT__iexact=rut) | Q(CON_CRUT__iexact=rut_con_puntos)
        ).order_by('id')
        if _conductor_coincide_identidad(candidato, nombre, rut)
    ]
    return coincidencias[0] if len(coincidencias) == 1 else None


def _resolver_transportista_snapshot_camion_patio(camion):
    nombre = str(
        getattr(camion, 'CPA_CTRANSPORTISTA_DECLARADO', '') or ''
    ).strip()
    if not nombre:
        return None
    nombre_normalizado = _normalizar_match_texto(nombre)
    candidatos = SOCIONEGOCIO.objects.filter(
        EP_NID_id=getattr(camion, 'EP_NID_id', None),
        SN_BHABILITADO=True,
        SN_CTIPO='S',
    ).order_by('id')
    return next(
        (
            candidato for candidato in candidatos
            if _normalizar_match_texto(candidato.SN_CRAZONSOCIAL)
            == nombre_normalizado
        ),
        None,
    )


def _datos_precarga_camion_patio(camion):
    # Los snapshots de patio tienen prioridad; el maestro solo completa vacios.
    datos = {
        'conductor': str(getattr(camion, 'CPA_CNOMBRE_CONDUCTOR', '') or '').strip(),
        'rut_conductor': str(getattr(camion, 'CPA_CRUT_CONDUCTOR', '') or '').strip(),
        'telefono_codigo_pais': str(getattr(camion, 'CPA_CCODIGO_PAIS_TELEFONO', '') or '').strip(),
        'telefono_conductor': str(getattr(camion, 'CPA_CTELEFONO_CONDUCTOR', '') or '').strip(),
        'transportista': str(getattr(camion, 'CPA_CTRANSPORTISTA_DECLARADO', '') or '').strip(),
    }
    if all(datos.values()):
        return datos
    conductor = _resolver_conductor_snapshot_camion_patio(camion)
    if conductor:
        nombre_maestro = ' '.join(filter(None, [
            str(conductor.CON_CNOMBRE or '').strip(),
            str(conductor.CON_CAPELLIDO or '').strip(),
        ]))
        datos['conductor'] = datos['conductor'] or nombre_maestro
        datos['rut_conductor'] = datos['rut_conductor'] or str(conductor.CON_CRUT or '').strip()
        datos['telefono_codigo_pais'] = datos['telefono_codigo_pais'] or str(conductor.CON_CCODIGO_PAIS_TELEFONO or '').strip()
        datos['telefono_conductor'] = datos['telefono_conductor'] or str(conductor.CON_CTELEFONO or '').strip()
        transportista_maestro = getattr(conductor, 'SN_NID', None)
        if not datos['transportista'] and transportista_maestro:
            datos['transportista'] = str(transportista_maestro.SN_CRAZONSOCIAL or '').strip()
    return datos


def _normalizar_bl_match(valor):
    """Normaliza BL solo para comparar; nunca altera el dato persistido."""
    return re.sub(r'[^A-Z0-9]', '', str(valor or '').strip().upper())


def _distancia_edicion_bl(valor_a, valor_b):
    """Distancia Levenshtein acotada a la regla de un caracter."""
    if valor_a == valor_b:
        return 0
    if abs(len(valor_a) - len(valor_b)) > 1:
        return 2
    anterior = list(range(len(valor_b) + 1))
    for indice_a, caracter_a in enumerate(valor_a, 1):
        actual = [indice_a]
        for indice_b, caracter_b in enumerate(valor_b, 1):
            actual.append(min(
                actual[-1] + 1,
                anterior[indice_b] + 1,
                anterior[indice_b - 1] + (caracter_a != caracter_b),
            ))
        if min(actual) > 1:
            return 2
        anterior = actual
    return anterior[-1]


def _es_camion_recepcion_sbh_patio(camion):
    return bool(
        getattr(camion, 'EP_NID_id', None) == 2
        and str(getattr(camion, 'CPA_CTIPO_RECEPCION', '') or '').upper() in {'NACIONAL', 'IMPORTACION', 'EXTRANJERO'}
    )


def _detalle_operacional_citacion(citacion):
    try:
        return citacion.detalle_operacional
    except (CITACION_DETALLE_OPERACIONAL.DoesNotExist, AttributeError):
        return None


PLAN_CODIGO_CLIENTE_SAP = 'PLAN_CODIGO_CLIENTE_SAP'
PLAN_CLIENTE_SAP = 'PLAN_CLIENTE_SAP'


def es_citacion_recepcion_sbh(citacion):
    return bool(
        citacion
        and citacion.EP_NID_id == 2
        and str(citacion.CI_CTIPO or '').upper() == CIT_RECEPCION
    )


def obtener_cliente_planificacion_citacion(citacion):
    """Obtiene el cliente de planificación, priorizando el detalle SAP en Despacho."""
    cache = getattr(citacion, '_cliente_planificacion_cache', None)
    if cache is not None:
        return cache

    fallback = {
        'codigo': citacion.SN_NID.SN_CCODIGO_SAP if citacion and citacion.SN_NID else '',
        'nombre': citacion.SN_NID.SN_CRAZONSOCIAL if citacion and citacion.SN_NID else '',
    }
    tipo_citacion = str(
        citacion.CI_CTIPO or (citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '') or ''
    ).upper()
    es_despacho = tipo_citacion == CIT_DESPACHO
    if not es_despacho and not es_citacion_recepcion_sbh(citacion):
        setattr(citacion, '_cliente_planificacion_cache', fallback)
        return fallback

    registros = getattr(citacion, '_datos_cliente_planificacion', None)
    if registros is None:
        filtros = {
            'CI_NID': citacion,
            'CAMP_NID__CA_CCODIGO__in': [PLAN_CODIGO_CLIENTE_SAP, PLAN_CLIENTE_SAP],
        }
        if not es_despacho:
            filtros['SC_NID'] = citacion.SC_NID
        registros = DATO_OPERACION.objects.filter(**filtros).select_related('CAMP_NID').order_by('-id')

    valores = {}
    for dato in registros:
        codigo = dato.CAMP_NID.CA_CCODIGO
        if codigo not in valores:
            valores[codigo] = str(dato.DO_CVALOR or '').strip()

    detalle_despacho = _detalle_despacho_citacion_patio(citacion) if es_despacho else None
    resultado = {
        'codigo': (
            str(getattr(detalle_despacho, 'CDD_CSAP_CLIENTE_CODIGO', '') or '').strip()
            or valores.get(PLAN_CODIGO_CLIENTE_SAP)
            or fallback['codigo']
        ),
        'nombre': (
            str(getattr(detalle_despacho, 'CDD_CSAP_CLIENTE_NOMBRE', '') or '').strip()
            or valores.get(PLAN_CLIENTE_SAP)
            or fallback['nombre']
        ),
    }
    setattr(citacion, '_cliente_planificacion_cache', resultado)
    return resultado


def obtener_contrato_planificacion_citacion(citacion):
    """Obtiene el contrato SAP persistido para una citación de Despacho."""
    if _tipo_citacion_patio(citacion) != CIT_DESPACHO:
        return ''

    detalle_despacho = _detalle_despacho_citacion_patio(citacion)
    contrato_detalle = str(
        getattr(detalle_despacho, 'CDD_CSAP_NUMERO_ACUERDO', '') or ''
    ).strip()
    if contrato_detalle:
        return contrato_detalle

    registros = getattr(citacion, '_datos_cliente_planificacion', None)
    if registros is None:
        registros = DATO_OPERACION.objects.filter(
            CI_NID=citacion,
            CAMP_NID__CA_CCODIGO='PLAN_CONTRATO_SAP',
        ).select_related('CAMP_NID').order_by('-id')
    for dato in registros:
        if dato.CAMP_NID.CA_CCODIGO == 'PLAN_CONTRATO_SAP':
            return str(dato.DO_CVALOR or '').strip()
    return ''


def _normalizar_patente_camion_patio(valor):
    return (
        str(valor or '')
        .strip()
        .upper()
        .replace('-', '')
        .replace(' ', '')
        .replace('.', '')
    )


def _tipo_citacion_patio(citacion):
    tipo = str(citacion.CI_CTIPO or (citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '') or '').upper()
    return tipo if tipo in {CIT_DESPACHO, CIT_RECEPCION} else CIT_RECEPCION


def _detalle_despacho_citacion_patio(citacion):
    try:
        return citacion.detalle_despacho
    except (CITACION_DESPACHO_DETALLE.DoesNotExist, AttributeError):
        return None


def _etiqueta_salida_documento_despacho(valor):
    codigo = str(valor or '').strip().upper()
    return {
        'FE': 'Factura de cliente',
        'GD': 'Guía de despacho',
        'FE_RESERVA': 'Factura reserva',
    }.get(codigo, codigo)


def _patente_planificada_despacho_patio(citacion, valores_ingreso=None):
    if _tipo_citacion_patio(citacion) != CIT_DESPACHO:
        return ''
    detalle_despacho = _detalle_despacho_citacion_patio(citacion)
    if detalle_despacho and str(detalle_despacho.CDD_CPATENTE or '').strip():
        return str(detalle_despacho.CDD_CPATENTE or '').strip()
    valores_ingreso = valores_ingreso if valores_ingreso is not None else obtener_valores_ingreso_camion(citacion)
    return str(valores_ingreso.get('patente') or '').strip()


def _estado_patente_despacho_patio(camion, citacion, valores_ingreso=None):
    patente_citacion = _patente_planificada_despacho_patio(citacion, valores_ingreso=valores_ingreso)
    patente_camion_normalizada = _normalizar_patente_camion_patio(camion.CPA_CPATENTE)
    patente_citacion_normalizada = _normalizar_patente_camion_patio(patente_citacion)
    if not patente_citacion_normalizada:
        return patente_citacion, patente_citacion_normalizada, False, 'pendiente'
    if patente_camion_normalizada and patente_camion_normalizada == patente_citacion_normalizada:
        return patente_citacion, patente_citacion_normalizada, True, 'coincide'
    return patente_citacion, patente_citacion_normalizada, False, 'distinta'


def _detalle_recepcion_terramar_citacion_patio(citacion):
    if not es_citacion_recepcion_terramar(citacion):
        return None
    try:
        return citacion.detalle_recepcion_terramar
    except (CITACION_RECEPCION_TERRAMAR_DETALLE.DoesNotExist, AttributeError):
        return None


def _normalizar_identificador_match(valor):
    return re.sub(r'[^A-Z0-9]', '', str(valor or '').strip().upper())


def _nombre_conductor_patio(conductor):
    if not conductor:
        return ''
    return ' '.join(filter(None, [
        str(getattr(conductor, 'CON_CNOMBRE', '') or '').strip(),
        str(getattr(conductor, 'CON_CAPELLIDO', '') or '').strip(),
    ]))


def _datos_planificados_recepcion_terramar_patio(citacion, detalle_operacional=None):
    detalle_operacional = detalle_operacional or _detalle_operacional_citacion(citacion)
    detalle_terramar = _detalle_recepcion_terramar_citacion_patio(citacion)
    conductor = (
        getattr(detalle_terramar, 'CON_NID', None)
        or getattr(citacion, 'CON_NID', None)
    )
    transportista = getattr(detalle_terramar, 'SN_NID_TRANSPORTISTA', None)
    proveedor = getattr(citacion, 'PRO_NID', None)
    nombre_proveedor = str(
        (getattr(detalle_operacional, 'CDO_CPRODUCTOR', '') if detalle_operacional else '')
        or (getattr(proveedor, 'SN_CRAZONSOCIAL', '') if proveedor else '')
        or ''
    ).strip()
    nombre_conductor = str(
        getattr(detalle_terramar, 'RTD_CCONDUCTOR', '') or ''
    ).strip() or _nombre_conductor_patio(conductor)
    nombre_transportista = str(
        getattr(detalle_terramar, 'RTD_CEMPRESA_TRANSPORTE', '') or ''
    ).strip() or str(
        getattr(transportista, 'SN_CRAZONSOCIAL', '') or ''
    ).strip()
    return {
        'patente': str(getattr(detalle_terramar, 'RTD_CPATENTE', '') or '').strip(),
        'producto': str(getattr(detalle_operacional, 'CDO_CINSUMO', '') or '').strip(),
        'transportista': nombre_transportista,
        'transportista_id': getattr(detalle_terramar, 'SN_NID_TRANSPORTISTA_id', None),
        'conductor': nombre_conductor,
        'conductor_id': getattr(detalle_terramar, 'CON_NID_id', None) or getattr(citacion, 'CON_NID_id', None),
        'rut_conductor': str(getattr(conductor, 'CON_CRUT', '') or '').strip(),
        'guia': str(
            getattr(citacion, 'CI_CNUMERODOCUMENTO', '')
            or (getattr(detalle_operacional, 'CDO_CGUIA', '') if detalle_operacional else '')
            or ''
        ).strip(),
        'contenedor': str(
            getattr(detalle_terramar, 'RTD_CCONTENEDOR_CRT', '')
            or (getattr(detalle_operacional, 'CDO_CBL_CONTENEDOR', '') if detalle_operacional else '')
            or ''
        ).strip(),
        'proveedor': nombre_proveedor,
        'proveedor_id': getattr(citacion, 'PRO_NID_id', None),
        'proveedor_codigo': str(getattr(proveedor, 'SN_CCODIGO_SAP', '') or '').strip() if proveedor else '',
    }


def _diferencia_horaria_patio(camion, citacion):
    fecha_planificada = (
        getattr(getattr(citacion, 'PL_NID', None), 'PL_FFECHAINICIO', None)
        or getattr(citacion, 'CI_FFECHACITACION', None)
    )
    llegada = getattr(camion, 'CPA_FFECHALLEGADA', None)
    if not fecha_planificada or not llegada:
        return None
    return abs((llegada - fecha_planificada).total_seconds()) / 3600


def _detalle_diferencia_horaria_patio(horas):
    minutos = int(round(float(horas or 0) * 60))
    if minutos < 60:
        return f'{minutos} min'
    horas_enteras, minutos_restantes = divmod(minutos, 60)
    return f'{horas_enteras} h {minutos_restantes:02d} min'


def _score_recepcion_terramar_patio(camion, citacion, detalle_operacional=None):
    """Score 0..100 para sugerencias de Recepcion Terramar."""
    datos = _datos_planificados_recepcion_terramar_patio(
        citacion,
        detalle_operacional=detalle_operacional,
    )
    desglose = []

    def sumar(criterio, puntos, detalle):
        desglose.append({
            'criterio': criterio,
            'puntos': puntos,
            'detalle': detalle,
        })

    patente_camion = _normalizar_patente_camion_patio(camion.CPA_CPATENTE)
    patente_citacion = _normalizar_patente_camion_patio(datos['patente'])
    if patente_camion and patente_camion == patente_citacion:
        sumar('Patente', 30, f'Patente coincide: {datos["patente"]}')

    guia_camion = _normalizar_identificador_match(camion.CPA_CNUMERO_GUIA)
    guia_citacion = _normalizar_identificador_match(datos['guia'])
    if guia_camion and guia_camion == guia_citacion:
        sumar('Guia', 20, f'Guia coincide: {datos["guia"]}')

    transportista_camion = _resolver_transportista_snapshot_camion_patio(camion)
    mismo_transportista_id = bool(
        transportista_camion
        and datos['transportista_id']
        and transportista_camion.id == datos['transportista_id']
    )
    mismo_transportista_texto = bool(
        _normalizar_match_texto(camion.CPA_CTRANSPORTISTA_DECLARADO)
        and _normalizar_match_texto(camion.CPA_CTRANSPORTISTA_DECLARADO)
        == _normalizar_match_texto(datos['transportista'])
    )
    if mismo_transportista_id or mismo_transportista_texto:
        sumar('Transportista', 15, f'Transportista coincide: {datos["transportista"]}')

    producto_camion = _normalizar_match_texto(camion.CPA_CINSUMO_DECLARADO_GUIA)
    producto_citacion = _normalizar_match_texto(datos['producto'])
    if (
        producto_camion
        and producto_citacion
        and (producto_camion in producto_citacion or producto_citacion in producto_camion)
    ):
        sumar('Producto', 10, 'Producto coincide')

    conductor_camion = getattr(camion, 'CON_NID', None)
    mismo_conductor_id = bool(
        conductor_camion
        and datos['conductor_id']
        and conductor_camion.id == datos['conductor_id']
    )
    mismo_conductor_nombre = bool(
        _normalizar_match_texto(camion.CPA_CNOMBRE_CONDUCTOR)
        and _normalizar_match_texto(camion.CPA_CNOMBRE_CONDUCTOR)
        == _normalizar_match_texto(datos['conductor'])
    )
    if mismo_conductor_id or mismo_conductor_nombre:
        sumar('Conductor', 7, f'Conductor coincide: {datos["conductor"]}')

    rut_camion = _normalizar_identificador_match(camion.CPA_CRUT_CONDUCTOR)
    rut_citacion = _normalizar_identificador_match(datos['rut_conductor'])
    if rut_camion and rut_camion == rut_citacion:
        sumar('RUT conductor', 5, f'RUT coincide: {datos["rut_conductor"]}')

    contenedor_camion = _normalizar_identificador_match(camion.CPA_CLOTE_CONTENEDOR)
    contenedor_citacion = _normalizar_identificador_match(datos['contenedor'])
    if contenedor_camion and contenedor_camion == contenedor_citacion:
        sumar('Contenedor', 5, f'Contenedor coincide: {datos["contenedor"]}')

    proveedor_camion = _normalizar_match_texto(camion.CPA_CPROVEEDOR_DECLARADO)
    proveedor_citacion = _normalizar_match_texto(datos['proveedor'])
    if proveedor_camion and proveedor_camion == proveedor_citacion:
        sumar('Proveedor', 5, f'Proveedor coincide: {datos["proveedor"]}')

    diferencia_horas = _diferencia_horaria_patio(camion, citacion)
    if diferencia_horas is not None and diferencia_horas <= 24:
        sumar('Horario', 3, f'Horario cercano: {_detalle_diferencia_horaria_patio(diferencia_horas)}')
    elif diferencia_horas is not None and diferencia_horas <= 72:
        sumar('Horario', 1, f'Horario relacionado: {_detalle_diferencia_horaria_patio(diferencia_horas)}')

    score = sum(item['puntos'] for item in desglose)
    return score, [item['detalle'] for item in desglose], {
        **datos,
        'patente_normalizada': patente_citacion,
        'patente_coincide': bool(patente_camion and patente_camion == patente_citacion),
        'patente_estado': (
            'pendiente' if not patente_citacion
            else ('coincide' if patente_camion == patente_citacion else 'distinta')
        ),
        'desglose': desglose,
        'diferencia_horas': diferencia_horas,
    }

def _score_despacho_terramar_patio(camion, citacion):
    # Score y desglose para sugerencias de Despacho Terramar.
    datos = _payload_citacion_terramar_patio(citacion)
    desglose = []

    def sumar(criterio, puntos, detalle):
        desglose.append({
            'criterio': criterio,
            'puntos': puntos,
            'detalle': detalle,
        })

    patente_camion = _normalizar_patente_camion_patio(camion.CPA_CPATENTE)
    patente_citacion = _normalizar_patente_camion_patio(datos.get('patente'))
    patente_coincide = bool(patente_camion and patente_camion == patente_citacion)
    if patente_coincide:
        sumar('Patente', 100, f'Patente coincide: {datos.get("patente") or ""}')

    transportista_camion = _normalizar_match_texto(camion.CPA_CTRANSPORTISTA_DECLARADO)
    transportista_citacion = _normalizar_match_texto(datos.get('empresa_transporte_nombre'))
    if transportista_camion and transportista_citacion and transportista_camion == transportista_citacion:
        sumar('Transportista', 15, f'Transportista coincide: {datos.get("empresa_transporte_nombre") or ""}')

    producto_camion = _normalizar_match_texto(camion.CPA_CINSUMO_DECLARADO_GUIA)
    producto_citacion = _normalizar_match_texto(datos.get('insumo'))
    if producto_camion and producto_citacion and (
        producto_camion in producto_citacion or producto_citacion in producto_camion
    ):
        sumar('Producto', 45, 'Producto coincide')

    conductor_camion = getattr(camion, 'CON_NID', None)
    conductor_citacion_id = datos.get('conductor_id')
    mismo_conductor_id = bool(
        conductor_camion and conductor_citacion_id and conductor_camion.id == conductor_citacion_id
    )
    mismo_conductor_nombre = bool(
        _normalizar_match_texto(camion.CPA_CNOMBRE_CONDUCTOR)
        and _normalizar_match_texto(camion.CPA_CNOMBRE_CONDUCTOR)
        == _normalizar_match_texto(datos.get('conductor_nombre'))
    )
    if mismo_conductor_id or mismo_conductor_nombre:
        sumar('Conductor', 7, f'Conductor coincide: {datos.get("conductor_nombre") or ""}')

    rut_camion = _normalizar_identificador_match(camion.CPA_CRUT_CONDUCTOR)
    rut_citacion = _normalizar_identificador_match(datos.get('conductor_rut'))
    if rut_camion and rut_citacion and rut_camion == rut_citacion:
        sumar('RUT conductor', 5, f'RUT coincide: {datos.get("conductor_rut") or ""}')

    cliente_camion = _normalizar_match_texto(camion.CPA_CCLIENTE_DECLARADO)
    cliente_citacion = _normalizar_match_texto(datos.get('cliente'))
    if cliente_camion and cliente_citacion and (
        cliente_camion in cliente_citacion or cliente_citacion in cliente_camion
    ):
        sumar('Cliente', 15, 'Cliente coincide')

    diferencia_horas = _diferencia_horaria_patio(camion, citacion)
    if diferencia_horas is not None and diferencia_horas <= 24:
        sumar('Horario', 10, f'Horario cercano: {_detalle_diferencia_horaria_patio(diferencia_horas)}')
    elif diferencia_horas is not None and diferencia_horas <= 72:
        sumar('Horario', 4, f'Horario relacionado: {_detalle_diferencia_horaria_patio(diferencia_horas)}')

    score = sum(item['puntos'] for item in desglose)
    return score, [item['detalle'] for item in desglose], {
        **datos,
        'patente_normalizada': patente_citacion,
        'patente_coincide': patente_coincide,
        'patente_estado': (
            'pendiente' if not patente_citacion
            else ('coincide' if patente_coincide else 'distinta')
        ),
        'desglose': desglose,
        'diferencia_horas': diferencia_horas,
    }


def _score_citacion_camion_patio(camion, citacion):
    if es_citacion_despacho_terramar_principal(citacion):
        return _score_despacho_terramar_patio(camion, citacion)
    detalle = _detalle_operacional_citacion(citacion)
    if es_citacion_recepcion_terramar(citacion):
        return _score_recepcion_terramar_patio(
            camion,
            citacion,
            detalle_operacional=detalle,
        )
    valores_ingreso = obtener_valores_ingreso_camion(citacion)
    tipo = _tipo_citacion_patio(citacion)
    score = 0
    razones = []
    patente, patente_normalizada, patente_coincide, patente_estado = _estado_patente_despacho_patio(
        camion,
        citacion,
        valores_ingreso=valores_ingreso,
    )
    producto_camion = _normalizar_match_texto(camion.CPA_CINSUMO_DECLARADO_GUIA)
    proveedor_camion = _normalizar_match_texto(camion.CPA_CPROVEEDOR_DECLARADO)
    cliente_camion = _normalizar_match_texto(camion.CPA_CCLIENTE_DECLARADO)
    producto_citacion = _normalizar_match_texto(detalle.CDO_CINSUMO if detalle else '')
    proveedor_citacion = _normalizar_match_texto((detalle.CDO_CPRODUCTOR if detalle else '') or (citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else ''))
    cliente_citacion = _normalizar_match_texto(obtener_cliente_planificacion_citacion(citacion)['nombre'])

    bl_camion = str(getattr(camion, 'CPA_CBL', '') or '').strip()
    bl_citacion = str(getattr(detalle, 'CDO_CBL', '') or '').strip() if detalle else ''
    bl_camion_normalizado = _normalizar_bl_match(bl_camion)
    bl_citacion_normalizado = _normalizar_bl_match(bl_citacion)
    bl_estado = ''
    comparar_bl = _es_camion_recepcion_sbh_patio(camion) and es_citacion_recepcion_sbh(citacion)
    if comparar_bl and bl_camion_normalizado and bl_citacion_normalizado:
        if bl_camion_normalizado == bl_citacion_normalizado:
            score += 40
            razones.append('BL coincide')
            bl_estado = 'coincide'
        elif (
            min(len(bl_camion_normalizado), len(bl_citacion_normalizado)) >= 6
            and _distancia_edicion_bl(bl_camion_normalizado, bl_citacion_normalizado) == 1
        ):
            score += 15
            razones.append('BL similar \u2014 revisar dato')
            bl_estado = 'similar'
        else:
            bl_estado = 'distinto'

    if tipo == CIT_DESPACHO and patente_coincide:
        score += 100
        razones.append('Patente coincide')
    if producto_camion and producto_citacion and (producto_camion in producto_citacion or producto_citacion in producto_camion):
        score += 45
        razones.append('Producto coincide')
    if proveedor_camion and proveedor_citacion and (proveedor_camion in proveedor_citacion or proveedor_citacion in proveedor_camion):
        score += 30
        razones.append('Proveedor coincide')
    if cliente_camion and cliente_citacion and (cliente_camion in cliente_citacion or cliente_citacion in cliente_camion):
        score += 15
        razones.append('Cliente coincide')
    if citacion.PL_NID and citacion.PL_NID.PL_FFECHAINICIO:
        llegada = timezone.localtime(camion.CPA_FFECHALLEGADA)
        plan = timezone.localtime(citacion.PL_NID.PL_FFECHAINICIO)
        horas = abs((llegada - plan).total_seconds()) / 3600
        if horas <= 24:
            score += 10
            razones.append('Horario cercano')
        elif horas <= 72:
            score += 4
            razones.append('Horario relacionado')
    diferencia_horas = _diferencia_horaria_patio(camion, citacion)
    return score, list(dict.fromkeys(razones)), {
        'patente': patente if tipo == CIT_DESPACHO else '',
        'patente_normalizada': patente_normalizada if tipo == CIT_DESPACHO else '',
        'patente_coincide': patente_coincide if tipo == CIT_DESPACHO else False,
        'patente_estado': patente_estado if tipo == CIT_DESPACHO else '',
        'bl': bl_citacion if comparar_bl else '',
        'bl_normalizado': bl_citacion_normalizado if comparar_bl else '',
        'bl_estado': bl_estado if comparar_bl else '',
        'desglose': [],
        'diferencia_horas': diferencia_horas,
    }

def _fecha_planificacion_sugerida_patio(citacion):
    if not citacion.PL_NID or not citacion.PL_NID.PL_FFECHAINICIO:
        return ''
    formato = '%d/%m/%Y' if es_citacion_recepcion_sbh(citacion) else '%d/%m/%Y %H:%M'
    return timezone.localtime(citacion.PL_NID.PL_FFECHAINICIO).strftime(formato)


def _serializar_citacion_patio(camion, citacion, citacion_aprobada_id=None):
    detalle = _detalle_operacional_citacion(citacion)
    score, razones, patente_info = _score_citacion_camion_patio(camion, citacion)
    tipo = _tipo_citacion_patio(citacion)
    abrir_url = ''
    if citacion.PL_NID_id:
        abrir_url = (
            f'{reverse("pla_listone", args=[citacion.PL_NID_id])}'
            f'?_empresa_id={camion.EP_NID_id}'
            f'&camion_patio_id={camion.id}'
            f'&camion_patio={camion.id}'
            f'&citacion={citacion.id}'
            f'&tipo={tipo}'
        )
    secuencia = citacion.SC_NID
    cliente_planificacion = obtener_cliente_planificacion_citacion(citacion)
    es_despacho_sbh = tipo == CIT_DESPACHO and getattr(citacion, 'EP_NID_id', None) == 2
    detalle_despacho = sap_despacho_detalle_resumen_dict(citacion) if es_despacho_sbh else {}
    salida_documento = detalle_despacho.get('salida_documento') or ''
    fecha_planificacion_orden = (
        getattr(getattr(citacion, 'PL_NID', None), 'PL_FFECHAINICIO', None)
        or getattr(citacion, 'CI_FFECHACITACION', None)
    )
    return {
        'id': citacion.id,
        'es_citacion_aprobada': citacion.id == citacion_aprobada_id,
        'score': score,
        'razones': razones,
        'desglose': patente_info.get('desglose', []),
        'diferencia_horas': patente_info.get('diferencia_horas'),
        'tipo': tipo,
        'tipo_label': 'DESPACHO' if tipo == CIT_DESPACHO else 'RECEPCION',
        'abrir_url': abrir_url,
        'planificacion': citacion.PL_NID_id,
        'secuencia_operacional': {
            'id': secuencia.id,
            'codigo': secuencia.SE_CCODIGO or '',
            'nombre': secuencia.SE_CNOMBRE or '',
        } if secuencia else None,
        'fecha_planificacion': _fecha_planificacion_sugerida_patio(citacion),
        'fecha_planificacion_orden': fecha_planificacion_orden.isoformat() if fecha_planificacion_orden else '',
        'cliente': cliente_planificacion['nombre'],
        'cliente_nombre': cliente_planificacion['nombre'],
        'cliente_codigo': cliente_planificacion['codigo'],
        'proveedor': patente_info.get('proveedor') or (detalle.CDO_CPRODUCTOR if detalle else '') or (citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else ''),
        'producto': patente_info.get('producto') or (detalle.CDO_CINSUMO if detalle else ''),
        'transportista': patente_info.get('transportista', ''),
        'conductor': patente_info.get('conductor', ''),
        'rut_conductor': patente_info.get('rut_conductor', ''),
        'guia': patente_info.get('guia', ''),
        'contenedor': patente_info.get('contenedor', ''),
        'pedido_sap': detalle.CDO_CPEDIDO_SAP if detalle else '',
        'contrato_sap': (obtener_contrato_planificacion_citacion(citacion) if tipo == CIT_DESPACHO else (detalle.CDO_CCONTRATO_SAP if detalle and hasattr(detalle, 'CDO_CCONTRATO_SAP') else '')),
        'docentry': detalle.CDO_CDOCENTRY if detalle else '',
        'estado': citacion.CI_CESTADO,
        'patente': patente_info.get('patente', ''),
        'patente_normalizada': patente_info.get('patente_normalizada', ''),
        'patente_coincide': patente_info.get('patente_coincide', False),
        'patente_estado': patente_info.get('patente_estado', ''),
        'bl': patente_info.get('bl', ''),
        'bl_normalizado': patente_info.get('bl_normalizado', ''),
        'bl_estado': patente_info.get('bl_estado', ''),
        **({
            'almacen_destino': str(getattr(detalle, 'CDO_CALMACEN_DESTINO', '') or '').strip(),
            'estanque_destino': str(getattr(detalle, 'CDO_CESTANQUE_DESTINO', '') or '').strip(),
        } if tipo == CIT_RECEPCION else {}),
        **({
            'es_despacho_sbh': True,
            'salida_documento': salida_documento,
            'salida_documento_label': _etiqueta_salida_documento_despacho(salida_documento),
            'destino': detalle_despacho.get('destino') or '',
            'ventana_horaria': detalle_despacho.get('ventana_horaria_despacho') or '',
        } if es_despacho_sbh else {}),
    }


def _estado_visible_camion_patio(camion):
    if camion.CPA_CESTADO == CAMION_PATIO.ESTADO_PENDIENTE_ASOCIACION:
        return 'Sin asignar'
    return camion.get_CPA_CESTADO_display()


def citacion_disponible_para_asociar_camion_patio(citacion):
    if citacion and es_recepcion_new_jersey_p2(citacion):
        return False
    if not citacion or not citacion.CI_BHABILITADO or citacion.CI_BARCHIVADO:
        return False
    estado_citacion = normalizar_nombre_perfil(citacion.CI_CESTADO)
    if estado_citacion in {
        normalizar_nombre_perfil(CIT_TERMINADO),
        normalizar_nombre_perfil(CIT_RECHAZADO),
        'SALIDA CONFIRMADA',
        'ANULADO',
        'ANULADA',
        'CANCELADO',
        'CANCELADA',
        'COMPLETADO',
        'COMPLETADA',
    } or citacion.CI_FFECHATERMINO:
        return False
    if not citacion.PL_NID_id or citacion.PL_NID.PL_BARCHIVADO:
        return False
    if CAMION_PATIO.objects.filter(
        CI_NID=citacion,
        CPA_CESTADO=CAMION_PATIO.ESTADO_ASOCIADO_CITACION
    ).exists():
        return False
    if SYSLOGGER.objects.filter(
        LOG_CADD1=str(citacion.id),
        LOG_COPERACION__in=[
            'ING_CAMION',
            'GUARDIA_INGRESO',
            'AVANZA_AR',
            'APRUEBA_AR',
            'ENVIA_CD_NEXT',
            'ENVIA_GUARDIA_PORTERIA',
            'AUTORIZA_INGRESO_PLANTA',
        ]
    ).exists():
        return False
    try:
        detalle_actual = DETALLE_SECUENCIA.objects.filter(
            SC_NID=citacion.SC_NID,
            ET_NID=citacion.ETAPA_ACTUAL,
            SE_BHABILITADO=True
        ).first()
    except Exception:
        detalle_actual = None
    if detalle_actual and detalle_actual.SE_NPASO > 1:
        return False
    valores_ingreso = obtener_valores_ingreso_camion(citacion)
    solicitud_patio_vinculada = CAMION_PATIO_NO_PLANIFICADO.objects.filter(
        CI_NID=citacion,
        CPNP_CESTADO=CAMION_PATIO_NO_PLANIFICADO.ESTADO_APROBADO,
    ).exists()
    if (
        not es_citacion_despacho_sbh(citacion)
        and
        any(valores_ingreso.get(campo) for campo in ['patente', 'conductor', 'transportista'])
        and not solicitud_patio_vinculada
    ):
        return False
    estado = normalizar_nombre_perfil(citacion.CI_CESTADO)
    estados_disponibles = {
        'INSUMO PROGRAMADO',
        'DESPACHO PROGRAMADO',
        'PROGRAMADO',
        'PENDIENTE',
        'PLANIFICADO',
        'EN PROCESO',
    }
    etapa_actual = normalizar_nombre_perfil(obtener_etapa_actual_operacional_citacion(citacion))
    etapas_iniciales = {
        normalizar_nombre_perfil(NOMBRE_ETAPA_INSUMO_PROGRAMADO),
        'DESPACHO PROGRAMADO',
    }
    return not estado or estado in estados_disponibles or etapa_actual in etapas_iniciales


def _clave_orden_sugerencia_patio(item):
    return (
        0 if item['es_citacion_aprobada'] else 1,
        -item['score'],
        item['diferencia_horas'] if item['diferencia_horas'] is not None else float('inf'),
        item['fecha_planificacion_orden'],
        item['id'],
    )

def _citaciones_disponibles_para_patio(camion):
    solicitud = _solicitud_no_planificado_visible(camion)
    citacion_aprobada_id = (
        solicitud.CI_NID_id
        if solicitud and solicitud.CPNP_CESTADO == CAMION_PATIO_NO_PLANIFICADO.ESTADO_APROBADO
        else None
    )
    asociados = CAMION_PATIO.objects.filter(
        EP_NID=camion.EP_NID,
        CI_NID__isnull=False,
        CPA_CESTADO=CAMION_PATIO.ESTADO_ASOCIADO_CITACION
    ).values_list('CI_NID_id', flat=True)
    citaciones = CITACION.objects.select_related(
        'PL_NID', 'SN_NID', 'PRO_NID', 'SC_NID', 'CON_NID', 'detalle_despacho', 'detalle_operacional',
        'detalle_recepcion_terramar__SN_NID_TRANSPORTISTA', 'detalle_recepcion_terramar__CON_NID'
    ).prefetch_related(
        Prefetch(
            'dato_operacion_set',
            queryset=DATO_OPERACION.objects.filter(
                CAMP_NID__CA_CCODIGO__in=[PLAN_CODIGO_CLIENTE_SAP, PLAN_CLIENTE_SAP, 'PLAN_CONTRATO_SAP'],
            ).select_related('CAMP_NID').order_by('-id'),
            to_attr='_datos_cliente_planificacion',
        )
    ).filter(
        EP_NID=camion.EP_NID,
        CI_BHABILITADO=True,
        CI_BARCHIVADO=False,
        PL_NID__PL_BARCHIVADO=False,
    ).exclude(
        CI_CESTADO=CIT_TERMINADO
    ).exclude(
        id__in=asociados
    ).order_by('-CI_FFECHACITACION')
    if _es_camion_despacho_sbh_patio(camion):
        citaciones = citaciones.filter(CI_CTIPO=CIT_DESPACHO, EP_NID_id=ID_ACEITES_SBH)
    elif (
        getattr(camion, 'EP_NID_id', None) == ID_TERRAMAR
        and _es_camion_despacho_terramar_principal(camion)
    ):
        citaciones = citaciones.filter(
            CI_CTIPO=CIT_DESPACHO,
            SC_NID__SE_CCODIGO='DESPACHO_TERRAMAR',
        )
    citaciones = citaciones[:80]
    citaciones = [
        citacion for citacion in citaciones
        if citacion_disponible_para_asociar_camion_patio(citacion)
    ]

    if citacion_aprobada_id and not any(citacion.id == citacion_aprobada_id for citacion in citaciones):
        citacion_aprobada = CITACION.objects.select_related(
            'PL_NID', 'SN_NID', 'PRO_NID', 'SC_NID', 'CON_NID', 'detalle_despacho', 'detalle_operacional',
            'detalle_recepcion_terramar__SN_NID_TRANSPORTISTA', 'detalle_recepcion_terramar__CON_NID',
        ).prefetch_related(
            Prefetch(
                'dato_operacion_set',
                queryset=DATO_OPERACION.objects.filter(
                    CAMP_NID__CA_CCODIGO__in=[PLAN_CODIGO_CLIENTE_SAP, PLAN_CLIENTE_SAP, 'PLAN_CONTRATO_SAP'],
                ).select_related('CAMP_NID').order_by('-id'),
                to_attr='_datos_cliente_planificacion',
            )
        ).filter(
            pk=citacion_aprobada_id,
            EP_NID=camion.EP_NID,
            CI_BHABILITADO=True,
            CI_BARCHIVADO=False,
            PL_NID__PL_BARCHIVADO=False,
        ).first()
        if citacion_aprobada and citacion_disponible_para_asociar_camion_patio(citacion_aprobada):
            citaciones.insert(0, citacion_aprobada)

    data = [
        _serializar_citacion_patio(camion, citacion, citacion_aprobada_id=citacion_aprobada_id)
        for citacion in citaciones
    ]
    data.sort(key=_clave_orden_sugerencia_patio)
    return data


def _formatear_fecha_documental_camion_patio(valor):
    texto = str(valor or '').strip()
    if len(texto) == 8 and texto.isdigit():
        try:
            return datetime.strptime(texto, '%d%m%Y').strftime('%d/%m/%Y')
        except ValueError:
            pass
    return texto

def _serializar_camion_patio(camion):
    solicitud = _solicitud_no_planificado_visible(camion)
    try:
        traza = camion.trazabilidad_planificacion
    except (CAMION_PATIO_TRAZABILIDAD_PLANIFICACION.DoesNotExist, AttributeError):
        traza = None
    candidata = traza.CI_NID if traza and traza.CI_NID_id else None
    detalle_candidata = _detalle_despacho_citacion_patio(candidata) if candidata else None
    resultado_origen = traza.CPTR_CRESULTADO_BUSQUEDA if traza else ''
    origen_ingreso = (
        'Estado del camion / Guardia' if resultado_origen.startswith('GUARDIA_')
        else ('Registro manual / Asistente Recepcion' if resultado_origen.startswith('RECEPCION_') else 'Registro patio existente')
    )


    datos_precarga = _datos_precarga_camion_patio(camion)
    conductor_precarga = None
    if not getattr(camion, 'CON_NID_id', None):
        try:
            traza_precarga = camion.trazabilidad_planificacion
        except (CAMION_PATIO_TRAZABILIDAD_PLANIFICACION.DoesNotExist, AttributeError):
            traza_precarga = None
        if traza_precarga and traza_precarga.CI_NID_id:
            conductor_precarga = _resolver_conductor_snapshot_camion_patio(camion)
    telefono_precarga = split_legacy_phone(
        datos_precarga['telefono_codigo_pais'],
        datos_precarga['telefono_conductor'],
    )
    data = {
        'id': camion.id,
        'estado': camion.CPA_CESTADO,
        'estado_visible': _estado_visible_camion_patio(camion),
        'patente': camion.CPA_CPATENTE,
        'transporte_a_cargo': camion.transporte_a_cargo,
        'transporte_a_cargo_label': camion.get_transporte_a_cargo_display(),
        'conductor': datos_precarga['conductor'],
        'conductor_id': (
            getattr(camion, 'CON_NID_id', None)
            or getattr(conductor_precarga, 'id', None)
            or ''
        ),
        'rut_conductor': datos_precarga['rut_conductor'],
        'telefono': telefono_precarga['local_number'],
        'telefono_codigo_pais': telefono_precarga['country_code'],
        'telefono_completo': telefono_precarga['full_number'],
        'transportista': datos_precarga['transportista'],
        'proveedor': camion.CPA_CPROVEEDOR_DECLARADO or '',
        'insumo_declarado_guia': camion.CPA_CINSUMO_DECLARADO_GUIA or '',
        'tipo_recepcion': camion.CPA_CTIPO_RECEPCION or '',
        'tipo_recepcion_label': etiqueta_tipo_recepcion_sbh(camion.CPA_CTIPO_RECEPCION),
        'es_recepcion_sbh': _es_camion_recepcion_sbh_patio(camion),
        'cda': camion.CPA_CCDA or '',
        'di': camion.CPA_CDI or '',
        'nave_naviera': camion.CPA_CNAVE_NAVIERA or '',
        'fecha_produccion': camion.CPA_CFECHAPRODUCCION or '',
        'fecha_produccion_display': _formatear_fecha_documental_camion_patio(camion.CPA_CFECHAPRODUCCION),
        'fecha_vencimiento': camion.CPA_CFECHAVENCIMIENTOPRODUCTO or '',
        'fecha_vencimiento_display': _formatear_fecha_documental_camion_patio(camion.CPA_CFECHAVENCIMIENTOPRODUCTO),
        'sui': camion.CPA_CSUI or '',
        'cliente': camion.CPA_CCLIENTE_DECLARADO or '',
        'guia': camion.CPA_CNUMERO_GUIA or '',
        'bl': camion.CPA_CBL or '',
        'lote_contenedor': camion.CPA_CLOTE_CONTENEDOR or '',
        'observacion': camion.CPA_COBSERVACION or '',
        'guardia': camion.US_GUARDIA_ID.username if camion.US_GUARDIA_ID else '',
        'llegada': timezone.localtime(camion.CPA_FFECHALLEGADA).strftime('%d/%m/%Y %H:%M'),
        'citacion_id': camion.CI_NID_id or '',
        'numero_citacion': camion.CI_NID_id or '',
        'bloqueado_edicion': _camion_patio_bloqueado_para_edicion(camion),
        'es_despacho_sbh': _es_camion_despacho_sbh_patio(camion),
        'origen_ingreso': origen_ingreso,
        'planificacion_encontrada': bool(candidata),
        'citacion_candidata_id': candidata.id if candidata else None,
        'planificacion_candidata_id': candidata.PL_NID_id if candidata else None,
        'fecha_citacion_candidata': timezone.localtime(candidata.CI_FFECHACITACION).strftime('%d/%m/%Y %H:%M') if candidata and candidata.CI_FFECHACITACION else '',
        'fecha_despacho_candidata': detalle_candidata.CDD_FFECHA_DESPACHO.strftime('%d/%m/%Y') if detalle_candidata and detalle_candidata.CDD_FFECHA_DESPACHO else '',
        'fecha_llegada_destino_candidata': detalle_candidata.CDD_FFECHA_LLEGADA_DESTINO.strftime('%d/%m/%Y') if detalle_candidata and detalle_candidata.CDD_FFECHA_LLEGADA_DESTINO else '',
        'hora_llegada_destino_candidata': detalle_candidata.CDD_FHORA_LLEGADA_DESTINO.strftime('%H:%M') if detalle_candidata and detalle_candidata.CDD_FHORA_LLEGADA_DESTINO else '',
        'estado_citacion_candidata': candidata.CI_CESTADO if candidata else '',
        'tipo_citacion_candidata': _tipo_citacion_patio(candidata) if candidata else '',
        'tipo_operacion_sugerida': (
            _tipo_citacion_patio(candidata)
            if candidata else (CIT_DESPACHO if _es_camion_despacho_patio(camion) else CIT_RECEPCION)
        ),
        'resultado_busqueda_planificacion': resultado_origen,
        'responsable_pendiente': 'Asistente Despacho' if _es_camion_despacho_sbh_patio(camion) and not camion.CI_NID_id else '',
    }
    data.update({
        'existe_solicitud_no_planificado': bool(solicitud),
        'solicitud_id': solicitud.id if solicitud else None,
        'solicitud_estado': solicitud.CPNP_CESTADO if solicitud else '',
        'solicitud_estado_label': solicitud.get_CPNP_CESTADO_display() if solicitud else '',
        'solicitud_citacion_id': solicitud.CI_NID_id if solicitud else None,
        'solicitud_planificacion_id': solicitud.PL_NID_id if solicitud else None,
        'solicitud_citacion_url': (
            _serializar_citacion_patio(camion, solicitud.CI_NID, solicitud.CI_NID_id)['abrir_url']
            if solicitud and solicitud.CI_NID_id else ''
        ),
        'solicitado_en': timezone.localtime(solicitud.CPNP_FFECHASOLICITUD).strftime('%d/%m/%Y %H:%M') if solicitud else '',
        'motivo_rechazo': solicitud.CPNP_CMOTIVO_RECHAZO if solicitud else '',
        'teams_enviado': solicitud.CPNP_BTEAMS_ENVIADO if solicitud else False,
        'teams_estado': solicitud.CPNP_CTEAMS_ESTADO if solicitud else '',
    })
    return data


def _es_camion_despacho_patio(camion):
    if _es_camion_recepcion_sbh_patio(camion):
        return False
    if getattr(camion, 'CI_NID_id', None):
        return _tipo_citacion_patio(camion.CI_NID) == CIT_DESPACHO
    try:
        traza = camion.trazabilidad_planificacion
    except (CAMION_PATIO_TRAZABILIDAD_PLANIFICACION.DoesNotExist, AttributeError):
        return False
    if traza.CI_NID_id:
        return _tipo_citacion_patio(traza.CI_NID) == CIT_DESPACHO
    if getattr(traza, 'PL_NID_id', None):
        return str(getattr(traza.PL_NID, 'PL_CTIPOCUPO', '') or '').upper() == CIT_DESPACHO
    return bool(
        getattr(camion, 'EP_NID_id', None) == ID_ACEITES_SBH
        and str(traza.CPTR_CRESULTADO_BUSQUEDA or '').startswith('GUARDIA_')
    )


def _es_camion_despacho_terramar_principal(camion):
    citacion = getattr(camion, 'CI_NID', None)
    if citacion is None:
        try:
            traza = camion.trazabilidad_planificacion
        except (CAMION_PATIO_TRAZABILIDAD_PLANIFICACION.DoesNotExist, AttributeError):
            traza = None
        citacion = getattr(traza, 'CI_NID', None) if traza else None
    return es_citacion_despacho_terramar_principal(citacion)


def _es_camion_despacho_sbh_patio(camion):
    return bool(
        getattr(camion, 'EP_NID_id', None) == ID_ACEITES_SBH
        and _es_camion_despacho_patio(camion)
    )


def usuario_puede_asociar_camion_patio(user, camion):
    if getattr(user, 'is_superuser', False):
        return True
    return bool(
        usuario_puede_revisar_camion_patio(user)
        or usuario_es_asistente_despacho_empresa(user, camion.EP_NID_id)
    )


def usuario_puede_modificar_camion_patio_objeto(user, camion):
    if getattr(user, 'is_superuser', False) or usuario_puede_revisar_camion_patio(user):
        return True
    return usuario_es_asistente_despacho_empresa(user, camion.EP_NID_id)


def _formatear_tiempo_patio(segundos):
    segundos = max(0, int(segundos or 0))
    horas = segundos // 3600
    minutos = (segundos % 3600) // 60
    return f'{horas:02d}h {minutos:02d}m' if horas < 100 else f'{horas}h {minutos:02d}m'


PATIO_CONTROL_ZONA_ESPERA = 'espera_asignacion'
PATIO_CONTROL_ZONA_ACEITE = 'aceite'
PATIO_CONTROL_ZONA_HARINA = 'harina'
PATIO_CONTROL_ZONA_TERRESTRES = 'terrestres'
PATIO_CONTROL_ZONA_NO_PLANIFICADOS = 'no_planificados'

PATIO_CONTROL_ZONAS = [
    PATIO_CONTROL_ZONA_ESPERA,
    PATIO_CONTROL_ZONA_HARINA,
    PATIO_CONTROL_ZONA_ACEITE,
    PATIO_CONTROL_ZONA_TERRESTRES,
    PATIO_CONTROL_ZONA_NO_PLANIFICADOS,
]

PATIO_CONTROL_CAPACIDADES = {
    PATIO_CONTROL_ZONA_ESPERA: 0,
    PATIO_CONTROL_ZONA_ACEITE: 20,
    PATIO_CONTROL_ZONA_HARINA: 20,
    PATIO_CONTROL_ZONA_TERRESTRES: 4,
    PATIO_CONTROL_ZONA_NO_PLANIFICADOS: 8,
}


def _slots_patio_control(zona):
    if zona == PATIO_CONTROL_ZONA_ESPERA:
        slots = []
        for fila, y in enumerate([23, 29]):
            for columna in range(4):
                slots.append({'x': 19 + (columna * 8.0), 'y': y, 'rotacion': 0})
        return slots
    if zona == PATIO_CONTROL_ZONA_HARINA:
        slots = []
        for fila, y in enumerate([38, 50]):
            for columna in range(10):
                slots.append({'x': 41 + (columna * 4.3), 'y': y, 'rotacion': 90})
        return slots
    if zona == PATIO_CONTROL_ZONA_ACEITE:
        slots = []
        for fila, y in enumerate([68, 80]):
            for columna in range(10):
                slots.append({'x': 48 + (columna * 4.1), 'y': y, 'rotacion': 90})
        return slots
    if zona == PATIO_CONTROL_ZONA_TERRESTRES:
        return [
            {'x': 90, 'y': 47 + (indice * 8.6), 'rotacion': 90}
            for indice in range(4)
        ]
    slots = []
    for fila, y in enumerate([68, 80]):
        for columna in range(4):
            slots.append({'x': 31 + (columna * 4.2), 'y': y, 'rotacion': 90})
    return slots


def _slot_patio_control(zona, indice):
    slots = _slots_patio_control(zona)
    if indice < len(slots):
        return slots[indice]
    base = slots[indice % len(slots)]
    vuelta = indice // len(slots)
    return {
        'x': min(92, base['x'] + (vuelta * 1.8)),
        'y': min(92, base['y'] + (vuelta * 3.2)),
        'rotacion': base['rotacion'],
    }


def _texto_zona_patio_control(zona):
    return {
        PATIO_CONTROL_ZONA_ESPERA: 'Camion en espera de asignacion',
        PATIO_CONTROL_ZONA_ACEITE: 'Zona Camiones Aceite',
        PATIO_CONTROL_ZONA_HARINA: 'Zona Camiones Harina',
        PATIO_CONTROL_ZONA_TERRESTRES: 'Zona Camiones Terrestres',
        PATIO_CONTROL_ZONA_NO_PLANIFICADOS: 'Zona Camiones No Planificados',
    }.get(zona, 'Zona Camiones No Planificados')


def _estadisticas_zonas_control(camiones_data):
    stats = []
    for zona in PATIO_CONTROL_ZONAS:
        capacidad = PATIO_CONTROL_CAPACIDADES.get(zona, 0)
        ocupados = sum(1 for camion in camiones_data if camion.get('zona') == zona)
        disponibles = max(capacidad - ocupados, 0) if capacidad else 0
        stats.append({
            'zona': zona,
            'nombre': _texto_zona_patio_control(zona),
            'capacidad': capacidad,
            'ocupados': ocupados,
            'disponibles': disponibles,
            'texto': (
                f'En espera: {ocupados} camiones'
                if zona == PATIO_CONTROL_ZONA_ESPERA
                else
                f'Capacidad: {capacidad} | Ocupados: {ocupados} | Disponibles: {disponibles}'
                if capacidad
                else f'Ocupados: {ocupados}'
            ),
        })
    return stats


def _texto_planificacion_camion_patio(camion):
    citacion = camion.CI_NID
    if not citacion:
        return ''
    detalle = _detalle_operacional_citacion(citacion)
    partes = []
    if detalle:
        partes.extend([
            detalle.CDO_CINSUMO,
            detalle.CDO_CCODIGO_SAP,
            detalle.CDO_CALMACEN_DESTINO,
            detalle.CDO_CESTANQUE_DESTINO,
            detalle.CDO_CPRODUCTOR,
        ])
    partes.extend([
        citacion.CI_CTIPO_FLETE,
        citacion.CI_CTIPO,
        citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '',
        citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else '',
        citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else '',
    ])
    return ' '.join(str(parte or '') for parte in partes)


def _insumo_sap_planificado_camion_patio(camion):
    if not camion.CI_NID:
        return ''
    detalle = _detalle_operacional_citacion(camion.CI_NID)
    if detalle and detalle.CDO_CINSUMO:
        return detalle.CDO_CINSUMO
    return ''


def _zona_patio_control_camion(camion):
    if camion.CPA_CESTADO == CAMION_PATIO.ESTADO_PENDIENTE_ASOCIACION:
        return PATIO_CONTROL_ZONA_ESPERA
    if camion.CPA_CESTADO != CAMION_PATIO.ESTADO_ASOCIADO_CITACION:
        return PATIO_CONTROL_ZONA_NO_PLANIFICADOS

    texto = _normalizar_match_texto(_texto_planificacion_camion_patio(camion))
    if 'HARINA' in texto:
        return PATIO_CONTROL_ZONA_HARINA
    if 'ACEITE' in texto:
        return PATIO_CONTROL_ZONA_ACEITE
    if any(palabra in texto for palabra in ['TERRESTRE', 'TRASVASIJE', 'CONTENEDOR', 'CAMION']):
        return PATIO_CONTROL_ZONA_TERRESTRES
    return PATIO_CONTROL_ZONA_NO_PLANIFICADOS


def excluir_camiones_patio_ingresados_planta(queryset, empresa_id):
    autorizacion_ingreso = SYSLOGGER.objects.filter(
        EP_NID_id=empresa_id,
        LOG_COPERACION='AUTORIZA_INGRESO_PLANTA',
        LOG_CADD1=Cast(OuterRef('CI_NID_id'), output_field=CharField()),
    )
    habilitacion_planta = OPERACION_PLANTA_LOG.objects.filter(
        EP_NID_id=empresa_id,
        CI_NID_id=OuterRef('CI_NID_id'),
        OPL_CPASO='Habilitar Operacion Planta',
    )
    return queryset.annotate(
        _patio_ingreso_autorizado=Exists(autorizacion_ingreso),
        _patio_operacion_habilitada=Exists(habilitacion_planta),
    ).filter(
        _patio_ingreso_autorizado=False,
        _patio_operacion_habilitada=False,
    )


def _camiones_patio_en_control_queryset(empresa_id):
    queryset = CAMION_PATIO.objects.select_related(
        'CI_NID',
        'CI_NID__PL_NID',
        'CI_NID__SN_NID',
        'CI_NID__PRO_NID',
        'CI_NID__detalle_operacional',
        'US_GUARDIA_ID',
        'US_ASOCIA_ID',
    ).filter(
        EP_NID_id=empresa_id,
    ).exclude(
        CPA_CESTADO__in=[
            CAMION_PATIO.ESTADO_RECHAZADO,
            CAMION_PATIO.ESTADO_CANCELADO,
        ]
    ).exclude(CI_NID__CI_BARCHIVADO=True)

    queryset = excluir_camiones_patio_ingresados_planta(queryset, empresa_id)

    return queryset.order_by('CPA_FFECHALLEGADA', 'id')


def _serializar_camion_control_patio(camion, indice_zona, zona, ahora=None):
    ahora = ahora or timezone.now()
    llegada = camion.CPA_FFECHALLEGADA or camion.CPA_FFECHACREACION or ahora
    if timezone.is_naive(llegada):
        llegada = timezone.make_aware(llegada, timezone.get_current_timezone())
    llegada_local = timezone.localtime(llegada)
    segundos = max(0, int((ahora - llegada).total_seconds()))

    slot = _slot_patio_control(zona, indice_zona)

    estado_visual = 'pendiente'
    if camion.CPA_CESTADO == CAMION_PATIO.ESTADO_ASOCIADO_CITACION:
        estado_visual = 'asociado'
    elif camion.CPA_CESTADO == CAMION_PATIO.ESTADO_EN_REVISION_RECEPCION:
        estado_visual = 'revision'
    if segundos >= 6 * 3600:
        estado_visual = 'alerta'

    return {
        'id': camion.id,
        'patente': camion.CPA_CPATENTE or '',
        'insumo_declarado_guia': camion.CPA_CINSUMO_DECLARADO_GUIA or 'Sin informacion',
        'hora_llegada': llegada_local.strftime('%d/%m/%Y %H:%M'),
        'hora_llegada_iso': llegada_local.isoformat(),
        'tiempo_segundos': segundos,
        'tiempo_patio': _formatear_tiempo_patio(segundos),
        'transportista': camion.CPA_CTRANSPORTISTA_DECLARADO or 'Sin informacion',
        'conductor': camion.CPA_CNOMBRE_CONDUCTOR or 'Sin informacion',
        'telefono': split_legacy_phone(camion.CPA_CCODIGO_PAIS_TELEFONO, camion.CPA_CTELEFONO_CONDUCTOR)['local_number'],
        'telefono_codigo_pais': split_legacy_phone(camion.CPA_CCODIGO_PAIS_TELEFONO, camion.CPA_CTELEFONO_CONDUCTOR)['country_code'],
        'telefono_completo': split_legacy_phone(camion.CPA_CCODIGO_PAIS_TELEFONO, camion.CPA_CTELEFONO_CONDUCTOR)['full_number'],
        'estado': camion.CPA_CESTADO,
        'estado_visible': _estado_visible_camion_patio(camion),
        'estado_visual': estado_visual,
        'guia': camion.CPA_CNUMERO_GUIA or '',
        'bl': camion.CPA_CBL or '',
        'lote_contenedor': camion.CPA_CLOTE_CONTENEDOR or '',
        'citacion_id': camion.CI_NID_id or '',
        'numero_citacion': camion.CI_NID_id or '',
        'insumo_sap_planificado': _insumo_sap_planificado_camion_patio(camion) or 'Sin informacion',
        'zona': zona,
        'zona_visible': _texto_zona_patio_control(zona),
        'x': round(slot['x'], 2),
        'y': round(slot['y'], 2),
        'rotacion': slot['rotacion'],
    }


def _serializar_camiones_control_patio(empresa_id):
    camiones = list(_camiones_patio_en_control_queryset(empresa_id))
    ahora = timezone.now()
    indices_por_zona = {}
    data = []
    for camion in camiones:
        zona = _zona_patio_control_camion(camion)
        indice_zona = indices_por_zona.get(zona, 0)
        indices_por_zona[zona] = indice_zona + 1
        data.append(_serializar_camion_control_patio(camion, indice_zona, zona, ahora))
    return data


def _generar_base_control_patio():
    cache_key = 'camiones_patio_control_base_svg_v7'
    try:
        cached = cache.get(cache_key)
    except Exception:
        cached = None
    if cached:
        return cached
    try:
        import matplotlib
        matplotlib.use('Agg')
        import matplotlib.pyplot as plt
        from matplotlib.patches import FancyArrowPatch, Rectangle
    except Exception as exc:
        logger.warning('Matplotlib no disponible para base de control patio: %s', exc)
        return ''

    fig, ax = plt.subplots(figsize=(15, 9), dpi=120)
    ax.set_xlim(0, 100)
    ax.set_ylim(100, 0)
    ax.axis('off')
    ax.add_patch(Rectangle((0, 0), 100, 100, facecolor='#0b1220', edgecolor='none'))
    ax.add_patch(Rectangle((3.5, 4.5), 93, 91, facecolor='#111827', edgecolor='#94a3b8', linewidth=1.8))
    ax.add_patch(Rectangle((7.5, 11), 85, 80, facecolor='#172033', edgecolor='#64748b', linewidth=1.2))

    ax.text(82, 7.8, 'N', color='#e2e8f0', ha='center', va='center', fontsize=12, weight='bold',
            bbox={'boxstyle': 'square,pad=0.18', 'facecolor': '#1f2937', 'edgecolor': '#94a3b8'})
    ax.add_patch(FancyArrowPatch((85, 7.8), (94, 7.8), arrowstyle='-|>', mutation_scale=18, color='#94a3b8', linewidth=1.6))

    ax.plot([8, 92], [34, 34], color='#94a3b8', linewidth=1, linestyle=':', alpha=.75)

    ax.add_patch(Rectangle((7, 40), 7, 20, facecolor='#111827', edgecolor='#94a3b8', linewidth=1.1))
    ax.add_patch(FancyArrowPatch((6.4, 47), (12.4, 47), arrowstyle='-|>', mutation_scale=18, color='#e2e8f0', linewidth=1.5))
    ax.add_patch(FancyArrowPatch((12.4, 54), (6.4, 54), arrowstyle='-|>', mutation_scale=18, color='#e2e8f0', linewidth=1.5))
    ax.text(13.4, 50.5, 'ENTRADA / SALIDA', color='#cbd5e1', ha='left', va='center', fontsize=7, rotation=90, weight='bold')

    ax.add_patch(Rectangle((27, 43), 9, 13, facecolor='#263340', edgecolor='#cbd5e1', linewidth=1.2))
    ax.text(31.5, 49.5, 'Garita\nPorteria', color='#e5e7eb', ha='center', va='center', fontsize=8, weight='bold')
    ax.add_patch(Rectangle((31, 52), 1.4, 1.4, facecolor='#e5e7eb', edgecolor='#111827', linewidth=.5))

    def draw_slots(slots, color):
        for slot in slots:
            ancho, alto = (8.5, 2.5)
            if slot['rotacion'] == 90:
                ancho, alto = (2.5, 8.5)
            ax.add_patch(Rectangle(
                (slot['x'] - ancho / 2, slot['y'] - alto / 2),
                ancho,
                alto,
                facecolor='none',
                edgecolor=color,
                linewidth=.9,
                alpha=.82,
            ))

    draw_slots(_slots_patio_control(PATIO_CONTROL_ZONA_HARINA), '#60a5fa')
    draw_slots(_slots_patio_control(PATIO_CONTROL_ZONA_ACEITE), '#22c55e')
    draw_slots(_slots_patio_control(PATIO_CONTROL_ZONA_TERRESTRES), '#38bdf8')
    draw_slots(_slots_patio_control(PATIO_CONTROL_ZONA_NO_PLANIFICADOS)[:8], '#a78bfa')

    ax.add_patch(Rectangle((7.5, 89), 8, 4.5, facecolor='#1f2937', edgecolor='#64748b', linewidth=.9))
    ax.text(11.5, 91.25, 'Comedor', color='#cbd5e1', ha='center', va='center', fontsize=6)
    ax.add_patch(Rectangle((16, 89), 8, 4.5, facecolor='#1f2937', edgecolor='#64748b', linewidth=.9))
    ax.text(20, 91.25, 'Bano\nMujeres', color='#cbd5e1', ha='center', va='center', fontsize=6)
    ax.add_patch(Rectangle((24.5, 89), 8, 4.5, facecolor='#1f2937', edgecolor='#64748b', linewidth=.9))
    ax.text(28.5, 91.25, 'Bano\nHombres', color='#cbd5e1', ha='center', va='center', fontsize=6)

    ax.text(50, 97, 'Plano operativo basado en patio real - posiciones vivas desde CAMION_PATIO', color='#94a3b8', ha='center', va='center', fontsize=8)

    buffer = BytesIO()
    fig.savefig(buffer, format='svg', bbox_inches='tight', pad_inches=0)
    plt.close(fig)
    image = 'data:image/svg+xml;base64,' + base64.b64encode(buffer.getvalue()).decode('ascii')
    try:
        cache.set(cache_key, image, 3600)
    except Exception:
        pass
    return image


def _camion_patio_asociado_citacion(citacion):
    return CAMION_PATIO.objects.select_related('US_ASOCIA_ID', 'US_GUARDIA_ID').filter(
        CI_NID=citacion,
        CPA_CESTADO=CAMION_PATIO.ESTADO_ASOCIADO_CITACION
    ).order_by('-CPA_FFECHAASOCIACION', '-id').first()


def _contexto_ingreso_camion_patio(citacion):
    camion = _camion_patio_asociado_citacion(citacion)
    if not camion:
        return {
            'camion': None,
            'usuario_ingreso_nombre': 'usuario no identificado',
            'transporte_a_cargo': '',
            'transporte_a_cargo_display': 'No informado',
            # Conserva el comportamiento historico para citaciones sin CAMION_PATIO asociado.
            'requiere_ruta_transportista': True,
        }

    transporte_a_cargo = str(camion.transporte_a_cargo or 'TERRAMAR').strip().upper()
    if transporte_a_cargo not in {'TERRAMAR', 'CLIENTE'}:
        transporte_a_cargo = 'TERRAMAR'
    return {
        'camion': camion,
        'usuario_ingreso_nombre': (
            camion.US_GUARDIA_ID.username
            if camion.US_GUARDIA_ID_id and camion.US_GUARDIA_ID
            else 'usuario no identificado'
        ),
        'transporte_a_cargo': transporte_a_cargo,
        'transporte_a_cargo_display': 'Cliente' if transporte_a_cargo == 'CLIENTE' else 'Terramar',
        'requiere_ruta_transportista': transporte_a_cargo == 'TERRAMAR',
    }


def condicion_entrega_despacho_revision(citacion):
    if not es_citacion_despacho(citacion):
        return ''
    condicion = normalizar_nombre_perfil(
        sap_despacho_detalle_resumen_dict(citacion).get('condicion_entrega')
    )
    return condicion if condicion in {'CLIENTE', 'TERRAMAR'} else ''


def requiere_ruta_transportista_revision(citacion, contexto_ingreso=None):
    """En Despacho usa la condicion persistida; Recepcion conserva el contexto del camion."""
    if es_flujo_recepcion_new_jersey_sin_calidad(citacion):
        return False
    if es_recepcion_new_jersey_p3(citacion):
        return False
    # El retiro de contenedor PROSESA Piso 2 siempre necesita una ruta tarifada.
    # No depende de la modalidad que haya quedado registrada en CAMION_PATIO.
    if es_recepcion_prosesa_piso_2(citacion):
        return True
    condicion_entrega = condicion_entrega_despacho_revision(citacion)
    if condicion_entrega:
        return condicion_entrega == 'TERRAMAR'
    contexto = contexto_ingreso or _contexto_ingreso_camion_patio(citacion)
    return bool(contexto['requiere_ruta_transportista'])


CAMION_PATIO_LOG_ASOCIACION = 'CAMION_PATIO_ASOC'
CAMION_PATIO_LOG_EDICION = 'CAMION_PATIO_EDIT'
CAMION_PATIO_LOG_ADJUNTO = 'CAMION_PATIO_ADJ'
CAMION_PATIO_LOG_DERIVACION = 'CAM_PATIO_DERIVA'
CAMION_PATIO_EXTENSIONES_ADJUNTO = {'.pdf', '.jpg', '.jpeg', '.png', '.doc', '.docx', '.xls', '.xlsx'}


def _usuario_puede_modificar_camion_patio(user):
    return usuario_puede_revisar_camion_patio(user)


def _url_adjunto_patio(adjunto):
    return reverse('camion_patio_adjunto_ver', args=[adjunto.id])


def _archivo_adjunto_patio_disponible(adjunto):
    try:
        return bool(adjunto.CPA_FARCHIVO and os.path.exists(adjunto.CPA_FARCHIVO.path))
    except Exception:
        return False


def _camion_patio_bloqueado_para_edicion(camion):
    return bool(
        camion.CI_NID_id
        or camion.CPA_CESTADO == CAMION_PATIO.ESTADO_ASOCIADO_CITACION
    )


def _mensaje_camion_patio_bloqueado():
    return 'Este camion ya esta asociado a una citacion. No se pueden editar sus datos desde este modal.'


def _validar_archivo_camion_patio(archivo):
    if not archivo:
        raise ValueError('Debe seleccionar un archivo.')
    extension = os.path.splitext(archivo.name or '')[1].lower()
    if extension not in CAMION_PATIO_EXTENSIONES_ADJUNTO:
        permitidas = ', '.join(sorted(CAMION_PATIO_EXTENSIONES_ADJUNTO))
        raise ValueError(f'Extension no permitida. Use: {permitidas}.')


def _serializar_adjunto_patio(adjunto, puede_modificar=False):
    return {
        'id': adjunto.id,
        'tipo': adjunto.CPA_CTIPO_DOCUMENTO,
        'tipo_label': adjunto.get_CPA_CTIPO_DOCUMENTO_display(),
        'nombre': os.path.basename(adjunto.CPA_FARCHIVO.name),
        'url': _url_adjunto_patio(adjunto),
        'disponible': _archivo_adjunto_patio_disponible(adjunto),
        'fecha_carga': timezone.localtime(adjunto.CPA_FFECHACARGA).strftime('%d/%m/%Y %H:%M') if adjunto.CPA_FFECHACARGA else '',
        'usuario': adjunto.US_CARGA_ID.username if adjunto.US_CARGA_ID else '',
        'puede_modificar': bool(puede_modificar),
        'puede_eliminar': bool(puede_modificar),
    }


def _serializar_adjuntos_patio(camion, puede_modificar=False):
    return [
        _serializar_adjunto_patio(adjunto, puede_modificar=puede_modificar)
        for adjunto in camion.adjuntos.all().order_by('CPA_CTIPO_DOCUMENTO', '-CPA_FFECHACARGA', '-id')
    ]


def _detalle_camion_patio_response(camion, request):
    puede_modificar = (
        usuario_puede_modificar_camion_patio_objeto(request.user, camion)
        and not _camion_patio_bloqueado_para_edicion(camion)
    )
    puede_asociar = bool(
        usuario_puede_asociar_camion_patio(request.user, camion)
        and not camion.CI_NID_id
        and camion.CPA_CESTADO == CAMION_PATIO.ESTADO_PENDIENTE_ASOCIACION
    )
    validacion_asociacion = _validar_datos_asociacion_camion_despacho_sbh(camion)
    return JsonResponse({
        'success': True,
        'camion': _serializar_camion_patio(camion),
        'adjuntos': _serializar_adjuntos_patio(camion, puede_modificar=puede_modificar),
        'citaciones': _citaciones_disponibles_para_patio(camion),
        'validacion_asociacion': {
            'aplica': validacion_asociacion['aplica'],
            'valido': validacion_asociacion['valido'],
            'errores': validacion_asociacion['errores'],
            'campos': validacion_asociacion['campos'],
        },
        'tipos_documento': [
            {'value': value, 'label': label}
            for value, label in CAMION_PATIO_ADJUNTO.TIPOS
        ],
        'permisos': {
            'puede_editar': puede_modificar,
            'puede_gestionar_adjuntos': puede_modificar,
            'puede_asociar': puede_asociar,
            'asociacion_directa_asistente_despacho': bool(
                puede_asociar
                and _es_camion_despacho_patio(camion)
                and usuario_es_asistente_despacho_empresa(request.user, camion.EP_NID_id)
            ),
            'puede_solicitar_no_planificado': bool(
                usuario_puede_registrar_camion_patio_empresa(request.user, camion.EP_NID_id)
                and not camion.CI_NID_id
                and camion.CPA_CESTADO not in [CAMION_PATIO.ESTADO_RECHAZADO, CAMION_PATIO.ESTADO_CANCELADO]
            ),
            'mensaje_bloqueo': _mensaje_camion_patio_bloqueado() if _camion_patio_bloqueado_para_edicion(camion) else '',
        }
    })


TIPOS_RECEPCION_CAMION_PATIO_SBH_NUEVOS = {'NACIONAL', 'IMPORTACION'}
TIPOS_RECEPCION_CAMION_PATIO_SBH_HISTORICOS = {
    *TIPOS_RECEPCION_CAMION_PATIO_SBH_NUEVOS,
    'EXTRANJERO',
}


def _normalizar_tipo_recepcion_camion_patio_sbh(
    valor,
    permitir_extranjero_historico=False,
):
    texto = str(valor or '').strip()
    if not texto:
        raise ValueError('Debe seleccionar si la recepción es Nacional o Importación.')
    normalizado = texto.upper()
    permitidos = (
        TIPOS_RECEPCION_CAMION_PATIO_SBH_HISTORICOS
        if permitir_extranjero_historico
        else TIPOS_RECEPCION_CAMION_PATIO_SBH_NUEVOS
    )
    if normalizado not in permitidos:
        raise ValueError('Tipo de recepción inválido.')
    return normalizado


def _normalizar_fecha_documental_sbh(valor, etiqueta):
    """Valida una fecha real opcional y devuelve el formato operacional DDMMAAAA."""
    texto = str(valor or '').strip()
    if not texto:
        return ''
    partes = None
    for separador in ('/', '-', '.'):
        if separador in texto:
            partes = texto.split(separador)
            break
    if (
        partes
        and len(partes) == 3
        and len(partes[0]) != 4
        and len(partes[-1]) == 2
    ):
        raise ValueError('Ingrese la fecha con año de cuatro dígitos.')

    formatos = ('%d/%m/%Y', '%d-%m-%Y', '%d.%m.%Y', '%d%m%Y', '%Y-%m-%d')
    fecha = None
    for formato in formatos:
        try:
            fecha = datetime.strptime(texto, formato).date()
            break
        except ValueError:
            continue
    if fecha is None:
        raise ValueError(f'{etiqueta} inválida.')
    normalizada = fecha.strftime('%d%m%Y')
    if len(normalizada) != 8:
        raise ValueError(f'{etiqueta} inválida.')
    return normalizada


def _normalizar_fecha_vencimiento_producto_sbh(valor):
    return _normalizar_fecha_documental_sbh(valor, 'Fecha de vencimiento de producto')


def _normalizar_fecha_produccion_producto_sbh(valor):
    return _normalizar_fecha_documental_sbh(valor, 'Fecha de producción')

def _render_camiones_patio_registrar(request, empresa_id, form_data=None, status=200):
    camiones_pendientes = CAMION_PATIO.objects.filter(
        EP_NID_id=empresa_id,
        CPA_CESTADO=CAMION_PATIO.ESTADO_PENDIENTE_ASOCIACION,
        CI_NID__isnull=True
    ).order_by('-CPA_FFECHALLEGADA')[:30]
    return render(request, 'home/CAMION_PATIO/registrar.html', {
        'empresa_activa_id': empresa_id,
        'tipos_documento': CAMION_PATIO_ADJUNTO.TIPOS,
        'camiones_pendientes': camiones_pendientes,
        'form_data': form_data,
        'country_calling_codes': country_options(),
    }, status=status)


def _normalizar_guia_planificacion(valor):
    return ''.join(ch for ch in str(valor or '').upper() if ch.isalnum())


def _citacion_terramar_disponible_para_llegada(citacion, ahora=None):
    ahora = ahora or timezone.now()
    if (
        not (es_citacion_recepcion_terramar(citacion) or es_citacion_despacho_terramar(citacion))
        or not citacion.CI_BHABILITADO
        or _estado_citacion_no_vigente(citacion)
    ):
        return False
    if not citacion.CI_FFECHACITACION or abs((citacion.CI_FFECHACITACION - ahora).total_seconds()) > 24 * 60 * 60:
        return False
    patios_candidatos = CAMION_PATIO.objects.filter(
        CI_NID=citacion,
        CPA_CESTADO__in=CAMION_PATIO.ESTADOS_ACTIVOS,
    )
    if any(_camion_patio_es_ciclo_activo(camion) for camion in patios_candidatos):
        return False
    return not ETAPA_LOG.objects.filter(CI_NID=citacion).exists() and not OPERACION_PLANTA_LOG.objects.filter(CI_NID=citacion).exists()


def _resolver_conductor_planificado_despacho_patio(citacion, detalle):
    conductor_fk = getattr(citacion, 'CON_NID', None)
    if (
        conductor_fk
        and conductor_fk.EP_NID_id == ID_TERRAMAR
        and conductor_fk.CON_BHABILITADO
    ):
        return conductor_fk

    nombre_planificado = str(getattr(detalle, 'CDD_CCONDUCTOR', '') or '').strip()
    nombre_normalizado = _normalizar_match_texto(nombre_planificado)
    if not nombre_normalizado:
        return None

    candidatos = [
        conductor for conductor in CONDUCTOR.objects.filter(
            EP_NID_id=ID_TERRAMAR,
            CON_BHABILITADO=True,
        ).order_by('id')
        if _normalizar_match_texto(
            f'{conductor.CON_CNOMBRE or ""} {conductor.CON_CAPELLIDO or ""}'
        ) == nombre_normalizado
    ]
    return candidatos[0] if len(candidatos) == 1 else None

def _payload_citacion_terramar_patio(citacion):
    if es_citacion_despacho_terramar(citacion):
        detalle = CITACION_DESPACHO_DETALLE.objects.filter(CI_NID=citacion, EP_NID_id=1).first()
        item_rel = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion, EP_NID_id=1).order_by('id').first()
        empresa_transporte_nombre = str(getattr(detalle, 'CDD_CEMPRESA_TRANSPORTE', '') or '').strip()
        empresa_transporte = queryset_transportistas_validos_ingreso_camion(1, estrictamente_empresa=True).filter(
            SN_CRAZONSOCIAL__iexact=empresa_transporte_nombre
        ).first() if empresa_transporte_nombre else None
        conductor_planificado = str(getattr(detalle, 'CDD_CCONDUCTOR', '') or '').strip()
        patente_planificada = str(getattr(detalle, 'CDD_CPATENTE', '') or '').strip()
        conductor_pendiente = not conductor_planificado and not patente_planificada
        conductor = _resolver_conductor_planificado_despacho_patio(citacion, detalle)
        conductor_nombre = (
            f'{conductor.CON_CNOMBRE or ""} {conductor.CON_CAPELLIDO or ""}'.strip()
            if conductor else conductor_planificado
        )
        telefono_maestro = split_legacy_phone(
            getattr(conductor, 'CON_CCODIGO_PAIS_TELEFONO', ''),
            getattr(conductor, 'CON_CTELEFONO', ''),
        ) if conductor else {'country_code': '+56', 'local_number': ''}
        datos_cliente = {}
        for dato in DATO_OPERACION.objects.select_related('CAMP_NID').filter(
            CI_NID=citacion,
            CAMP_NID__CA_CCODIGO__in=[PLAN_CODIGO_CLIENTE_SAP, PLAN_CLIENTE_SAP, 'PLAN_CONTRATO_SAP'],
        ).order_by('-id'):
            datos_cliente.setdefault(dato.CAMP_NID.CA_CCODIGO, str(dato.DO_CVALOR or '').strip())
        cliente_codigo = getattr(detalle, 'CDD_CSAP_CLIENTE_CODIGO', '') or datos_cliente.get(PLAN_CODIGO_CLIENTE_SAP, '') or (citacion.SN_NID.SN_CCODIGO_SAP if citacion.SN_NID else '')
        cliente_nombre = getattr(detalle, 'CDD_CSAP_CLIENTE_NOMBRE', '') or datos_cliente.get(PLAN_CLIENTE_SAP, '') or (citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else '')
        return {
            'citacion_id': citacion.id, 'citacion_numero': citacion.id, 'numero_citacion': citacion.id, 'planificacion_id': citacion.PL_NID_id,
            'fecha_citacion': timezone.localtime(citacion.CI_FFECHACITACION).strftime('%d/%m/%Y %H:%M'), 'estado': citacion.CI_CESTADO or '', 'tipo_citacion': CIT_DESPACHO,
            'empresa_transporte_id': empresa_transporte.id if empresa_transporte else None, 'empresa_transporte_nombre': empresa_transporte_nombre,
            'transporte_id': empresa_transporte.id if empresa_transporte else None, 'transporte_nombre': empresa_transporte_nombre,
            'conductor_pendiente': conductor_pendiente, 'conductor_id': conductor.id if conductor else None,
            'conductor_registrado': bool(conductor), 'conductor_nombre': conductor_nombre,
            'conductor_rut': str(getattr(conductor, 'CON_CRUT', '') or '').strip(),
            'conductor_telefono': getattr(detalle, 'CDD_CTELEFONO_CONDUCTOR', '') or telefono_maestro['local_number'],
            'codigo_pais': getattr(detalle, 'CDD_CCODIGO_PAIS_TELEFONO', '') or telefono_maestro['country_code'],
            'patente': getattr(detalle, 'CDD_CPATENTE', '') or '', 'transporte_a_cargo': getattr(detalle, 'CDD_CTRANSPORTE_A_CARGO', '') or 'Terramar',
            'proveedor': citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else '', 'cliente': cliente_nombre, 'cliente_codigo': cliente_codigo,
            'insumo': getattr(detalle, 'CDD_CSAP_NOMBRE_PRODUCTO', '') or (item_rel.IT_NID.IT_CNOMBRE if item_rel else ''),
            'tipo_documento': citacion.CI_CTIPODOCUMENTO or '', 'guia_esperada': '', 'bl': '',
            'contenedor_crt': getattr(detalle, 'CDD_CCONTENEDOR_CRT', '') or '', 'lote_contenedor': getattr(detalle, 'CDD_CCONTENEDOR_CRT', '') or '',
            'secuencia': citacion.SC_NID.SE_CNOMBRE if citacion.SC_NID else '',
        }
    detalle = CITACION_RECEPCION_TERRAMAR_DETALLE.objects.select_related('SN_NID_TRANSPORTISTA', 'CON_NID').filter(CI_NID=citacion).first()
    item_rel = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion, EP_NID_id=1).order_by('id').first()
    conductor = detalle.CON_NID if detalle else None
    transportista = detalle.SN_NID_TRANSPORTISTA if detalle else None
    conductor_nombre = (f'{conductor.CON_CNOMBRE or ""} {conductor.CON_CAPELLIDO or ""}'.strip() if conductor else (detalle.RTD_CCONDUCTOR if detalle else ''))
    return {
        'citacion_id': citacion.id, 'citacion_numero': citacion.id, 'numero_citacion': citacion.id, 'planificacion_id': citacion.PL_NID_id,
        'fecha_citacion': timezone.localtime(citacion.CI_FFECHACITACION).strftime('%d/%m/%Y %H:%M'), 'estado': citacion.CI_CESTADO or '',
        'empresa_transporte_id': transportista.id if transportista else None,
        'empresa_transporte_nombre': transportista.SN_CRAZONSOCIAL if transportista else (detalle.RTD_CEMPRESA_TRANSPORTE if detalle else ''),
        'conductor_id': conductor.id if conductor else None, 'conductor_registrado': bool(conductor), 'conductor_nombre': conductor_nombre,
        'conductor_rut': conductor.CON_CRUT if conductor else '', 'conductor_telefono': (conductor.CON_CTELEFONO if conductor else (detalle.RTD_CTELEFONO_CONDUCTOR if detalle else '')),
        'codigo_pais': (conductor.CON_CCODIGO_PAIS_TELEFONO if conductor else (detalle.RTD_CCODIGO_PAIS_TELEFONO if detalle else '+56')),
        'patente': detalle.RTD_CPATENTE if detalle else '', 'transporte_a_cargo': detalle.RTD_CTRANSPORTE_A_CARGO if detalle else 'Terramar',
        'proveedor': citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else '', 'cliente': citacion.SN_NID.SN_CRAZONSOCIAL if citacion.SN_NID else '',
        'insumo': item_rel.IT_NID.IT_CNOMBRE if item_rel else '', 'tipo_documento': citacion.CI_CTIPODOCUMENTO or '',
        'guia_esperada': citacion.CI_CNUMERODOCUMENTO or '', 'bl': '', 'contenedor_crt': detalle.RTD_CCONTENEDOR_CRT if detalle else '', 'lote_contenedor': detalle.RTD_CCONTENEDOR_CRT if detalle else '',
        'secuencia': citacion.SC_NID.SE_CNOMBRE if citacion.SC_NID else '',
    }


def consultar_citacion_patente_patio(request):
    if (
        not usuario_puede_registrar_camion_patio(request.user)
        and not usuario_es_asistente_despacho_global(request.user)
    ):
        return JsonResponse({'ok': False, 'status': 'UNAUTHORIZED_COMPANY'}, status=403)
    empresa_id = Verificar_empresa(request)
    if not empresa_id or not usuario_puede_registrar_camion_patio_empresa(request.user, empresa_id):
        return JsonResponse({'ok': False, 'status': 'UNAUTHORIZED_COMPANY'}, status=403)
    if empresa_id != 1:
        return JsonResponse({'ok': False, 'status': 'UNAUTHORIZED_COMPANY'}, status=403)
    patente = _normalizar_patente_busqueda(request.GET.get('patente'))
    if not patente:
        return JsonResponse({'ok': False, 'status': 'INVALID_PLATE', 'matches': []}, status=400)
    detalles_recepcion = _queryset_patente_normalizada(CITACION_RECEPCION_TERRAMAR_DETALLE.objects.filter(EP_NID_id=1), 'RTD_CPATENTE', patente).select_related('CI_NID__PL_NID', 'CI_NID__SC_NID', 'CI_NID__SN_NID', 'CI_NID__PRO_NID')
    detalles_despacho = _queryset_patente_normalizada(CITACION_DESPACHO_DETALLE.objects.filter(EP_NID_id=1), 'CDD_CPATENTE', patente).select_related('CI_NID__PL_NID', 'CI_NID__SC_NID', 'CI_NID__SN_NID', 'CI_NID__PRO_NID')
    citaciones = {detalle.CI_NID_id: detalle.CI_NID for detalle in detalles_recepcion}
    citaciones.update({detalle.CI_NID_id: detalle.CI_NID for detalle in detalles_despacho})
    matches = [citacion for citacion in citaciones.values() if _citacion_terramar_disponible_para_llegada(citacion)]
    if not matches:
        detalles_pendientes = CITACION_DESPACHO_DETALLE.objects.filter(
            EP_NID_id=1,
        ).filter(
            (Q(CDD_CCONDUCTOR__isnull=True) | Q(CDD_CCONDUCTOR=''))
            & (Q(CDD_CPATENTE__isnull=True) | Q(CDD_CPATENTE=''))
        ).select_related(
            'CI_NID__PL_NID', 'CI_NID__SC_NID', 'CI_NID__SN_NID', 'CI_NID__PRO_NID'
        )
        matches = [
            detalle.CI_NID for detalle in detalles_pendientes
            if _citacion_terramar_disponible_para_llegada(detalle.CI_NID)
        ]
    payload = [_payload_citacion_terramar_patio(c) for c in matches]
    status = 'NO_MATCH' if not payload else ('MATCH' if len(payload) == 1 else 'MULTIPLE_MATCHES')
    return JsonResponse({'ok': True, 'status': status, 'matches': payload})


def _validar_carga_planificada_patio(request, empresa_id):
    if str(request.POST.get('carga_desde_planificacion') or '') != '1':
        return None, None
    if empresa_id != 1:
        raise ValueError('La carga desde planificación sólo está disponible para Terramar.')
    citacion_id = str(request.POST.get('citacion_planificada_id') or '').strip()
    if not citacion_id.isdigit():
        raise ValueError('Debe seleccionar una citación válida de planificación.')
    citacion = CITACION.objects.select_related('PL_NID', 'SC_NID', 'SN_NID', 'PRO_NID').filter(pk=citacion_id, EP_NID_id=1).first()
    if not citacion or not _citacion_terramar_disponible_para_llegada(citacion):
        raise ValueError('La citación seleccionada ya no está disponible para registrar llegada.')
    if str(request.POST.get('planificacion_planificada_id') or '') != str(citacion.PL_NID_id):
        raise ValueError('La planificación seleccionada no corresponde a la citación.')
    guia_esperada = (citacion.CI_CNUMERODOCUMENTO or '') if es_citacion_recepcion_terramar(citacion) else ''
    guia_recibida = str(request.POST.get('numero_guia') or '').strip()
    coinciden = not guia_esperada or _normalizar_guia_planificacion(guia_esperada) == _normalizar_guia_planificacion(guia_recibida)
    acepta = str(request.POST.get('acepta_diferencia_guia') or '') == '1'
    observacion = str(request.POST.get('observacion_diferencia_guia') or '').strip()
    if guia_esperada and not coinciden and (not acepta or not observacion):
        raise ValueError('La guía no coincide con la planificación. Debe confirmar la diferencia e indicar una observación.')
    return citacion, {'guia_esperada': guia_esperada, 'guia_recibida': guia_recibida, 'resultado_guia': 'SIN_GUIA_ESPERADA' if not guia_esperada else ('COINCIDE' if coinciden else 'DIFERENTE'), 'acepta_diferencia': bool(guia_esperada and not coinciden and acepta), 'observacion': observacion}

def CAMIONES_PATIO_REGISTRAR(request):
    Empresa = Verificar_empresa(request)
    if Empresa is None:
        messages.error(request, 'Debe seleccionar una empresa.')
        return redirect('/')
    if not usuario_puede_registrar_camion_patio_empresa(request.user, Empresa):
        messages.error(request, 'No tiene permisos para registrar camiones en patio.')
        return redirect('/')
    empresa = EMPRESA.objects.filter(pk=Empresa).first()
    if request.method == 'POST':
        es_despacho = str(request.POST.get('es_despacho') or '').strip().lower() in {
            '1', 'true', 'on', 'yes', 'si', 'sí'
        }
        try:
            citacion_planificada, trazabilidad_guia = _validar_carga_planificada_patio(request, Empresa)
        except ValueError as exc:
            messages.error(request, str(exc))
            return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
        datos_planificados = (
            _payload_citacion_terramar_patio(citacion_planificada)
            if citacion_planificada and es_citacion_despacho_terramar(citacion_planificada)
            else None
        )
        transporte_a_cargo = str(
            (datos_planificados or {}).get('transporte_a_cargo')
            or request.POST.get('transporte_a_cargo')
            or ''
        ).strip().upper()
        if transporte_a_cargo not in {'TERRAMAR', 'CLIENTE'}:
            messages.error(request, 'Debe seleccionar quien esta a cargo del transporte.')
            return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)

        transporte_cliente = transporte_a_cargo == 'CLIENTE'
        conductor_no_registrado = (
            not transporte_cliente
            and str(request.POST.get('conductor_manual') or '').strip().lower() in {
                '1', 'true', 'on', 'yes'
            }
        )
        conductor_manual_terramar = bool(
            conductor_no_registrado
            and Empresa == ID_TERRAMAR
            and not es_despacho
        )
        if conductor_no_registrado and not conductor_manual_terramar:
            messages.error(
                request,
                'Debe registrar al conductor en el maestro antes de continuar con Transporte Terramar.',
            )
            return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
        conductor_manual = transporte_cliente or conductor_manual_terramar
        patente = str(request.POST.get('patente') or '').strip().upper()
        rut_conductor = str(request.POST.get('rut_conductor') or '').strip()
        telefono_conductor = str(request.POST.get('telefono_conductor') or '').strip()
        telefono_codigo_pais = str(
            request.POST.get('telefono_codigo_pais')
            or ('' if es_despacho else '+56')
        ).strip()
        conductor = str(
            (request.POST.get('conductor_nombre_manual') or '')
            if conductor_manual
            else (request.POST.get('conductor') or '')
        ).strip()
        empresa_transporte_cliente = re.sub(
            r'\s+', ' ', str(request.POST.get('empresa_transporte') or '')
        ).strip()
        transportista = (
            empresa_transporte_cliente
            if transporte_cliente and not es_despacho
            else (
                'CLIENTE'
                if transporte_cliente
                else str(
                    (datos_planificados or {}).get('empresa_transporte_nombre')
                    or request.POST.get('transportista')
                    or ''
                ).strip()
            )
        )
        if (
            transporte_cliente
            and not es_despacho
            and (
                not transportista
                or transportista.upper() == 'CLIENTE'
            )
        ):
            messages.error(request, 'Debe ingresar la empresa de transporte.')
            return _render_camiones_patio_registrar(
                request, Empresa, request.POST, status=400,
            )
        if Empresa == ID_ACEITES_SBH and transporte_a_cargo == 'TERRAMAR':
            transportista_id = str(request.POST.get('transportista_id') or '').strip()
            if not transportista_id.isdigit():
                messages.error(request, 'Debe seleccionar un transportista válido de SBH.')
                return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
            transportista_sbh = queryset_transportistas_validos_ingreso_camion(
                Empresa, estrictamente_empresa=True,
            ).filter(pk=transportista_id).first()
            if not transportista_sbh:
                messages.error(request, 'El transportista seleccionado no pertenece al maestro habilitado de SBH.')
                return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
            transportista = transportista_sbh.SN_CRAZONSOCIAL
        conductor_maestro = None
        if not conductor_manual:
            conductor_id = str(request.POST.get('conductor_id') or '').strip()
            if not conductor_id.isdigit():
                messages.error(request, 'Debe seleccionar un conductor registrado del maestro.')
                return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
            conductores_maestro = CONDUCTOR.objects.filter(
                pk=conductor_id,
                CON_BHABILITADO=True,
            )
            conductor_maestro = conductores_maestro.first()
            if not conductor_maestro:
                messages.error(request, 'El conductor seleccionado no está habilitado en el maestro.')
                return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
            conductor = ' '.join(
                parte for parte in (
                    str(conductor_maestro.CON_CNOMBRE or '').strip(),
                    str(conductor_maestro.CON_CAPELLIDO or '').strip(),
                ) if parte
            )
            if not (Empresa == ID_TERRAMAR and not es_despacho):
                rut_conductor = str(conductor_maestro.CON_CRUT or '').strip()
        proveedor = str(request.POST.get('proveedor') or '').strip()
        cliente = str(request.POST.get('cliente') or '').strip()
        tipo_documento = str(request.POST.get('tipo_documento') or '').strip().upper()
        numero_guia = str(request.POST.get('numero_guia') or '').strip()
        insumo_declarado_guia = str(request.POST.get('insumo_declarado_guia') or '').strip()
        observacion = str(request.POST.get('observacion') or '').strip()
        es_recepcion_sbh = Empresa == 2 and not es_despacho
        tipo_recepcion = ''
        cda = ''
        di = ''
        nave_naviera = ''
        fecha_produccion = ''
        fecha_vencimiento_producto = ''
        sui = ''
        bl = str(request.POST.get('bl') or '').strip()
        lote_contenedor = str(request.POST.get('lote_contenedor') or '').strip()
        if es_recepcion_sbh:
            try:
                tipo_recepcion = _normalizar_tipo_recepcion_camion_patio_sbh(
                    request.POST.get('tipo_recepcion')
                )
                fecha_produccion = _normalizar_fecha_produccion_producto_sbh(
                    request.POST.get('fecha_produccion')
                )
                fecha_vencimiento_producto = _normalizar_fecha_vencimiento_producto_sbh(
                    request.POST.get('fecha_vencimiento_producto')
                )
                if tipo_recepcion in {'NACIONAL', 'IMPORTACION'} and not fecha_produccion:
                    raise ValueError('Debe ingresar la fecha de producción.')
            except ValueError as exc:
                messages.error(request, str(exc))
                return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
            if tipo_recepcion in {'IMPORTACION', 'EXTRANJERO'}:
                cda = str(request.POST.get('cda') or '').strip()
                di = str(request.POST.get('di') or '').strip()
                nave_naviera = str(request.POST.get('nave_naviera') or '').strip()
                sui = str(request.POST.get('sui') or '').strip()
            else:
                bl = ''
                lote_contenedor = ''
            if len(observacion) > 250:
                messages.error(request, 'La observación no puede superar los 250 caracteres.')
                return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
        errores_validacion = []
        if transporte_a_cargo == 'TERRAMAR' and not transportista:
            errores_validacion.append('Empresa transporte')
        if not conductor:
            errores_validacion.append('Nombre conductor')
        if not patente:
            errores_validacion.append('Patente camion')
        if not rut_conductor:
            errores_validacion.append('RUT conductor')
        if not telefono_conductor:
            errores_validacion.append('Celular conductor')
        if es_despacho and not telefono_codigo_pais:
            errores_validacion.append('Codigo pais')
        if not es_despacho and not proveedor:
            errores_validacion.append('Proveedor declarado')
        if not es_despacho and not cliente:
            errores_validacion.append('Cliente declarado')
        if tipo_documento not in {'GD', 'FE'} and (not es_despacho or tipo_documento):
            messages.error(request, 'Tipo de documento inválido.')
            return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
        if not es_despacho and not numero_guia:
            errores_validacion.append('Numero guia/documento')
        if not es_despacho and not insumo_declarado_guia:
            errores_validacion.append('Insumo declarado en guia')
        if errores_validacion:
            messages.error(request, 'Debe completar los campos obligatorios: ' + ', '.join(errores_validacion) + '.')
            return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
        if Empresa == ID_TERRAMAR and not es_despacho:
            try:
                rut_conductor = normalizar_rut_chileno(rut_conductor)
            except RutChilenoInvalido:
                messages.error(request, 'El RUT del conductor no es válido.')
                return _render_camiones_patio_registrar(
                    request, Empresa, request.POST, status=400,
                )
        if telefono_conductor:
            try:
                telefono = normalize_international_phone(telefono_codigo_pais, telefono_conductor)
                telefono_conductor = telefono['local_number']
                telefono_codigo_pais = telefono['country_code']
            except ValueError as exc:
                messages.error(request, str(exc))
                return _render_camiones_patio_registrar(request, Empresa, request.POST, status=400)
        with transaction.atomic():
            if citacion_planificada:
                citacion_planificada = CITACION.objects.select_for_update().select_related('PL_NID', 'SC_NID', 'EP_NID').get(
                    pk=citacion_planificada.pk,
                    EP_NID_id=Empresa,
                    CI_BHABILITADO=True,
                )
                if es_citacion_recepcion_terramar(citacion_planificada):
                    detalle_planificado = CITACION_RECEPCION_TERRAMAR_DETALLE.objects.filter(CI_NID=citacion_planificada).first()
                    patente_planificada = _normalizar_patente_busqueda(detalle_planificado.RTD_CPATENTE if detalle_planificado else '')
                else:
                    detalle_planificado = CITACION_DESPACHO_DETALLE.objects.filter(CI_NID=citacion_planificada).first()
                    patente_planificada = _normalizar_patente_busqueda(detalle_planificado.CDD_CPATENTE if detalle_planificado else '')
                if (
                    not (getattr(request.user, 'is_superuser', False) or _usuario_tiene_acceso_empresa(request.user, Empresa))
                    or not _citacion_terramar_disponible_para_llegada(citacion_planificada)
                    or not (es_citacion_recepcion_terramar(citacion_planificada) or es_citacion_despacho_terramar(citacion_planificada))
                    or citacion_planificada.PL_NID_id != int(request.POST.get('planificacion_planificada_id') or 0)
                    or (patente_planificada and patente_planificada != _normalizar_patente_busqueda(patente))
                ):
                    raise ValueError('La citación planificada ya no es válida para asociar automáticamente el camión.')
            camion = CAMION_PATIO.objects.create(
                EP_NID=empresa,
                CI_NID=None,
                CON_NID=conductor_maestro,
            transporte_a_cargo=transporte_a_cargo,
            CPA_CPATENTE=patente,
            CPA_CNOMBRE_CONDUCTOR=conductor,
            CPA_CRUT_CONDUCTOR=rut_conductor,
            CPA_CTELEFONO_CONDUCTOR=telefono_conductor,
            CPA_CCODIGO_PAIS_TELEFONO=telefono_codigo_pais,
            CPA_CTRANSPORTISTA_DECLARADO=transportista,
            CPA_CPROVEEDOR_DECLARADO=proveedor,
            CPA_CINSUMO_DECLARADO_GUIA=insumo_declarado_guia,
            CPA_CTIPO_RECEPCION=tipo_recepcion,
            CPA_CCDA=cda,
            CPA_CDI=di,
            CPA_CNAVE_NAVIERA=nave_naviera,
            CPA_CFECHAPRODUCCION=fecha_produccion,
            CPA_CFECHAVENCIMIENTOPRODUCTO=fecha_vencimiento_producto,
            CPA_CSUI=sui,
            CPA_CCLIENTE_DECLARADO=cliente,
            CPA_CTIPO_DOCUMENTO=tipo_documento,
            CPA_CNUMERO_GUIA=numero_guia,
            CPA_CBL=bl,
            CPA_CLOTE_CONTENEDOR=lote_contenedor,
            CPA_COBSERVACION=observacion,
                US_GUARDIA_ID=request.user,
            )
            if citacion_planificada:
                detalle_planificado = getattr(citacion_planificada, 'detalle_recepcion_terramar', None)
                patente_planificada = detalle_planificado.RTD_CPATENTE if detalle_planificado else ''
                if es_citacion_despacho_terramar(citacion_planificada):
                    detalle_planificado = CITACION_DESPACHO_DETALLE.objects.filter(CI_NID=citacion_planificada).first()
                    patente_planificada = detalle_planificado.CDD_CPATENTE if detalle_planificado else ''
                CAMION_PATIO_TRAZABILIDAD_PLANIFICACION.objects.create(CPA_NID=camion, CI_NID=citacion_planificada, PL_NID=citacion_planificada.PL_NID, EP_NID=empresa, CPTR_CPATENTE_CONSULTADA=_normalizar_patente_busqueda(request.POST.get('patente_consultada') or patente), CPTR_CRESULTADO_BUSQUEDA='MATCH', CPTR_BCARGADO_DESDE_PLANIFICACION=True, CPTR_CPATENTE_PLANIFICADA=patente_planificada, CPTR_CPATENTE_LLEGADA=patente, CPTR_CGUIA_ESPERADA=trazabilidad_guia['guia_esperada'], CPTR_CGUIA_RECIBIDA=trazabilidad_guia['guia_recibida'], CPTR_CRESULTADO_GUIA=trazabilidad_guia['resultado_guia'], CPTR_BDIFERENCIA_ACEPTADA=trazabilidad_guia['acepta_diferencia'], CPTR_COBSERVACION_DIFERENCIA=trazabilidad_guia['observacion'], US_NID=request.user, CPTR_FFECHACONSULTA=timezone.now())
            elif Empresa == ID_ACEITES_SBH and es_despacho:
                CAMION_PATIO_TRAZABILIDAD_PLANIFICACION.objects.create(
                    CPA_NID=camion, CI_NID=None, PL_NID=None, EP_NID=empresa,
                    CPTR_CPATENTE_CONSULTADA=patente,
                    CPTR_CRESULTADO_BUSQUEDA='RECEPCION_SIN_PLAN',
                    CPTR_BCARGADO_DESDE_PLANIFICACION=False,
                    CPTR_CPATENTE_PLANIFICADA='', CPTR_CPATENTE_LLEGADA=patente,
                    US_NID=request.user, CPTR_FFECHACONSULTA=timezone.now(),
                )
            for archivo in request.FILES.getlist('archivos_documentos'):
                CAMION_PATIO_ADJUNTO.objects.create(
                    CPA_NID=camion,
                    CPA_FARCHIVO=archivo,
                    CPA_CTIPO_DOCUMENTO=CAMION_PATIO_ADJUNTO.TIPO_OTRO,
                    US_CARGA_ID=request.user,
                )
        tipo_conductor = 'manual/cliente' if transporte_cliente else ('manual/no registrado' if conductor_manual else 'registrado/seleccionado')
        conductor_id = str(request.POST.get('conductor_id') or '').strip() if not conductor_manual else ''
        registrar_log_camion_no_planificado(
            request.user,
            empresa,
            'CAM_PATIO_REG',
            (
                f'Asistente Recepcion registra camion en patio #{camion.id}. Patente: {camion.CPA_CPATENTE}. '
                f'Transporte a cargo: {transporte_a_cargo}. Conductor: {tipo_conductor}. '
                f'Conductor ID: {conductor_id or "sin ID maestro"}.'
            ),
            camion.id,
            camion.CPA_CPATENTE
        )
        logger.info(
            'CAMIONES_PATIO_REGISTRAR camion_patio_id=%s empresa_id=%s transporte_a_cargo=%s modo_conductor=%s conductor_id=%s',
            camion.id, Empresa, transporte_a_cargo, 'manual' if conductor_manual else 'registrado', conductor_id or None
        )
        messages.success(
            request,
            'Camion registrado en patio pendiente de derivacion y asociacion.',
        )
        return redirect(f'{reverse("camiones_patio_registrar")}?_empresa_id={Empresa}')
    return _render_camiones_patio_registrar(request, Empresa)


def _camiones_patio_queryset(Empresa, request, solo_pendientes_asistente_despacho=False):
    queryset = CAMION_PATIO.objects.select_related(
        'US_GUARDIA_ID', 'US_ASOCIA_ID', 'CI_NID',
        'trazabilidad_planificacion__CI_NID', 'trazabilidad_planificacion__CI_NID__PL_NID',
        'trazabilidad_planificacion__PL_NID',
    ).filter(
        EP_NID_id=Empresa
    ).exclude(CI_NID__CI_BARCHIVADO=True)
    queryset = excluir_camiones_patio_ingresados_planta(queryset, Empresa)
    estado = request.GET.get('estado', '').strip()
    q = request.GET.get('q', '').strip()
    if estado:
        queryset = queryset.filter(CPA_CESTADO=estado)
    else:
        queryset = queryset.filter(CPA_CESTADO__in=CAMION_PATIO.ESTADOS_ACTIVOS)
    if q:
        queryset = queryset.filter(Q(CPA_CPATENTE__icontains=q) | Q(CPA_CNOMBRE_CONDUCTOR__icontains=q) | Q(CPA_CTRANSPORTISTA_DECLARADO__icontains=q) | Q(CPA_CINSUMO_DECLARADO_GUIA__icontains=q) | Q(CPA_CPROVEEDOR_DECLARADO__icontains=q) | Q(CPA_CNUMERO_GUIA__icontains=q) | Q(CPA_CBL__icontains=q))
    if solo_pendientes_asistente_despacho:
        queryset = queryset.filter(CPA_CESTADO=CAMION_PATIO.ESTADO_PENDIENTE_ASOCIACION, CI_NID__isnull=True)
        filtro_despacho = (
            Q(trazabilidad_planificacion__CI_NID__CI_CTIPO=CIT_DESPACHO)
            | Q(trazabilidad_planificacion__CI_NID__PL_NID__PL_CTIPOCUPO=CIT_DESPACHO)
            | Q(trazabilidad_planificacion__PL_NID__PL_CTIPOCUPO=CIT_DESPACHO)
        )
        if Empresa == ID_ACEITES_SBH:
            filtro_despacho |= Q(trazabilidad_planificacion__CPTR_CRESULTADO_BUSQUEDA__startswith='GUARDIA_')
            queryset = queryset.filter(
                Q(CPA_CTIPO_RECEPCION__isnull=True) | Q(CPA_CTIPO_RECEPCION='')
            )
        queryset = queryset.filter(filtro_despacho)
    return queryset.distinct().order_by('-CPA_FFECHALLEGADA')


def CAMIONES_PATIO_LIST(request):
    Empresa = Verificar_empresa(request)
    if Empresa is None:
        messages.error(request, 'Debe seleccionar una empresa.')
        return redirect('/')
    if not usuario_puede_revisar_camion_patio_empresa(request.user, Empresa):
        messages.error(request, 'No tiene permisos para revisar camiones en patio.')
        return redirect('/')
    es_asistente_despacho_patio = bool(
        Empresa == ID_TERRAMAR
        and usuario_es_asistente_despacho_empresa(request.user, Empresa)
    )
    return render(request, 'home/CAMION_PATIO/list.html', {
        'camiones': _camiones_patio_queryset(
            Empresa, request,
            solo_pendientes_asistente_despacho=es_asistente_despacho_patio,
        ),
        'estados': CAMION_PATIO.ESTADOS,
        'estado_actual': request.GET.get('estado', ''),
        'q': request.GET.get('q', ''),
        'empresa_activa_id': Empresa,
        'es_asistente_despacho_patio': es_asistente_despacho_patio,
        'puede_retirar_camion_patio': _usuario_puede_retirar_camion_patio(request.user),
    })


