def es_citacion_despacho(citacion):
    return str(citacion.CI_CTIPO or (citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '') or '').upper() == CIT_DESPACHO


def es_citacion_despacho_sbh(citacion):
    return citacion.EP_NID_id == 2 and es_citacion_despacho(citacion)


FLUJOS_DESPACHO_SBH_SAP_UPDATE = {
    'EST_SBH_CLIENTE',
    'TRASVASIJE_CLIENTE',
    'BODEGA_PATIO_CLIENTE',
}


def es_despacho_sbh_operacion(citacion):
    secuencia_codigo = str(
        citacion.SC_NID.SE_CCODIGO if getattr(citacion, 'SC_NID', None) else ''
    ).strip().upper()
    return es_citacion_despacho_sbh(citacion) and secuencia_codigo in FLUJOS_DESPACHO_SBH_SAP_UPDATE


def datos_asistente_cd_despacho(citacion, datos_operacion=None, detalle_operacional=None):
    datos_operacion = datos_operacion or {}
    detalle_operacional = detalle_operacional or detalle_operacional_dict(citacion)
    try:
        detalle_despacho = citacion.detalle_despacho
    except CITACION_DESPACHO_DETALLE.DoesNotExist:
        detalle_despacho = None

    def valor_codigo(codigo):
        dato = datos_operacion.get(codigo)
        return str(dato.DO_CVALOR or '').strip() if dato else ''

    peso_detalle = getattr(detalle_despacho, 'CDD_NPESO_INFORMADO', None) if detalle_despacho else None
    cantidad_intentada = (
        getattr(detalle_despacho, 'CDD_NCANTIDAD_INTENTADA_DESPACHAR', None)
        if detalle_despacho else None
    )

    return {
        'zona_carga': valor_codigo('ACD_ZONA_CARGA'),
        'estanque_origen': valor_codigo('ACD_ESTANQUE_ORIGEN'),
        'codigo_sap': valor_codigo('ACD_CODIGO_SAP') or str(detalle_operacional.get('codigo') or '').strip(),
        'numero_bach': valor_codigo('ACD_NUMERO_BACH'),
        'peso_informado': valor_codigo('ACD_PESO_INFORMADO') or (format(peso_detalle, 'f') if peso_detalle is not None else ''),
        'cantidad_intentada_despachar': format(cantidad_intentada.normalize(), 'f') if cantidad_intentada is not None else '',
        'intermes_id': valor_codigo('ACD_INTERMES_ID') or valor_codigo('AR_INTERMES_ID'),
        'lote_quantity': valor_codigo('ACD_LOTE_QUANTITY'),
        'lote_indate': valor_codigo('ACD_LOTE_INDATE'),
        'lote_status': valor_codigo('ACD_LOTE_STATUS'),
        'lote_item_name': valor_codigo('ACD_LOTE_ITEM_NAME'),
    }


def datos_asistente_cd_despacho_guardados(citacion, datos_operacion=None):
    datos = datos_asistente_cd_despacho(citacion, datos_operacion)
    campos_requeridos = ['zona_carga', 'estanque_origen', 'codigo_sap', 'numero_bach', 'intermes_id']
    campos_requeridos.append(
        'cantidad_intentada_despachar' if es_citacion_despacho_sbh(citacion) else 'peso_informado'
    )
    return all(str(datos.get(campo) or '').strip() for campo in campos_requeridos)


def mensaje_error_sap_despacho_usuario(sap_error):
    if not isinstance(sap_error, dict) or not isinstance(sap_error.get('data'), dict):
        return ''
    return sap_despacho_error_corto({'data': sap_error['data']})


def estado_draft_sap_despacho_modal(citacion):
    estado = dict(get_sap_despacho_draft_status(citacion) or {})
    if estado.get('created'):
        estado['is_error'] = False
        return estado
    ultimo_intento = OPERACION_PLANTA_LOG.objects.filter(
        CI_NID=citacion,
        OPL_CPASO=LOG_BORRADOR_SAP_DESPACHO_ENVIO,
    ).order_by('-OPL_FFECHAREGISTRO', '-id').first()
    if not ultimo_intento or ultimo_intento.OPL_CESTADO == OPERACION_PLANTA_LOG.ESTADO_COMPLETADO:
        estado['is_error'] = False
        return estado
    try:
        metadata = json.loads(ultimo_intento.OPL_COBSERVACION or '{}')
    except (TypeError, ValueError):
        metadata = {}
    estado.update({
        'is_error': True,
        'label': 'Error al crear Draft SAP',
        'error_message': mensaje_error_sap_despacho_usuario(metadata.get('sap_error')) or 'SAP no pudo crear el Draft.',
    })
    return estado


def guardar_datos_y_crear_draft_despacho_sbh(citacion, data, usuario):
    if not es_citacion_despacho_sbh(citacion):
        return False, {
            'success': False,
            'message': 'La creación automática del Draft SAP solo aplica a Despacho SBH.',
            'datos_guardados': False,
            'draft_sap': {},
            'sap_despacho_draft': {},
            'puede_avanzar': False,
        }
    estado_inicial = get_sap_despacho_draft_status(citacion)
    if estado_inicial.get('created'):
        datos_operacion, _ = obtener_datos_operacion_citacion(citacion)
        if not datos_asistente_cd_despacho_guardados(citacion, datos_operacion):
            return False, {
                'success': False,
                'message': 'El Draft SAP existe, pero faltan datos operacionales guardados.',
                'datos_guardados': False,
                'draft_sap': estado_inicial,
                'sap_despacho_draft': estado_inicial,
                'puede_avanzar': False,
            }
        return True, {
            'success': True,
            'message': 'Datos guardados. Draft SAP creado correctamente.',
            'datos_guardados': True,
            'draft_sap': estado_inicial,
            'sap_despacho_draft': estado_inicial,
            'puede_avanzar': True,
            'already_created': True,
        }

    ok, mensaje = guardar_datos_asistente_cd_despacho(citacion, data, usuario)
    if not ok:
        return False, {
            'success': False,
            'message': mensaje,
            'datos_guardados': False,
            'draft_sap': estado_inicial,
            'sap_despacho_draft': estado_inicial,
            'puede_avanzar': False,
        }

    resultado_sap = sap_despacho_crear_borrador(citacion, usuario)
    estado_modelo = getattr(citacion, '_state', None)
    if estado_modelo is not None:
        estado_modelo.fields_cache.pop('detalle_despacho', None)
    estado_final = get_sap_despacho_draft_status(citacion)
    if estado_final.get('created'):
        return True, {
            'success': True,
            'message': 'Datos guardados. Draft SAP creado correctamente.',
            'datos_guardados': True,
            'draft_sap': estado_final,
            'sap_despacho_draft': estado_final,
            'puede_avanzar': True,
            'already_created': not bool(resultado_sap.get('success')),
        }

    sap_message = (
        mensaje_error_sap_despacho_usuario(resultado_sap.get('sap_error'))
        or 'Revise el detalle informado por SAP e intente nuevamente.'
    )
    return False, {
        'success': False,
        'message': 'Datos guardados, pero SAP no pudo crear el Draft.',
        'datos_guardados': True,
        'draft_sap': estado_final,
        'sap_despacho_draft': estado_final,
        'puede_avanzar': False,
        'sap_message': sap_message,
    }


def respuesta_guardado_despacho_sbh_operador(ok, resultado):
    """Reduce la respuesta del guardado SBH a datos funcionales para el operador."""
    datos_guardados = bool(resultado.get('datos_guardados'))
    puede_avanzar = bool(resultado.get('puede_avanzar'))
    if ok:
        return {
            'success': True,
            'message': 'Datos guardados correctamente.',
            'datos_guardados': datos_guardados,
            'puede_avanzar': puede_avanzar,
        }
    if datos_guardados:
        return {
            'success': False,
            'message': 'No fue posible completar el guardado. Intente nuevamente o contacte a soporte.',
            'datos_guardados': True,
            'puede_avanzar': False,
        }
    return {
        'success': False,
        'message': resultado.get('message') or 'No fue posible guardar los datos.',
        'datos_guardados': False,
        'puede_avanzar': False,
    }


DESPACHO_CIERRE_NRO_SELLOS = 'DESPACHO_CIERRE_NRO_SELLOS'
DESPACHO_CIERRE_TEMPERATURA = 'DESPACHO_CIERRE_TEMPERATURA'
DESPACHO_ULTIMAS_CARGAS = 'DESPACHO_ULTIMAS_CARGAS'
DESPACHO_SELLO_EXTENSIONES = {'.jpg', '.jpeg', '.png'}
DESPACHO_SELLO_MIME = {'image/jpeg', 'image/png'}
DESPACHO_SELLO_MAX_BYTES = 10 * 1024 * 1024


def _documentos_sellos_despacho(citacion):
    documentos = CITACION_DOCUMENTO.objects.select_related('US_SUBE_NID', 'DO_NID').filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CD_CTIPO=CITACION_DOCUMENTO.TIPO_IMAGEN_SELLO_DESPACHO,
        CD_BACTIVO=True
    ).order_by('-CD_FFECHASUBIDA', '-id')

    return [
        {
            'id': documento.id,
            'nombre': documento.CD_CNOMBRE_ARCHIVO,
            'fecha': timezone.localtime(documento.CD_FFECHASUBIDA).strftime('%d/%m/%Y %H:%M') if documento.CD_FFECHASUBIDA else '',
            'usuario': documento.US_SUBE_NID.username if documento.US_SUBE_NID else '',
            'dato_operacion_id': documento.DO_NID_id,
            'download_url': reverse('expediente_citacion_documento_ver', args=[documento.id]),
            'etapa': PASO_CIERRE_CARGA,
        }
        for documento in documentos
    ]


def _payload_cierre_carga_despacho(citacion, datos_operacion=None):
    datos_operacion = datos_operacion or {}

    def valor_codigo(codigo):
        dato = datos_operacion.get(codigo)
        return str(dato.DO_CVALOR or '').strip() if dato else ''

    dato_sellos = datos_operacion.get(DESPACHO_CIERRE_NRO_SELLOS)

    return {
        'nro_sellos': valor_codigo(DESPACHO_CIERRE_NRO_SELLOS),
        'nro_sellos_dato_id': dato_sellos.id if dato_sellos else '',
        'temperatura': valor_codigo(DESPACHO_CIERRE_TEMPERATURA),
    }


def _validar_imagen_sello_despacho(archivo):
    extension = os.path.splitext(str(getattr(archivo, 'name', '') or ''))[1].lower()
    content_type = str(getattr(archivo, 'content_type', '') or '').lower()
    if extension not in DESPACHO_SELLO_EXTENSIONES or content_type not in DESPACHO_SELLO_MIME:
        raise ValueError('Las imagenes de sellos deben ser archivos JPG, JPEG o PNG.')
    if getattr(archivo, 'size', 0) > DESPACHO_SELLO_MAX_BYTES:
        raise ValueError('Cada imagen de sello debe pesar como maximo 10 MB.')


def _guardar_imagenes_sellos_despacho(citacion, archivos, usuario):
    documentos = []
    for archivo in archivos:
        _validar_imagen_sello_despacho(archivo)
        nombre_original = get_valid_filename(os.path.basename(archivo.name or 'imagen_sello'))
        ruta_archivo, _ = guardar_archivo_expediente_citacion(
            citacion,
            CITACION_DOCUMENTO.TIPO_IMAGEN_SELLO_DESPACHO,
            archivo,
        )
        documentos.append(CITACION_DOCUMENTO.objects.create(
            CI_NID=citacion,
            EP_NID=citacion.EP_NID,
            CD_CTIPO=CITACION_DOCUMENTO.TIPO_IMAGEN_SELLO_DESPACHO,
            CD_CRUTA_ARCHIVO=ruta_archivo,
            CD_CNOMBRE_ARCHIVO=nombre_original,
            US_SUBE_NID=usuario,
            CD_BACTIVO=True,
        ))
    return documentos


def guardar_cierre_carga_despacho(citacion, data, usuario):
    nro_sellos = str(data.get('despacho_cierre_nro_sellos') or '').strip()
    temperatura = str(data.get('despacho_cierre_temperatura') or '').strip()

    if not nro_sellos:
        return False, 'Debe ingresar Nro. Sellos.'
    if not temperatura:
        return False, 'Debe ingresar Temperatura.'
    try:
        temperatura_decimal = Decimal(temperatura.replace(',', '.'))
    except InvalidOperation:
        return False, 'La Temperatura debe ser un valor numerico valido.'
    if not temperatura_decimal.is_finite():
        return False, 'La Temperatura debe ser un valor numerico valido.'
    temperatura = str(temperatura_decimal)

    dato_sellos = guardar_dato_operacion_codigo(
        citacion,
        DESPACHO_CIERRE_NRO_SELLOS,
        nro_sellos,
        usuario,
        etiqueta='Nro. Sellos',
        etapa=citacion.ETAPA_ACTUAL
    )
    guardar_dato_operacion_codigo(
        citacion,
        DESPACHO_CIERRE_TEMPERATURA,
        temperatura,
        usuario,
        etiqueta='Temperatura',
        etapa=citacion.ETAPA_ACTUAL
    )

    return True, {
        'nro_sellos': nro_sellos,
        'temperatura': temperatura,
        'nro_sellos_dato_id': dato_sellos.id,
    }


def _leer_ultimas_cargas_despacho(citacion):
    return _leer_metadata_terramar(citacion, DESPACHO_ULTIMAS_CARGAS)


def _guardar_ultimas_cargas_despacho(citacion, usuario, data):
    valores = [str(data.get(f'carga_{indice}') or '').strip() for indice in range(1, 4)]
    if any(not valor for valor in valores):
        raise ValueError('Debe ingresar exactamente las tres últimas cargas.')
    ahora = timezone.now()
    metadata = {
        **{f'carga_{indice}': valor for indice, valor in enumerate(valores, start=1)},
        'usuario': usuario.username,
        'usuario_id': usuario.id,
        'fecha_iso': ahora.isoformat(),
    }
    return _guardar_metadata_terramar(
        citacion, usuario, DESPACHO_ULTIMAS_CARGAS, 'Tres últimas cargas', metadata,
    )


def _payload_datos_finales_despacho_sbh(citacion, datos_operacion=None):
    carga = CITACION_DESPACHO_CARGA.objects.prefetch_related(
        'acuerdos__estanques__lotes',
    ).filter(CI_NID=citacion).first()
    registros = []
    if carga:
        for acuerdo in carga.acuerdos.all():
            for estanque in acuerdo.estanques.all():
                for lote in estanque.lotes.all():
                    registros.append({
                        'numero_acuerdo': acuerdo.numero_acuerdo,
                        'item_code': estanque.item_code,
                        'item_name': estanque.item_name,
                        'warehouse_code': estanque.warehouse_code,
                        'batch_number': lote.batch_number,
                        'fecha_elaboracion': '',
                        'fecha_vencimiento': (
                            lote.fecha_vencimiento.strftime('%d/%m/%Y')
                            if lote.fecha_vencimiento else ''
                        ),
                    })
    cierre = _payload_cierre_carga_despacho(citacion, datos_operacion)
    ultimas = _leer_ultimas_cargas_despacho(citacion)
    valores = [str(ultimas.get(f'carga_{indice}') or '').strip() for indice in range(1, 4)]
    return {
        'registros': registros,
        'nro_sellos': cierre.get('nro_sellos', ''),
        'temperatura': cierre.get('temperatura', ''),
        'ultimas_cargas': valores,
        'ultimas_cargas_completas': all(valores),
        'ultimas_cargas_usuario': ultimas.get('usuario', ''),
        'ultimas_cargas_fecha_iso': ultimas.get('fecha_iso', ''),
    }


def _payload_drafts_sap_despacho_operacionales(citacion):
    documentacion = estado_documentos_definitivos(citacion)
    documentos_por_acuerdo = {
        documento['acuerdo_id']: documento
        for documento in documentacion['documentos']
    }
    carga = CITACION_DESPACHO_CARGA.objects.prefetch_related(
        'acuerdos__draft',
    ).filter(CI_NID=citacion).first()
    if not carga:
        return {
            'aplicable': False,
            'drafts': [],
            'completos': False,
            'actualizacion_habilitada': False,
            'mensaje_actualizacion': '',
            'documentacion_completa': False,
            'estado_documentacion': 'DOCUMENTACIÓN SAP INCOMPLETA',
            'todos_actualizados': False,
            'verificacion_documentos_habilitada': False,
        }

    drafts = []
    for acuerdo in carga.acuerdos.all():
        try:
            draft = acuerdo.draft
        except CITACION_DESPACHO_DRAFT_SAP.DoesNotExist:
            draft = None
        respuesta_draft = (
            draft.respuesta
            if draft and isinstance(draft.respuesta, dict)
            else {}
        )
        actualizacion_peso = respuesta_draft.get('actualizacion_peso_real')
        actualizado_correctamente = bool(
            isinstance(actualizacion_peso, dict)
            and actualizacion_peso.get('success') is True
        )
        verificacion_sap = documentos_por_acuerdo.get(acuerdo.id, {
            'estado': 'PENDIENTE',
            'cerrado': False,
            'resultado_count': None,
            'verificado_en': '',
            'error': '',
            'valido': False,
        })
        drafts.append({
            'acuerdo_id': acuerdo.id,
            'sap_abs_id': acuerdo.sap_abs_id,
            'numero_acuerdo': acuerdo.numero_acuerdo,
            'estado': draft.estado if draft else 'PENDIENTE',
            'docentry': draft.docentry if draft else '',
            'docnum': draft.docnum if draft else '',
            'error': draft.error if draft else '',
            'intentos': draft.intentos if draft else 0,
            'actualizado': (
                timezone.localtime(draft.actualizado).strftime('%d/%m/%Y %H:%M')
                if draft and draft.actualizado else ''
            ),
            'actualizacion_peso_real_confirmada': actualizado_correctamente,
            'verificacion_sap': verificacion_sap,
        })

    completos = bool(drafts) and all(
        item['estado'] in {'CREADO', 'ACTUALIZADO'} and item['docentry']
        for item in drafts
    )
    todos_actualizados = bool(drafts) and all(
        item['actualizacion_peso_real_confirmada']
        for item in drafts
    )
    verificacion_habilitada = bool(
        completos
        and todos_actualizados
        and not documentacion['completo']
    )
    return {
        'aplicable': True,
        'drafts': drafts,
        'completos': completos,
        'actualizacion_habilitada': completos,
        'mensaje_actualizacion': (
            '' if completos else
            'La actualizacion requiere que todos los Drafts SAP esten creados y tengan DocEntry.'
        ),
        'documentacion_completa': documentacion['completo'],
        'estado_documentacion': documentacion['estado'],
        'todos_actualizados': todos_actualizados,
        'verificacion_documentos_habilitada': verificacion_habilitada,
    }


def guardar_datos_asistente_cd_despacho(citacion, data, usuario):
    es_despacho_sbh = es_citacion_despacho_sbh(citacion)
    detalle_despacho = None
    if es_despacho_sbh:
        try:
            detalle_despacho = citacion.detalle_despacho
        except CITACION_DESPACHO_DETALLE.DoesNotExist:
            return False, 'No existe el detalle de despacho definido en la planificacion.'

        cantidad_intentada = detalle_despacho.CDD_NCANTIDAD_INTENTADA_DESPACHAR
        if cantidad_intentada is None or cantidad_intentada <= 0:
            return False, 'La planificacion no tiene una cantidad intentada a despachar valida.'

    valores = {}
    for key, (codigo, etiqueta) in ACD_CAMPOS_DESPACHO.items():
        if es_despacho_sbh and key == 'peso_informado':
            continue
        valor = str(data.get(key) or '').strip()
        if not valor:
            return False, f'Debe ingresar {etiqueta}.'
        if key == 'peso_informado':
            try:
                peso = Decimal(valor.replace(',', '.'))
            except (InvalidOperation, ValueError):
                return False, 'Peso informado debe ser numerico.'
            if peso <= 0:
                return False, 'Peso informado debe ser mayor a 0.'
            valor = format(peso, 'f')
        valores[key] = valor

    lote_quantity = str(data.get('lote_quantity') or '').strip()
    try:
        stock_lote = Decimal(lote_quantity.replace(',', '.'))
    except (InvalidOperation, ValueError):
        return False, 'Debe seleccionar un lote/batch SAP con stock disponible.'
    if stock_lote <= 0:
        return False, 'Debe seleccionar un lote/batch SAP con stock disponible.'
    if str(data.get('lote_status') or '').strip() != '0':
        return False, 'Debe seleccionar un lote/batch SAP liberado.'

    for key, valor in valores.items():
        codigo, etiqueta = ACD_CAMPOS_DESPACHO[key]
        guardar_dato_operacion_codigo(
            citacion,
            codigo,
            valor,
            usuario,
            etiqueta=etiqueta,
            etapa=citacion.ETAPA_ACTUAL
        )

    for key, (codigo, etiqueta) in ACD_CAMPOS_LOTE_SAP_DESPACHO.items():
        valor = str(data.get(key) or '').strip()
        if valor:
            guardar_dato_operacion_codigo(
                citacion,
                codigo,
                valor,
                usuario,
                etiqueta=etiqueta,
                etapa=citacion.ETAPA_ACTUAL
            )

    detalle = obtener_detalle_operacional_citacion(citacion)
    if detalle and valores.get('codigo_sap') and detalle.CDO_CCODIGO_SAP != valores['codigo_sap']:
        detalle.CDO_CCODIGO_SAP = valores['codigo_sap']
        detalle.save(update_fields=['CDO_CCODIGO_SAP'])

    if not es_despacho_sbh:
        detalle_despacho, _ = CITACION_DESPACHO_DETALLE.objects.get_or_create(
            CI_NID=citacion,
            defaults={
                'EP_NID': citacion.EP_NID,
                'US_NID': usuario,
            }
        )
        detalle_despacho.CDD_NPESO_INFORMADO = Decimal(valores['peso_informado'])
        detalle_despacho.save(update_fields=['CDD_NPESO_INFORMADO', 'CDD_FFECHAACTUALIZACION'])

    return True, ''


def normalizar_texto_reserva(valor):
    return ' '.join(str(valor or '').strip().upper().split())


def obtener_reserva_estanque_ocupada(citacion, almacen, estanque, excluir_citacion=True):
    queryset = ESTANQUE_RESERVA.objects.select_related('CI_NID').filter(
        EP_NID=citacion.EP_NID,
        ER_CALMACEN=normalizar_texto_reserva(almacen),
        ER_CESTANQUE=normalizar_texto_reserva(estanque),
        ER_CESTADO=ESTANQUE_RESERVA.ESTADO_OCUPADO
    )

    if excluir_citacion:
        queryset = queryset.exclude(CI_NID=citacion)

    return queryset.order_by('-ER_FFECHA_ASIGNACION').first()


def obtener_reserva_ocupada_citacion(citacion):
    return ESTANQUE_RESERVA.objects.filter(
        CI_NID=citacion,
        ER_CESTADO=ESTANQUE_RESERVA.ESTADO_OCUPADO
    ).order_by('-ER_FFECHA_ASIGNACION').first()


def liberar_reservas_estanque_citacion(citacion, usuario=None, observacion=''):
    reservas = ESTANQUE_RESERVA.objects.filter(
        CI_NID=citacion,
        ER_CESTADO=ESTANQUE_RESERVA.ESTADO_OCUPADO
    )
    ahora = timezone.now()
    total = reservas.update(
        ER_CESTADO=ESTANQUE_RESERVA.ESTADO_LIBERADO,
        ER_FFECHA_LIBERACION=ahora,
        US_LIBERA_NID=usuario,
        ER_COBSERVACION=observacion or 'Reserva liberada'
    )
    return total


def sincronizar_liberacion_estanques_pesaje_salida(empresa):
    citaciones_con_pesaje_salida = OPERACION_PLANTA_LOG.objects.filter(
        EP_NID=empresa,
        OPL_CPASO='Pesaje Salida',
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).values_list('CI_NID_id', flat=True)
    reservas = ESTANQUE_RESERVA.objects.filter(
        EP_NID=empresa,
        ER_CESTADO=ESTANQUE_RESERVA.ESTADO_OCUPADO,
        CI_NID_id__in=citaciones_con_pesaje_salida
    )
    ahora = timezone.now()
    return reservas.update(
        ER_CESTADO=ESTANQUE_RESERVA.ESTADO_LIBERADO,
        ER_FFECHA_LIBERACION=ahora,
        ER_COBSERVACION='Reserva liberada automaticamente al completar Pesaje Salida'
    )


def descripcion_reserva_estanque_ocupada(reserva):
    if not reserva:
        return ''
    citacion_id = reserva.CI_NID_id or ''
    patente = reserva.ER_CPATENTE or 'No registrada'
    etapa = ''
    try:
        etapa = obtener_etapa_actual_operacional_citacion(reserva.CI_NID) if reserva.CI_NID else ''
    except Exception:
        etapa = ''
    texto = f'Tomado por citacion {citacion_id} / patente {patente}'
    if etapa:
        texto = f'{texto} / etapa {etapa}'
    return texto


def reservar_estanque_citacion(citacion, almacen, estanque, usuario, patente=None):
    almacen_normalizado = normalizar_texto_reserva(almacen)
    estanque_normalizado = normalizar_texto_reserva(estanque)
    reserva_ocupada = obtener_reserva_estanque_ocupada(
        citacion,
        almacen_normalizado,
        estanque_normalizado,
        excluir_citacion=True
    )

    if reserva_ocupada:
        return None, reserva_ocupada

    reserva_citacion = obtener_reserva_ocupada_citacion(citacion)
    defaults = {
        'US_NID': usuario,
        'EP_NID': citacion.EP_NID,
        'PL_NID': citacion.PL_NID,
        'CI_NID': citacion,
        'ER_CALMACEN': almacen_normalizado,
        'ER_CESTANQUE': estanque_normalizado,
        'ER_CPATENTE': patente or '',
        'ER_CESTADO': ESTANQUE_RESERVA.ESTADO_OCUPADO,
        'ER_FFECHA_ASIGNACION': timezone.now(),
        'ER_FFECHA_LIBERACION': None,
        'US_LIBERA_NID': None,
        'ER_COBSERVACION': 'Reserva creada por Asistente_C_D',
    }

    if reserva_citacion:
        for campo, valor in defaults.items():
            setattr(reserva_citacion, campo, valor)
        reserva_citacion.save()
        return reserva_citacion, None

    return ESTANQUE_RESERVA.objects.create(**defaults), None


def construir_opciones_estanque_reserva(citacion, almacen, opciones_estanque, estanque_actual=''):
    opciones = []
    almacen_normalizado = normalizar_texto_reserva(almacen)
    sincronizar_liberacion_estanques_pesaje_salida(citacion.EP_NID)
    reservas = ESTANQUE_RESERVA.objects.select_related('CI_NID').filter(
        EP_NID=citacion.EP_NID,
        ER_CALMACEN=almacen_normalizado,
        ER_CESTADO=ESTANQUE_RESERVA.ESTADO_OCUPADO,
        ER_CESTANQUE__in=[normalizar_texto_reserva(estanque) for estanque in opciones_estanque]
    )
    reservas_por_estanque = {
        normalizar_texto_reserva(reserva.ER_CESTANQUE): reserva
        for reserva in reservas
    }
    estanque_actual_normalizado = normalizar_texto_reserva(estanque_actual)

    for estanque in opciones_estanque:
        estanque_normalizado = normalizar_texto_reserva(estanque)
        reserva = reservas_por_estanque.get(estanque_normalizado)
        ocupado_por_otra = bool(reserva and reserva.CI_NID_id != citacion.id)
        texto = estanque
        etapa_ocupante = ''
        if ocupado_por_otra:
            etapa_ocupante = obtener_etapa_actual_operacional_citacion(reserva.CI_NID) if reserva.CI_NID else ''
            texto = f'{estanque} - {descripcion_reserva_estanque_ocupada(reserva)}'

        opciones.append({
            'valor': estanque,
            'texto': texto,
            'disponible': True,
            'ocupado': ocupado_por_otra,
            'patente_ocupante': reserva.ER_CPATENTE if ocupado_por_otra else '',
            'citacion_ocupante': reserva.CI_NID_id if ocupado_por_otra else None,
            'etapa_ocupante': etapa_ocupante,
            'seleccionado': estanque_normalizado == estanque_actual_normalizado,
        })

    return opciones


def obtener_comentario_json_citacion(citacion):
    if not citacion.CI_CCOMENTARIO:
        return {}
    try:
        data = json.loads(citacion.CI_CCOMENTARIO)
        return data if isinstance(data, dict) else {}
    except (TypeError, ValueError):
        return {}


def decimal_or_none(value):
    if value in [None, '']:
        return None
    try:
        return Decimal(str(value).replace(',', '.'))
    except (InvalidOperation, ValueError):
        return None


def normalizar_texto_busqueda_socio(valor):
    texto = str(valor or '').strip()
    if not texto:
        return ''
    return texto.split('(', 1)[0].strip()


def resolver_socio_negocio_planificacion(empresa_id, tipo, valor=None, codigo=None, nombre=None):
    candidatos_codigo = []
    for candidato in [codigo, valor]:
        candidato = str(candidato or '').strip()
        if candidato and candidato not in candidatos_codigo:
            candidatos_codigo.append(candidato)

    base = SOCIONEGOCIO.objects.filter(
        EP_NID_id=empresa_id,
        SN_CTIPO=tipo,
        SN_BHABILITADO=True
    )

    for candidato in candidatos_codigo:
        socio = base.filter(SN_CCODIGO_SAP__iexact=candidato).first()
        if socio:
            return socio

    valor = str(valor or '').strip()
    if valor.isdigit():
        socio = base.filter(id=int(valor)).first()
        if socio:
            return socio

    for candidato in [nombre, valor]:
        nombre_limpio = normalizar_texto_busqueda_socio(candidato)
        if not nombre_limpio:
            continue
        socio = base.filter(SN_CRAZONSOCIAL__iexact=nombre_limpio).first()
        if socio:
            return socio

    return None


def normalizar_proveedor_recepcion_sbh_etapa_0(item, empresa_id):
    """Keep the selected supplier's code and name together in a new SBH receipt."""
    seleccionado = str(item.get('proveedor') or '').strip()
    if seleccionado.startswith('maestro:'):
        socio_id = seleccionado.partition(':')[2]
        socio = SOCIONEGOCIO.objects.filter(
            pk=socio_id if socio_id.isdigit() else None,
            EP_NID_id=empresa_id,
            SN_CTIPO='S',
            SN_BHABILITADO=True,
        ).first()
        if not socio:
            raise ValueError('El proveedor seleccionado no pertenece al maestro habilitado de SBH.')
        codigo = str(socio.SN_CCODIGO_SAP or '').strip()
        nombre = socio.SN_CRAZONSOCIAL
        item['proveedor'] = codigo or str(socio.id)
    elif seleccionado.startswith('manual:'):
        nombre = seleccionado.partition(':')[2].strip()
        if not nombre or len(nombre) > 128:
            raise ValueError('Debe ingresar un nombre de proveedor válido (máximo 128 caracteres).')
        codigo = ''
        item['proveedor'] = ''
    elif seleccionado.startswith('sap:'):
        codigo = seleccionado.partition(':')[2].strip()
        nombre = str(item.get('proveedor_nombre') or '').strip()
        if not codigo or not nombre or len(codigo) > 128 or len(nombre) > 256:
            raise ValueError('El proveedor sugerido por SAP no tiene código y nombre válidos.')
        item['proveedor'] = codigo
    else:
        # Legacy clients send the CardCode directly; it remains the source for
        # both code snapshots even if hidden inputs contain a previous choice.
        if seleccionado:
            item['proveedor_codigo'] = seleccionado
            item['codigo_proveedor_sap'] = seleccionado
        return False

    item['proveedor_nombre'] = nombre
    item['proveedor_sap'] = nombre
    item['proveedor_codigo'] = codigo
    item['codigo_proveedor_sap'] = codigo
    return seleccionado.startswith('manual:')


def observacion_con_metadata_sap(data):
    observacion = str(data.get('observacion') or '').strip()
    if str(data.get('tipo_operacion') or '').upper() == 'DESPACHO':
        try:
            observacion_json = json.loads(observacion)
            if isinstance(observacion_json, dict):
                return ''
        except (TypeError, ValueError):
            pass
    return observacion


def observacion_planificacion_visible(valor):
    texto = str(valor or '').strip()
    if not texto:
        return ''

    etiquetas_automaticas = {
        'CONTRATO SAP',
        'CODIGO PROVEEDOR SAP',
        'CODIGO PROVEEDOR',
    }
    partes_visibles = []
    for parte in texto.split('|'):
        parte = parte.strip()
        etiqueta = parte.split(':', 1)[0].strip().upper()
        if etiqueta in etiquetas_automaticas:
            continue
        partes_visibles.append(parte)
    return ' | '.join(partes_visibles)


def obtener_contrato_sap_visible_por_pedido(pedido):
    pedido = str(pedido or '').strip()
    if not pedido:
        return ''

    try:
        resultado = consultar_detalle_pedido_sap(pedido)
    except Exception:
        return ''

    if not resultado.get('ok'):
        return ''

    for linea in resultado.get('lineas') or []:
        contrato = str(linea.get('contrato_sap') or '').strip()
        if contrato:
            return contrato
    return 'Sin contrato'


def datos_operacionales_resumen_visible(detalle_operacional):
    resumen = {}
    contrato_sap = obtener_contrato_sap_visible_por_pedido(detalle_operacional.get('pedido'))

    for llave, valor in detalle_operacional.items():
        if llave == 'sap_opor_id':
            resumen['contrato_sap'] = contrato_sap
            continue
        if llave == 'observacion':
            resumen[llave] = observacion_planificacion_visible(valor)
            continue
        resumen[llave] = valor

    return resumen


def valor_dato_operacion(datos_operacion, codigo):
    dato = datos_operacion.get(codigo)
    return dato.DO_CVALOR if dato else ''


def es_recepcion_sbh_snapshot(citacion):
    tipo_citacion = str(
        citacion.CI_CTIPO
        or (citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '')
        or ''
    ).strip().upper()
    return citacion.EP_NID_id == 2 and tipo_citacion == CIT_RECEPCION


def valor_snapshot_operacional(valor):
    if valor is None:
        return 'Sin información'
    texto = str(valor).strip()
    return texto if texto else 'Sin información'


def fecha_snapshot_operacional(valor):
    if valor is None or str(valor).strip() == '':
        return 'Sin información'
    if hasattr(valor, 'strftime'):
        return valor.strftime('%d/%m/%Y')

    texto = str(valor).strip()
    fecha = None
    try:
        fecha = parse_datetime(texto)
    except (TypeError, ValueError):
        fecha = None
    if fecha is None:
        try:
            fecha = parse_date(texto[:10])
        except (TypeError, ValueError):
            fecha = None
    return fecha.strftime('%d/%m/%Y') if fecha else texto


def datos_snapshot_recepcion_sbh_presentacion(citacion, detalle_operacional, datos_operacion=None):
    if not es_recepcion_sbh_snapshot(citacion):
        return None

    datos_operacion = datos_operacion or {}
    proveedor_citacion = (
        citacion.PRO_NID.SN_CRAZONSOCIAL
        if getattr(citacion, 'PRO_NID', None)
        else ''
    )
    proveedor_sap = (
        detalle_operacional.get('proveedor_sap')
        or valor_dato_operacion(datos_operacion, 'PLAN_PROVEEDOR_SAP')
        or proveedor_citacion
    )
    codigo_proveedor = (
        detalle_operacional.get('proveedor_codigo')
        or valor_dato_operacion(datos_operacion, 'PLAN_CODIGO_PROVEEDOR_SAP')
    )

    return {
        'Origen': valor_snapshot_operacional(detalle_operacional.get('origen')),
        'Tipo recepción': valor_snapshot_operacional(
            etiqueta_tipo_recepcion_sbh(detalle_operacional.get('tipo_origen_recepcion'))
        ),
        'Inf 24 hrs': valor_snapshot_operacional(detalle_operacional.get('inf_24hrs')),
        'Código SAP': valor_snapshot_operacional(detalle_operacional.get('codigo')),
        'Insumo': valor_snapshot_operacional(detalle_operacional.get('insumo')),
        'Pedido SAP': valor_snapshot_operacional(detalle_operacional.get('pedido')),
        'Proveedor SAP': valor_snapshot_operacional(proveedor_sap),
        'Código proveedor SAP': valor_snapshot_operacional(codigo_proveedor),
        'Contrato SAP': valor_snapshot_operacional(valor_dato_operacion(datos_operacion, 'PLAN_CONTRATO_SAP')),
        'Cantidad disponible': valor_snapshot_operacional(detalle_operacional.get('cantidad_disponible')),
        'DocEntry SAP': valor_snapshot_operacional(detalle_operacional.get('docentry') or detalle_operacional.get('sap_opor_id')),
        'Guía': valor_snapshot_operacional(detalle_operacional.get('guia')),
        'CDA': valor_snapshot_operacional(detalle_operacional.get('cda')),
        'DI': valor_snapshot_operacional(detalle_operacional.get('di')),
        'BL': valor_snapshot_operacional(detalle_operacional.get('bl')),
        'Nave / Naviera': valor_snapshot_operacional(detalle_operacional.get('nave_naviera')),
        'Booking': valor_snapshot_operacional(detalle_operacional.get('booking')),
        'Contenedor': valor_snapshot_operacional(detalle_operacional.get('contenedor')),
        'Fecha producción': fecha_snapshot_operacional(detalle_operacional.get('fecha_produccion')),
        'Fecha vencimiento': fecha_snapshot_operacional(detalle_operacional.get('fecha_vencimiento')),
        'SUI': valor_snapshot_operacional(detalle_operacional.get('sui')),
        'Almacén destino': valor_snapshot_operacional(detalle_operacional.get('almacen_destino')),
        'Estanque destino': valor_snapshot_operacional(detalle_operacional.get('estanque_destino')),
        'Observación planificación': valor_snapshot_operacional(observacion_planificacion_visible(detalle_operacional.get('observacion'))),
    }

def datos_operacionales_resumen_planificacion(citacion, detalle_operacional, datos_operacion=None):
    datos_operacion = datos_operacion or {}
    snapshot_recepcion_sbh = datos_snapshot_recepcion_sbh_presentacion(
        citacion,
        detalle_operacional,
        datos_operacion,
    )
    if snapshot_recepcion_sbh is not None:
        return [
            {'label': etiqueta, 'value': valor}
            for etiqueta, valor in snapshot_recepcion_sbh.items()
        ]
    contrato_sap = (
        valor_dato_operacion(datos_operacion, 'PLAN_CONTRATO_SAP')
        or obtener_contrato_sap_visible_por_pedido(detalle_operacional.get('pedido'))
    )
    proveedor_sap = (
        detalle_operacional.get('proveedor_sap')
        or valor_dato_operacion(datos_operacion, 'PLAN_PROVEEDOR_SAP')
        or (citacion.PRO_NID.SN_CRAZONSOCIAL if citacion.PRO_NID else '')
    )
    codigo_proveedor = (
        valor_dato_operacion(datos_operacion, 'PLAN_CODIGO_PROVEEDOR_SAP')
        or detalle_operacional.get('proveedor_codigo')
    )
    almacen_estanque = (
        detalle_operacional.get('almacen_destino')
        or detalle_operacional.get('estanque_destino')
    )

    return [
        {'label': 'Origen', 'value': detalle_operacional.get('origen')},
        {'label': 'Inf 24 hrs', 'value': detalle_operacional.get('inf_24hrs')},
        {'label': 'Codigo SAP', 'value': detalle_operacional.get('codigo')},
        {'label': 'Insumo SAP', 'value': detalle_operacional.get('insumo')},
        {'label': 'Pedido SAP', 'value': detalle_operacional.get('pedido')},
        {'label': 'Proveedor SAP', 'value': proveedor_sap},
        {'label': 'Codigo proveedor SAP', 'value': codigo_proveedor},
        {'label': 'Contrato SAP', 'value': contrato_sap},
        {'label': 'Cantidad disponible', 'value': detalle_operacional.get('cantidad_disponible')},
        {'label': 'DocEntry SAP', 'value': detalle_operacional.get('docentry') or detalle_operacional.get('sap_opor_id')},
        {'label': 'Almacen/estanque destino', 'value': almacen_estanque},
        {'label': 'Observacion planificacion', 'value': observacion_planificacion_visible(detalle_operacional.get('observacion'))},
    ]


def guardar_detalle_operacional_citacion(citacion, data, usuario=None, origen_default='planificacion'):
    proveedor_sap = (
        data.get('proveedor_sap')
        or data.get('proveedor_nombre')
        or data.get('cardname')
        or ''
    )
    es_recepcion_sbh = citacion.EP_NID_id == 2 and str(citacion.CI_CTIPO or '').upper() == CIT_RECEPCION
    if es_citacion_despacho(citacion):
        contenedor = ''
        bl = ''
    elif es_recepcion_sbh:
        contenedor = data.get('contenedor') or ''
        bl = data.get('bl') or ''
    else:
        contenedor = data.get('contenedor') or data.get('bl') or data.get('bl_contenedor') or ''
        bl = data.get('bl') or ''
    detalle, _ = CITACION_DETALLE_OPERACIONAL.objects.update_or_create(
        CI_NID=citacion,
        defaults={
            'EP_NID': citacion.EP_NID,
            'US_NID': usuario or citacion.US_NID,
            'CDO_CORIGEN': data.get('origen') or origen_default,
            'CDO_CINF_24HRS': data.get('inf_24hrs') or '',
            'CDO_CCODIGO_SAP': data.get('codigo') or data.get('codigo_sap') or '',
            'CDO_CINSUMO': data.get('insumo') or '',
            'CDO_CPEDIDO_SAP': data.get('pedido') or data.get('pedido_sap') or '',
            'CDO_CSAP_OPOR_ID': data.get('sap_opor_id') or '',
            'CDO_CPROVEEDOR_CODIGO': data.get('codigo_proveedor_sap') or data.get('proveedor_codigo') or '',
            'CDO_CBL_CONTENEDOR': contenedor,
            'CDO_CBL': bl,
            'CDO_CGUIA': data.get('guia') or '',
            'CDO_CFECHA_PRODUCCION': data.get('fecha_produccion') or '',
            'CDO_CFECHA_VENCIMIENTO': data.get('fecha_vencimiento') or '',
            'CDO_CCDA': data.get('cda') or '',
            'CDO_CDI': data.get('di') or '',
            'CDO_CSUI': data.get('sui') or '',
            'CDO_CNAVE_NAVIERA': data.get('nave_naviera') or '',
            'CDO_CBOOKING': data.get('booking') or '',
            'CDO_NCANTIDAD_DISPONIBLE': decimal_or_none(data.get('cantidad_disponible')),
            'CDO_CDOCENTRY': data.get('docentry') or '',
            'CDO_CPRODUCTOR': proveedor_sap,
            'CDO_CALMACEN_DESTINO': data.get('almacen_destino') or data.get('estanque_destino') or '',
            'CDO_CESTANQUE_ORIGEN': data.get('estanque_origen') or '',
            'CDO_CCODIGO_PROPIETARIO': data.get('codigo_propietario'),
            'CDO_CPROPIEDAD_PRODUCTO': data.get('propiedad_producto'),
            'CDO_CUNIDAD_INVENTARIO': data.get('unidad_inventario_snapshot'),
            'CDO_NCANTIDAD_CAMION': decimal_or_none(data.get('cantidad_camion')),
            'CDO_NCANTIDAD_A_MOVER': decimal_or_none(data.get('cantidad_a_mover')),
            'CDO_CESTANQUE_DESTINO': data.get('estanque_destino') or '',
            'CDO_COBSERVACION': observacion_con_metadata_sap(data),
        }
    )
    if es_recepcion_sbh and 'tipo_origen_recepcion' in data:
        detalle.CDO_CTIPO_RECEPCION = str(
            data.get('tipo_origen_recepcion') or ''
        ).strip().upper()
        detalle.save(update_fields=['CDO_CTIPO_RECEPCION'])
    return detalle


def guardar_detalle_recepcion_terramar_citacion(citacion, data, usuario=None):
    transporte_terramar = str(data.get('transporte_a_cargo') or '') == 'Terramar'
    transportista_id = str(data.get('empresa_transporte_id') or '').strip()
    conductor_id = str(data.get('conductor_id') or '').strip()
    return CITACION_RECEPCION_TERRAMAR_DETALLE.objects.update_or_create(
        CI_NID=citacion,
        defaults={
            'EP_NID': citacion.EP_NID,
            'US_NID': usuario or citacion.US_NID,
            'RTD_CCONTENEDOR_CRT': str(data.get('contenedor_crt') or '').strip(),
            'RTD_CBODEGA': str(data.get('bodega') or '').strip(),
            'RTD_CTRANSPORTE_A_CARGO': str(data.get('transporte_a_cargo') or '').strip(),
            'SN_NID_TRANSPORTISTA_id': int(transportista_id) if transporte_terramar and transportista_id.isdigit() else None,
            'RTD_CEMPRESA_TRANSPORTE': str(data.get('empresa_transporte') or '').strip(),
            'CON_NID_id': int(conductor_id) if transporte_terramar and conductor_id.isdigit() else None,
            'RTD_CCONDUCTOR': str(data.get('conductor') or '').strip(),
            'RTD_CCODIGO_PAIS_TELEFONO': str(data.get('telefono_codigo_pais') or '').strip(),
            'RTD_CTELEFONO_CONDUCTOR': str(data.get('telefono_conductor') or '').strip(),
            'RTD_CPATENTE': str(data.get('patente') or '').strip(),
        }
    )

def obtener_detalle_operacional_citacion(citacion):
    detalle = getattr(citacion, 'detalle_operacional', None)
    if detalle:
        return detalle

    data = obtener_comentario_json_citacion(citacion)
    if not data:
        return None

    return guardar_detalle_operacional_citacion(
        citacion,
        data,
        usuario=citacion.US_NID,
        origen_default=data.get('origen') or 'planificacion'
    )


def detalle_operacional_dict(citacion):
    detalle = obtener_detalle_operacional_citacion(citacion)
    if not detalle:
        return {}
    contenedor = '' if es_citacion_despacho(citacion) else detalle.CDO_CBL_CONTENEDOR
    bl = '' if es_citacion_despacho(citacion) else detalle.CDO_CBL
    resultado = {
        'origen': detalle.CDO_CORIGEN,
        'inf_24hrs': detalle.CDO_CINF_24HRS,
        'codigo': detalle.CDO_CCODIGO_SAP,
        'insumo': detalle.CDO_CINSUMO,
        'pedido': detalle.CDO_CPEDIDO_SAP,
        'sap_opor_id': detalle.CDO_CSAP_OPOR_ID,
        'proveedor_codigo': detalle.CDO_CPROVEEDOR_CODIGO,
        'proveedor_sap': detalle.CDO_CPRODUCTOR,
        'tipo_origen_recepcion': detalle.CDO_CTIPO_RECEPCION,
        'contenedor': contenedor,
        'bl': bl,
        'bl_contenedor': contenedor,
        'guia': detalle.CDO_CGUIA,
        'fecha_produccion': detalle.CDO_CFECHA_PRODUCCION,
        'fecha_vencimiento': detalle.CDO_CFECHA_VENCIMIENTO,
        'cda': detalle.CDO_CCDA,
        'di': detalle.CDO_CDI,
        'sui': detalle.CDO_CSUI,
        'nave_naviera': detalle.CDO_CNAVE_NAVIERA,
        'booking': detalle.CDO_CBOOKING,
        'cantidad_disponible': detalle.CDO_NCANTIDAD_DISPONIBLE,
        'docentry': detalle.CDO_CDOCENTRY,
        'almacen_destino': detalle.CDO_CALMACEN_DESTINO,
        'estanque_destino': detalle.CDO_CESTANQUE_DESTINO,
        'observacion': detalle.CDO_COBSERVACION,
    }
    if es_flujo_recepcion_transferencia_sbh(citacion):
        resultado['movimientos_transferencia'] = detalles_transferencia_dict(citacion)
    return resultado


def detalles_transferencia_dict(citacion):
    return [
        {
            'estanque_origen': detalle.CTD_CESTANQUE_ORIGEN,
            'codigo_sap': detalle.CTD_CCODIGO_SAP,
            'insumo': detalle.CTD_CINSUMO,
            'codigo_propietario': detalle.CTD_CCODIGO_PROPIETARIO,
            'propiedad_producto': detalle.CTD_CPROPIEDAD_PRODUCTO,
            'stock_disponible_snapshot': detalle.CTD_NSTOCK_DISPONIBLE,
            'unidad_inventario_snapshot': detalle.CTD_CUNIDAD_INVENTARIO,
            'cantidad_a_mover': detalle.CTD_NCANTIDAD_A_MOVER,
            'orden': detalle.CTD_NORDEN,
        }
        for detalle in CITACION_TRANSFERENCIA_DETALLE.objects.filter(
            CI_NID=citacion,
            EP_NID=citacion.EP_NID,
        ).order_by('CTD_NORDEN', 'id')
    ]


def guardar_detalles_transferencia_citacion(citacion, movimientos, usuario=None):
    CITACION_TRANSFERENCIA_DETALLE.objects.filter(CI_NID=citacion).delete()
    CITACION_TRANSFERENCIA_DETALLE.objects.bulk_create([
        CITACION_TRANSFERENCIA_DETALLE(
            CI_NID=citacion,
            EP_NID=citacion.EP_NID,
            US_NID=usuario or citacion.US_NID,
            CTD_CESTANQUE_ORIGEN=movimiento['estanque_origen'],
            CTD_CCODIGO_SAP=movimiento['codigo_sap'],
            CTD_CINSUMO=movimiento['insumo'],
            CTD_CCODIGO_PROPIETARIO=movimiento.get('codigo_propietario') or '',
            CTD_CPROPIEDAD_PRODUCTO=movimiento.get('propiedad_producto') or '',
            CTD_NSTOCK_DISPONIBLE=movimiento['stock_disponible_snapshot'],
            CTD_CUNIDAD_INVENTARIO=movimiento.get('unidad_inventario_snapshot') or '',
            CTD_NCANTIDAD_A_MOVER=movimiento['cantidad_a_mover'],
            CTD_NORDEN=movimiento.get('orden') or orden,
        )
        for orden, movimiento in enumerate(movimientos, start=1)
    ])


def texto_o_primero(*valores):
    for valor in valores:
        if valor not in [None, '']:
            texto = str(valor).strip()
            if texto:
                return texto
    return ''


def decimal_o_primero(*valores):
    for valor in valores:
        decimal = decimal_or_none(valor)
        if decimal is not None:
            return decimal
    return None


def parsear_json_despacho_legacy(*valores):
    return sap_despacho_parsear_json_legacy(*valores)


