def obtener_clientes_aceite(empresa_id):
    query = '''
        SELECT
            "SCA_CARDCODE",
            "SCA_CARDNAME"
        FROM "SAP_CLIENTES_ACEITE"
        WHERE "EP_NID_id" = %s
          AND "SCA_BHABILITADO" = true
        ORDER BY "SCA_CARDNAME"
    '''

    with connection.cursor() as cursor:
        cursor.execute(query, [empresa_id])
        rows = cursor.fetchall()

    clientes = []

    for row in rows:
        clientes.append({
            'SOP_CARDCODE': row[0],
            'SOP_CARDNAME': row[1],
        })

    return clientes


