def normalizar_nombre_perfil(valor):
    texto = str(valor or '').strip().upper()
    texto = unicodedata.normalize('NFKD', texto)
    texto = ''.join(caracter for caracter in texto if not unicodedata.combining(caracter))
    return ' '.join(texto.replace('_', ' ').replace('-', ' ').split())


def expandir_aliases_perfiles_operacion(perfiles):
    perfiles_expandidos = {normalizar_nombre_perfil(perfil) for perfil in perfiles if perfil}
    if perfiles_expandidos & {'ASISTENTE DE RECEPCION', 'ASISTENTE RECEPCION', 'AR'}:
        perfiles_expandidos.update({'ASISTENTE DE RECEPCION', 'ASISTENTE RECEPCION', 'AR'})
    if perfiles_expandidos & {'ASISTENTE C D', 'ASISTENTE CD'}:
        perfiles_expandidos.update({'ASISTENTE C D', 'ASISTENTE CD'})
    if perfiles_expandidos & {'GUARDIA PORTERIA'}:
        perfiles_expandidos.add('GUARDIA PORTERIA')
    if perfiles_expandidos & {'ASISTENTE DESPACHO'}:
        perfiles_expandidos.add('ASISTENTE DESPACHO')
    return perfiles_expandidos


def usuario_es_operador_romana(user):
    username_normalizado = normalizar_nombre_perfil(getattr(user, 'username', ''))
    if username_normalizado == 'OPERADOR ROMANA' or username_normalizado.startswith('OPERADOR ROMANA'):
        return True

    perfiles_usuario = PERFIL_USUARIO.objects.select_related('PR_NID').filter(
        US_NID=user.id,
        PE_BHABILITADO=True,
        PR_NID__PR_BHABILITADO=True
    )

    for perfil_usuario in perfiles_usuario:
        nombre = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CNOMBRE)
        codigo = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CCODIGO)
        if nombre == 'OPERADOR ROMANA' or codigo == 'OPERADOR ROMANA':
            return True

    return False


def usuario_es_ingreso_camion(user):
    if getattr(user, 'is_superuser', False):
        return False

    username_normalizado = normalizar_nombre_perfil(getattr(user, 'username', ''))

    if username_normalizado in PERFILES_INGRESO_CAMION:
        return True

    if username_normalizado in USUARIOS_ASISTENTE_CD:
        return True

    if username_normalizado in USUARIOS_GUARDIA_PORTERIA:
        return True

    perfiles_usuario = PERFIL_USUARIO.objects.select_related('PR_NID').filter(
        US_NID=user.id,
        PE_BHABILITADO=True,
        PR_NID__PR_BHABILITADO=True
    )

    for perfil_usuario in perfiles_usuario:
        nombre = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CNOMBRE)
        codigo = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CCODIGO)

        if nombre in PERFILES_INGRESO_CAMION or codigo in PERFILES_INGRESO_CAMION:
            return True

    return False


