def usuario_es_asistente_recepcion(user):
    """Compatibilidad interna: la autorización es siempre RBAC canónico."""
    return usuario_tiene_perfil_asistente_recepcion(user)


def usuario_tiene_perfil_asistente_recepcion(user):
    """RBAC estricto del Asistente de Recepcion, sin inferencias por username."""
    if not user or not getattr(user, 'is_authenticated', False):
        return False
    if getattr(user, 'is_superuser', False):
        return False

    perfiles_usuario = PERFIL_USUARIO.objects.select_related('PR_NID').filter(
        US_NID=user.id,
        PE_BHABILITADO=True,
        PR_NID__PR_BHABILITADO=True,
    )
    return any(
        normalizar_nombre_perfil(valor) in PERFILES_ASISTENTE_RECEPCION
        for perfil_usuario in perfiles_usuario
        for valor in (
            perfil_usuario.PR_NID.PR_CNOMBRE,
            perfil_usuario.PR_NID.PR_CCODIGO,
        )
    )


def usuario_es_asistente_cd(user):
    if getattr(user, 'is_superuser', False):
        return False

    if normalizar_nombre_perfil(getattr(user, 'username', '')) in USUARIOS_ASISTENTE_CD:
        return True

    user_id = getattr(user, 'id', None)
    if not user_id:
        return False

    perfiles_usuario = PERFIL_USUARIO.objects.select_related('PR_NID').filter(
        US_NID=user_id,
        PE_BHABILITADO=True,
        PR_NID__PR_BHABILITADO=True
    )

    for perfil_usuario in perfiles_usuario:
        nombre = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CNOMBRE)
        codigo = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CCODIGO)

        if nombre in PERFILES_ASISTENTE_CD or codigo in PERFILES_ASISTENTE_CD:
            return True

    return False


def usuario_es_planificador(user):
    if getattr(user, 'is_superuser', False):
        return True

    userv = getattr(user, 'userv', None)

    if userv and getattr(userv, 'UX_IS_PLANIFICADOR', False):
        return True

    perfiles_usuario = PERFIL_USUARIO.objects.select_related('PR_NID').filter(
        US_NID=user.id,
        PE_BHABILITADO=True,
        PR_NID__PR_BHABILITADO=True
    )

    for perfil_usuario in perfiles_usuario:
        nombre = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CNOMBRE)
        codigo = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CCODIGO)

        if nombre in PERFILES_PLANIFICADOR or codigo in PERFILES_PLANIFICADOR:
            return True

    return False


def perfiles_normalizados_usuario(user):
    perfiles = set()
    username = normalizar_nombre_perfil(getattr(user, 'username', ''))
    if username:
        perfiles.add(username)

    for perfil_usuario in PERFIL_USUARIO.objects.select_related('PR_NID').filter(
        US_NID=user.id,
        PE_BHABILITADO=True,
        PR_NID__PR_BHABILITADO=True
    ):
        perfiles.add(normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CNOMBRE))
        perfiles.add(normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CCODIGO))

    if usuario_es_asistente_cd(user):
        perfiles.update({'ASISTENTE C D', 'ASISTENTE CD'})
    if usuario_es_asistente_recepcion(user):
        perfiles.update({'ASISTENTE DE RECEPCION', 'ASISTENTE RECEPCION'})
    if usuario_es_guardia_porteria(user):
        perfiles.add('GUARDIA PORTERIA')
    elif usuario_es_guardia(user):
        perfiles.update({'GUARDIA', 'GUA'})
    if usuario_es_operador_romana(user):
        # TODO tecnico: crear perfil dedicado Operador Romana con permisos minimos y evitar heredar vistas amplias de OP/REC.
        perfiles.add('OPERADOR ROMANA')

    return expandir_aliases_perfiles_operacion(perfiles)


def usuario_es_operacion_planta(user):
    if getattr(user, 'is_superuser', False):
        return True
    return bool(perfiles_normalizados_usuario(user) & expandir_aliases_perfiles_operacion(PERFILES_OPERACION_PLANTA))


def usuario_puede_paso_operacion(user, responsables):
    if getattr(user, 'is_superuser', False):
        return True
    responsables_normalizados = expandir_aliases_perfiles_operacion(responsables)
    return bool(perfiles_normalizados_usuario(user) & responsables_normalizados)


def usuario_puede_reabrir_cierre_carga(user):
    if getattr(user, 'is_superuser', False):
        return True
    identidad = normalizar_nombre_perfil(getattr(user, 'username', ''))
    return identidad == 'ADMIN DESARROLLO' or 'ADMIN DESARROLLO' in perfiles_normalizados_usuario(user)


def usuario_puede_actualizar_borrador_sap_recepcion(citacion, user):
    """Permiso funcional; no concede acceso al detalle técnico SAP."""
    if getattr(user, 'is_superuser', False) or usuario_es_asistente_cd(user):
        return True
    return bool(
        aplica_timbraje_recepcion(citacion)
        and _empresa_timbre_recepcion(citacion) == 'SBH'
        and usuario_es_asistente_recepcion(user)
    )

def usuario_es_asistente_despacho_terramar(user):
    return bool(
        getattr(user, 'is_authenticated', False)
        and _usuario_tiene_acceso_empresa(user, 1)
        and usuario_puede_paso_operacion(user, [PERFIL_TERRAMAR_ASISTENTE_DESPACHO])
    )


def citacion_habilitada_operacion(citacion):
    if es_recepcion_new_jersey_p3(citacion):
        return bool(
            CAMION_PATIO.objects.filter(CI_NID=citacion).exists()
            and OPERACION_NEW_JERSEY_PROCESO.objects.filter(
                CI_NID=citacion,
                EP_NID_id=ID_ACEITES_SBH,
                ONJP_CTIPO=OPERACION_NEW_JERSEY_PROCESO.TipoProceso.PROCESO_3,
                ONJP_CESTADO__in=[
                    OPERACION_NEW_JERSEY_PROCESO.Estado.EN_PROCESO,
                    OPERACION_NEW_JERSEY_PROCESO.Estado.COMPLETADO,
                ],
            ).exists()
            and ETAPA_LOG.objects.filter(
                CI_NID=citacion,
                SC_NID=citacion.SC_NID,
                ET_NID__ET_CCODIGO=nj_p3.ETAPA_P3_PESAJE_TARA,
            ).exists()
        )
    if es_recepcion_new_jersey_p2(citacion):
        return OPERACION_NEW_JERSEY_PROCESO.objects.filter(
            CI_NID=citacion, EP_NID_id=ID_ACEITES_SBH,
            ONJP_CTIPO=OPERACION_NEW_JERSEY_PROCESO.TipoProceso.PROCESO_2,
            ONJP_CESTADO__in=[
                OPERACION_NEW_JERSEY_PROCESO.Estado.EN_PROCESO,
                OPERACION_NEW_JERSEY_PROCESO.Estado.COMPLETADO,
            ],
        ).exists()
    return SYSLOGGER.objects.filter(
        LOG_COPERACION='AUTORIZA_INGRESO_PLANTA',
        LOG_CADD1=str(citacion.id)
    ).exists()


def obtener_etapa_preoperacional_citacion(citacion):
    if es_recepcion_new_jersey_p3(citacion) and citacion_habilitada_operacion(citacion):
        return ''
    if es_recepcion_new_jersey_p2(citacion):
        return '' if citacion_habilitada_operacion(citacion) else 'Pendiente de activar P2'
    citacion_id = str(citacion.id)
    if SYSLOGGER.objects.filter(LOG_COPERACION='AUTORIZA_INGRESO_PLANTA', LOG_CADD1=citacion_id).exists():
        return ''
    if SYSLOGGER.objects.filter(LOG_COPERACION='ENVIA_GUARDIA_PORTERIA', LOG_CADD1=citacion_id).exists():
        return NOMBRE_ETAPA_AUTORIZACION_INGRESO_PLANTA
    if es_recepcion_new_jersey_p3(citacion) and SYSLOGGER.objects.filter(
        LOG_COPERACION='APRUEBA_AR', LOG_CADD1=citacion_id
    ).exists():
        return NOMBRE_ETAPA_PENDIENTE_GUARDIA
    if SYSLOGGER.objects.filter(LOG_COPERACION='ENVIA_CD_NEXT', LOG_CADD1=citacion_id).exists():
        return NOMBRE_ETAPA_AUTORIZACION_INGRESO
    return ''


def obtener_etapa_visible_resumen_citacion(citacion):
    etapa_legacy = citacion.ETAPA_ACTUAL.ET_CNOMBRE if citacion.ETAPA_ACTUAL else ''
    if citacion.CI_CTIPO != CIT_RECEPCION:
        return etapa_legacy

    return obtener_etapa_actual_operacional_citacion(citacion)


def obtener_etapa_actual_operacional_citacion(citacion):
    if not citacion:
        return ''
    if es_recepcion_new_jersey_p3(citacion) and citacion_habilitada_operacion(citacion):
        paso_actual, _, _ = obtener_paso_activo_operacion(citacion)
        return nombre_visible_paso_operacion(citacion, paso_actual) if paso_actual else 'P3 completado'
    if es_recepcion_new_jersey_p2(citacion):
        if not citacion_habilitada_operacion(citacion):
            return 'Pendiente de activar P2'
        return nj_p2.paso_actual_p2(citacion) or 'P2 completado'

    etapa_legacy = citacion.ETAPA_ACTUAL.ET_CNOMBRE if citacion.ETAPA_ACTUAL else ''
    if citacion.CI_CTIPO != CIT_RECEPCION:
        return etapa_legacy

    citacion_id = str(citacion.id)
    if SYSLOGGER.objects.filter(LOG_COPERACION='AUTORIZA_INGRESO_PLANTA', LOG_CADD1=citacion_id).exists():
        _, pasos_config = obtener_pasos_operacion_citacion(citacion)
        paso_actual, _, _ = obtener_paso_activo_operacion(citacion, pasos_config)
        return paso_actual or 'Inicia Ciclo Romana / Pesaje Entrada'

    if SYSLOGGER.objects.filter(LOG_COPERACION='ENVIA_GUARDIA_PORTERIA', LOG_CADD1=citacion_id).exists():
        return NOMBRE_ETAPA_AUTORIZACION_INGRESO_PLANTA

    if es_recepcion_new_jersey_p3(citacion) and SYSLOGGER.objects.filter(
        LOG_COPERACION='APRUEBA_AR', LOG_CADD1=citacion_id
    ).exists():
        return NOMBRE_ETAPA_PENDIENTE_GUARDIA

    if SYSLOGGER.objects.filter(LOG_COPERACION='ENVIA_CD_NEXT', LOG_CADD1=citacion_id).exists():
        return NOMBRE_ETAPA_AUTORIZACION_INGRESO

    if SYSLOGGER.objects.filter(LOG_COPERACION='APRUEBA_AR', LOG_CADD1=citacion_id).exists():
        return NOMBRE_ETAPA_DOCUMENTACION_APROBADA

    if SYSLOGGER.objects.filter(LOG_COPERACION__in=['AVANZA_AR', 'GUARDIA_INGRESO'], LOG_CADD1=citacion_id).exists():
        return NOMBRE_ETAPA_AUTORIZACION_INGRESO

    return NOMBRE_ETAPA_INSUMO_PROGRAMADO


def normalizar_nombre_flujo_operacion(valor):
    texto = normalizar_nombre_perfil(valor)
    return ' '.join(texto.replace('(', ' ').replace(')', ' ').split())


def normalizar_etapa_tecnica_operacion(valor):
    texto = normalizar_nombre_perfil(valor)
    return ' '.join(
        texto.replace('(', ' ')
        .replace(')', ' ')
        .replace('_', ' ')
        .replace('-', ' ')
        .split()
    )


def obtener_boton_operacional_desde_etapa_tecnica(citacion):
    etapa = citacion.ETAPA_ACTUAL
    if not etapa:
        return None

    candidatos = [
        normalizar_etapa_tecnica_operacion(etapa.ET_CNOMBRE),
        normalizar_etapa_tecnica_operacion(etapa.ET_CCODIGO),
    ]

    for candidato in candidatos:
        if candidato in MAPEO_ETAPA_TECNICA_BOTON_OPERACIONAL:
            return MAPEO_ETAPA_TECNICA_BOTON_OPERACIONAL[candidato]

    for candidato in candidatos:
        for etapa_tecnica, boton_visible in MAPEO_ETAPA_TECNICA_BOTON_OPERACIONAL.items():
            if etapa_tecnica in candidato:
                return boton_visible

    return None


def obtener_pasos_operacion_citacion(citacion):
    tipo_citacion = str(
        citacion.CI_CTIPO
        or (citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '')
        or ''
    ).strip().upper()
    if tipo_citacion == CIT_DESPACHO:
        secuencia_codigo_real = str(citacion.SC_NID.SE_CCODIGO if citacion.SC_NID else '').strip().upper()
        pasos_despacho = FLUJOS_DESPACHO_OPERACION_PLANTA.get(secuencia_codigo_real)
        if pasos_despacho and not aplica_inspeccion_inicio_carga(citacion):
            pasos_despacho = [paso for paso in pasos_despacho if paso[0] != PASO_APROBAR_INICIO_CARGA]
        if pasos_despacho:
            nombre_flujo = str(citacion.SC_NID.SE_CNOMBRE or '').strip() or secuencia_codigo_real
            return nombre_flujo, pasos_despacho_operacion_activos(pasos_despacho)

    def pasos_recepcion_sin_borrador_sap(pasos):
        if tipo_citacion == CIT_RECEPCION and RECEPCION_BORRADOR_SAP_TEMPORALMENTE_DESACTIVADO:
            return [paso for paso in pasos if paso[0] != PASO_BORRADOR_SAP]
        return pasos

    secuencia_codigo_real = str(citacion.SC_NID.SE_CCODIGO if citacion.SC_NID else '').strip().upper()
    if tipo_citacion == CIT_RECEPCION and secuencia_codigo_real == rs.SECUENCIA_CODIGO:
        return 'RECEPCIÓN SERVICIO', PASOS_RECEPCION_SERVICIO
    if es_recepcion_new_jersey_p1(citacion):
        return 'RECEPCION SECTOR NEW JERSEY', PASOS_RECEPCION_NEW_JERSEY_P1
    if es_recepcion_new_jersey_p2(citacion):
        return 'NEW JERSEY PROCESO 2', [(paso, [nj_p2.RESPONSABLE_P2]) for paso in nj_p2.PASOS_P2]
    if es_recepcion_new_jersey_p3(citacion):
        return 'NEW JERSEY PROCESO 3', PASOS_RECEPCION_NEW_JERSEY_P3

    if tipo_citacion == CIT_RECEPCION and secuencia_codigo_real in {
        'RECEPCION_TERRAMAR',
        'RECEPCION_TERRAMAR_BODEGA_EXTERNA',
    }:
        return secuencia_codigo_real, FLUJOS_OPERACION_PLANTA[secuencia_codigo_real]

    secuencia_nombre = normalizar_nombre_flujo_operacion(citacion.SC_NID.SE_CNOMBRE if citacion.SC_NID else '')
    secuencia_codigo = normalizar_nombre_flujo_operacion(citacion.SC_NID.SE_CCODIGO if citacion.SC_NID else '')

    for nombre_flujo, pasos in FLUJOS_OPERACION_PLANTA.items():
        flujo_normalizado = normalizar_nombre_flujo_operacion(nombre_flujo)
        if flujo_normalizado in secuencia_nombre or flujo_normalizado in secuencia_codigo:
            return nombre_flujo, pasos_recepcion_sin_borrador_sap(pasos)

    flujo_default = 'RECEPCION BODEGA EXTERNA' if citacion.CI_CTIPO == CIT_RECEPCION else 'RETIRO CONTENEDOR CISTERNA VACIO'
    return flujo_default, pasos_recepcion_sin_borrador_sap(FLUJOS_OPERACION_PLANTA[flujo_default])


def nombre_visible_paso_operacion(citacion, nombre_paso):
    if es_recepcion_new_jersey_p3(citacion):
        return {
            'Pesaje Entrada': 'Pesaje tara camión',
            PASO_NJ_P3_CARGA_DESCARGA: 'Retiro contenedor vacío',
            'Pesaje Salida': 'Pesaje camión y contenedor vacío',
        }.get(nombre_paso, nombre_paso)
    if es_recepcion_bodega_externa_operacion(citacion) and nombre_paso == PASO_CICLO_DESCARGA:
        return 'Salida temporal a bodega externa'
    tipo_citacion = str(
        citacion.CI_CTIPO
        or (citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '')
        or ''
    ).strip().upper()
    if tipo_citacion == CIT_DESPACHO:
        return NOMBRES_VISIBLES_PASOS_DESPACHO.get(nombre_paso, nombre_paso)
    return nombre_paso


_CALIDAD_NO_PRECARGADA = object()


def resolver_estado_operacional_visible(citacion, pasos_config, pasos_completados=None, *, resultado_calidad=_CALIDAD_NO_PRECARGADA):
    pasos_completados = pasos_completados or set()
    if leer_inspeccion_inicio_carga(citacion).get('resultado') == 'RECHAZADO':
        return PASO_CONFIRMAR_SALIDA
    nombres_pasos = [paso for paso, _ in pasos_config]
    es_flujo_terramar = es_flujo_preoperacional_terramar(citacion)
    boton_desde_etapa_tecnica = (
        '' if es_flujo_terramar or es_recepcion_new_jersey_p1(citacion) or es_recepcion_new_jersey_p2(citacion) or es_recepcion_new_jersey_p3(citacion)
        else obtener_boton_operacional_desde_etapa_tecnica(citacion)
    )
    tipo_citacion = str(
        citacion.CI_CTIPO
        or (citacion.PL_NID.PL_CTIPOCUPO if citacion.PL_NID else '')
        or ''
    ).strip().upper()

    if resultado_calidad is _CALIDAD_NO_PRECARGADA:
        resultado_calidad = RESULTADO_CALIDAD_OPERACION.objects.filter(CI_NID=citacion).only('RCO_CESTADO').first()
    es_recepcion_bodega_externa = es_recepcion_bodega_externa_operacion(citacion)
    if (
        not es_recepcion_bodega_externa
        and resultado_calidad
        and resultado_calidad.RCO_CESTADO == RESULTADO_CALIDAD_OPERACION.Estado.RECHAZADO
        and PASO_ANALISIS_CALIDAD in nombres_pasos
    ):
        return PASO_ANALISIS_CALIDAD

    if (
        not es_recepcion_bodega_externa
        and not es_flujo_terramar
        and tipo_citacion != CIT_DESPACHO
        and boton_desde_etapa_tecnica in nombres_pasos
        and 'Confirmar Salida' not in pasos_completados
    ):
        return boton_desde_etapa_tecnica

    return next((paso for paso in nombres_pasos if paso not in pasos_completados), nombres_pasos[-1] if nombres_pasos else 'Sin flujo')


def obtener_paso_activo_operacion(citacion, pasos_config=None):
    if es_recepcion_new_jersey_p2(citacion):
        actual = nj_p2.paso_actual_p2(citacion)
        completados = set(OPERACION_PLANTA_LOG.objects.filter(
            CI_NID=citacion, OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        ).values_list('OPL_CPASO', flat=True))
        return actual, [nj_p2.RESPONSABLE_P2] if actual else [], completados
    if pasos_config is None:
        _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    logs_completados = set(OPERACION_PLANTA_LOG.objects.filter(
        CI_NID=citacion,
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).values_list('OPL_CPASO', flat=True))
    paso_actual = resolver_estado_operacional_visible(citacion, pasos_config, logs_completados)
    responsables_actuales = []
    for nombre_paso, responsables in pasos_config:
        if nombre_paso == paso_actual:
            responsables_actuales = responsables
            break
    return paso_actual, responsables_actuales, logs_completados


def construir_estado_pasos_operacion(nombres_pasos, paso_actual, pasos_completados, pasos_no_ejecutados=()):
    pasos = []
    paso_actual_index = nombres_pasos.index(paso_actual) if paso_actual in nombres_pasos else -1

    for index, paso in enumerate(nombres_pasos):
        if paso in pasos_no_ejecutados:
            estado = 'pending'
        elif paso == paso_actual:
            estado = 'active'
        elif paso in pasos_completados or (paso_actual_index >= 0 and index < paso_actual_index):
            estado = 'completed'
        else:
            estado = 'pending'
        pasos.append({
            'nombre': paso,
            'estado': estado,
        })

    return pasos


