def _metadata_ticket_mop_dato(dato):
    if not dato:
        return None
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return None
    return metadata if isinstance(metadata, dict) else None


def _ticket_mop_guardado_valido(citacion, metadata=None, ticket_salida_metadata=None):
    metadata = metadata or _metadata_ticket_mop_dato(_dato_ticket_mop_despacho_terramar(citacion))
    if not es_pesaje_salida_mop_despacho_terramar(citacion, 'Pesaje Salida', 'SAL') or not metadata:
        return False
    if ticket_salida_metadata is None:
        ticket_salida_metadata = _leer_metadata_ticket_dato(_dato_ticket_pesaje(citacion, 'Pesaje Salida'))
    ruta = metadata.get('ruta_local')
    datos_nombre = _extraer_timestamp_ticket_ejes(metadata.get('nombre'))
    return bool(
        ruta and os.path.isfile(ruta) and _ruta_ticket_permitida(ruta)
        and datos_nombre
        and datos_nombre['patente'] == _normalizar_patente(metadata.get('patente'))
        and metadata.get('paso') == 'Pesaje Salida'
        and ticket_salida_metadata
        and metadata.get('ticket_salida_nombre') == ticket_salida_metadata.get('nombre_archivo_pdf')
        and metadata.get('ticket_salida_timestamp')
        == (_timestamp_base_ticket_salida(ticket_salida_metadata.get('nombre_archivo_pdf')).isoformat()
            if _timestamp_base_ticket_salida(ticket_salida_metadata.get('nombre_archivo_pdf')) else '')
    )


def _payload_ticket_mop_guardado(citacion, request=None):
    requerido = es_pesaje_salida_mop_despacho_terramar(citacion, 'Pesaje Salida', 'SAL')
    if not requerido:
        return {'requerido': False, 'ok': False, 'nombre': '', 'download_url': ''}
    dato = _dato_ticket_mop_despacho_terramar(citacion)
    metadata = _metadata_ticket_mop_dato(dato)
    if not dato or not _ticket_mop_guardado_valido(citacion, metadata):
        return {'requerido': True, 'ok': False, 'nombre': '', 'download_url': ''}
    url = f"{reverse('ajax_operacion_planta_descargar_ticket_pesaje')}?dato_id={dato.id}"
    if request:
        url = request.build_absolute_uri(url)
    return {
        'requerido': True,
        'ok': True,
        'nombre': metadata.get('nombre') or '',
        'download_url': url,
        'dato_id': dato.id,
    }

def _buscar_ticket_pesaje_mas_reciente(patente, tipo_ticket):
    patente_normalizada = _normalizar_patente(patente)
    _debug_ticket_pesaje(
        'Inicio busqueda ticket',
        patente_original=repr(patente),
        patente_normalizada=patente_normalizada,
        tipo_ticket=tipo_ticket
    )
    if not patente_normalizada or tipo_ticket not in {'ENT', 'SAL'}:
        _debug_ticket_pesaje('Busqueda cancelada por patente o tipo invalido', patente=patente_normalizada, tipo_ticket=tipo_ticket)
        return None

    candidatos = []
    patron_ticket = re.compile(
        r'^COM_(ENT|SAL)_(.+?)_(\d{2})_(\d{2})_(\d{2})_(\d{2})_(\d{2})(?:_\d{8}_\d{6})?\.pdf$',
        re.IGNORECASE
    )
    for carpeta in [TICKET_PESAJE_SHARED_PATH, TICKET_PESAJE_LOCAL_PATH]:
        _debug_ticket_pesaje('Revisando carpeta tickets', carpeta=carpeta, existe=os.path.isdir(carpeta) if carpeta else False)
        if not carpeta or not os.path.isdir(carpeta):
            continue
        try:
            nombres_archivos = os.listdir(carpeta)
        except OSError as e:
            _debug_ticket_pesaje('No fue posible listar carpeta tickets', carpeta=carpeta, error=str(e))
            continue
        for nombre in nombres_archivos:
            match = patron_ticket.match(nombre)
            if not match:
                continue
            tipo_archivo = match.group(1).upper()
            patente_archivo = _normalizar_patente(match.group(2))
            if tipo_archivo != tipo_ticket or patente_archivo != patente_normalizada:
                continue
            ruta = os.path.join(carpeta, nombre)
            if not os.path.isfile(ruta):
                continue
            fecha_nombre = _fecha_ticket_desde_nombre(nombre) or datetime.min
            try:
                fecha_modificacion = datetime.fromtimestamp(os.path.getmtime(ruta))
            except OSError:
                fecha_modificacion = datetime.min
            candidatos.append((fecha_nombre, fecha_modificacion, ruta))
            _debug_ticket_pesaje(
                'Candidato ticket encontrado',
                archivo=nombre,
                patente_archivo=patente_archivo,
                fecha_nombre=fecha_nombre,
                fecha_modificacion=fecha_modificacion
            )

    if not candidatos:
        _debug_ticket_pesaje('Sin candidatos ticket', patente=patente_normalizada, tipo_ticket=tipo_ticket)
        return None
    candidatos.sort(key=lambda item: (item[0], item[1]), reverse=True)
    _debug_ticket_pesaje(
        'Ticket seleccionado',
        archivo=os.path.basename(candidatos[0][2]),
        ruta=candidatos[0][2],
        total_candidatos=len(candidatos)
    )
    return candidatos[0][2]


def _peso_entero(valor):
    texto = re.sub(r'[^0-9]', '', str(valor or ''))
    return int(texto) if texto else 0


def _extraer_folio_ticket_pesaje(lineas):
    for indice, linea in enumerate(lineas):
        if re.search(r'Folio\s+Nro', linea, re.IGNORECASE):
            bloque = lineas[indice + 1:indice + 10]
            for candidata in bloque:
                texto = candidata.strip()
                if re.fullmatch(r'\d{3,}', texto):
                    return texto
    texto_completo = '\n'.join(lineas)
    folio_match = re.search(r'Folio\s*Nro\.?\s*:?\s*(\d{3,})', texto_completo, re.IGNORECASE)
    return folio_match.group(1).strip() if folio_match else ''


def _filas_fecha_pesaje_ticket(lineas):
    filas = []
    patron_fecha_peso = re.compile(r'^\d{2}-\d{2}-\d{4}\s+\d{2}:\d{2}\s+([\d\.,]+)\b')
    for linea in lineas:
        if linea.startswith('01-01-1900'):
            continue
        match = patron_fecha_peso.search(linea)
        if match:
            filas.append({
                'linea': linea,
                'peso': _peso_entero(match.group(1)),
            })
    return filas


def _extraer_pesos_semanticos_ticket(lineas, tipo_ticket):
    filas_pesaje = _filas_fecha_pesaje_ticket(lineas)
    resultado = {
        'peso_entrada_kg': None,
        'peso_salida_bruto_kg': None,
        'peso_neto_producto_kg': None,
        'fuente_peso_neto': '',
        'peso_neto_calculado_kg': None,
        'diferencia_control_kg': None,
        'control_pesaje_ok': None,
    }
    if tipo_ticket == 'ENT':
        if filas_pesaje:
            resultado['peso_entrada_kg'] = filas_pesaje[0]['peso']
        return resultado

    if tipo_ticket != 'SAL':
        return resultado

    if filas_pesaje:
        resultado['peso_entrada_kg'] = filas_pesaje[0]['peso']
    if len(filas_pesaje) > 1:
        resultado['peso_salida_bruto_kg'] = filas_pesaje[-1]['peso']

    pesos_netos_explicitos = []
    for linea in lineas:
        if re.search(r'Peso\s+Neto', linea, re.IGNORECASE) and not re.search(r'informado', linea, re.IGNORECASE):
            numeros = re.findall(r'\d[\d\.,]*', linea)
            if numeros:
                pesos_netos_explicitos.append(_peso_entero(numeros[-1]))
    peso_neto_explicito = next(
        (valor for valor in reversed(pesos_netos_explicitos) if valor),
        None,
    )

    entrada = resultado['peso_entrada_kg']
    salida_bruta = resultado['peso_salida_bruto_kg']
    if entrada is not None and salida_bruta is not None:
        resultado['peso_neto_calculado_kg'] = salida_bruta - entrada

    if peso_neto_explicito is not None:
        resultado['peso_neto_producto_kg'] = peso_neto_explicito
        resultado['fuente_peso_neto'] = 'ticket_explicito'
    elif resultado['peso_neto_calculado_kg'] is not None:
        if resultado['peso_neto_calculado_kg'] < 0:
            resultado['control_pesaje_ok'] = False
            return resultado
        resultado['peso_neto_producto_kg'] = resultado['peso_neto_calculado_kg']
        resultado['fuente_peso_neto'] = 'calculado_desde_pesadas'

    peso_neto = resultado['peso_neto_producto_kg']
    peso_calculado = resultado['peso_neto_calculado_kg']
    if peso_neto is not None and peso_calculado is not None:
        resultado['diferencia_control_kg'] = peso_calculado - peso_neto
        resultado['control_pesaje_ok'] = resultado['diferencia_control_kg'] == 0
    return resultado


def _extraer_datos_ticket_pesaje(
    ruta_pdf,
    tipo_ticket,
    semantica_despacho_sbh=False,
    conservar_pesos_brutos=False,
):
    texto_paginas = []
    with open(ruta_pdf, 'rb') as archivo:
        reader = PdfReader(archivo)
        for page in reader.pages:
            texto_paginas.append(page.extract_text() or '')
    texto = '\n'.join(texto_paginas)
    lineas = [linea.strip() for linea in texto.splitlines() if linea.strip()]

    folio = _extraer_folio_ticket_pesaje(lineas)

    pesos_semanticos = (
        _extraer_pesos_semanticos_ticket(lineas, tipo_ticket)
        if semantica_despacho_sbh or conservar_pesos_brutos
        else {}
    )
    peso = 0
    if tipo_ticket == 'ENT':
        filas_pesaje = _filas_fecha_pesaje_ticket(lineas)
        peso = (
            pesos_semanticos.get('peso_entrada_kg')
            if semantica_despacho_sbh
            else (filas_pesaje[0]['peso'] if filas_pesaje else 0)
        ) or 0
        if not peso:
            for linea in lineas:
                if re.search(r'\bEntrada\b', linea, re.IGNORECASE):
                    numeros = re.findall(r'\d[\d\.,]*', linea)
                    if numeros:
                        peso = _peso_entero(numeros[-1])
                        break
    elif tipo_ticket == 'SAL':
        pesos = []
        for linea in lineas:
            if re.search(r'Peso\s+Neto', linea, re.IGNORECASE) and not re.search(r'informado', linea, re.IGNORECASE):
                numeros = re.findall(r'\d[\d\.,]*', linea)
                if numeros:
                    pesos.append(_peso_entero(numeros[-1]))
        peso = next((valor for valor in reversed(pesos) if valor), 0)
        filas_pesaje = _filas_fecha_pesaje_ticket(lineas)
        if not peso and len(filas_pesaje) > 1:
            # Compatibilidad: peso_neto/DO_NPESO conservan el valor histórico.
            # La automatización SBH usa peso_neto_producto_kg, no este fallback.
            peso = filas_pesaje[-1]['peso']

    observacion_match = re.search(r'\b([A-Z]{3,4}\d{6,7}(?:-\d)?)\b', texto.upper())
    observacion = _normalizar_observacion_ticket(observacion_match.group(1)) if observacion_match else ''

    if not folio:
        raise ValueError('No fue posible leer el folio del ticket de pesaje.')
    if (
        semantica_despacho_sbh
        and tipo_ticket == 'SAL'
        and pesos_semanticos.get('control_pesaje_ok') is False
        and pesos_semanticos.get('peso_neto_producto_kg') is None
    ):
        raise ValueError(
            'El ticket de salida es inconsistente: el peso bruto de salida es menor al peso de entrada.'
        )
    if not peso:
        raise ValueError('No fue posible leer un peso valido del ticket de pesaje.')

    resultado = {
        'folio': folio,
        'peso_neto': peso,
        'observacion': observacion,
    }
    if semantica_despacho_sbh or conservar_pesos_brutos:
        resultado.update(pesos_semanticos)
        if tipo_ticket == 'ENT' and not resultado.get('peso_entrada_kg'):
            resultado['peso_entrada_kg'] = peso
        resultado['peso_bruto_kg'] = (
            resultado.get('peso_entrada_kg')
            if tipo_ticket == 'ENT'
            else resultado.get('peso_salida_bruto_kg')
        )
    return resultado


def _ruta_ticket_permitida(ruta):
    try:
        ruta_real = os.path.realpath(os.path.abspath(ruta))
        local_real = os.path.realpath(os.path.abspath(TICKET_PESAJE_LOCAL_PATH))
        return ruta_real.startswith(local_real + os.sep) or ruta_real == local_real
    except (TypeError, ValueError, OSError):
        return False


def _copiar_ticket_local_si_necesario(ruta_pdf):
    os.makedirs(TICKET_PESAJE_LOCAL_PATH, exist_ok=True)
    destino = os.path.join(TICKET_PESAJE_LOCAL_PATH, os.path.basename(ruta_pdf))
    if os.path.realpath(os.path.abspath(ruta_pdf)) != os.path.realpath(os.path.abspath(destino)):
        if not os.path.exists(destino):
            shutil.copy2(ruta_pdf, destino)
        return destino
    return ruta_pdf


def _obtener_campo_ticket_pesaje(citacion, tipo_ticket, usuario):
    codigo = _codigo_campo_ticket_pesaje(tipo_ticket)
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=codigo,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'NUMERO',
            'CA_CETIQUETA': f'Ticket pesaje {tipo_ticket}',
            'CA_CPLACEMARK': 'Peso obtenido desde ticket',
            'CA_BOBLIGATORIO': True,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        }
    )
    cambios = []
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        cambios.append('CA_BHABILITADO')
    if campo.CA_CTIPO != 'NUMERO':
        campo.CA_CTIPO = 'NUMERO'
        cambios.append('CA_CTIPO')
    if cambios:
        campo.save(update_fields=cambios)
    return campo


def _metadata_ticket_pesaje(citacion, paso, tipo_ticket, patente, ruta_local, datos, usuario):
    fecha_ticket = _fecha_ticket_desde_nombre(os.path.basename(ruta_local))
    metadata = {
        'folio': datos['folio'],
        'peso_neto': datos['peso_neto'],
        'observacion': datos.get('observacion') or '',
        'ruta_real_pdf': os.path.abspath(ruta_local),
        'nombre_archivo_pdf': os.path.basename(ruta_local),
        'fecha_hora_ticket': fecha_ticket.isoformat() if fecha_ticket else '',
        'patente': _normalizar_patente(patente),
        'tipo_ticket': tipo_ticket,
        'citacion_id': citacion.id,
        'paso_operacion': paso,
        'usuario_id': usuario.id,
    }
    for clave in (
        'peso_entrada_kg',
        'peso_salida_bruto_kg',
        'peso_bruto_kg',
        'peso_neto_producto_kg',
        'fuente_peso_neto',
        'peso_neto_calculado_kg',
        'diferencia_control_kg',
        'control_pesaje_ok',
    ):
        if clave in datos:
            metadata[clave] = datos.get(clave)
    return metadata


def _dato_ticket_pesaje(citacion, paso):
    tipo_ticket = _tipo_ticket_pesaje(paso)
    if not tipo_ticket:
        return None
    return DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO=_codigo_campo_ticket_pesaje(tipo_ticket)
    ).select_related('CAMP_NID').order_by('-id').first()


def _leer_metadata_ticket_dato(dato):
    if not dato:
        return None
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return None
    return metadata if isinstance(metadata, dict) else None


def _ticket_pesaje_obligatorio_guardado(citacion, paso):
    tipo_ticket = _tipo_ticket_pesaje(paso)
    if not tipo_ticket:
        return True
    dato = _dato_ticket_pesaje(citacion, paso)
    metadata = _leer_metadata_ticket_dato(dato)
    if not metadata:
        return False
    ruta_pdf = metadata.get('ruta_real_pdf')
    return all([
        metadata.get('folio'),
        int(metadata.get('peso_neto') or 0) > 0,
        metadata.get('tipo_ticket') == tipo_ticket,
        metadata.get('paso_operacion') == paso,
        ruta_pdf,
        os.path.isfile(ruta_pdf),
        _ruta_ticket_permitida(ruta_pdf),
    ])


def _payload_ticket_pesaje_guardado(citacion, paso, request=None):
    dato = _dato_ticket_pesaje(citacion, paso)
    metadata = _leer_metadata_ticket_dato(dato)
    if not dato or not metadata or not _ticket_pesaje_obligatorio_guardado(citacion, paso):
        return None
    download_url = reverse('ajax_operacion_planta_descargar_ticket_pesaje')
    url = f'{download_url}?dato_id={dato.id}'
    if request:
        url = request.build_absolute_uri(url)
    return {
        'dato_id': dato.id,
        'peso_neto': metadata.get('peso_neto') or dato.DO_NPESO,
        'folio': metadata.get('folio') or '',
        'observacion': metadata.get('observacion') or '',
        'download_url': url,
        'nombre_archivo_pdf': metadata.get('nombre_archivo_pdf') or '',
        'tipo_ticket': metadata.get('tipo_ticket') or '',
    }


def _resolver_ticket_mop_despacho_terramar(citacion, patente, ticket_salida_metadata, usuario, request=None):
    payload_existente = _payload_ticket_mop_guardado(citacion, request)
    if payload_existente.get('ok'):
        return {
            'estado': 'MOP_ENCONTRADO',
            'ok': True,
            'nombre': payload_existente.get('nombre') or '',
            'download_url': payload_existente.get('download_url') or '',
            'mensaje': 'Ticket MOP obtenido correctamente.',
        }

    ticket_salida_nombre = str(ticket_salida_metadata.get('nombre_archivo_pdf') or '').strip()
    timestamp_ticket_salida = _timestamp_base_ticket_salida(ticket_salida_nombre)
    if not timestamp_ticket_salida:
        return {
            'estado': 'MOP_NO_ENCONTRADO',
            'ok': False,
            'nombre': '',
            'download_url': '',
            'mensaje': 'No fue posible determinar la fecha y hora del ticket de salida congelado.',
        }

    candidato, estado, _ = _buscar_ticket_mop_ejes_despacho_terramar(
        patente,
        timestamp_ticket_salida,
    )
    if estado == 'MOP_AMBIGUO':
        return {
            'estado': estado,
            'ok': False,
            'nombre': '',
            'download_url': '',
            'mensaje': 'Se encontraron múltiples Ticket MOP candidatos para este pesaje.',
        }
    if not candidato:
        return {
            'estado': 'MOP_NO_ENCONTRADO',
            'ok': False,
            'nombre': '',
            'download_url': '',
            'mensaje': 'Ticket de pesaje obtenido. Ticket MOP pendiente.',
        }

    ruta_local = _copiar_ticket_mop_local(candidato['ruta'], citacion)
    if not _ruta_ticket_permitida(ruta_local):
        raise ValueError('La ruta local del Ticket MOP no está permitida.')
    campo = _obtener_campo_ticket_mop_despacho_terramar(citacion, usuario)
    metadata = {
        'nombre': candidato['nombre'],
        'ruta_local': os.path.abspath(ruta_local),
        'patente': _normalizar_patente(patente),
        'timestamp_archivo': candidato['timestamp'].isoformat(),
        'ticket_salida_nombre': ticket_salida_nombre,
        'ticket_salida_timestamp': timestamp_ticket_salida.isoformat(),
        'diferencia_segundos': candidato['diferencia_segundos'],
        'usuario': usuario.username,
        'usuario_id': usuario.id,
        'paso': 'Pesaje Salida',
    }
    dato, _ = DATO_OPERACION.objects.update_or_create(
        CI_NID=citacion,
        SC_NID=citacion.SC_NID,
        CAMP_NID=campo,
        defaults={
            'EP_NID': citacion.EP_NID,
            'ET_NID': citacion.ETAPA_ACTUAL,
            'US_NID': usuario,
            'DO_CVALOR': json.dumps(metadata, ensure_ascii=False),
            'DO_FFECHAREGISTRO': timezone.now(),
        },
    )
    payload = _payload_ticket_mop_guardado(citacion, request)
    return {
        'estado': 'MOP_ENCONTRADO',
        'ok': True,
        'nombre': candidato['nombre'],
        'download_url': payload.get('download_url') or '',
        'dato_id': dato.id,
        'mensaje': 'Ticket MOP obtenido correctamente.',
    }

def _observacion_cierre_ticket_pesaje(citacion, paso):
    ticket = _payload_ticket_pesaje_guardado(citacion, paso)
    if not ticket:
        return ''

    folio = ticket.get('folio') or 'Sin folio'
    peso = ticket.get('peso_neto') or ''
    archivo = ticket.get('nombre_archivo_pdf') or 'Sin archivo'
    if paso == 'Pesaje Salida':
        return f'Pesaje salida informado. Ticket: {folio} | Peso: {peso} | Archivo: {archivo}'
    if paso == 'Pesaje Entrada':
        return f'Pesaje entrada informado. Ticket: {folio} | Peso: {peso} | Archivo: {archivo}'
    return ''


CAMPO_DOCUMENTACION_TERRAMAR = 'OP_DOCUMENTACION_TERRAMAR'
CAMPO_TIMBRADO_TERRAMAR = 'OP_TIMBRADO_TERRAMAR'
CAMPO_TIMBRADO_RECEPCION = 'OP_TIMBRADO_RECEPCION'
CAMPO_REVISION_CONFORMIDAD_SBH = 'OP_REV_CONFORME_SBH'
LOG_DOCUMENTACION_TERRAMAR = 'DOC_VALIDA_TER'
LOG_TIMBRADO_TERRAMAR = 'TIMBRA_DOC_TER'
LOG_AUTORIZA_SALIDA_TERRAMAR = 'AUT_SALIDA_TER'
LOG_EXPORTA_DOCUMENTOS_TERRAMAR = 'EXPORTA_DOC_TER'


def _campo_timbrado_recepcion(citacion):
    return CAMPO_TIMBRADO_TERRAMAR if _empresa_timbre_recepcion(citacion) == 'TERRAMAR' else CAMPO_TIMBRADO_RECEPCION

def _etapa_actual_operacion_segura(citacion):
    try:
        return citacion.ETAPA_ACTUAL
    except (AttributeError, ETAPA.DoesNotExist):
        return None


def _obtener_campo_metadata_terramar(citacion, usuario, codigo, etiqueta):
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=codigo,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'TEXTO',
            'CA_CETIQUETA': etiqueta,
            'CA_CPLACEMARK': etiqueta,
            'CA_BOBLIGATORIO': True,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        },
    )
    cambios = []
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        cambios.append('CA_BHABILITADO')
    if campo.CA_CTIPO != 'TEXTO':
        campo.CA_CTIPO = 'TEXTO'
        cambios.append('CA_CTIPO')
    if cambios:
        campo.save(update_fields=cambios)
    return campo


def _guardar_metadata_terramar(citacion, usuario, codigo, etiqueta, metadata):
    campo = _obtener_campo_metadata_terramar(citacion, usuario, codigo, etiqueta)
    ahora = timezone.now()
    dato, _ = DATO_OPERACION.objects.update_or_create(
        CI_NID=citacion,
        CAMP_NID=campo,
        defaults={
            'EP_NID': citacion.EP_NID,
            'US_NID': usuario,
            'SC_NID': citacion.SC_NID,
            'ET_NID': _etapa_actual_operacion_segura(citacion),
            'DO_CVALOR': json.dumps(metadata, ensure_ascii=False),
            'DO_NPESO': None,
            'DO_FFECHAREGISTRO': ahora,
        },
    )
    metadata['dato_id'] = dato.id
    return metadata


def _leer_metadata_terramar(citacion, codigo):
    dato = DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO=codigo,
    ).select_related('CAMP_NID').order_by('-id').first()
    if not dato:
        return {}
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return {}
    if not isinstance(metadata, dict):
        return {}
    metadata['dato_id'] = dato.id
    return metadata


def _ruta_dentro_de_raiz(ruta, raiz):
    try:
        ruta_real = os.path.realpath(os.path.abspath(ruta))
        raiz_real = os.path.realpath(os.path.abspath(raiz))
        return os.path.commonpath([ruta_real, raiz_real]) == raiz_real
    except (TypeError, ValueError, OSError):
        return False


def _ruta_documento_terramar_permitida(ruta):
    if not ruta:
        return False
    raices = (
        settings.MEDIA_ROOT,
        CAMPO_TERRAMAR_PATH,
        TICKET_PESAJE_LOCAL_PATH,
    )
    return any(raiz and _ruta_dentro_de_raiz(ruta, raiz) for raiz in raices)


def _clave_documento_terramar(origen, source_id):
    raw = f'{origen}:{source_id}'.encode('utf-8')
    return hashlib.sha256(raw).hexdigest()[:24]


def _documentos_fuente_terramar(citacion):
    documentos = []
    deduplicados = set()

    def agregar(origen, source_id, tipo, nombre, ruta, categoria='original', obligatorio=False):
        ruta_resuelta = _resolver_ruta_archivo_citacion(ruta)
        disponible = bool(
            ruta_resuelta
            and os.path.isfile(ruta_resuelta)
            and _ruta_documento_terramar_permitida(ruta_resuelta)
        )
        size = os.path.getsize(ruta_resuelta) if disponible else None
        source_hash = sha256_archivo(ruta_resuelta) if disponible else ''
        ruta_normalizada = os.path.normcase(os.path.realpath(ruta_resuelta)) if ruta_resuelta else ''
        nombre_seguro = os.path.basename(str(nombre or ruta or 'documento'))
        if source_hash:
            dedupe_key = f'{categoria}:hash:{source_hash}'
        elif ruta_normalizada:
            dedupe_key = f'{categoria}:ruta:{ruta_normalizada}'
        elif size is not None:
            dedupe_key = f'{categoria}:nombre:{nombre_seguro.lower()}:{size}'
        else:
            dedupe_key = f'{categoria}:origen:{origen}:{source_id}'
        if dedupe_key in deduplicados:
            return
        deduplicados.add(dedupe_key)
        documentos.append({
            'key': _clave_documento_terramar(origen, source_id),
            'source_ref': f'{origen}:{source_id}',
            'source_id': source_id,
            'origen': origen,
            'tipo': tipo or 'Documento',
            'nombre': nombre_seguro,
            'categoria': categoria,
            'obligatorio': bool(obligatorio),
            'disponible': disponible,
            'estado': 'Disponible' if disponible else 'Archivo no disponible',
            'mime': mime_archivo(ruta_resuelta) if disponible else '',
            'size': size,
            'source_hash': source_hash,
            'formato_timbrable': formato_timbrable(ruta_resuelta) if disponible else '',
            '_ruta': ruta_resuelta if disponible else '',
        })

    labels = dict(EXPEDIENTE_TIPO_LABELS)
    for documento in CITACION_DOCUMENTO.objects.filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CD_BACTIVO=True,
    ).order_by('CD_CTIPO', '-CD_FFECHASUBIDA', '-id'):
        agregar(
            'CITACION_DOCUMENTO',
            documento.id,
            labels.get(documento.CD_CTIPO, documento.get_CD_CTIPO_display()),
            documento.CD_CNOMBRE_ARCHIVO,
            documento.CD_CRUTA_ARCHIVO,
            obligatorio=documento.CD_CTIPO in {
                CITACION_DOCUMENTO.TIPO_GUIA,
                CITACION_DOCUMENTO.TIPO_TICKET_ORIGEN,
                CITACION_DOCUMENTO.TIPO_SERNAPESCA,
            },
        )

    for adjunto in CAMION_PATIO_ADJUNTO.objects.filter(
        CPA_NID__CI_NID=citacion,
        CPA_NID__EP_NID=citacion.EP_NID,
    ).select_related('CPA_NID').order_by('CPA_CTIPO_DOCUMENTO', '-CPA_FFECHACARGA', '-id'):
        agregar(
            'CAMION_PATIO_ADJUNTO',
            adjunto.id,
            adjunto.get_CPA_CTIPO_DOCUMENTO_display(),
            os.path.basename(adjunto.CPA_FARCHIVO.name),
            adjunto.CPA_FARCHIVO.name,
            obligatorio=adjunto.CPA_CTIPO_DOCUMENTO != CAMION_PATIO_ADJUNTO.TIPO_OTRO,
        )

    for dato in DATO_OPERACION.objects.select_related('CAMP_NID').filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CAMP_NID__CA_CTIPO__iexact='archivo',
    ).exclude(DO_CVALOR='').order_by('CAMP_NID_id', '-id'):
        agregar(
            'DATO_OPERACION',
            dato.id,
            dato.CAMP_NID.CA_CETIQUETA or dato.CAMP_NID.CA_CCODIGO,
            os.path.basename(dato.DO_CVALOR),
            dato.DO_CVALOR,
            obligatorio=str(dato.CAMP_NID.CA_CCODIGO or '').startswith('ING_DOC_'),
        )

    for paso, etiqueta in (('Pesaje Entrada', 'Ticket Pesaje Entrada'), ('Pesaje Salida', 'Ticket Pesaje Salida')):
        dato = _dato_ticket_pesaje(citacion, paso)
        metadata = _leer_metadata_ticket_dato(dato)
        if not dato or not metadata:
            continue
        agregar(
            'TICKET_PESAJE',
            dato.id,
            etiqueta,
            metadata.get('nombre_archivo_pdf') or os.path.basename(metadata.get('ruta_real_pdf') or ''),
            metadata.get('ruta_real_pdf'),
            categoria='ticket',
            obligatorio=True,
        )

    return documentos


def obtener_documentos_salida_recepcion(citacion):
    """Paquete de salida para timbraje, exportación y envío manual de recepción."""
    documentos = _documentos_fuente_terramar(citacion)
    salida = [
        documento for documento in documentos
        if documento.get('origen') == 'CITACION_DOCUMENTO'
        or (documento.get('origen') == 'TICKET_PESAJE' and documento.get('tipo') == 'Ticket Pesaje Salida')
    ]
    if _empresa_timbre_recepcion(citacion) == 'SBH':
        salida = [
            documento for documento in salida
            if 'COM_ENT' not in ' '.join((str(documento.get(campo) or '') for campo in ('nombre', 'tipo'))).upper()
        ]
    return salida


def obtener_documentos_salida_terramar(citacion):
    """Alias de compatibilidad para el paquete documental de recepción."""
    return obtener_documentos_salida_recepcion(citacion)


def _documento_terramar_publico(citacion, documento, request=None):
    base_url = reverse(
        'ajax_operacion_planta_documento_terramar',
        args=[citacion.id, documento['key']],
    )
    view_url = f'{base_url}?version=original&accion=ver'
    download_url = f'{base_url}?version=original&accion=descargar'
    if request:
        view_url = request.build_absolute_uri(view_url)
        download_url = request.build_absolute_uri(download_url)
    return {
        key: value
        for key, value in {
            **documento,
            'view_url': view_url if documento.get('disponible') else '',
            'download_url': download_url if documento.get('disponible') else '',
        }.items()
        if not key.startswith('_')
    }


def _estado_timbrado_documentos_terramar(citacion, fuentes=None):
    fuentes = fuentes if fuentes is not None else obtener_documentos_salida_terramar(citacion)
    metadata = _leer_metadata_terramar(citacion, _campo_timbrado_recepcion(citacion))
    registros = metadata.get('documentos') if isinstance(metadata.get('documentos'), list) else []
    por_clave = {item.get('key'): item for item in registros if isinstance(item, dict) and item.get('key')}
    actuales = []
    for fuente in fuentes:
        registro = por_clave.get(fuente['key']) or {}
        vigente = bool(
            registro.get('source_hash')
            and registro.get('source_hash') == fuente.get('source_hash')
            and registro.get('stamp_version') == STAMP_VERSION
            and bool(registro.get('codigo_validacion'))
        )
        ruta_timbrada = registro.get('stamped_path') if vigente else ''
        timbrado_disponible = bool(
            ruta_timbrada
            and os.path.isfile(ruta_timbrada)
            and _ruta_documento_terramar_permitida(ruta_timbrada)
        )
        estado = registro.get('estado') if vigente else ''
        if timbrado_disponible:
            estado = 'TIMBRADO'
        elif fuente.get('disponible') and not fuente.get('formato_timbrable'):
            estado = 'NO_COMPATIBLE'
        elif not fuente.get('disponible'):
            estado = 'NO_DISPONIBLE'
        else:
            estado = 'PENDIENTE'
        actuales.append({
            **fuente,
            'estado_timbrado': estado,
            'timbrado_disponible': timbrado_disponible,
            'stamped_name': registro.get('stamped_name') if timbrado_disponible else '',
            'stamped_path': ruta_timbrada if timbrado_disponible else '',
            'stamped_hash': registro.get('stamped_hash') if timbrado_disponible else '',
            'fecha_timbrado': registro.get('fecha_timbrado') if vigente else '',
            'usuario_timbrado': registro.get('usuario') if vigente else '',
        })
    obligatorios_pendientes = [
        item for item in actuales
        if item.get('obligatorio') and item.get('estado_timbrado') != 'TIMBRADO'
    ]
    return {
        'metadata': metadata,
        'documentos': actuales,
        'obligatorios_pendientes': obligatorios_pendientes,
        'completo': bool(actuales) and not obligatorios_pendientes,
    }


def _payload_documentacion_terramar(citacion, request=None):
    fuentes = obtener_documentos_salida_terramar(citacion)
    estado_timbrado = _estado_timbrado_documentos_terramar(citacion, fuentes)
    validacion = _leer_metadata_terramar(citacion, CAMPO_DOCUMENTACION_TERRAMAR)
    documentos = []
    for item in estado_timbrado['documentos']:
        publico = _documento_terramar_publico(citacion, item, request)
        if item.get('timbrado_disponible'):
            stamped_url = reverse(
                'ajax_operacion_planta_documento_terramar',
                args=[citacion.id, item['key']],
            )
            stamped_url = f'{stamped_url}?version=timbrado&accion=descargar'
            publico['stamped_download_url'] = request.build_absolute_uri(stamped_url) if request else stamped_url
        else:
            publico['stamped_download_url'] = ''
        documentos.append(publico)
    antecedentes = [
        _documento_terramar_publico(citacion, item, request)
        for item in _documentos_fuente_terramar(citacion)
        if item.get('origen') == 'TICKET_PESAJE'
        and item.get('tipo') == 'Ticket Pesaje Entrada'
    ]
    return {
        'validada': bool(validacion.get('validada')),
        'usuario_validacion': validacion.get('usuario') or '',
        'fecha_validacion': validacion.get('fecha_hora') or '',
        'observacion_validacion': validacion.get('observacion') or '',
        'originales': [item for item in documentos if item.get('categoria') == 'original'],
        'tickets': [item for item in documentos if item.get('categoria') == 'ticket'],
        'antecedentes': antecedentes,
        'timbrados': [item for item in documentos if item.get('timbrado_disponible')],
        'obligatorios_pendientes': [item.get('nombre') for item in estado_timbrado['obligatorios_pendientes']],
        'timbrado_completo': estado_timbrado['completo'],
        'puede_validar_timbraje': not estado_timbrado['obligatorios_pendientes'],
        'total_documentos': len(documentos),
        'whatsapp_media_disponible': False,
    }


def _config_accion_toma_muestra(nombre_flujo, citacion=None):
    if citacion is not None and es_recepcion_new_jersey_p2(citacion):
        return {
            'tipo': 'analisis', 'accion_label': 'Toma de muestra',
            'estado_label': 'Muestra tomada', 'pendiente_label': 'Pendiente de toma de muestra',
            'mensaje_guardado': 'Muestra tomada.', 'log_operacion': 'MUESTRA_TOMADA',
            'log_mensaje': 'Muestra tomada en Toma de muestra',
            'mide_tiempo_toma_muestra': True,
        }
    flujo_normalizado = normalizar_nombre_flujo_operacion(nombre_flujo)
    es_recepcion_trasvasije = flujo_normalizado == normalizar_nombre_flujo_operacion('RECEPCION TRASVASIJE')
    es_recepcion_bodega_externa = flujo_normalizado == normalizar_nombre_flujo_operacion('RECEPCION BODEGA EXTERNA')
    if flujo_normalizado in {normalizar_nombre_flujo_operacion(flujo) for flujo in FLUJOS_TOMA_MUESTRA_VAPOR}:
        return {
            'tipo': 'vapor',
            'accion_label': 'Enviar a vapor',
            'estado_label': 'Camion enviado a vapor',
            'pendiente_label': 'Pendiente de envio a vapor',
            'mensaje_guardado': 'Camion enviado a vapor.',
            'log_operacion': 'TOMA_MUESTRA_ENVIA_VAPOR',
            'log_mensaje': 'Camion enviado a vapor en Toma de muestra',
            'mide_tiempo_toma_muestra': False,
        }
    if es_recepcion_trasvasije:
        return {
            'tipo': 'analisis',
            'accion_label': 'Toma de muestra',
            'estado_label': 'Muestra tomada',
            'pendiente_label': 'Pendiente de toma de muestra',
            'mensaje_guardado': 'Muestra tomada.',
            'log_operacion': 'MUESTRA_TOMADA',
            'log_mensaje': 'Muestra tomada en Toma de muestra',
            'mide_tiempo_toma_muestra': True,
        }
    return {
        'tipo': 'analisis',
        'accion_label': 'Enviar a analisis',
        'estado_label': 'Muestra enviada a analisis',
        'pendiente_label': 'Pendiente de envio a analisis',
        'mensaje_guardado': 'Muestra enviada a analisis.',
        'log_operacion': 'MUESTRA_A_ANALISIS',
        'log_mensaje': 'Muestra enviada a analisis en Toma de muestra',
        'mide_tiempo_toma_muestra': es_recepcion_bodega_externa,
    }


def _obtener_campo_toma_muestra_accion(citacion, usuario):
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=CAMPO_TOMA_MUESTRA_ACCION,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'CHECK',
            'CA_CETIQUETA': 'Accion toma de muestra',
            'CA_CPLACEMARK': 'Evento operacional de toma de muestra',
            'CA_BOBLIGATORIO': True,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        }
    )
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        campo.save(update_fields=['CA_BHABILITADO'])
    return campo


def _dato_toma_muestra_accion(citacion):
    return DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO__in=[CAMPO_TOMA_MUESTRA_ACCION, CAMPO_TOMA_MUESTRA_VAPOR_LEGACY]
    ).select_related('CAMP_NID').order_by('-id').first()


def _leer_metadata_toma_muestra_accion(citacion):
    dato = _dato_toma_muestra_accion(citacion)
    if not dato:
        return None
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return None
    if not isinstance(metadata, dict) or not (metadata.get('accion_registrada') or metadata.get('enviado_vapor')):
        return None
    if metadata.get('enviado_vapor') and not metadata.get('tipo_accion'):
        metadata['tipo_accion'] = 'vapor'
        metadata['mensaje'] = metadata.get('mensaje') or 'Camion enviado a vapor'
    metadata['dato_id'] = dato.id
    return metadata


def _actualizar_observacion_toma_muestra_accion(citacion, observacion):
    dato = _dato_toma_muestra_accion(citacion)
    if not dato:
        return
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return
    if not isinstance(metadata, dict):
        return
    metadata['observacion'] = str(observacion or '').strip()
    dato.DO_CVALOR = json.dumps(metadata, ensure_ascii=False)
    dato.save(update_fields=['DO_CVALOR'])


def _obtener_campo_observacion_etapa(citacion, usuario):
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=CAMPO_OBSERVACION_ETAPA,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'TEXTO',
            'CA_CETIQUETA': 'Observacion etapa operacional',
            'CA_CPLACEMARK': 'Observacion independiente por etapa de Operacion Planta',
            'CA_BOBLIGATORIO': False,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        }
    )
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        campo.save(update_fields=['CA_BHABILITADO'])
    return campo


def _metadata_observacion_etapa(citacion, paso_operacion, observacion, usuario):
    ahora = timezone.now()
    return {
        'citacion_id': citacion.id,
        'paso_operacion': str(paso_operacion or '').strip(),
        'observacion': str(observacion or '').strip(),
        'usuario_id': usuario.id,
        'usuario': usuario.username,
        'fecha_hora': timezone.localtime(ahora).strftime('%d/%m/%Y %H:%M'),
        'fecha_iso': ahora.isoformat(),
    }


def _registrar_observacion_etapa(citacion, paso_operacion, observacion, usuario):
    metadata = _metadata_observacion_etapa(citacion, paso_operacion, observacion, usuario)
    campo = _obtener_campo_observacion_etapa(citacion, usuario)
    DATO_OPERACION.objects.create(
        CI_NID=citacion,
        SC_NID=citacion.SC_NID,
        ET_NID=citacion.ETAPA_ACTUAL,
        CAMP_NID=campo,
        EP_NID=citacion.EP_NID,
        US_NID=usuario,
        DO_CVALOR=json.dumps(metadata, ensure_ascii=False),
        DO_FFECHAREGISTRO=timezone.now(),
    )
    return metadata


def _leer_metadata_observacion_etapa(citacion, paso_operacion):
    paso_operacion = str(paso_operacion or '').strip()
    if not paso_operacion:
        return None
    registros = DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO=CAMPO_OBSERVACION_ETAPA
    ).select_related('CAMP_NID', 'US_NID').order_by('-DO_FFECHAREGISTRO', '-id')
    for dato in registros:
        try:
            metadata = json.loads(dato.DO_CVALOR or '{}')
        except (TypeError, ValueError):
            continue
        if not isinstance(metadata, dict):
            continue
        if str(metadata.get('paso_operacion') or '').strip() == paso_operacion:
            return metadata
    return None


def _observacion_etapa_visible(citacion, paso_operacion):
    metadata = _leer_metadata_observacion_etapa(citacion, paso_operacion) or {}
    return str(metadata.get('observacion') or '').strip()


def _observacion_toma_muestra_visible(citacion, log_toma_muestra=None):
    observacion_log = _observacion_visible_operacion(
        PASO_TOMA_MUESTRA,
        log_toma_muestra.OPL_COBSERVACION if log_toma_muestra else ''
    )
    if observacion_log:
        return observacion_log

    observacion_independiente = _leer_metadata_observacion_etapa(citacion, PASO_TOMA_MUESTRA)
    if observacion_independiente is not None:
        return str(observacion_independiente.get('observacion') or '').strip()

    metadata = _leer_metadata_toma_muestra_accion(citacion) or {}
    return str(metadata.get('observacion') or '').strip()


def _insumo_operacion_planta(citacion):
    detalle = obtener_detalle_operacional_citacion(citacion)
    if detalle and detalle.CDO_CINSUMO:
        return detalle.CDO_CINSUMO
    citacion_item = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion).first()
    if citacion_item and citacion_item.IT_NID:
        return citacion_item.IT_NID.IT_CNOMBRE or ''
    return ''


def _codigo_sap_operacion_planta(citacion):
    detalle = obtener_detalle_operacional_citacion(citacion)
    if detalle and detalle.CDO_CCODIGO_SAP:
        return detalle.CDO_CCODIGO_SAP
    citacion_item = CITACION_ITEM.objects.select_related('IT_NID').filter(CI_NID=citacion).first()
    if citacion_item and citacion_item.IT_NID:
        return citacion_item.IT_NID.IT_CCODIGO or ''
    return ''


def _fecha_ingreso_operacion_planta(citacion):
    log_ingreso = SYSLOGGER.objects.filter(
        LOG_COPERACION='AUTORIZA_INGRESO_PLANTA',
        LOG_CADD1=str(citacion.id)
    ).order_by('-LOG_FFECHAREGISTRO').first()
    fecha = (
        log_ingreso.LOG_FFECHAREGISTRO if log_ingreso and log_ingreso.LOG_FFECHAREGISTRO
        else (citacion.CI_FFECHAINICIO or citacion.CI_FFECHACITACION)
    )
    if fecha and timezone.is_naive(fecha):
        fecha = timezone.make_aware(fecha, timezone.get_current_timezone())
    return timezone.localtime(fecha).strftime('%d/%m/%Y %H:%M') if fecha else ''


def _guia_operacion_planta_url(citacion, documentos_operacion):
    documento_guia = CITACION_DOCUMENTO.objects.filter(
        CI_NID=citacion,
        EP_NID=citacion.EP_NID,
        CD_CTIPO=CITACION_DOCUMENTO.TIPO_GUIA,
        CD_BACTIVO=True
    ).order_by('-CD_FFECHASUBIDA', '-id').first()
    if documento_guia:
        return reverse('expediente_citacion_documento_ver', args=[documento_guia.id])

    for documento in documentos_operacion:
        etiqueta = f"{documento.get('label', '')} {documento.get('nombre_archivo', '')}".lower()
        if 'guia' in etiqueta or 'Guía' in etiqueta:
            return documento.get('download_url') or ''
    return ''


def _toma_muestra_accion_guardada(citacion):
    return bool(_leer_metadata_toma_muestra_accion(citacion))


def _calidad_inicia_al_finalizar_toma_muestra(citacion):
    return (
        getattr(citacion, 'EP_NID_id', None) == ID_ACEITES_SBH
        and es_recepcion_bodega_externa_operacion(citacion)
    )


def _payload_toma_muestra_accion(citacion, nombre_flujo):
    config = _config_accion_toma_muestra(nombre_flujo, citacion)
    metadata = _leer_metadata_toma_muestra_accion(citacion)
    if not metadata:
        return {
            **config,
            'registrada': False,
            'usuario': '',
            'fecha': '',
            'observacion': '',
        }
    return {
        **config,
        'registrada': True,
        'tipo': metadata.get('tipo_accion') or config['tipo'],
        'usuario': metadata.get('usuario') or '',
        'fecha': metadata.get('fecha') or '',
        'observacion': metadata.get('observacion') or '',
        'mensaje': metadata.get('mensaje') or config['estado_label'],
    }


def _registrar_toma_muestra_accion(citacion, usuario, nombre_flujo, observacion=''):
    metadata_existente = _leer_metadata_toma_muestra_accion(citacion)
    if metadata_existente:
        if (
            es_recepcion_bodega_externa_operacion(citacion)
            and not _calidad_inicia_al_finalizar_toma_muestra(citacion)
        ):
            asegurar_calidad_iniciada(citacion, usuario)
        return metadata_existente

    config = _config_accion_toma_muestra(nombre_flujo, citacion)
    campo = _obtener_campo_toma_muestra_accion(citacion, usuario)
    fecha = timezone.localtime(timezone.now())
    metadata = {
        'accion_registrada': True,
        'tipo_accion': config['tipo'],
        'citacion_id': citacion.id,
        'paso_operacion': PASO_TOMA_MUESTRA,
        'mensaje': config['estado_label'],
        'observacion': observacion,
        'usuario_id': usuario.id,
        'usuario': usuario.username,
        'fecha': fecha.strftime('%d/%m/%Y %H:%M'),
        'fecha_iso': fecha.isoformat(),
        'fecha_fin': '',
        'fecha_fin_iso': '',
        'duracion_segundos': None,
        'duracion_legible': '',
        'usuario_fin': '',
    }
    dato, _ = DATO_OPERACION.objects.update_or_create(
        CI_NID=citacion,
        CAMP_NID=campo,
        defaults={
            'EP_NID': citacion.EP_NID,
            'US_NID': usuario,
            'SC_NID': citacion.SC_NID,
            'ET_NID': citacion.ETAPA_ACTUAL,
            'DO_CVALOR': json.dumps(metadata, ensure_ascii=False),
            'DO_NPESO': None,
            'DO_FFECHAREGISTRO': timezone.now(),
        }
    )
    metadata['dato_id'] = dato.id
    registrar_log_camion_no_planificado(
        usuario,
        citacion.EP_NID,
        config['log_operacion'],
        f'{config["log_mensaje"]} para citacion #{citacion.id}.',
        citacion.id,
        ''
    )
    if (
        es_recepcion_bodega_externa_operacion(citacion)
        and not _calidad_inicia_al_finalizar_toma_muestra(citacion)
    ):
        asegurar_calidad_iniciada(citacion, usuario)
    return metadata


def _payload_tiempo_toma_muestra(citacion, nombre_flujo):
    config = _config_accion_toma_muestra(nombre_flujo, citacion)
    metadata = _leer_metadata_toma_muestra_accion(citacion) or {}
    inicio = _parse_iso_operacion(metadata.get('fecha_iso'))
    if not inicio and metadata:
        dato = _dato_toma_muestra_accion(citacion)
        inicio = dato.DO_FFECHAREGISTRO if dato else None
        if inicio and timezone.is_naive(inicio):
            inicio = timezone.make_aware(inicio, timezone.get_current_timezone())
    fin = _parse_iso_operacion(metadata.get('fecha_fin_iso'))

    duracion_segundos = metadata.get('duracion_segundos')
    duracion_legible = metadata.get('duracion_legible') or ''
    if inicio:
        duracion = (fin or timezone.now()) - inicio
        if fin or duracion_segundos is None:
            duracion_segundos = max(int(duracion.total_seconds()), 0)
        if fin or not duracion_legible:
            duracion_legible = formatear_duracion_operacional(duracion)

    habilitado = bool(config.get('mide_tiempo_toma_muestra'))
    return {
        'habilitado': habilitado,
        'iniciada': bool(habilitado and inicio),
        'en_proceso': bool(habilitado and inicio and not fin),
        'finalizada': bool(habilitado and inicio and fin),
        'inicio_iso': inicio.isoformat() if inicio else '',
        'inicio_ms': int(inicio.timestamp() * 1000) if inicio else None,
        'inicio_legible': timezone.localtime(inicio).strftime('%d/%m/%Y %H:%M') if inicio else '',
        'fin_iso': fin.isoformat() if fin else '',
        'fin_legible': timezone.localtime(fin).strftime('%d/%m/%Y %H:%M') if fin else '',
        'duracion_segundos': duracion_segundos,
        'duracion_legible': duracion_legible,
        'usuario_inicio': metadata.get('usuario') or '',
        'usuario_fin': metadata.get('usuario_fin') or '',
    }


def _finalizar_tiempo_toma_muestra(citacion, usuario, nombre_flujo):
    config = _config_accion_toma_muestra(nombre_flujo, citacion)
    if not config.get('mide_tiempo_toma_muestra'):
        return None

    dato = _dato_toma_muestra_accion(citacion)
    metadata = _leer_metadata_toma_muestra_accion(citacion)
    if not dato or not metadata:
        raise ValueError(TOMA_MUESTRA_ACCION_REQUIRED_MESSAGE)
    if metadata.get('fecha_fin_iso'):
        return _payload_tiempo_toma_muestra(citacion, nombre_flujo)

    inicio = _parse_iso_operacion(metadata.get('fecha_iso'))
    if not inicio and dato.DO_FFECHAREGISTRO:
        inicio = dato.DO_FFECHAREGISTRO
        if timezone.is_naive(inicio):
            inicio = timezone.make_aware(inicio, timezone.get_current_timezone())
    if not inicio:
        raise ValueError('La fecha de inicio de la toma de muestra no es valida.')

    fin = timezone.now()
    duracion = fin - inicio
    metadata.update({
        'fecha_fin': timezone.localtime(fin).strftime('%d/%m/%Y %H:%M'),
        'fecha_fin_iso': fin.isoformat(),
        'duracion_segundos': max(int(duracion.total_seconds()), 0),
        'duracion_legible': formatear_duracion_operacional(duracion),
        'usuario_fin': usuario.username,
        'usuario_fin_id': usuario.id,
    })
    dato.DO_CVALOR = json.dumps(metadata, ensure_ascii=False)
    dato.save(update_fields=['DO_CVALOR'])
    return _payload_tiempo_toma_muestra(citacion, nombre_flujo)


def _obtener_campo_tiempo_vapor(citacion, usuario):
    campo, _ = CAMPO.objects.get_or_create(
        EP_NID=citacion.EP_NID,
        CA_CCODIGO=CAMPO_TOMA_MUESTRA_TIEMPO_VAPOR,
        defaults={
            'US_NID': usuario,
            'CA_CTIPO': 'TEXTO',
            'CA_CETIQUETA': 'Tiempo vapor',
            'CA_CPLACEMARK': 'Metadata operacional de tiempo en vapor',
            'CA_BOBLIGATORIO': False,
            'CA_BHABILITADO': True,
            'CA_BASIGNARVALOR': False,
        }
    )
    cambios = []
    if not campo.CA_BHABILITADO:
        campo.CA_BHABILITADO = True
        cambios.append('CA_BHABILITADO')
    if campo.CA_CTIPO != 'TEXTO':
        campo.CA_CTIPO = 'TEXTO'
        cambios.append('CA_CTIPO')
    if cambios:
        campo.save(update_fields=cambios)
    return campo


def _dato_tiempo_vapor(citacion):
    return DATO_OPERACION.objects.filter(
        CI_NID=citacion,
        CAMP_NID__CA_CCODIGO=CAMPO_TOMA_MUESTRA_TIEMPO_VAPOR
    ).select_related('CAMP_NID').order_by('-id').first()


def _leer_metadata_tiempo_vapor(citacion):
    dato = _dato_tiempo_vapor(citacion)
    if not dato:
        return None
    try:
        metadata = json.loads(dato.DO_CVALOR or '{}')
    except (TypeError, ValueError):
        return None
    if not isinstance(metadata, dict):
        return None
    metadata['dato_id'] = dato.id
    return metadata


def _metadata_tiempo_vapor_desde_accion(citacion):
    metadata_accion = _leer_metadata_toma_muestra_accion(citacion)
    if not metadata_accion:
        return None
    if str(metadata_accion.get('tipo_accion') or '').strip().lower() != 'vapor':
        return None

    inicio = metadata_accion.get('fecha_iso') or ''
    if not inicio:
        dato_accion = _dato_toma_muestra_accion(citacion)
        if dato_accion and dato_accion.DO_FFECHAREGISTRO:
            inicio = dato_accion.DO_FFECHAREGISTRO.isoformat()
    if not inicio:
        return None

    return {
        'inicio_vapor': inicio,
        'fin_vapor': '',
        'duracion_segundos': None,
        'duracion_legible': '',
        'usuario_inicio': metadata_accion.get('usuario') or '',
        'usuario_fin': '',
        'usuario_inicio_id': metadata_accion.get('usuario_id'),
        'usuario_fin_id': None,
        'citacion_id': citacion.id,
        'paso_operacion': PASO_TOMA_MUESTRA,
        'origen_inicio': 'accion_toma_muestra',
    }


def _guardar_metadata_tiempo_vapor(citacion, usuario, metadata):
    campo = _obtener_campo_tiempo_vapor(citacion, usuario)
    dato, _ = DATO_OPERACION.objects.update_or_create(
        CI_NID=citacion,
        CAMP_NID=campo,
        defaults={
            'EP_NID': citacion.EP_NID,
            'US_NID': usuario,
            'SC_NID': citacion.SC_NID,
            'ET_NID': citacion.ETAPA_ACTUAL,
            'DO_CVALOR': json.dumps(metadata, ensure_ascii=False),
            'DO_NPESO': None,
            'DO_FFECHAREGISTRO': timezone.now(),
        }
    )
    metadata['dato_id'] = dato.id
    return metadata


def _payload_tiempo_vapor(citacion):
    """
    Construye el estado actual del tiempo de vapor para una citación.

    El estado se obtiene únicamente desde el registro específico del
    cronómetro de vapor. La Acción operativa de enviar a vapor no debe
    considerarse como inicio automático del contador.
    """
    metadata = _leer_metadata_tiempo_vapor(citacion) or {}

    inicio = _parse_iso_operacion(metadata.get('inicio_vapor'))
    fin = _parse_iso_operacion(metadata.get('fin_vapor'))

    duracion_segundos = metadata.get('duracion_segundos')
    duracion_legible = metadata.get('duracion_legible') or ''

    if inicio:
        if fin:
            duracion_calculada = fin - inicio
        else:
            duracion_calculada = timezone.now() - inicio

        if duracion_segundos is None:
            duracion_segundos = max(
                int(duracion_calculada.total_seconds()),
                0,
            )

        if not duracion_legible:
            duracion_legible = formatear_duracion_operacional(
                duracion_calculada
            )

    return {
        'inicio_vapor': metadata.get('inicio_vapor') or '',
        'inicio_vapor_legible': (
            timezone.localtime(inicio).strftime('%d/%m/%Y %H:%M')
            if inicio
            else ''
        ),
        'fin_vapor': metadata.get('fin_vapor') or '',
        'fin_vapor_legible': (
            timezone.localtime(fin).strftime('%d/%m/%Y %H:%M')
            if fin
            else ''
        ),
        'duracion_segundos': duracion_segundos,
        'duracion_legible': duracion_legible,
        'usuario_inicio': metadata.get('usuario_inicio') or '',
        'usuario_fin': metadata.get('usuario_fin') or '',
        'en_proceso': bool(inicio and not fin),
        'finalizada': bool(inicio and fin),
        'iniciada': bool(inicio),
    }

def _iniciar_tiempo_vapor(citacion, usuario):
    """
    Inicia el contador de vapor para la citación actual.

    El contador solo se considera iniciado cuando existe metadata específica
    guardada por este proceso. La Acción operativa "enviar a vapor" no debe
    iniciar ni bloquear automáticamente el cronómetro.
    """
    metadata = _leer_metadata_tiempo_vapor(citacion) or {}

    if metadata.get('fin_vapor'):
        raise ValueError('El tiempo de vapor ya fue finalizado.')

    if metadata.get('inicio_vapor'):
        raise ValueError(
            'La citación ya tiene un tiempo de vapor activo.'
        )

    ahora = timezone.now()

    metadata = {
        'inicio_vapor': ahora.isoformat(),
        'fin_vapor': '',
        'duracion_segundos': None,
        'duracion_legible': '',
        'usuario_inicio': usuario.username,
        'usuario_fin': '',
        'usuario_inicio_id': usuario.id,
        'usuario_fin_id': None,
        'citacion_id': citacion.id,
        'paso_operacion': PASO_TOMA_MUESTRA,
    }

    metadata = _guardar_metadata_tiempo_vapor(
        citacion=citacion,
        usuario=usuario,
        metadata=metadata,
    )

    OPERACION_PLANTA_LOG.objects.create(
        US_NID=usuario,
        EP_NID=citacion.EP_NID,
        PL_NID=citacion.PL_NID,
        CI_NID=citacion,
        OPL_CPASO='TOMA_MUESTRA_INICIO_VAPOR',
        OPL_CPERFIL_RESPONSABLE='ASISTENTE C D',
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        OPL_COBSERVACION='Inicio manual del tiempo de vapor',
    )

    return metadata

def _finalizar_tiempo_vapor(citacion, usuario):
    """
    Finaliza el contador de vapor de la citación actual.

    Solo utiliza la metadata específica del cronómetro de vapor.
    La Acción operativa "enviar a vapor" no se considera como inicio
    válido del contador.
    """
    metadata = _leer_metadata_tiempo_vapor(citacion)

    if not metadata or not metadata.get('inicio_vapor'):
        raise ValueError(
            'Debe iniciar el tiempo de vapor antes de finalizar.'
        )

    if metadata.get('fin_vapor'):
        return metadata, None

    inicio = _parse_iso_operacion(metadata.get('inicio_vapor'))

    if not inicio:
        raise ValueError(
            'La fecha de inicio del tiempo de vapor no es válida.'
        )

    ahora = timezone.now()
    duracion = ahora - inicio

    metadata.update({
        'fin_vapor': ahora.isoformat(),
        'duracion_segundos': max(
            int(duracion.total_seconds()),
            0,
        ),
        'duracion_legible': formatear_duracion_operacional(
            duracion
        ),
        'usuario_fin': usuario.username,
        'usuario_fin_id': usuario.id,
    })

    metadata = _guardar_metadata_tiempo_vapor(
        citacion=citacion,
        usuario=usuario,
        metadata=metadata,
    )

    payload_vapor = _payload_tiempo_vapor(citacion)

    observacion = (
        f'Inicio vapor: '
        f'{payload_vapor.get("inicio_vapor_legible") or "Sin inicio"} | '
        f'Fin vapor: '
        f'{timezone.localtime(ahora).strftime("%d/%m/%Y %H:%M")} | '
        f'Duracion: '
        f'{metadata.get("duracion_legible") or "No disponible"} | '
        f'Usuario inicio: '
        f'{metadata.get("usuario_inicio") or ""} | '
        f'Usuario fin: '
        f'{metadata.get("usuario_fin") or ""}'
    )

    log = OPERACION_PLANTA_LOG.objects.create(
        US_NID=usuario,
        EP_NID=citacion.EP_NID,
        PL_NID=citacion.PL_NID,
        CI_NID=citacion,
        OPL_CPASO='TOMA_MUESTRA_FIN_VAPOR',
        OPL_CPERFIL_RESPONSABLE='ASISTENTE C D',
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        OPL_COBSERVACION=observacion,
    )

    return metadata, log

