def OBTENER_EMPRESA_USUARIO(request):
    """
    Obtiene información de la empresa activa del usuario.

    Compatible con usuarios multiempresa.
    """

    try:

        Empresa = Verificar_empresa(request)

        # Si no hay empresa activa seleccionada
        if Empresa is None:
            return JsonResponse({
                'empresa': False,
                'lista_empresas': [],
                'perm_act': False
            })

        # Obtener nombre de empresa activa
        empresa = EMPRESA.objects.get(id=Empresa).EP_CRAZONSOCIAL

        # Obtener solo empresas asignadas al usuario
        lista_empresas = list(
            USERS_EMPRESA.objects.filter(
                US_NID=request.user
            ).select_related('EP_NID').values_list(
                'EP_NID__EP_CRAZONSOCIAL',
                'EP_NID__id'
            )
        )

        # Validación de permisos navbar
        perm_act = validar_perfiles_activos(request.user.id, 'nav')

        return JsonResponse({
            'empresa': empresa,
            'lista_empresas': lista_empresas,
            'perm_act': perm_act
        })

    except Exception as e:
        print(e)

        return JsonResponse({
            'empresa': False,
            'lista_empresas': [],
            'perm_act': False
        })

def ACTUALIZAR_EMPRESA_USUARIO(request,ep_id):
    try:
        acceso = USERS_EMPRESA.objects.filter(
            US_NID_id=request.user.id,
            EP_NID_id=ep_id
        ).exists()

        if not acceso:
            messages.error(request, 'No tiene acceso a la empresa seleccionada.')
            return redirect('/seleccionar_empresa/')

        request.session['empresa_id'] = ep_id
        next_url = request.META.get('HTTP_REFERER', '/') or '/'
        separator = '&' if '?' in next_url else '?'
        messages.success(request, 'Empresa actualizada correctamente')
        return redirect(f'{next_url}{separator}{EMPRESA_ACTIVA_PARAM}={ep_id}')
    except Exception as e:
        print(e)
        messages.error(request, f'Error, {str(e)}')
        return redirect(request.META.get('HTTP_REFERER', '/'))

##########################################################################
#####################  VALIDACIÓN DE EMPRESA ACTIVA  #####################
##########################################################################

def Verificar_empresa(request):
    """
    Retorna el ID de la empresa activa del usuario.

    Flujo:
    - Si existe empresa activa en session y el usuario tiene acceso, retorna esa empresa.
    - Si el usuario tiene solo una empresa asignada, la guarda en session y la retorna.
    - Si el usuario tiene más de una empresa asignada, retorna None para forzar selección.
    - Si el usuario no tiene empresa asignada, retorna None.
    """

    try:

        # Prioridad: empresa de la ventana/pestaña actual.
        empresa_id = obtener_empresa_request_id(request)

        if empresa_id:
            if usuario_tiene_empresa(request, empresa_id):
                request.session['empresa_id'] = empresa_id
                return empresa_id

            messages.error(request, 'No tiene acceso a la empresa seleccionada.')
            return None

        # Fallback: empresa activa en session para compatibilidad.
        empresa_id = request.session.get('empresa_id')
        if empresa_id is not None:
            try:
                empresa_id = int(empresa_id)
            except (TypeError, ValueError):
                empresa_id = None
                request.session.pop('empresa_id', None)

        # Validar acceso a empresa activa
        if empresa_id:
            if usuario_tiene_empresa(request, empresa_id):
                request.session['empresa_id'] = empresa_id
                request.session.modified = True
                return empresa_id

            # Si perdió acceso, limpiar session
            request.session.pop('empresa_id', None)

        # Obtener todas las empresas del usuario
        empresas_usuario = USERS_EMPRESA.objects.filter(
            US_NID=request.user
        ).select_related('EP_NID')

        # Usuario con una sola empresa
        if empresas_usuario.count() == 1:

            empresa_id = int(empresas_usuario.first().EP_NID_id)

            request.session['empresa_id'] = empresa_id
            request.session.modified = True

            return empresa_id

        # Usuario con múltiples empresas
        if empresas_usuario.count() > 1:
            return None

        # Usuario sin empresa
        messages.error(request, 'Solicite al administrador que asigne su empresa')
        return None

    except Exception as e:
        print(e)
        messages.error(request, 'Solicite al administrador que asigne su empresa')
        return None


def _empresa_control_flota_o_404(request):
    """Empresa activa, validada nuevamente contra USERS_EMPRESA."""
    empresa_id = Verificar_empresa(request)
    relacion = get_object_or_404(
        USERS_EMPRESA,
        US_NID=request.user,
        EP_NID_id=empresa_id if empresa_id is not None else -1,
    )
    return relacion.EP_NID_id


def _objeto_control_flota_o_404(request, modelo, **filtros):
    empresa_id = _empresa_control_flota_o_404(request)
    return get_object_or_404(modelo, EP_NID_id=empresa_id, **filtros)


def _conductor_control_flota_o_404(request, pk):
    """Autoriza detalle por pertenencia operacional sólo para SBH."""
    empresa_id = _empresa_control_flota_o_404(request)
    if empresa_id != ID_ACEITES_SBH:
        return get_object_or_404(CONDUCTOR, pk=pk, EP_NID_id=empresa_id)
    return get_object_or_404(
        CONDUCTOR,
        pk=pk,
        empresas_operacionales__EP_NID_id=ID_ACEITES_SBH,
        empresas_operacionales__CEM_BHABILITADO=True,
    )

