@require_POST
@csrf_protect
def ajax_operacion_planta_resolver_revision_calidad(request, pk):
    empresa_id = Verificar_empresa(request)
    if empresa_id is None:
        return JsonResponse(
            {'success': False, 'message': 'Debe seleccionar una empresa.'},
            status=400,
        )

    decision = str(request.POST.get('decision') or '').strip().upper()
    comentario = str(request.POST.get('comentario') or '').strip()
    if decision not in {
        RESULTADO_CALIDAD_OPERACION.Estado.APROBADO,
        RESULTADO_CALIDAD_OPERACION.Estado.RECHAZADO,
    }:
        return JsonResponse(
            {'success': False, 'message': 'Decision de revision no valida.'},
            status=400,
        )
    if not comentario:
        return JsonResponse(
            {'success': False, 'message': 'Los comentarios de revision son obligatorios.'},
            status=400,
        )

    try:
        with transaction.atomic():
            citacion = CITACION.objects.select_for_update().select_related(
                'EP_NID', 'PL_NID', 'SC_NID'
            ).get(
                pk=pk,
                EP_NID_id=empresa_id,
                CI_BHABILITADO=True,
            )
            if not usuario_puede_paso_operacion(request.user, ['CALIDAD']):
                return JsonResponse(
                    {'success': False, 'message': 'Solo el perfil CALIDAD puede resolver esta revision.'},
                    status=403,
                )
            if not (es_flujo_recepcion_estanque_sbh_calidad(citacion) or es_recepcion_new_jersey_p2(citacion)):
                return JsonResponse(
                    {'success': False, 'message': 'La revision manual no aplica a este flujo.'},
                    status=409,
                )
            if not citacion_habilitada_operacion(citacion):
                return JsonResponse(
                    {'success': False, 'message': 'La citacion no esta habilitada para Operacion Planta.'},
                    status=409,
                )

            registro = RESULTADO_CALIDAD_OPERACION.objects.select_for_update().get(
                CI_NID=citacion
            )
            if (
                registro.RCO_CESTADO
                != RESULTADO_CALIDAD_OPERACION.Estado.RECHAZADO_PENDIENTE_REVISION
            ):
                return JsonResponse(
                    {
                        'success': False,
                        'message': 'La revision ya fue resuelta o el estado actual no permite esta accion.',
                    },
                    status=409,
                )

            evento_bot = EVENTO_INTEGRACION_CALIDAD.objects.select_related(
                'RCO_NID'
            ).filter(
                CI_NID=citacion,
                RCO_NID=registro,
                EIC_CESTADO_SOLICITADO=RESULTADO_CALIDAD_OPERACION.Estado.RECHAZADO,
                EIC_CORIGEN=RESULTADO_CALIDAD_OPERACION.Origen.EXCEL_CALIDAD,
                EIC_CESTADO_PROCESAMIENTO=EVENTO_INTEGRACION_CALIDAD.EstadoProcesamiento.PROCESADO,
                EIC_BDUPLICADO=False,
            ).order_by('-EIC_FRECEPCION', '-id').first()
            if not es_rechazo_bot_revisable(citacion, evento_bot):
                return JsonResponse(
                    {'success': False, 'message': 'No existe evidencia valida del rechazo BOT revisable.'},
                    status=409,
                )

            registro, cambiado = procesar_resultado_calidad(
                citacion,
                decision,
                RESULTADO_CALIDAD_OPERACION.Origen.REVISION_MANUAL,
                observacion=comentario,
                usuario=request.user,
            )
            if not cambiado:
                return JsonResponse(
                    {'success': False, 'message': 'La revision ya fue resuelta.'},
                    status=409,
                )
            metadata = serializar_resultado_calidad(registro)
    except CITACION.DoesNotExist:
        return JsonResponse(
            {'success': False, 'message': 'Citacion no encontrada.'},
            status=404,
        )
    except RESULTADO_CALIDAD_OPERACION.DoesNotExist:
        return JsonResponse(
            {'success': False, 'message': 'No existe un resultado de calidad para revisar.'},
            status=409,
        )
    except ValueError as exc:
        return JsonResponse({'success': False, 'message': str(exc)}, status=409)

    return JsonResponse({
        'success': True,
        'message': (
            'Resultado aprobado manualmente.'
            if decision == RESULTADO_CALIDAD_OPERACION.Estado.APROBADO
            else 'Rechazo definitivo confirmado.'
        ),
        'resultado_calidad': metadata,
        'cambiado': True,
    })


def ajax_operacion_planta_guardar_preparacion_descarga(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)

    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'}, status=400)

    try:
        citacion = CITACION.objects.select_related('EP_NID', 'PL_NID', 'SC_NID').get(
            pk=pk,
            EP_NID_id=Empresa,
            CI_BHABILITADO=True
        )
    except CITACION.DoesNotExist:
        return JsonResponse({'success': False, 'message': 'Citacion no encontrada.'}, status=404)

    if not citacion_habilitada_operacion(citacion):
        return JsonResponse({'success': False, 'message': 'La citacion aun no esta habilitada para Operacion Planta.'}, status=400)

    if not _leer_metadata_resultado_calidad(citacion):
        return JsonResponse({'success': False, 'message': 'No existe resultado de calidad registrado para revisar.'}, status=400)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, responsables_paso, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    if paso_actual_visible != PASO_RESULTADO_CALIDAD:
        return JsonResponse({
            'success': False,
            'message': f'Solo puede guardar durante la etapa activa: {PASO_RESULTADO_CALIDAD}.'
        }, status=409)

    if not usuario_puede_paso_operacion(request.user, responsables_paso):
        return JsonResponse({
            'success': False,
            'message': f'Solo lectura: este paso corresponde a {" / ".join(responsables_paso)}'
        }, status=403)

    sitio_descarga = request.POST.get('sitio_descarga')
    bomba_descarga = request.POST.get('bomba_descarga')
    estanque_destino = request.POST.get('estanque_destino')
    observaciones_descarga = request.POST.get('observaciones_descarga')

    try:
        with transaction.atomic():
            metadata = _registrar_preparacion_descarga(
                citacion,
                request.user,
                sitio_descarga,
                bomba_descarga,
                estanque_destino,
                observaciones_descarga
            )
            log = OPERACION_PLANTA_LOG.objects.create(
                US_NID=request.user,
                EP_NID=citacion.EP_NID,
                PL_NID=citacion.PL_NID,
                CI_NID=citacion,
                OPL_CPASO=PASO_RESULTADO_CALIDAD,
                OPL_CPERFIL_RESPONSABLE=' / '.join(responsables_paso),
                OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
                OPL_COBSERVACION=metadata.get('observaciones_descarga') or ''
            )
    except ValueError as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=400)
    except Exception as e:
        return JsonResponse({'success': False, 'message': f'No fue posible guardar preparacion de descarga: {str(e)}'}, status=500)

    return JsonResponse({
        'success': True,
        'message': 'Resultado confirmado y descarga preparada.',
        'preparacion_descarga': metadata,
        'paso': PASO_RESULTADO_CALIDAD,
        'usuario': request.user.username,
        'fecha': timezone.localtime(log.OPL_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M')
    })


def _obtener_citacion_operacion_planta_ajax(request, pk):
    Empresa = Verificar_empresa(request)
    if Empresa is None:
        if _pk_corresponde_recepcion_terramar(pk):
            return None, JsonResponse({
                'success': False,
                'message': 'No tiene acceso a la empresa Terramar de esta citación.'
            }, status=403)
        return None, JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'}, status=400)
    try:
        citacion = CITACION.objects.select_related('EP_NID', 'PL_NID', 'SC_NID').get(
            pk=pk,
            EP_NID_id=Empresa,
            CI_BHABILITADO=True
        )
    except CITACION.DoesNotExist:
        return None, JsonResponse({'success': False, 'message': 'Citacion no encontrada.'}, status=404)
    if not citacion_habilitada_operacion(citacion):
        return None, JsonResponse({'success': False, 'message': 'La citacion aun no esta habilitada para Operacion Planta.'}, status=400)
    if request.method == 'POST' and operacion_planta_esta_terminada(citacion):
        return None, JsonResponse({
            'success': False,
            'message': 'Operacion terminada: el historial esta disponible en modo solo lectura.',
        }, status=409)
    return citacion, None


def _validar_citacion_terramar_etapa2(request, pk, responsables=None):
    if not request.user.is_authenticated or not request.user.is_active:
        return None, JsonResponse({'success': False, 'message': 'Usuario no autenticado o inactivo.'}, status=403)
    if not usuario_es_operacion_planta(request.user):
        return None, JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)
    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return None, error_response
    if not aplica_timbraje_recepcion(citacion):
        return None, JsonResponse({'success': False, 'message': 'Esta accion solo aplica a Recepciones Terramar o SBH.'}, status=404)
    if not _usuario_tiene_acceso_empresa(request.user, citacion.EP_NID_id):
        return None, JsonResponse({'success': False, 'message': 'No tiene acceso a la empresa de la citacion.'}, status=403)
    if responsables and not usuario_puede_paso_operacion(request.user, responsables):
        return None, JsonResponse({
            'success': False,
            'message': f'Solo lectura: esta accion corresponde a {" / ".join(responsables)}.',
        }, status=403)
    return citacion, None


def _paso_activo_es(citacion, paso):
    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    return obtener_paso_activo_operacion(citacion, pasos_config)[0] == paso


def _configuracion_timbrado_recepcion(citacion):
    """Resuelve etapa y perfil autorizados sin ampliar el alcance de cada flujo."""
    paso_activo, _, _ = obtener_paso_activo_operacion(citacion)
    if es_recepcion_terramar_principal(citacion) and paso_activo == PASO_DOCUMENTACION_TERRAMAR:
        return {
            'paso': PASO_DOCUMENTACION_TERRAMAR,
            'responsables': [PERFIL_TERRAMAR_ASISTENTE_RECEPCION],
            'requiere_documentacion_validada': False,
        }
    if paso_activo == PASO_AUTORIZAR_SALIDA and not es_recepcion_terramar_principal(citacion):
        return {
            'paso': PASO_AUTORIZAR_SALIDA,
            'responsables': (
                [PERFIL_TERRAMAR_ASISTENTE_DESPACHO]
                if _empresa_timbre_recepcion(citacion) == 'TERRAMAR'
                else ['ASISTENTE DE RECEPCION']
            ),
            'requiere_documentacion_validada': _empresa_timbre_recepcion(citacion) == 'TERRAMAR',
        }
    return None


def ajax_operacion_planta_validar_documentacion_terramar(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    citacion, error_response = _validar_citacion_terramar_etapa2(
        request,
        pk,
        [PERFIL_TERRAMAR_ASISTENTE_RECEPCION],
    )
    if error_response:
        return error_response
    validada = str(request.POST.get('documentacion_validada') or '').lower() in {'1', 'true', 'on', 'si'}
    if not validada:
        return JsonResponse({'success': False, 'message': 'Debe marcar He validado la documentacion.'}, status=400)
    observacion = str(request.POST.get('observacion') or '').strip()

    with transaction.atomic():
        citacion = _recargar_citacion_bloqueada_operacion(citacion)
        if OPERACION_PLANTA_LOG.objects.filter(
            CI_NID=citacion,
            OPL_CPASO=PASO_DOCUMENTACION_TERRAMAR,
            OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        ).exists():
            return JsonResponse({'success': False, 'message': 'La documentacion ya fue validada.'}, status=409)
        if not _paso_activo_es(citacion, PASO_DOCUMENTACION_TERRAMAR):
            return JsonResponse({'success': False, 'message': 'Documentacion no es la etapa activa.'}, status=409)
        es_flujo_principal = es_recepcion_terramar_principal(citacion)
        if es_flujo_principal:
            if not _ticket_pesaje_obligatorio_guardado(citacion, 'Pesaje Salida'):
                return JsonResponse({
                    'success': False,
                    'message': 'El ticket de Pesaje Salida es obligatorio para autorizar la salida.',
                }, status=409)
            estado_timbrado = _estado_timbrado_documentos_terramar(citacion)
            if estado_timbrado['obligatorios_pendientes']:
                pendientes = ', '.join(
                    item.get('nombre') or 'Documento obligatorio'
                    for item in estado_timbrado['obligatorios_pendientes']
                )
                return JsonResponse({
                    'success': False,
                    'message': f'Debe timbrar los documentos obligatorios antes de validar: {pendientes}.',
                }, status=409)
        ahora = timezone.now()
        metadata = {
            'validada': True,
            'usuario_id': request.user.id,
            'usuario': request.user.username,
            'fecha_iso': ahora.isoformat(),
            'fecha_hora': timezone.localtime(ahora).strftime('%d/%m/%Y %H:%M'),
            'observacion': observacion,
            'citacion_id': citacion.id,
            'paso_operacion': PASO_DOCUMENTACION_TERRAMAR,
        }
        if es_flujo_principal:
            metadata.update({
                'salida_autorizada': True,
                'accion': 'AUTORIZA_SALIDA',
                'usuario_autorizacion_id': request.user.id,
                'usuario_autorizacion': request.user.username,
                'fecha_autorizacion_iso': ahora.isoformat(),
                'fecha_autorizacion': timezone.localtime(ahora).strftime('%d/%m/%Y %H:%M'),
            })
        _guardar_metadata_terramar(
            citacion,
            request.user,
            CAMPO_DOCUMENTACION_TERRAMAR,
            'Validacion documental Terramar',
            metadata,
        )
        log = OPERACION_PLANTA_LOG.objects.create(
            US_NID=request.user,
            EP_NID=citacion.EP_NID,
            PL_NID=citacion.PL_NID,
            CI_NID=citacion,
            OPL_CPASO=PASO_DOCUMENTACION_TERRAMAR,
            OPL_CPERFIL_RESPONSABLE=PERFIL_TERRAMAR_ASISTENTE_RECEPCION,
            OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
            OPL_COBSERVACION=observacion,
            OPL_FFECHAREGISTRO=ahora,
        )
        registrar_log_camion_no_planificado(
            request.user,
            citacion.EP_NID,
            LOG_AUTORIZA_SALIDA_TERRAMAR if es_flujo_principal else LOG_DOCUMENTACION_TERRAMAR,
            (
                f'Salida autorizada al completar Documentacion para citacion Terramar #{citacion.id}.'
                if es_flujo_principal
                else f'Documentacion validada para citacion Terramar #{citacion.id}.'
            ),
            citacion.id,
            observacion[:128],
        )
    mensaje = (
        'Salida autorizada. La citacion avanzo directamente a Confirmar Salida.'
        if es_flujo_principal
        else 'Documentacion validada. La citacion avanzo a Autorizar Salida.'
    )
    return JsonResponse({
        'success': True,
        'message': mensaje,
        'salida_autorizada': es_flujo_principal,
        'paso': PASO_DOCUMENTACION_TERRAMAR,
        'usuario': request.user.username,
        'fecha': timezone.localtime(log.OPL_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M'),
    })


def _nombre_timbrado_terramar(documento):
    base, extension = os.path.splitext(documento.get('nombre') or 'documento')
    base = get_valid_filename(base)[:80] or 'documento'
    base = f'{base}_v{STAMP_VERSION}'
    extension = extension.lower()
    if extension not in {'.pdf', '.png', '.jpg', '.jpeg', '.tif', '.tiff'}:
        extension = '.pdf'
    return f'{base}_{documento["key"]}_{documento.get("source_hash", "")[:12]}_timbrado{extension}'


def _lineas_timbre_recepcion(citacion, usuario, fecha_local):
    nombre_usuario = usuario.get_full_name().strip() or usuario.username
    razon_social, rut = _datos_empresa_timbre(citacion)
    return [
        'ÁREA DE RECEPCIÓN',
        'Oficina de Operaciones',
        fecha_local.strftime('%d/%m/%Y %H:%M'),
        nombre_usuario,
        razon_social,
        rut,
    ]


def _lineas_timbre_terramar(usuario, fecha_local):
    """Compatibilidad para llamadas históricas."""
    nombre_usuario = usuario.get_full_name().strip() or usuario.username
    return ['ÁREA DE RECEPCIÓN', 'Oficina de Operaciones', fecha_local.strftime('%d/%m/%Y %H:%M'), nombre_usuario, 'Terramar Chile SpA', '77.620.020-4']


def _procesar_documentos_timbrados_terramar(citacion, usuario):
    fuentes = obtener_documentos_salida_terramar(citacion)
    estado_previo = _estado_timbrado_documentos_terramar(citacion, fuentes)
    previos = {
        item.get('key'): item
        for item in estado_previo['metadata'].get('documentos', [])
        if isinstance(item, dict) and item.get('key')
    }
    codigos_usados = {
        item.get('codigo_validacion')
        for item in previos.values()
        if item.get('codigo_validacion')
    }
    ahora = timezone.now()
    fecha_local = timezone.localtime(ahora)
    destino_root = os.path.join(
        settings.MEDIA_ROOT,
        'documentos_citaciones',
        f'CITACION_{citacion.id}',
        'timbrados',
    )
    documentos = []
    generados = 0
    reutilizados = 0
    for fuente in fuentes:
        previo = previos.get(fuente['key']) or {}
        previo_vigente = (
            previo.get('source_hash') == fuente.get('source_hash')
            and previo.get('stamp_version') == STAMP_VERSION
            and bool(previo.get('codigo_validacion'))
        )
        ruta_previa = previo.get('stamped_path') if previo_vigente else ''
        if (
            ruta_previa
            and os.path.isfile(ruta_previa)
            and _ruta_documento_terramar_permitida(ruta_previa)
        ):
            documentos.append(previo)
            reutilizados += 1
            continue

        codigo_validacion = secrets.token_hex(12).upper()
        while codigo_validacion in codigos_usados:
            codigo_validacion = secrets.token_hex(12).upper()
        codigos_usados.add(codigo_validacion)
        registro = {
            'key': fuente['key'],
            'codigo_validacion': codigo_validacion,
            'citacion_id': citacion.id,
            'empresa_id': citacion.EP_NID_id,
            'source_ref': fuente['source_ref'],
            'source_hash': fuente.get('source_hash') or '',
            'source_name': fuente.get('nombre') or '',
            'source_mime': fuente.get('mime') or '',
            'origen': fuente.get('origen') or '',
            'obligatorio': bool(fuente.get('obligatorio')),
            'stamp_version': STAMP_VERSION,
            'usuario_id': usuario.id,
            'usuario': usuario.username,
            'fecha_iso': ahora.isoformat(),
            'fecha_timbrado': fecha_local.strftime('%d/%m/%Y %H:%M'),
            'ubicacion_timbre': 'Esquina inferior derecha, margen proporcional, sello rectangular negro.',
        }
        if not fuente.get('disponible'):
            registro.update({'estado': 'NO_DISPONIBLE', 'mensaje': 'Archivo original no disponible.'})
        elif not fuente.get('formato_timbrable'):
            registro.update({'estado': 'NO_COMPATIBLE', 'mensaje': 'Formato no compatible con timbrado.'})
        else:
            try:
                validar_archivo_fuente(fuente['_ruta'])
                nombre_destino = _nombre_timbrado_terramar(fuente)
                ruta_destino = os.path.join(destino_root, nombre_destino)
                resultado = timbrar_documento(
                    fuente['_ruta'],
                    ruta_destino,
                    _lineas_timbre_recepcion(citacion, usuario, fecha_local) + [
                        f'Código: {codigo_validacion}',
                    ],
                    codigo_validacion,
                )
                registro.update({
                    'estado': 'TIMBRADO',
                    'stamped_path': ruta_destino,
                    'stamped_name': nombre_destino,
                    'stamped_mime': resultado['mime'],
                    'stamped_size': resultado['size'],
                    'stamped_hash': resultado['hash'],
                    'format': resultado['format'],
                })
                generados += 1
            except (ValueError, OSError, fitz.FileDataError) as exc:
                registro.update({'estado': 'ERROR', 'mensaje': str(exc)})
        documentos.append(registro)
    return {
        'citacion_id': citacion.id,
        'stamp_version': STAMP_VERSION,
        'usuario_id': usuario.id,
        'usuario': usuario.username,
        'fecha_iso': ahora.isoformat(),
        'fecha_hora': fecha_local.strftime('%d/%m/%Y %H:%M'),
        'documentos': documentos,
        'generados': generados,
        'reutilizados': reutilizados,
    }


def ajax_operacion_planta_timbrar_documentos_terramar(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    citacion, error_response = _validar_citacion_terramar_etapa2(
        request,
        pk,
        None,
    )
    if error_response:
        return error_response

    configuracion = _configuracion_timbrado_recepcion(citacion)
    if not configuracion:
        return JsonResponse({
            'success': False,
            'message': 'El timbrado no esta habilitado en la etapa activa.',
        }, status=409)
    if not usuario_puede_paso_operacion(request.user, configuracion['responsables']):
        return JsonResponse({'success': False, 'message': 'Solo el perfil responsable puede timbrar documentos.'}, status=403)
    if configuracion['requiere_documentacion_validada']:
        validacion = _leer_metadata_terramar(citacion, CAMPO_DOCUMENTACION_TERRAMAR)
        if not validacion.get('validada'):
            return JsonResponse({'success': False, 'message': 'Debe validar Documentacion antes de timbrar.'}, status=409)
    if not obtener_documentos_salida_terramar(citacion):
        return JsonResponse({'success': False, 'message': 'No existen documentos disponibles para timbrar.'}, status=400)

    metadata = _procesar_documentos_timbrados_terramar(citacion, request.user)
    with transaction.atomic():
        citacion = _recargar_citacion_bloqueada_operacion(citacion)
        configuracion_bloqueada = _configuracion_timbrado_recepcion(citacion)
        if (
            not configuracion_bloqueada
            or configuracion_bloqueada['paso'] != configuracion['paso']
        ):
            return JsonResponse({'success': False, 'message': 'La etapa activa cambio durante el timbrado.'}, status=409)
        _guardar_metadata_terramar(
            citacion,
            request.user,
            _campo_timbrado_recepcion(citacion),
            f'Documentos timbrados {_empresa_timbre_recepcion(citacion)}',
            metadata,
        )
        registrar_log_camion_no_planificado(
            request.user,
            citacion.EP_NID,
            LOG_TIMBRADO_TERRAMAR,
            f'Documentos timbrados para citacion Terramar #{citacion.id}. Nuevos: {metadata["generados"]}.',
            citacion.id,
            str(metadata['generados']),
        )
    payload = _payload_documentacion_terramar(citacion, request)
    return JsonResponse({
        'success': True,
        'message': 'Timbrado finalizado.' if metadata['generados'] else 'Los documentos ya estaban timbrados.',
        'generados': metadata['generados'],
        'reutilizados': metadata['reutilizados'],
        'documentacion': payload,
    })

def ajax_operacion_planta_documento_terramar(request, pk, documento_key):
    citacion, error_response = _validar_citacion_terramar_etapa2(request, pk)
    if error_response:
        return error_response
    fuente = next(
        (item for item in _documentos_fuente_terramar(citacion) if item.get('key') == documento_key),
        None,
    )
    if not fuente:
        return JsonResponse({'success': False, 'message': 'Documento no encontrado.'}, status=404)
    version = str(request.GET.get('version') or 'original').lower()
    if version == 'timbrado':
        claves_salida = {
            item.get('key')
            for item in obtener_documentos_salida_terramar(citacion)
        }
        if documento_key not in claves_salida:
            return JsonResponse({'success': False, 'message': 'El antecedente no pertenece al paquete de salida.'}, status=404)
        estado = _estado_timbrado_documentos_terramar(citacion, [fuente])['documentos'][0]
        ruta = estado.get('stamped_path') if estado.get('timbrado_disponible') else ''
        nombre = estado.get('stamped_name') or fuente.get('nombre')
    elif version == 'original':
        ruta = fuente.get('_ruta')
        nombre = fuente.get('nombre')
    else:
        return JsonResponse({'success': False, 'message': 'Version documental no valida.'}, status=400)
    if not ruta or not os.path.isfile(ruta) or not _ruta_documento_terramar_permitida(ruta):
        return JsonResponse({'success': False, 'message': 'Documento no disponible.'}, status=404)
    descargar = str(request.GET.get('accion') or 'descargar').lower() != 'ver'
    response = FileResponse(
        open(ruta, 'rb'),
        as_attachment=descargar,
        filename=os.path.basename(nombre or ruta),
        content_type=mime_archivo(ruta),
    )
    return response


def _patente_citacion_terramar(citacion):
    valores = obtener_valores_ingreso_camion(citacion)
    patente = str(valores.get('patente') or '').strip()
    if not patente:
        camion = _camion_patio_asociado_citacion(citacion)
        patente = str(camion.CPA_CPATENTE or '').strip() if camion else ''
    return patente


def descargar_documentos_timbrados_terramar(request, pk):
    if request.method != 'GET':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    citacion, error_response = _validar_citacion_terramar_etapa2(request, pk)
    if error_response:
        return error_response
    configuracion = _configuracion_timbrado_recepcion(citacion)
    if not configuracion:
        return JsonResponse({'success': False, 'message': 'La descarga no esta habilitada en la etapa activa.'}, status=409)
    if not usuario_puede_paso_operacion(request.user, configuracion['responsables']):
        return JsonResponse({'success': False, 'message': 'Solo el perfil responsable puede descargar documentos firmados.'}, status=403)
    if configuracion['requiere_documentacion_validada']:
        documentacion = _leer_metadata_terramar(citacion, CAMPO_DOCUMENTACION_TERRAMAR)
        if not documentacion.get('validada'):
            return JsonResponse({'success': False, 'message': 'Debe validar Documentacion antes de descargar.'}, status=409)

    estado = _estado_timbrado_documentos_terramar(citacion)
    if not estado['completo']:
        return JsonResponse({'success': False, 'message': 'Debe timbrar los documentos obligatorios antes de descargar.'}, status=409)
    com_sal = [
        item for item in estado['documentos']
        if item.get('origen') == 'TICKET_PESAJE'
        and item.get('tipo') == 'Ticket Pesaje Salida'
    ]
    if not com_sal or not all(item.get('timbrado_disponible') for item in com_sal):
        return JsonResponse({'success': False, 'message': 'El ticket timbrado COM_SAL es obligatorio.'}, status=409)

    try:
        patente = sanitizar_patente_exportacion(_patente_citacion_terramar(citacion))
        nombre_zip = nombre_carpeta_exportacion_terramar(
            patente, timezone.localdate().strftime('%Y%m%d'), citacion.id,
        ) + '.zip'
        contenido, nombres = generar_zip_documentos_timbrados(estado['documentos'])
    except (OSError, ValueError):
        return JsonResponse({
            'success': False,
            'message': 'No fue posible preparar el paquete de documentos firmados.',
        }, status=409)

    registrar_log_camion_no_planificado(
        request.user,
        citacion.EP_NID,
        LOG_EXPORTA_DOCUMENTOS_TERRAMAR,
        f'Paquete ZIP documental generado para citacion {citacion.id}; '
        f'patente {patente}; archivo {nombre_zip}; documentos {len(nombres)}.',
        citacion.id,
        patente,
    )
    response = HttpResponse(contenido, content_type='application/zip')
    response['Content-Disposition'] = f'attachment; filename="{nombre_zip}"'
    response['Cache-Control'] = 'no-store'
    return response


def ajax_operacion_planta_exportar_documentos_terramar(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    citacion, error_response = _validar_citacion_terramar_etapa2(
        request,
        pk,
        None,
    )
    if error_response:
        return error_response

    configuracion = _configuracion_timbrado_recepcion(citacion)
    if not configuracion:
        return JsonResponse({
            'success': False,
            'message': 'La exportacion no esta habilitada en la etapa activa.',
        }, status=409)
    if not usuario_puede_paso_operacion(request.user, configuracion['responsables']):
        return JsonResponse({'success': False, 'message': 'Solo el perfil responsable puede preparar documentos firmados.'}, status=403)
    if configuracion['requiere_documentacion_validada']:
        documentacion = _leer_metadata_terramar(citacion, CAMPO_DOCUMENTACION_TERRAMAR)
        if not documentacion.get('validada'):
            return JsonResponse({'success': False, 'message': 'Debe validar Documentacion antes de exportar.'}, status=409)

    estado = _estado_timbrado_documentos_terramar(citacion)
    if not estado['completo']:
        return JsonResponse({'success': False, 'message': 'Debe timbrar los documentos obligatorios antes de exportar.'}, status=409)
    com_sal = [
        item for item in estado['documentos']
        if item.get('origen') == 'TICKET_PESAJE'
        and item.get('tipo') == 'Ticket Pesaje Salida'
    ]
    if not com_sal or not all(item.get('timbrado_disponible') for item in com_sal):
        return JsonResponse({'success': False, 'message': 'El ticket timbrado COM_SAL es obligatorio.'}, status=409)

    base_configurada = str(
        getattr(settings, 'TERRAMAR_DOCUMENTOS_FIRMADOS_DIR', r'C:\Documentos_firmados')
        or ''
    ).strip()
    try:
        patente = sanitizar_patente_exportacion(_patente_citacion_terramar(citacion))
    except ValueError as exc:
        return JsonResponse({'success': False, 'message': str(exc)}, status=400)
    try:
        resultado = exportar_documentos_timbrados(
            base_configurada,
            patente,
            estado['documentos'],
            timezone.localdate().strftime('%Y%m%d'),
            citacion.id,
        )
    except ValueError as exc:
        return JsonResponse({
            'success': False,
            'message': str(exc),
            'carpeta_esperada': os.path.abspath(os.path.expandvars(base_configurada)),
        }, status=409)

    carpeta = resultado['carpeta']
    copiados = resultado['archivos_copiados']
    reutilizados = resultado['archivos_reutilizados']
    reemplazados = resultado['archivos_reemplazados']
    errores = resultado['archivos_fallidos']
    auditoria_previa = SYSLOGGER.objects.filter(
        EP_NID=citacion.EP_NID,
        LOG_COPERACION=LOG_EXPORTA_DOCUMENTOS_TERRAMAR,
        LOG_CADD1=str(citacion.id),
        LOG_CADD2=patente,
    ).exists()
    if copiados or reemplazados or errores or not auditoria_previa:
        resultado_texto = 'PARCIAL' if resultado['partial'] else ('OK' if resultado['success'] else 'ERROR')
        registrar_log_camion_no_planificado(
            request.user,
            citacion.EP_NID,
            LOG_EXPORTA_DOCUMENTOS_TERRAMAR,
            (
                f'Exportacion documental Terramar {resultado_texto}. Citacion {citacion.id}; '
                f'patente {patente}; carpeta {carpeta}; copiados {len(copiados)}; '
                f'reutilizados {len(reutilizados)}; reemplazados {len(reemplazados)}; '
                f'errores {len(errores)}.'
            ),
            citacion.id,
            patente,
        )
    success = resultado['success']
    return JsonResponse({
        'success': success,
        'partial': resultado['partial'],
        'message': (
            'Documentos preparados correctamente.'
            if success
            else 'La preparacion termino con errores. Puede reintentar los archivos pendientes.'
        ),
        'carpeta': carpeta,
        'cantidad_disponible': resultado['cantidad_disponible'],
        'cantidad_copiada': resultado['cantidad_copiada'],
        'cantidad_reutilizada': resultado['cantidad_reutilizada'],
        'cantidad_reemplazada': resultado['cantidad_reemplazada'],
        'cantidad_fallida': resultado['cantidad_fallida'],
        'total': resultado['total'],
        'archivos_copiados': copiados,
        'archivos_reutilizados': reutilizados,
        'archivos_reemplazados': reemplazados,
        'archivos_fallidos': errores,
        'errores': errores,
    }, status=200 if success else (207 if resultado['partial'] else 500))

def ajax_operacion_planta_guardar_observacion(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response

    paso_operacion = str(request.POST.get('paso_operacion') or request.POST.get('paso') or '').strip()
    observacion = str(request.POST.get('observacion') or '').strip()
    if not paso_operacion:
        return JsonResponse({'success': False, 'message': 'Debe indicar la etapa de Operacion Planta.'}, status=400)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    pasos_validos = {nombre for nombre, _ in pasos_config}
    if paso_operacion not in pasos_validos:
        return JsonResponse({'success': False, 'message': 'La etapa indicada no pertenece al flujo de esta citacion.'}, status=400)

    paso_actual_visible, _, pasos_completados = obtener_paso_activo_operacion(citacion, pasos_config)
    responsables_paso = next((responsables for nombre, responsables in pasos_config if nombre == paso_operacion), [])
    paso_completado = paso_operacion in pasos_completados
    if paso_operacion != paso_actual_visible and not paso_completado:
        return JsonResponse({
            'success': False,
            'message': f'Solo puede guardar observacion en la etapa activa o en etapas ya completadas.'
        }, status=409)

    if not usuario_puede_paso_operacion(request.user, responsables_paso):
        return JsonResponse({
            'success': False,
            'message': f'Solo lectura: este paso corresponde a {" / ".join(responsables_paso)}'
        }, status=403)

    if _leer_metadata_observacion_etapa(citacion, paso_operacion) is not None:
        return JsonResponse({
            'success': False,
            'message': 'La observacion de esta etapa ya fue registrada.'
        }, status=409)

    if paso_operacion == PASO_RESULTADO_CALIDAD and _leer_metadata_preparacion_descarga(citacion):
        return JsonResponse({
            'success': False,
            'message': 'La preparacion de descarga ya fue registrada; la observacion quedo bloqueada.'
        }, status=409)

    try:
        metadata = _registrar_observacion_etapa(citacion, paso_operacion, observacion, request.user)
        if paso_operacion == PASO_TOMA_MUESTRA:
            _actualizar_observacion_toma_muestra_accion(citacion, observacion)
    except Exception as e:
        return JsonResponse({'success': False, 'message': f'No fue posible guardar observacion: {str(e)}'}, status=500)

    return JsonResponse({
        'success': True,
        'message': 'Observacion guardada correctamente.',
        'observacion': metadata.get('observacion') or '',
        'paso': paso_operacion,
        'usuario': metadata.get('usuario') or '',
        'fecha': metadata.get('fecha_hora') or '',
    })


def _validar_accion_ciclo_descarga(request, citacion):
    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, responsables_paso, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    if paso_actual_visible != PASO_CICLO_DESCARGA:
        return None, JsonResponse({
            'success': False,
            'message': f'Solo puede operar durante la etapa activa: {PASO_CICLO_DESCARGA}.'
        }, status=409)
    if not usuario_puede_paso_operacion(request.user, responsables_paso):
        return None, JsonResponse({
            'success': False,
            'message': f'Solo lectura: este paso corresponde a {" / ".join(responsables_paso)}'
        }, status=403)
    return responsables_paso, None


def ajax_operacion_planta_iniciar_ciclo_recepcion_bodega_externa(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    es_prosesa_piso_1 = es_recepcion_prosesa_contenedor_piso_1(citacion)
    es_prosesa_piso_2 = es_recepcion_prosesa_piso_2(citacion)
    es_terramar_externa = es_recepcion_terramar_bodega_externa_operacion(citacion)
    perfil_inicio = (
        ['ASISTENTE RECEPCION'] if es_prosesa_piso_2
        else ([PERFIL_TERRAMAR_ASISTENTE_BODEGA] if es_terramar_externa else ['ASISTENTE C D'])
    )
    if (not usuario_es_asistente_recepcion(request.user) if es_prosesa_piso_2 else not usuario_puede_paso_operacion(request.user, perfil_inicio)):
        mensaje = (
            'Solo Asistente Recepcion puede iniciar el retiro de contenedor.'
            if es_prosesa_piso_2 else (
                'Solo Asistente Bodega puede iniciar la salida a Bodega Externa.'
                if es_terramar_externa else 'Solo Asistente_C_D puede autorizar la salida a Bodega Externa.'
            )
        )
        return JsonResponse({'success': False, 'message': mensaje}, status=403)

    try:
        if es_prosesa_piso_2:
            payload, creado = _iniciar_retiro_temporal_prosesa_piso_2(citacion, request.user)
        elif es_terramar_externa:
            payload, creado = _iniciar_ciclo_terramar_bodega_externa(citacion, request.user, request.POST.get('observacion'))
        elif es_prosesa_piso_1:
            payload, creado = _iniciar_salida_temporal_prosesa_piso_1(citacion, request.user)
        else:
            payload, creado = _iniciar_ciclo_recepcion_bodega_externa(citacion, request.user)
    except OperacionPlantaDuplicada as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=409)
    except ValueError as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=409 if es_terramar_externa else 400)
    except Exception as e:
        accion = 'salida temporal' if es_prosesa_piso_1 else 'salida a Bodega Externa'
        return JsonResponse({'success': False, 'message': f'No fue posible autorizar {accion}: {str(e)}'}, status=500)

    mensaje_creado = (
        'Retiro de contenedor iniciado. Guardia Porteria debe validar la salida temporal.'
        if es_prosesa_piso_2 else (
            'Salida temporal autorizada para depositar el contenedor en Piso 1.'
            if es_prosesa_piso_1 else 'Camion autorizado para salir a Bodega Externa.'
        )
    )
    mensaje_existente = (
        'El retiro de contenedor ya estaba iniciado.'
        if es_prosesa_piso_2 else (
            'La salida temporal ya estaba autorizada.'
            if es_prosesa_piso_1 else 'La salida a Bodega Externa ya estaba autorizada.'
        )
    )
    return JsonResponse({
        'success': True,
        'message': mensaje_creado if creado else mensaje_existente,
        'ciclo_bodega_externa': payload,
        'creado': creado,
    })


def ajax_operacion_planta_validar_salida_temporal_prosesa_piso_2(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_guardia_porteria(request.user):
        return JsonResponse({'success': False, 'message': 'Solo Guardia Porteria valida la salida temporal.'}, status=403)
    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    if not es_recepcion_prosesa_piso_2(citacion):
        return JsonResponse({'success': False, 'message': 'Esta accion solo aplica a PROSESA Piso 2.'}, status=400)
    try:
        payload, creado = _validar_salida_temporal_prosesa_piso_2(citacion, request.user)
    except ValueError as exc:
        return JsonResponse({'success': False, 'message': str(exc)}, status=409)
    return JsonResponse({
        'success': True,
        'message': 'Salida temporal validada por Guardia Porteria.' if creado else 'La salida temporal ya estaba validada.',
        'ciclo_bodega_externa': payload, 'creado': creado,
    })


def ajax_operacion_planta_finalizar_ciclo_recepcion_bodega_externa(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    if (not usuario_es_guardia_porteria(request.user) if es_recepcion_prosesa_piso_2(citacion) else not usuario_puede_paso_operacion(request.user, ['GUARDIA PORTERIA'])):
        return JsonResponse({'success': False, 'message': 'Solo Guardia Porteria puede registrar el regreso a planta.'}, status=403)

    es_prosesa_piso_1 = es_recepcion_prosesa_contenedor_piso_1(citacion)
    es_prosesa_piso_2 = es_recepcion_prosesa_piso_2(citacion)
    es_terramar_externa = es_recepcion_terramar_bodega_externa_operacion(citacion)
    try:
        if es_prosesa_piso_2:
            payload, creado = _finalizar_retiro_temporal_prosesa_piso_2(
                citacion, request.user, request.POST.get('observacion')
            )
        elif es_terramar_externa:
            payload, creado = _finalizar_ciclo_terramar_bodega_externa(citacion, request.user, request.POST.get('observacion'))
        elif es_prosesa_piso_1:
            payload, creado = _finalizar_salida_temporal_prosesa_piso_1(
                citacion, request.user, request.POST.get('observacion')
            )
        else:
            payload, creado = _finalizar_ciclo_recepcion_bodega_externa(citacion, request.user, request.POST.get('observacion'))
    except OperacionPlantaDuplicada as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=409)
    except ValueError as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=409 if es_terramar_externa else 400)
    except Exception as e:
        origen = 'la salida temporal' if es_prosesa_piso_1 else 'Bodega Externa'
        return JsonResponse({'success': False, 'message': f'No fue posible registrar regreso desde {origen}: {str(e)}'}, status=500)

    mensaje_creado = (
        'Retorno a planta registrado. Se habilito Pesaje Salida.'
        if es_prosesa_piso_1 or es_prosesa_piso_2 else
        'Camion regreso desde Bodega Externa. La citacion avanzo a Pesaje Salida.'
    )
    mensaje_existente = (
        'El retorno a planta ya estaba registrado.'
        if es_prosesa_piso_1 or es_prosesa_piso_2 else
        'El regreso desde Bodega Externa ya estaba registrado.'
    )
    return JsonResponse({
        'success': True,
        'message': mensaje_creado if creado else mensaje_existente,
        'ciclo_bodega_externa': payload,
        'paso': PASO_PROSESA_DEPOSITAR_PISO_1 if es_prosesa_piso_1 else PASO_CICLO_DESCARGA,
        'usuario': request.user.username,
        'fecha': payload.get('fin_legible') or '',
        'creado': creado,
    })


def ajax_operacion_planta_iniciar_ciclo_descarga(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    if es_recepcion_new_jersey_p2(citacion):
        try:
            resultado = _accion_new_jersey_p2_compartida(
                citacion, request.user, nj_p2.PASO_DESCARGA, 'iniciar',
                str(request.POST.get('observacion') or '').strip(),
                str(request.POST.get('tipo_descarga') or '').strip(),
            )
        except PermissionError as exc:
            return JsonResponse({'success': False, 'message': str(exc)}, status=403)
        except ValueError as exc:
            return JsonResponse({'success': False, 'message': str(exc)}, status=409)
        return JsonResponse({'success': True, 'message': 'Descarga iniciada.',
                             'ciclo_descarga': _payload_ciclo_descarga(citacion), **resultado})
    if es_recepcion_bodega_externa_operacion(citacion) or es_recepcion_terramar_bodega_externa_operacion(citacion):
        return JsonResponse({'success': False, 'message': 'El flujo Recepcion Bodega Externa utiliza un ciclo externo de salida y regreso.'}, status=400)
    _, error_response = _validar_accion_ciclo_descarga(request, citacion)
    if error_response:
        return error_response

    try:
        if es_citacion_despacho(citacion):
            metadata = _registrar_proceso_ciclo_carga_despacho(
                citacion,
                request.user,
                request.POST.get('proceso'),
                request.POST.get('punto_despacho'),
                request.POST.get('warehouse_code'),
            )
            return JsonResponse({
                'success': True,
                'message': 'Proceso de despacho iniciado.',
                'ciclo_carga_despacho': _payload_ciclo_carga_despacho(citacion),
                'metadata': metadata,
            })

        tipo_descarga = request.POST.get('tipo_descarga')
        metadata = _iniciar_ciclo_descarga(citacion, request.user, tipo_descarga)
    except PermissionError as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=403)
    except OperacionPlantaDuplicada as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=409)
    except ValueError as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=400)
    except Exception as e:
        return JsonResponse({'success': False, 'message': f'No fue posible iniciar ciclo: {str(e)}'}, status=500)

    return JsonResponse({
        'success': True,
        'message': 'Descarga iniciada.',
        'ciclo_descarga': _payload_ciclo_descarga(citacion),
        'metadata': metadata,
    })


