def ajax_operacion_planta_autorizar_salida(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    if es_recepcion_prosesa_piso_2(citacion):
        if not usuario_es_asistente_recepcion(request.user):
            return JsonResponse({'success': False, 'message': 'Solo Asistente Recepcion autoriza la salida Piso 2.'}, status=403)
        try:
            with transaction.atomic():
                citacion = _recargar_citacion_bloqueada_operacion(citacion)
                log = OPERACION_PLANTA_LOG.objects.filter(
                    CI_NID=citacion, OPL_CPASO=PASO_AUTORIZAR_SALIDA,
                    OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
                ).order_by('-OPL_FFECHAREGISTRO').first()
                if log:
                    creado = False
                else:
                    if obtener_paso_activo_operacion(citacion)[0] != PASO_AUTORIZAR_SALIDA:
                        raise ValueError('Autorizar Salida no es la etapa activa.')
                    if not _payload_salida_temporal_prosesa_piso_2(citacion)['finalizada']:
                        raise ValueError('Debe registrar el retorno del contenedor antes de autorizar la salida.')
                    for paso_previo in ('Pesaje Entrada', PASO_PROSESA_INICIO_RETIRO, 'Pesaje Salida'):
                        if not OPERACION_PLANTA_LOG.objects.filter(
                            CI_NID=citacion, OPL_CPASO=paso_previo,
                            OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
                        ).exists():
                            raise ValueError(f'Debe completar {paso_previo} antes de autorizar la salida.')
                    obtener_peso_real_prosesa_para_sap(citacion)
                    log = OPERACION_PLANTA_LOG.objects.create(
                        US_NID=request.user, EP_NID=citacion.EP_NID, PL_NID=citacion.PL_NID,
                        CI_NID=citacion, OPL_CPASO=PASO_AUTORIZAR_SALIDA,
                        OPL_CPERFIL_RESPONSABLE='ASISTENTE RECEPCION',
                        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
                        OPL_COBSERVACION='Salida final autorizada tras retorno y Pesaje Salida.',
                    )
                    _registrar_syslog_operacion_planta(
                        citacion, request.user, 'PROSESA_P2_AUT_SAL',
                        f'Asistente Recepcion autoriza salida final de citacion #{citacion.id}.',
                        'PROSESA_PISO_2',
                    )
                    creado = True
        except ValueError as exc:
            return JsonResponse({'success': False, 'message': str(exc)}, status=409)
        return JsonResponse({
            'success': True,
            'message': 'Salida autorizada. Guardia Porteria puede confirmar la salida final.',
            'paso': PASO_AUTORIZAR_SALIDA, 'creado': creado,
            'usuario': log.US_NID.username if log.US_NID_id else '',
            'fecha': timezone.localtime(log.OPL_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M'),
        })
    if es_citacion_recepcion_terramar(citacion):
        return _autorizar_salida_terramar(request, citacion)
    if _empresa_timbre_recepcion(citacion) == 'SBH' and str(citacion.CI_CTIPO or '').upper() == CIT_RECEPCION and str(request.POST.get('accion') or '').strip() == 'guardar_conformidad':
        if not (request.user.is_superuser or usuario_es_asistente_recepcion(request.user)):
            return JsonResponse({'success': False, 'message': 'Solo Asistente_Recepcion puede registrar la conformidad.'}, status=403)
        if not _paso_activo_es(citacion, PASO_AUTORIZAR_SALIDA):
            return JsonResponse({'success': False, 'message': 'Autorizar Salida no es la etapa activa.'}, status=409)
        if _leer_revision_conformidad_sbh(citacion).get('recepcion_conforme'):
            return JsonResponse({'success': False, 'message': 'La conformidad ya fue registrada.'}, status=409)
        try:
            with transaction.atomic():
                citacion = _recargar_citacion_bloqueada_operacion(citacion)
                metadata = _guardar_revision_conformidad_sbh(citacion, request.user, request.POST.get('recepcion_conforme'), request.POST.get('observacion_descarga'))
        except ValueError as exc:
            return JsonResponse({'success': False, 'message': str(exc)}, status=400)
        return JsonResponse({'success': True, 'message': 'Conformidad registrada. Autorizar Salida sigue pendiente.', 'revision_conformidad': metadata})
    if es_recepcion_new_jersey_p3(citacion):
        if not (request.user.is_superuser or usuario_es_asistente_recepcion(request.user)):
            return JsonResponse({'success': False, 'message': 'Solo Asistente Recepcion autoriza la salida New Jersey P3.'}, status=403)
        try:
            obtener_peso_real_new_jersey_p3_para_sap(citacion)
        except ValueError as exc:
            return JsonResponse({'success': False, 'message': str(exc)}, status=409)
        transferencia_p3 = estado_transferencia_new_jersey_p3(citacion)
        if not transferencia_p3.get('creada'):
            return JsonResponse({
                'success': False,
                'message': 'Debe crear la transferencia SAP final antes de autorizar la salida.',
                'transferencia_sap': transferencia_p3,
            }, status=409)
    log_existente = OPERACION_PLANTA_LOG.objects.filter(
        CI_NID=citacion,
        OPL_CPASO=PASO_AUTORIZAR_SALIDA,
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).order_by('-OPL_FFECHAREGISTRO').first()
    if log_existente:
        return JsonResponse({
            'success': True,
            'message': 'Salida ya autorizada. La citacion avanzo a Confirmar Salida.',
            'autorizar_salida': _payload_autorizar_salida(citacion),
            'paso': PASO_AUTORIZAR_SALIDA,
            'usuario': getattr(log_existente.US_NID, 'username', '') if log_existente.US_NID_id else '',
            'fecha': timezone.localtime(log_existente.OPL_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M')
        })

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, responsables_paso, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    if paso_actual_visible != PASO_AUTORIZAR_SALIDA:
        return JsonResponse({
            'success': False,
            'message': f'Solo puede autorizar durante la etapa activa: {PASO_AUTORIZAR_SALIDA}.'
        }, status=409)
    if not usuario_puede_paso_operacion(request.user, responsables_paso):
        return JsonResponse({
            'success': False,
            'message': f'Solo lectura: este paso corresponde a {" / ".join(responsables_paso)}'
        }, status=403)

    if es_despacho_sbh_operacion(citacion):
        accion = str(request.POST.get('accion') or '').strip()
        if accion == 'guardar_ultimas_cargas':
            try:
                with transaction.atomic():
                    citacion = _recargar_citacion_bloqueada_operacion(citacion)
                    if obtener_paso_activo_operacion(citacion)[0] != PASO_AUTORIZAR_SALIDA:
                        raise ValueError('Autorizar Salida no es la etapa activa.')
                    metadata = _guardar_ultimas_cargas_despacho(citacion, request.user, request.POST)
            except ValueError as exc:
                return JsonResponse({'success': False, 'message': str(exc)}, status=400)
            return JsonResponse({
                'success': True,
                'message': 'Tres últimas cargas guardadas correctamente.',
                'ultimas_cargas': metadata,
            })

        ultimas_cargas = _leer_ultimas_cargas_despacho(citacion)
        if any(not str(ultimas_cargas.get(f'carga_{indice}') or '').strip() for indice in range(1, 4)):
            return JsonResponse({
                'success': False,
                'message': 'Debe guardar las tres últimas cargas antes de continuar.',
            }, status=409)

        drafts_operacionales = _payload_drafts_sap_despacho_operacionales(citacion)
        if not drafts_operacionales.get('completos'):
            return JsonResponse({
                'success': False,
                'message': 'Todos los acuerdos deben tener su Draft SAP creado antes de autorizar la salida.'
            }, status=400)
        sap_update_status = get_sap_despacho_update_status(citacion)
        if not sap_update_status.get('updated'):
            return JsonResponse({
                'success': False,
                'message': 'Debe actualizar el Draft SAP con el peso de salida antes de autorizar.'
            }, status=400)
        if not OPERACION_PLANTA_LOG.objects.filter(
            CI_NID=citacion,
            OPL_CPASO=PASO_CIERRE_CARGA,
            OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        ).exists():
            return JsonResponse({
                'success': False,
                'message': 'Debe completar Cierre Proceso de Carga antes de autorizar la salida.'
            }, status=409)
        if accion == 'guardar_conformidad':
            if _leer_revision_conformidad_sbh(citacion).get('recepcion_conforme'):
                return JsonResponse({'success': False, 'message': 'La conformidad ya fue registrada.'}, status=409)
            try:
                with transaction.atomic():
                    metadata = _guardar_revision_conformidad_sbh(
                        citacion, request.user, request.POST.get('recepcion_conforme'),
                        request.POST.get('observacion_descarga'),
                    )
            except ValueError as exc:
                return JsonResponse({'success': False, 'message': str(exc)}, status=400)
            return JsonResponse({
                'success': True,
                'message': 'Conformidad registrada. Autorizar Salida sigue pendiente.',
                'revision_conformidad': metadata,
            })

        try:
            documentacion = verificar_documentos_definitivos(citacion)
        except VerificacionDocumentoSapError as exc:
            return JsonResponse({
                'success': False,
                'message': str(exc),
            }, status=502)
        if not documentacion.get('completo'):
            return JsonResponse({
                'success': False,
                'message': (
                    'No es posible autorizar la salida. Existen acuerdos cuyo Draft SAP '
                    'aún está abierto en ODRF.'
                ),
                'documentacion': documentacion,
            }, status=409)

    if es_despacho_bodega_externa_operacion(citacion):
        sap_update_status = get_sap_despacho_update_status(citacion)
        if sap_update_status.get('is_error'):
            return JsonResponse({
                'success': False,
                'message': 'No se puede autorizar la salida porque la actualizacion SAP fallo. Soporte fue notificado.'
            }, status=400)
        if not sap_update_status.get('updated'):
            return JsonResponse({
                'success': False,
                'message': 'Debe actualizar el documento SAP antes de autorizar la salida.'
            }, status=400)

    if (
        (
            _empresa_timbre_recepcion(citacion) == 'SBH'
            and str(citacion.CI_CTIPO or '').upper() == CIT_RECEPCION
        )
        or es_despacho_sbh_operacion(citacion)
    ):
        revision = _leer_revision_conformidad_sbh(citacion)
        if not revision.get('recepcion_conforme'):
            return JsonResponse({'success': False, 'message': 'Debe indicar si la recepción fue conforme.'}, status=409)
        request.POST = request.POST.copy()
        request.POST['recepcion_conforme'] = revision['recepcion_conforme']
        request.POST['observacion_descarga'] = revision.get('observacion') or ''

    if aplica_timbraje_recepcion(citacion):
        estado_timbrado = _estado_timbrado_documentos_terramar(citacion)
        if not estado_timbrado['completo']:
            return JsonResponse({'success': False, 'message': 'Debe timbrar todos los documentos obligatorios antes de autorizar la salida.'}, status=409)

    if es_flujo_recepcion_estanque_sbh(citacion):
        draft_status = get_goods_receipt_draft_guide_status(citacion)
        if not draft_status.get('sent') or not draft_status.get('docentry'):
            return JsonResponse({
                'success': False,
                'message': 'Debe existir el Borrador SAP de recepcion antes de autorizar la salida.',
            }, status=400)
        if not obtener_lote_recepcion_sap(citacion):
            return JsonResponse({
                'success': False,
                'message': 'Debe generar el Lote SAP antes de autorizar la salida.',
            }, status=400)

    if (
        str(getattr(citacion, 'CI_CTIPO', '') or '').upper() == CIT_RECEPCION
        and not es_recepcion_new_jersey_p1(citacion)
        and not es_recepcion_new_jersey_p3(citacion)
    ):
        sap_update_status = get_goods_receipt_draft_update_status(citacion)
        if sap_update_status.get('is_error'):
            return JsonResponse({
                'success': False,
                'message': 'No se puede autorizar la salida porque la actualizacion SAP fallo.'
            }, status=400)
        if not sap_update_status.get('updated'):
            return JsonResponse({
                'success': False,
                'message': 'Debe actualizar el Borrador SAP de recepcion antes de autorizar la salida.'
            }, status=400)

    try:
        with transaction.atomic():
            metadata = _registrar_autorizar_salida(
                citacion,
                request.user,
                request.POST.get('recepcion_conforme'),
                request.POST.get('observacion_descarga')
            )
            recepcion_label = 'Si' if metadata.get('recepcion_conforme') == 'SI' else 'No'
            observacion_log = metadata.get('observacion_descarga') or 'Sin observacion'
            log = OPERACION_PLANTA_LOG.objects.create(
                US_NID=request.user,
                EP_NID=citacion.EP_NID,
                PL_NID=citacion.PL_NID,
                CI_NID=citacion,
                OPL_CPASO=PASO_AUTORIZAR_SALIDA,
                OPL_CPERFIL_RESPONSABLE=' / '.join(responsables_paso),
                OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
                OPL_COBSERVACION=f'Recepcion conforme: {recepcion_label} | Observacion: {observacion_log}'
            )
    except ValueError as e:
        return JsonResponse({'success': False, 'message': str(e)}, status=400)
    except Exception as e:
        return JsonResponse({'success': False, 'message': f'No fue posible autorizar salida: {str(e)}'}, status=500)

    return JsonResponse({
        'success': True,
        'message': 'Salida autorizada. La citacion avanzo a Confirmar Salida.',
        'autorizar_salida': metadata,
        'paso': PASO_AUTORIZAR_SALIDA,
        'usuario': request.user.username,
        'fecha': timezone.localtime(log.OPL_FFECHAREGISTRO).strftime('%d/%m/%Y %H:%M')
    })


def usuario_puede_ver_detalle_tecnico_sap(user):
    if getattr(user, 'is_superuser', False):
        return True

    return False



def _usuarios_soporte_sap_despacho(empresa_id):
    perfiles = PERFIL_USUARIO.objects.select_related('US_NID', 'PR_NID').filter(
        US_NID__is_active=True,
        PE_BHABILITADO=True,
        PR_NID__PR_BHABILITADO=True,
        US_NID_id__in=USERS_EMPRESA.objects.filter(
            EP_NID_id=empresa_id
        ).values_list('US_NID_id', flat=True),
    )
    usuarios = []
    usuarios_ids = set()
    palabras_tecnicas = {'SOPORTE', 'TECNICO', 'TECNICA', 'TI', 'IT', 'ADMINISTRADOR'}
    for perfil_usuario in perfiles:
        nombre = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CNOMBRE)
        codigo = normalizar_nombre_perfil(perfil_usuario.PR_NID.PR_CCODIGO)
        if any(palabra in nombre.split() or palabra in codigo.split() for palabra in palabras_tecnicas):
            usuario = perfil_usuario.US_NID
            if usuario.id not in usuarios_ids:
                usuarios.append(usuario)
                usuarios_ids.add(usuario.id)

    if usuarios:
        return usuarios
    return list(User.objects.filter(
        is_superuser=True,
        is_active=True,
        empresas_asignadas__EP_NID_id=empresa_id,
    ).distinct().order_by('id')[:10])


def _notificar_soporte_error_sap_despacho(citacion, usuario, result):
    status = result.get('status') or {}
    docentry = status.get('docentry') or (result.get('preview') or {}).get('source_data', {}).get('draft_docentry') or ''
    peso_salida = status.get('peso_salida') or (result.get('preview') or {}).get('source_data', {}).get('peso_salida') or ''
    mensaje_error = status.get('error_message') or result.get('message') or 'Error no especificado.'
    fecha_hora = timezone.localtime(timezone.now()).strftime('%d/%m/%Y %H:%M:%S')
    secuencia = citacion.SC_NID.SE_CCODIGO if citacion.SC_NID else ''
    notificacion_url = f'/operacion-planta/{citacion.id}/?empresa_id={citacion.EP_NID_id}&_empresa_id={citacion.EP_NID_id}'
    contenido = (
        f'Error actualizacion SAP en citacion {citacion.id}. '
        f'No se pudo actualizar el Draft SAP {docentry or "-"} con el peso de salida {peso_salida or "-"}. Revisar log tecnico.\n'
        f'Empresa: {citacion.EP_NID}\n'
        f'Tipo: {citacion.CI_CTIPO}\n'
        f'Secuencia: {secuencia}\n'
        f'Mensaje: {mensaje_error}\n'
        f'Fecha/hora: {fecha_hora}\n'
        f'Usuario: {getattr(usuario, "username", "")}'
    )
    for receptor in _usuarios_soporte_sap_despacho(citacion.EP_NID_id):
        if NOTIFICACION.objects.filter(
            USER_RECEIVER_ID=receptor,
            EP_NID=citacion.EP_NID,
            NOT_CURL=notificacion_url,
            NOT_CCONTENIDO__icontains=f'Error actualizacion SAP en citacion {citacion.id}',
            NOT_BHABILITADO=True,
            NOT_BREAD=False
        ).exists():
            continue
        crear_notificacion_interna(
            USER_SENDER_ID=usuario,
            USER_RECEIVER_ID=receptor,
            EP_NID=citacion.EP_NID,
            NOT_CCONTENIDO=contenido,
            NOT_CURL=notificacion_url
        )


def _actualizar_sap_despacho_post_pesaje(citacion, usuario):
    if not es_despacho_sbh_operacion(citacion):
        return None
    return sap_despacho_actualizar_borrador(citacion, usuario)


def _limpiar_resultado_sap_despacho_para_usuario(result, user):
    if usuario_puede_ver_detalle_tecnico_sap(user):
        return result

    result = dict(result or {})
    result.pop('request_json', None)
    result.pop('response', None)
    preview = result.get('preview')
    if isinstance(preview, dict):
        preview = dict(preview)
        preview.pop('payload', None)
        result['preview'] = preview
    status = result.get('status')
    if isinstance(status, dict):
        status = dict(status)
        status.pop('request_json', None)
        status.pop('response_json', None)
        status.pop('request_json_pretty', None)
        status.pop('response_json_pretty', None)
        result['status'] = status
    return result


@require_POST
def ajax_operacion_planta_reabrir_cierre_carga_despacho_sbh(request, pk):
    if not usuario_puede_reabrir_cierre_carga(request.user):
        return JsonResponse({
            'success': False,
            'message': 'Solo un superusuario o ADMIN_DESARROLLO puede reabrir este paso.'
        }, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    if not es_despacho_sbh_operacion(citacion):
        return JsonResponse({
            'success': False,
            'message': 'La reapertura solo aplica a Despacho SBH.'
        }, status=400)

    motivo = str(request.POST.get('motivo') or '').strip()
    if not motivo:
        motivo = 'Reapertura tecnica: Draft SAP no fue actualizado despues de Pesaje Salida.'

    with transaction.atomic():
        citacion = _recargar_citacion_bloqueada_operacion(citacion)
        if OPERACION_PLANTA_LOG.objects.filter(
            CI_NID=citacion,
            OPL_CPASO=PASO_AUTORIZAR_SALIDA,
            OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        ).exists():
            return JsonResponse({
                'success': False,
                'message': 'No se puede reabrir porque Autorizar Salida ya fue completado.'
            }, status=409)

        cierre = OPERACION_PLANTA_LOG.objects.select_for_update().filter(
            CI_NID=citacion,
            OPL_CPASO=PASO_CIERRE_CARGA,
            OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO,
        ).order_by('-OPL_FFECHAREGISTRO', '-id').first()
        if not cierre:
            return JsonResponse({
                'success': False,
                'message': 'No existe un Cierre Proceso de Carga completado para reabrir.'
            }, status=409)

        observacion_anterior = str(cierre.OPL_COBSERVACION or '').strip()
        auditoria = (
            f'Reabierto por {request.user.username} el '
            f'{timezone.localtime(timezone.now()).strftime("%d/%m/%Y %H:%M")}. Motivo: {motivo}'
        )
        cierre.OPL_CESTADO = 'REABIERTO'
        cierre.OPL_COBSERVACION = ' | '.join(
            parte for parte in [observacion_anterior, auditoria] if parte
        )
        cierre.save(update_fields=['OPL_CESTADO', 'OPL_COBSERVACION'])

        registrar_log_camion_no_planificado(
            request.user,
            citacion.EP_NID,
            'REABRE_CIERRE_CARGA',
            f'Reapertura de Cierre Proceso de Carga para citacion #{citacion.id}. {motivo}',
            citacion.id,
            motivo[:128],
        )

    return JsonResponse({
        'success': True,
        'message': 'Cierre Proceso de Carga reabierto. Pesaje Salida y Draft SAP se conservaron.'
    })


def _registrar_log_preview_sap_despacho(preview):
    for documento in preview.get('documentos') or [{}]:
        acuerdo = documento.get('acuerdo') or {}
        draft = documento.get('draft') or {}
        bloque = {
            'citacion': preview.get('citacion'),
            'acuerdo': acuerdo.get('numero_visible'),
            'sap_abs_id': acuerdo.get('sap_abs_id'),
            'docentry': draft.get('docentry'),
            'endpoint': documento.get('endpoint'),
            'pesajes': documento.get('pesajes'),
            'headers': documento.get('headers'),
            'payload_original': documento.get('payload_original'),
            'payload_patch': documento.get('payload_patch'),
            'validacion': documento.get('validacion'),
        }
        logger.info(
            '%s\nSAP DESPACHO - PREVIEW PATCH\n%s\n%s\n%s',
            '=' * 60,
            json.dumps(bloque, indent=2, ensure_ascii=False, default=str),
            preview.get('resultado'),
            '=' * 60,
        )


def ajax_operacion_planta_preview_sap_despacho(request, pk):
    if not getattr(settings, 'SAP_DESPACHO_PREVIEW_ENABLED', False):
        return JsonResponse({'success': False, 'message': 'Preview SAP de despacho no disponible.'}, status=404)
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({
            'success': False,
            'message': 'No tiene permisos para Operacion Planta.'
        }, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    if citacion.EP_NID_id != 2 or not es_despacho_sbh_operacion(citacion):
        return JsonResponse({
            'success': False,
            'message': 'El preview solo aplica a Despacho SBH.'
        }, status=404)
    if not _usuario_tiene_acceso_empresa(request.user, citacion.EP_NID_id):
        return JsonResponse({'success': False, 'message': 'No tiene acceso a la empresa de la citacion.'}, status=403)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, responsables_paso, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    if paso_actual_visible != PASO_AUTORIZAR_SALIDA:
        return JsonResponse({
            'success': False,
            'message': f'Solo puede previsualizar durante la etapa activa: {PASO_AUTORIZAR_SALIDA}.'
        }, status=409)
    if not usuario_puede_paso_operacion(request.user, responsables_paso):
        return JsonResponse({
            'success': False,
            'message': f'Solo lectura: este paso corresponde a {" / ".join(responsables_paso)}'
        }, status=403)

    preview = construir_diagnostico_preview_update_drafts_operacionales(citacion)
    if preview.get("success") and preview.get("documentos"):
        carga = CITACION_DESPACHO_CARGA.objects.filter(CI_NID=citacion).first()
        try:
            preview["disponibilidad_lotes"] = validar_disponibilidad_final_despacho(
                citacion,
                carga,
                preview["documentos"],
            )
            preview["validacion_estructural"]["disponibilidad_lotes_suficiente"] = True
        except despacho_carga.CargaInvalida as exc:
            preview["success"] = False
            preview["resultado"] = "PREVIEW INVÁLIDO"
            preview["validacion_estructural"]["disponibilidad_lotes_suficiente"] = False
            preview.setdefault("motivos", []).append(str(exc))
    _registrar_log_preview_sap_despacho(preview)
    return JsonResponse(preview)

def ajax_operacion_planta_actualizar_sap_despacho(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({
            'success': False,
            'message': 'No tiene permisos para Operacion Planta.'
        }, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response

    es_sbh = es_despacho_sbh_operacion(citacion)
    es_bodega_externa = es_despacho_bodega_externa_operacion(citacion)
    if not es_sbh and not es_bodega_externa:
        return JsonResponse({
            'success': False,
            'message': 'La actualizacion SAP no aplica al flujo de esta citacion.'
        }, status=400)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, responsables_paso, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    paso_sap_esperado = PASO_AUTORIZAR_SALIDA
    if paso_actual_visible != paso_sap_esperado:
        return JsonResponse({
            'success': False,
            'message': f'Solo puede actualizar SAP durante la etapa activa: {paso_sap_esperado}.'
        }, status=409)
    if not usuario_puede_paso_operacion(request.user, responsables_paso):
        return JsonResponse({
            'success': False,
            'message': f'Solo lectura: este paso corresponde a {" / ".join(responsables_paso)}'
        }, status=403)

    if es_sbh:
        ultimas_cargas = _leer_ultimas_cargas_despacho(citacion)
        if any(not str(ultimas_cargas.get(f'carga_{indice}') or '').strip() for indice in range(1, 4)):
            return JsonResponse({
                'success': False,
                'message': 'Debe guardar las tres últimas cargas antes de actualizar SAP.',
            }, status=409)
        drafts_operacionales = _payload_drafts_sap_despacho_operacionales(citacion)
        if drafts_operacionales.get('aplicable') and not drafts_operacionales.get('actualizacion_habilitada'):
            return JsonResponse({
                'success': False,
                'message': drafts_operacionales['mensaje_actualizacion'],
                'drafts': drafts_operacionales['drafts'],
            }, status=409)

    allow_retry = (
        str(request.POST.get('allow_retry') or '').strip().lower() in {'1', 'true', 'yes'}
        and getattr(request.user, 'is_superuser', False)
    )
    result = sap_despacho_actualizar_borrador(
        citacion,
        request.user,
        allow_retry=allow_retry,
        revalidar_disponibilidad=es_sbh,
    )
    if not result.get('success') and (result.get('status') or {}).get('is_error'):
        _notificar_soporte_error_sap_despacho(citacion, request.user, result)
        result['message'] = result.get('message') or 'No se puede autorizar la salida porque la actualizacion SAP fallo. Soporte fue notificado.'
    return JsonResponse(
        _limpiar_resultado_sap_despacho_para_usuario(result, request.user),
        status=200 if result.get('success') else 400
    )


@require_POST
def ajax_operacion_planta_preview_update_sap_recepcion(request, pk):
    if not getattr(settings, 'SAP_RECEPCION_PREVIEW_ENABLED', False):
        return JsonResponse({
            'success': False,
            'message': 'Preview SAP de recepcion no disponible.',
        }, status=404)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({
            'success': False,
            'message': 'No tiene permisos para Operacion Planta.',
        }, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    if not es_recepcion_prosesa_descarga_camion(citacion):
        return JsonResponse({
            'success': False,
            'message': 'El preview solo aplica a Recepcion PROSESA con descarga sobre camion.',
        }, status=404)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, _, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    if paso_actual_visible != PASO_AUTORIZAR_SALIDA:
        return JsonResponse({
            'success': False,
            'message': f'Solo puede previsualizar SAP durante la etapa activa: {PASO_AUTORIZAR_SALIDA}.',
        }, status=409)
    if not usuario_puede_actualizar_borrador_sap_recepcion(citacion, request.user):
        return JsonResponse({
            'success': False,
            'message': 'Solo Asistente_C_D, Asistente_Recepcion SBH o administrador pueden previsualizar el Borrador SAP de recepcion.',
        }, status=403)

    try:
        preview = build_goods_receipt_draft_update_preview(citacion)
    except Exception as exc:
        return JsonResponse({
            'success': False,
            'message': str(exc),
            'read_only': True,
            'preview': {'payload': {}, 'errors': [str(exc)]},
        }, status=400)

    tiene_errores = bool(preview.get('errors'))
    return JsonResponse({
        'success': not tiene_errores,
        'message': (
            'Previsualizacion generada. No se envio informacion a SAP.'
            if not tiene_errores
            else 'Previsualizacion generada con errores. No se envio informacion a SAP.'
        ),
        'read_only': True,
        'preview': preview,
    })


def ajax_operacion_planta_actualizar_sap_recepcion(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({
            'success': False,
            'message': 'No tiene permisos para Operacion Planta.'
        }, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response

    if str(getattr(citacion, 'CI_CTIPO', '') or '').upper() != CIT_RECEPCION:
        return JsonResponse({
            'success': False,
            'message': 'La actualizacion SAP de recepcion solo aplica al flujo Recepcion.'
        }, status=400)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, responsables_paso, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    if paso_actual_visible != PASO_AUTORIZAR_SALIDA:
        return JsonResponse({
            'success': False,
            'message': f'Solo puede actualizar SAP durante la etapa activa: {PASO_AUTORIZAR_SALIDA}.'
        }, status=409)
    if not usuario_puede_actualizar_borrador_sap_recepcion(citacion, request.user):
        return JsonResponse({
            'success': False,
            'message': 'Solo Asistente_C_D, Asistente_Recepcion SBH o administrador pueden actualizar el Borrador SAP de recepción.'
        }, status=403)
    accion = str(request.POST.get('accion') or '').strip().lower()
    if accion == 'generar_lote':
        if not es_flujo_recepcion_estanque_sbh(citacion):
            return JsonResponse({
                'success': False,
                'message': 'La generación manual de lote SAP solo aplica a Recepción Estanque SBH.',
            }, status=400)

        try:
            with transaction.atomic():
                citacion_bloqueada = (
                    CITACION.objects.select_for_update()
                    .select_related('EP_NID', 'SC_NID', 'ETAPA_ACTUAL')
                    .get(pk=citacion.pk)
                )
                lote_existente = (
                    DATO_OPERACION.objects.filter(
                        CI_NID=citacion_bloqueada,
                        SC_NID=citacion_bloqueada.SC_NID,
                        CAMP_NID__CA_CCODIGO=CAMPO_LOTE_RECEPCION_SAP,
                    )
                    .order_by('-id')
                    .first()
                )
                if lote_existente and str(lote_existente.DO_CVALOR or '').strip():
                    lote = str(lote_existente.DO_CVALOR).strip()
                    return JsonResponse({
                        'success': True,
                        'message': 'La citación ya tiene un lote SAP generado.',
                        'lote': lote,
                        'reused': True,
                    })

                draft_status = get_goods_receipt_draft_guide_status(citacion_bloqueada)
                if not draft_status.get('sent') or not draft_status.get('docentry'):
                    return JsonResponse({
                        'success': False,
                        'message': 'Debe existir un Draft SAP con DocEntry antes de generar el lote.',
                    }, status=409)

                update_status = get_goods_receipt_draft_update_status(citacion_bloqueada)
                if not update_status.get('peso_salida_kg'):
                    return JsonResponse({
                        'success': False,
                        'message': 'Debe existir Pesaje Salida antes de generar el lote SAP.',
                    }, status=409)

                item_code = str(
                    update_status.get('item_code') or draft_status.get('item_code') or ''
                ).strip()
                if not item_code:
                    return JsonResponse({
                        'success': False,
                        'message': 'No se puede generar el lote SAP: falta ItemCode.',
                    }, status=400)

                lote = generar_lote_recepcion_sap(item_code)
                _guardar_lote_recepcion(citacion_bloqueada, request.user, lote)
        except (GoodsReceiptDraftError, SapDiApiError) as exc:
            return JsonResponse({'success': False, 'message': str(exc)}, status=400)

        return JsonResponse({
            'success': True,
            'message': 'Lote SAP generado y guardado correctamente.',
            'lote': lote,
            'reused': False,
        })

    if es_flujo_recepcion_estanque_sbh(citacion) and not obtener_lote_recepcion_sap(citacion):
        return JsonResponse({
            'success': False,
            'message': 'Genere el Lote SAP antes de actualizar el borrador.',
        }, status=409)

    allow_retry = (
        str(request.POST.get('allow_retry') or '').strip().lower() in {'1', 'true', 'yes'}
        and getattr(request.user, 'is_superuser', False)
    )
    result = send_goods_receipt_draft_update_to_sap(citacion, request.user, allow_retry=allow_retry)
    return JsonResponse(result, status=200 if result.get('success') else 400)


def _validar_borrador_sap_disponible(citacion, request, requiere_activo=False):
    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, responsables_paso, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    completados = set(OPERACION_PLANTA_LOG.objects.filter(
        CI_NID=citacion,
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).values_list('OPL_CPASO', flat=True))

    if 'Pesaje Salida' not in completados:
        return JsonResponse({
            'success': False,
            'message': 'Debe completar y congelar Pesaje Salida antes de generar el Borrador SAP.'
        }, status=400)

    responsables_borrador = []
    for nombre_paso, responsables in pasos_config:
        if nombre_paso == PASO_BORRADOR_SAP:
            responsables_borrador = responsables
            break

    if not usuario_puede_paso_operacion(request.user, responsables_borrador):
        return JsonResponse({
            'success': False,
            'message': f'Solo lectura: este paso corresponde a {" / ".join(responsables_borrador)}'
        }, status=403)

    if requiere_activo and paso_actual_visible != PASO_BORRADOR_SAP:
        return JsonResponse({
            'success': False,
            'message': f'Solo puede enviar SAP durante la etapa activa: {PASO_BORRADOR_SAP}. Etapa actual: {paso_actual_visible}.'
        }, status=409)

    return None


def ajax_operacion_planta_borrador_sap_preview(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response

    if es_flujo_recepcion_estanque_sbh(citacion):
        if not getattr(settings, 'SAP_RECEPCION_PREVIEW_ENABLED', False):
            return JsonResponse({
                'success': False,
                'message': 'Preview SAP de recepcion no disponible.',
            }, status=404)
        if not _usuario_tiene_acceso_empresa(request.user, citacion.EP_NID_id):
            return JsonResponse({
                'success': False,
                'message': 'No tiene acceso a la empresa de la citacion.',
            }, status=403)

        preview = build_goods_receipt_draft_preview_from_peso_guia(citacion)
        estado_draft = get_goods_receipt_draft_guide_status(citacion)
        preview['status'] = {
            'sent': bool(estado_draft.get('sent')),
            'label': estado_draft.get('local_status') or 'Pendiente de generar',
            'sap_status': estado_draft.get('sap_status') or 'No enviado',
            'docentry': estado_draft.get('docentry'),
            'docnum': estado_draft.get('docnum'),
        }
        preview['existing_draft'] = {
            'sent': bool(estado_draft.get('sent')),
            'docentry': estado_draft.get('docentry'),
            'docnum': estado_draft.get('docnum'),
            'local_status': estado_draft.get('local_status') or '',
            'sap_status': estado_draft.get('sap_status') or '',
            'usuario': estado_draft.get('usuario') or '',
            'fecha_hora': estado_draft.get('fecha_hora') or '',
            'request_json': estado_draft.get('request_json') or {},
            'response_json': estado_draft.get('response_json') or {},
        }
        detalle_operacional = _detalle_operacional_citacion(citacion)
        tipo_recepcion = str(
            getattr(detalle_operacional, 'CDO_CTIPO_RECEPCION', '') or ''
        ).strip().upper()
        return JsonResponse({
            'success': not bool(preview.get('errors')),
            'message': 'Preview generado.' if not preview.get('errors') else 'Preview generado con errores.',
            'read_only': True,
            'presentation': {
                'tipo_recepcion': tipo_recepcion,
                'tipo_recepcion_label': (
                    etiqueta_tipo_recepcion_sbh(tipo_recepcion) or tipo_recepcion
                ),
            },
            'preview': preview,
        })

    disponible_response = _validar_borrador_sap_disponible(citacion, request, requiere_activo=False)
    if disponible_response:
        return disponible_response

    preview = build_goods_receipt_draft_preview(citacion)
    print(f'\n[Borrador SAP][Preview][Citacion {citacion.id}] JSON SAP generado:')
    print(json.dumps(preview.get('payload') or {}, indent=2, ensure_ascii=False))
    return JsonResponse({
        'success': not bool(preview.get('errors')),
        'message': 'Preview generado.' if not preview.get('errors') else 'Preview generado con errores.',
        'preview': preview,
    })

@require_POST
def ajax_operacion_planta_reintentar_draft_sap_recepcion(request, pk):
    if not getattr(settings, 'SAP_RECEPCION_PREVIEW_ENABLED', False):
        return JsonResponse({
            'success': False,
            'message': 'El reintento manual del Draft SAP de recepcion no esta habilitado.',
        }, status=404)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({
            'success': False,
            'message': 'No tiene permisos para Operacion Planta.',
        }, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response
    if not es_flujo_recepcion_estanque_sbh(citacion):
        return JsonResponse({
            'success': False,
            'message': 'El reintento manual solo aplica a Recepcion Estanque SBH.',
        }, status=404)
    if not _usuario_tiene_acceso_empresa(request.user, citacion.EP_NID_id):
        return JsonResponse({
            'success': False,
            'message': 'No tiene acceso a la empresa de la citacion.',
        }, status=403)
    if not usuario_puede_actualizar_borrador_sap_recepcion(citacion, request.user):
        return JsonResponse({
            'success': False,
            'message': (
                'Solo Asistente_C_D, Asistente_Recepcion SBH o administrador '
                'pueden reintentar el Draft SAP de recepcion.'
            ),
        }, status=403)
    if not calidad_aprobada_para_reintento_draft_sap(citacion):
        return JsonResponse({
            'success': False,
            'message': 'La Calidad debe estar APROBADA antes de reintentar el Draft SAP.',
        }, status=409)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    paso_actual_visible, _, _ = obtener_paso_activo_operacion(citacion, pasos_config)
    if paso_actual_visible != PASO_RESULTADO_CALIDAD:
        return JsonResponse({
            'success': False,
            'message': (
                'El reintento manual solo esta disponible durante la etapa '
                f'{PASO_RESULTADO_CALIDAD}.'
            ),
        }, status=409)

    estado_existente = get_goods_receipt_draft_guide_status(citacion)
    if estado_existente.get('sent') and estado_existente.get('docentry'):
        resultado = {
            'success': True,
            'reused': True,
            'message': 'El Draft SAP ya existe.',
            'status': estado_existente,
        }
    else:
        resultado = crear_borrador_sap_recepcion_por_calidad_aprobada(
            citacion.id,
            request.user.id,
        )
        if not isinstance(resultado, dict):
            resultado = {
                'success': False,
                'message': 'El servicio SAP no devolvio un resultado valido.',
            }

    estado_final = (
        resultado.get('status')
        if isinstance(resultado.get('status'), dict)
        else {}
    )
    if resultado.get('success') and not (
        estado_final.get('sent') and estado_final.get('docentry')
    ):
        estado_final = get_goods_receipt_draft_guide_status(citacion)
        resultado['status'] = estado_final
    if resultado.get('success') and not (
        estado_final.get('sent') and estado_final.get('docentry')
    ):
        resultado = {
            **resultado,
            'success': False,
            'message': 'SAP no dejo un Draft valido con DocEntry.',
            'status': estado_final,
        }

    _registrar_log_reintento_manual_draft_sap(
        citacion,
        request.user,
        resultado,
    )

    estado_final = resultado.get('status') or {}
    es_reutilizado = bool(resultado.get('reused'))
    response_data = {
        'success': bool(resultado.get('success')),
        'message': (
            'El Draft SAP ya existe.'
            if es_reutilizado
            else (
                'Draft SAP creado correctamente.'
                if resultado.get('success')
                else detalle_error_borrador_sap_recepcion(resultado)
            )
        ),
        'reused': es_reutilizado,
        'docentry': estado_final.get('docentry'),
        'docnum': estado_final.get('docnum'),
        'status_code': resultado.get('status_code'),
        'confirmation_required': bool(resultado.get('confirmation_required')),
    }
    return JsonResponse(
        response_data,
        status=200 if response_data['success'] else 400,
    )


def ajax_operacion_planta_borrador_sap_enviar(request, pk):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'message': 'Metodo no permitido.'}, status=405)
    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para Operacion Planta.'}, status=403)

    citacion, error_response = _obtener_citacion_operacion_planta_ajax(request, pk)
    if error_response:
        return error_response

    disponible_response = _validar_borrador_sap_disponible(citacion, request, requiere_activo=True)
    if disponible_response:
        return disponible_response

    allow_duplicate = str(request.POST.get('allow_duplicate') or '').lower() in {'1', 'true', 'yes'}
    print(
        f'\n[Borrador SAP][Enviar][Citacion {citacion.id}] '
        'El endpoint reconstruira el JSON en backend antes del POST real a SAP.'
    )
    result = send_goods_receipt_draft_to_sap(citacion, request.user, allow_duplicate=allow_duplicate)
    return JsonResponse(result, status=200 if result.get('success') else 400)


def ajax_operacion_planta_descargar_documento_calidad(request):
    citacion_id = request.GET.get('citacion_id')
    if not citacion_id:
        return JsonResponse({'success': False, 'message': 'Debe indicar citacion.'}, status=400)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return JsonResponse({'success': False, 'message': 'Debe seleccionar una empresa.'}, status=400)

    try:
        citacion = CITACION.objects.get(pk=citacion_id, EP_NID_id=Empresa, CI_BHABILITADO=True)
    except CITACION.DoesNotExist:
        return JsonResponse({'success': False, 'message': 'Citacion no encontrada.'}, status=404)

    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'success': False, 'message': 'No tiene permisos para descargar este documento.'}, status=403)

    metadata = _leer_metadata_resultado_calidad(citacion)
    ruta = metadata.get('documento_ruta') if metadata else ''
    nombre = metadata.get('documento_nombre') if metadata else ''
    if not ruta or not nombre or not os.path.isfile(ruta) or not _ruta_ticket_permitida(ruta):
        return JsonResponse({'success': False, 'message': 'Documento de calidad no disponible.'}, status=404)

    return FileResponse(
        open(ruta, 'rb'),
        as_attachment=False,
        filename=nombre,
        content_type='application/octet-stream'
    )


def _validar_operacion_planta_ticket_request(request, citacion_id, paso_nombre):
    if not usuario_es_operacion_planta(request.user):
        return None, None, JsonResponse({'valid': False, 'msg': 'No tiene permisos para Operacion Planta.'}, status=403)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return None, None, JsonResponse({'valid': False, 'msg': 'Debe seleccionar una empresa.'}, status=400)

    try:
        citacion = CITACION.objects.select_related('EP_NID', 'PL_NID', 'SC_NID', 'CA_NID').get(
            pk=citacion_id,
            EP_NID_id=Empresa,
            CI_BHABILITADO=True
        )
    except CITACION.DoesNotExist:
        return None, None, JsonResponse({'valid': False, 'msg': 'Citacion no encontrada.'}, status=404)

    tipo_ticket = _tipo_ticket_pesaje(paso_nombre)
    if not tipo_ticket:
        return None, None, JsonResponse({'valid': False, 'msg': 'El paso indicado no requiere ticket de pesaje.'}, status=400)

    _, pasos_config = obtener_pasos_operacion_citacion(citacion)
    responsables_paso = None
    for nombre_paso, responsables in pasos_config:
        if nombre_paso == paso_nombre:
            responsables_paso = responsables
            break

    if not responsables_paso:
        return None, None, JsonResponse({'valid': False, 'msg': 'Paso operacional no valido.'}, status=400)
    if not usuario_puede_paso_operacion(request.user, responsables_paso):
        return None, None, JsonResponse({'valid': False, 'msg': f'Solo lectura: este paso corresponde a {" / ".join(responsables_paso)}'}, status=403)

    logs_completados = set(OPERACION_PLANTA_LOG.objects.filter(
        CI_NID=citacion,
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).values_list('OPL_CPASO', flat=True))
    paso_actual_visible = resolver_estado_operacional_visible(citacion, pasos_config, logs_completados)
    ciclo_descarga_p3 = (
        _payload_ciclo_descarga(citacion)
        if es_recepcion_new_jersey_p3(citacion)
        else None
    )
    permite_ticket_salida_p3 = bool(
        es_recepcion_new_jersey_p3(citacion)
        and citacion_habilitada_operacion(citacion)
        and paso_nombre == 'Pesaje Salida'
        and paso_actual_visible == PASO_NJ_P3_CARGA_DESCARGA
        and 'Pesaje Entrada' in logs_completados
        and (ciclo_descarga_p3 or {}).get('en_proceso')
        and 'Pesaje Salida' not in logs_completados
    )
    if paso_nombre != paso_actual_visible and not permite_ticket_salida_p3:
        return None, None, JsonResponse({'valid': False, 'msg': f'Solo puede operar la etapa activa actual: {paso_actual_visible}.'}, status=409)

    return citacion, tipo_ticket, None


def ajax_operacion_planta_obtener_ticket_pesaje(request):
    if request.method != 'GET':
        return JsonResponse({'valid': False, 'msg': 'Metodo no permitido.'}, status=405)

    citacion_id = request.GET.get('citacion_id')
    paso_nombre = str(request.GET.get('paso_codigo') or request.GET.get('paso_nombre') or '').strip()
    if not citacion_id or not paso_nombre:
        return JsonResponse({'valid': False, 'msg': 'Debe indicar citacion y paso operacional.'}, status=400)

    citacion, tipo_ticket, error_response = _validar_operacion_planta_ticket_request(request, citacion_id, paso_nombre)
    if error_response:
        return error_response

    valores_ingreso = obtener_valores_ingreso_camion(citacion)
    patente = obtener_patente_operacional_vigente(citacion, valores_ingreso)
    patente_normalizada = _normalizar_patente(patente)
    _debug_ticket_pesaje(
        'Patente obtenida para ticket',
        citacion_id=citacion.id,
        paso=paso_nombre,
        tipo_ticket=tipo_ticket,
        patente_original=repr(patente),
        patente_normalizada=patente_normalizada
    )
    if not patente_normalizada:
        return JsonResponse({'valid': False, 'msg': 'La citacion no tiene patente para buscar ticket de pesaje.'}, status=400)

    mop_requerido = es_pesaje_salida_mop_despacho_terramar(
        citacion,
        paso_nombre,
        tipo_ticket,
    )

    try:
        dato_existente = _dato_ticket_pesaje(citacion, paso_nombre)
        payload_existente = _payload_ticket_pesaje_guardado(citacion, paso_nombre, request)
        if mop_requerido and dato_existente:
            metadata_ticket = _leer_metadata_ticket_dato(dato_existente)
            if not payload_existente or not metadata_ticket:
                return JsonResponse({
                    'valid': False,
                    'msg': 'El ticket de salida congelado no es válido. No se reemplazará automáticamente.',
                    'mop_requerido': True,
                    'mop_ok': False,
                }, status=409)
            resultado_mop = _resolver_ticket_mop_despacho_terramar(
                citacion,
                patente_normalizada,
                metadata_ticket,
                request.user,
                request,
            )
            respuesta = {
                'valid': resultado_mop['estado'] != 'MOP_AMBIGUO',
                'guardado': True,
                'dato_id': dato_existente.id,
                'peso_neto': payload_existente.get('peso_neto'),
                'folio': payload_existente.get('folio'),
                'observacion': payload_existente.get('observacion') or '',
                'download_url': payload_existente.get('download_url') or '',
                'nombre_archivo_pdf': payload_existente.get('nombre_archivo_pdf') or '',
                'mop_requerido': True,
                'mop_ok': resultado_mop['ok'],
                'mop_estado': resultado_mop['estado'],
                'mop_nombre': resultado_mop['nombre'],
                'mop_download_url': resultado_mop['download_url'],
                'mop_mensaje': resultado_mop['mensaje'],
            }
            if resultado_mop['estado'] == 'MOP_AMBIGUO':
                respuesta['msg'] = resultado_mop['mensaje']
                return JsonResponse(respuesta, status=409)
            return JsonResponse(respuesta)

        if (
            (
                es_recepcion_prosesa_piso_1(citacion)
                or es_recepcion_prosesa_piso_2(citacion)
                or es_recepcion_new_jersey_p3(citacion)
            )
            and dato_existente
            and payload_existente
        ):
            respuesta_existente = {
                'valid': True,
                'guardado': True,
                'dato_id': dato_existente.id,
                'peso_neto': payload_existente.get('peso_neto'),
                'folio': payload_existente.get('folio'),
                'observacion': payload_existente.get('observacion') or '',
                'download_url': payload_existente.get('download_url') or '',
                'nombre_archivo_pdf': payload_existente.get('nombre_archivo_pdf') or '',
            }
            if es_recepcion_new_jersey_p3(citacion) and tipo_ticket == 'SAL':
                ciclo_p3 = _finalizar_carga_descarga_new_jersey_p3(citacion, request.user)
                respuesta_existente.update({
                    'carga_descarga_completada': True,
                    'duracion_carga_descarga': ciclo_p3.get('duracion_legible') or '',
                    'recargar_operacion': True,
                })
            return JsonResponse(respuesta_existente)

        ruta_pdf = _buscar_ticket_pesaje_mas_reciente(patente_normalizada, tipo_ticket)
        if not ruta_pdf:
            return JsonResponse({'valid': False, 'msg': f'No se encontro ticket COM_{tipo_ticket} para la patente {patente_normalizada}.'}, status=404)

        datos_ticket = _extraer_datos_ticket_pesaje(
            ruta_pdf,
            tipo_ticket,
            semantica_despacho_sbh=es_despacho_sbh_operacion(citacion),
            conservar_pesos_brutos=(
                es_recepcion_prosesa_piso_1(citacion)
                or es_recepcion_prosesa_piso_2(citacion)
            ),
        )
        ruta_local = _copiar_ticket_local_si_necesario(ruta_pdf)
        if not _ruta_ticket_permitida(ruta_local):
            return JsonResponse({'valid': False, 'msg': 'La ruta local del ticket no esta permitida.'}, status=400)

        campo = _obtener_campo_ticket_pesaje(citacion, tipo_ticket, request.user)
        metadata = _metadata_ticket_pesaje(
            citacion,
            paso_nombre,
            tipo_ticket,
            patente_normalizada,
            ruta_local,
            datos_ticket,
            request.user
        )
        dato, _ = DATO_OPERACION.objects.update_or_create(
            CI_NID=citacion,
            SC_NID=citacion.SC_NID,
            ET_NID=citacion.ETAPA_ACTUAL,
            CAMP_NID=campo,
            defaults={
                'EP_NID': citacion.EP_NID,
                'US_NID': request.user,
                'DO_CVALOR': json.dumps(metadata, ensure_ascii=False),
                'DO_NPESO': int(datos_ticket['peso_neto']),
                'DO_FFECHAREGISTRO': timezone.now(),
            }
        )

        registrar_log_camion_no_planificado(
            request.user,
            citacion.EP_NID,
            f'TICKET_PESAJE_{tipo_ticket}',
            f'Ticket {tipo_ticket} congelado para citacion #{citacion.id}. Folio: {datos_ticket["folio"]}. Peso: {datos_ticket["peso_neto"]}.',
            citacion.id,
            os.path.basename(ruta_local)
        )

        payload = _payload_ticket_pesaje_guardado(citacion, paso_nombre, request) or {}
        respuesta = {
            'valid': True,
            'guardado': True,
            'dato_id': dato.id,
            'peso_neto': datos_ticket['peso_neto'],
            'folio': datos_ticket['folio'],
            'observacion': datos_ticket.get('observacion') or '',
            'download_url': payload.get('download_url', ''),
            'nombre_archivo_pdf': payload.get('nombre_archivo_pdf', os.path.basename(ruta_local)),
        }
        if es_recepcion_new_jersey_p3(citacion) and tipo_ticket == 'SAL':
            ciclo_p3 = _finalizar_carga_descarga_new_jersey_p3(citacion, request.user)
            respuesta.update({
                'carga_descarga_completada': True,
                'duracion_carga_descarga': ciclo_p3.get('duracion_legible') or '',
                'recargar_operacion': True,
            })
        if mop_requerido:
            resultado_mop = _resolver_ticket_mop_despacho_terramar(
                citacion,
                patente_normalizada,
                metadata,
                request.user,
                request,
            )
            respuesta.update({
                'mop_requerido': True,
                'mop_ok': resultado_mop['ok'],
                'mop_estado': resultado_mop['estado'],
                'mop_nombre': resultado_mop['nombre'],
                'mop_download_url': resultado_mop['download_url'],
                'mop_mensaje': resultado_mop['mensaje'],
            })
            if resultado_mop['estado'] == 'MOP_AMBIGUO':
                respuesta.update({'valid': False, 'msg': resultado_mop['mensaje']})
                return JsonResponse(respuesta, status=409)
        return JsonResponse(respuesta)
    except ValueError as e:
        return JsonResponse({'valid': False, 'msg': str(e)}, status=400)
    except Exception as e:
        return JsonResponse({'valid': False, 'msg': f'Error al obtener ticket de pesaje: {str(e)}'}, status=500)

def ajax_operacion_planta_descargar_ticket_pesaje(request):
    dato_id = request.GET.get('dato_id')
    if not dato_id:
        return JsonResponse({'valid': False, 'msg': 'Debe indicar el dato del ticket.'}, status=400)

    Empresa = Verificar_empresa(request)
    if Empresa is None:
        return JsonResponse({'valid': False, 'msg': 'Debe seleccionar una empresa.'}, status=400)

    try:
        dato = DATO_OPERACION.objects.select_related('CI_NID__SC_NID', 'CAMP_NID').get(
            pk=dato_id,
            EP_NID_id=Empresa,
            CAMP_NID__CA_CCODIGO__in=[
                _codigo_campo_ticket_pesaje('ENT'),
                _codigo_campo_ticket_pesaje('SAL'),
                CAMPO_TICKET_MOP_SAL_DESP_TERRAMAR,
            ]
        )
    except DATO_OPERACION.DoesNotExist:
        return JsonResponse({'valid': False, 'msg': 'Ticket no encontrado.'}, status=404)

    if not usuario_es_operacion_planta(request.user):
        return JsonResponse({'valid': False, 'msg': 'No tiene permisos para descargar este ticket.'}, status=403)

    es_mop = dato.CAMP_NID.CA_CCODIGO == CAMPO_TICKET_MOP_SAL_DESP_TERRAMAR
    if es_mop:
        if not es_pesaje_salida_mop_despacho_terramar(dato.CI_NID, 'Pesaje Salida', 'SAL'):
            return JsonResponse({'valid': False, 'msg': 'Ticket no encontrado.'}, status=404)
        metadata = _metadata_ticket_mop_dato(dato)
        ruta_pdf = metadata.get('ruta_local') if metadata else ''
        nombre_descarga = metadata.get('nombre') if metadata else ''
        valido = _ticket_mop_guardado_valido(dato.CI_NID, metadata)
    else:
        metadata = _leer_metadata_ticket_dato(dato)
        ruta_pdf = metadata.get('ruta_real_pdf') if metadata else ''
        nombre_descarga = os.path.basename(ruta_pdf) if ruta_pdf else ''
        valido = bool(ruta_pdf and os.path.isfile(ruta_pdf) and _ruta_ticket_permitida(ruta_pdf))

    if not valido or not ruta_pdf:
        return JsonResponse({'valid': False, 'msg': 'El PDF congelado no existe o no esta permitido.'}, status=404)

    return FileResponse(
        open(ruta_pdf, 'rb'),
        as_attachment=True,
        filename=nombre_descarga or os.path.basename(ruta_pdf),
        content_type='application/pdf'
    )

def formatear_duracion_planta(fecha_inicio):
    if not fecha_inicio:
        return 'No disponible'

    delta = timezone.now() - fecha_inicio
    total_minutos = max(int(delta.total_seconds() // 60), 0)
    horas = total_minutos // 60
    minutos = total_minutos % 60

    if horas:
        return f'{horas}h {minutos}m'
    return f'{minutos}m'


def formatear_duracion_operacional(delta):
    if not delta:
        return 'No disponible'

    total_segundos = max(int(delta.total_seconds()), 0)
    dias = total_segundos // 86400
    horas = (total_segundos % 86400) // 3600
    minutos = (total_segundos % 3600) // 60
    segundos = total_segundos % 60

    if dias:
        return f'{dias}d {horas}h {minutos}m'
    if horas:
        return f'{horas}h {minutos:02d}m {segundos:02d}s'
    if minutos:
        return f'{minutos} min {segundos:02d} seg'
    return f'{segundos} seg'


LOG_AUTORIZA_SALIDA_PLANTA = 'AUTORIZA_SALIDA_PLANTA'
LOG_AUTORIZA_INGRESO_PLANTA_OP = 'AUTORIZA_REING_PLANTA'


def es_despacho_bodega_externa_operacion(citacion):
    if not citacion or not es_citacion_despacho(citacion):
        return False
    codigo = str(citacion.SC_NID.SE_CCODIGO if citacion.SC_NID else '').strip().upper()
    nombre = normalizar_nombre_flujo_operacion(citacion.SC_NID.SE_CNOMBRE if citacion.SC_NID else '')
    return codigo == 'BODEGA_EXTERNA_CLIENTE' or 'DESPACHO DESDE BODEGA EXTERNA' in nombre


def formatear_duracion_hms(delta):
    if not delta:
        return '00:00:00'
    total_segundos = max(int(delta.total_seconds()), 0)
    horas = total_segundos // 3600
    minutos = (total_segundos % 3600) // 60
    segundos = total_segundos % 60
    return f'{horas:02d}:{minutos:02d}:{segundos:02d}'


def _fecha_operacion_iso(fecha):
    return timezone.localtime(fecha).isoformat() if fecha else ''


def _fecha_operacion_ms(fecha):
    return int(timezone.localtime(fecha).timestamp() * 1000) if fecha else ''


def _fecha_operacion_legible(fecha):
    return timezone.localtime(fecha).strftime('%d/%m/%Y %H:%M') if fecha else ''


def _ultimo_log_operacion(citacion, paso):
    return OPERACION_PLANTA_LOG.objects.select_related('US_NID').filter(
        CI_NID=citacion,
        OPL_CPASO=paso,
        OPL_CESTADO=OPERACION_PLANTA_LOG.ESTADO_COMPLETADO
    ).order_by('-OPL_FFECHAREGISTRO').first()


