        {'label': 'OC cliente', 'value': datos['oc_cliente']},
        {'label': 'Producto SAP', 'value': datos['sap_nombre_producto']},
        {'label': 'Codigo producto', 'value': datos['sap_codigo_producto']},
        {'label': 'Cantidad intentada', 'value': datos['cantidad_intentada']},
